insert into public.heroes (slug, name, roles) values
  ('nightcrawler', 'Nightcrawler', array['Strategist']::public.hero_role[])
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Adam Warlock est le Strategist le plus exigeant du jeu, et l'un des plus rentables quand il est maîtrisé. Il ne gagne pas ses parties en soignant depuis l'arrière : il met la pression sur un angle décalé, charge sa résurrection par ses dégâts et annule les ults adverses avec son lien d'âmes.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["Joue **sur un angle décalé** et fais des dégâts : c'est ce qui charge ta résurrection.", "Ton **lien d'âmes** se garde pour l'ult adverse qui tuerait un allié.", "Lance ta **résurrection à couvert** : les alliés reviennent près de toi, avec très peu de vie."], "difficulty": 3, "tags": ["Angles décalés", "Dégâts", "Anti-ult", "Résurrection"], "strengths": ["Dégâts de DPS sur un Strategist", "Lien d'âmes : annule une ult de burst", "Résurrection de toute l'équipe"], "weaknesses": ["Aucune mobilité : un dive bien mené le tue", "Soins limités par les cooldowns", "Ult très longue à charger"], "playbook": [{"when": "Une ult de burst part sur un allié (Magneto, Psylocke, Winter Soldier)", "then": "Lance le **lien d'âmes** juste avant l'impact, en liant d'abord les alliés fragiles : les dégâts se répartissent et personne ne meurt."}, {"when": "Un allié a perdu la moitié de sa vie au milieu du groupe", "then": "C'est le moment d'envoyer ton **soin à rebonds** : il saute d'allié en allié. Sur un allié presque plein, la charge est gaspillée."}, {"when": "Un diver te saute dessus", "then": "Vise le sol pour te soigner, tire à la tête, et recule vers ton autre support. Tu n'as aucun déplacement : ta survie, c'est ta visée et ta position."}, {"when": "Le combo d'ults adverse est prêt (Groot, Strange, Magneto)", "then": "Écarte-toi du groupe avant qu'il tombe, laisse-le passer, puis **ressuscite**. Ta seule ult répond à deux des leurs."}, {"when": "Tu viens de mourir avec ton cocon disponible", "then": "Déplace ton âme derrière un mur avant de te relever. Si le fight est déjà perdu, ne te relève pas : garde le cocon pour le suivant."}, {"when": "Ta résurrection est prête", "then": "L'ennemi la surveille : joue plus loin et plus à couvert jusqu'au fight où tu en as besoin."}], "sections": [{"title": "Philosophie de jeu", "lead": "Si tu restes en retrait à soigner, n'importe quel autre Strategist fera mieux le travail. Adam se joue comme un troisième DPS qui garde deux soins et un lien pour les moments critiques.", "ability": "", "key": "", "kind": "tips", "items": ["Prends un **angle décalé** par rapport à ton tank : tu tires sur la backline adverse sans passer par leur bouclier, et tes dégâts chargent ton ult plus vite que les soins.", "Garde le **lien d'âmes** pour répondre à une ult adverse. Sans ult en face, il sert à forcer un fight : toute ton équipe encaisse mieux pendant quelques secondes.", "Ce qui distingue un bon Adam, ce n'est pas la visée : c'est de **passer des dégâts aux soins au bon moment**, sans rester bloqué sur l'un des deux."], "diagram": "angle"}, {"title": "Dégâts", "lead": "Ton tir principal est instantané et frappe très fort pour un Strategist : deux tirs à la tête laissent la plupart des cibles à un souffle de la mort.", "ability": "Quantum Magic · Cosmic Cluster", "key": "Clic G · Clic D", "kind": "default", "items": ["Le tir principal est **hitscan** : fiable à moyenne portée, mais ses dégâts baissent avec la distance.", "Le tir chargé envoie une salve de projectiles **sans perte de dégâts à distance** : c'est lui qui finit une cible éloignée. Écarte légèrement ta visée pour en toucher davantage.", "Au contact, enchaîne **tir principal, tir chargé, tir principal** : bien placé, ce combo tue une cible fragile.", "Les deux tirs partagent **les mêmes munitions**. Recharge avant chaque fight.", "Charge ton tir avant de sortir d'un mur, tire, puis rentre. Évite en revanche d'arroser les tanks : tu offres de l'ult aux supports adverses."], "diagram": ""}, {"title": "Soin", "lead": "Ton soin part sur un allié puis rebondit sur ses voisins, toujours vers celui qui a le moins de vie. Tu n'as que deux charges, longues à revenir.", "ability": "Avatar Life Stream", "key": "E", "kind": "default", "items": ["Depuis la saison 11, le premier impact soigne moins mais le soin **rebondit quatre fois** : il est fait pour un groupe serré, pas pour sauver un allié isolé.", "Sans allié autour de la cible, les rebonds reviennent sur elle, puis **sur toi**. Vise le sol pour te soigner directement.", "Attends qu'un allié ait **perdu une vraie partie de sa vie** avant de dépenser une charge.", "Tes auto-soins font de toi un bon duelliste, mais deux charges dépensées sur toi laissent ton équipe **sans soin** pendant plusieurs secondes.", "Sur ton angle, joue **autour d'un mur** : chaque dégât que tu ne prends pas est une charge de soin économisée."], "diagram": ""}, {"title": "Lien d'âmes", "lead": "Le lien répartit les dégâts subis entre tous les alliés liés et les soigne légèrement. Sa portée est courte : il faut être près de ton équipe pour le lancer.", "ability": "Soul Bond", "key": "Maj", "kind": "default", "items": ["Sa meilleure utilisation : **annuler une ult de burst** sur un allié. Les dégâts qui auraient tué une cible sont partagés entre quatre ou cinq barres de vie.", "Lance-le **une demi-seconde en avance** : il a un temps d'incantation pendant lequel tu peux être tué ou étourdi.", "Lie d'abord les **héros fragiles**. Les tanks ont assez de vie, et leur large hitbox fait monter les dégâts partagés trop vite.", "Il ne rend pas invincible : si l'ult adverse dépasse la vie cumulée du groupe, la cible meurt quand même.", "Le lien se rompt si tu t'éloignes : après l'avoir lancé depuis ton angle, **reviens vers ton équipe**."], "diagram": "", "scene": {"title": "Le lien contre une ult", "caption": "Une ult de burst tue une cible à 250 PV. Répartie sur quatre alliés liés, elle ne tue personne.", "steps": ["Magneto lance son ult sur ton autre support.", "Tu lies les alliés fragiles juste avant l'impact.", "Les dégâts se partagent : tout le monde survit."], "els": [{"t": "zone", "at": [88, 100], "r": 46, "team": "me", "label": "Alliés liés", "n": 2}, {"t": "pawn", "at": [104, 130], "team": "me"}, {"t": "pawn", "at": [60, 96], "team": "ally", "role": "heal", "label": "Visé"}, {"t": "pawn", "at": [72, 132], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [124, 104], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [170, 110], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [252, 50], "team": "enemy", "hero": "magneto", "above": true}, {"t": "path", "kind": "beam", "team": "enemy", "pts": [[252, 50], [60, 96]], "n": 1}, {"t": "path", "kind": "sight", "team": "me", "pts": [[104, 130], [60, 96]]}, {"t": "path", "kind": "sight", "team": "me", "pts": [[104, 130], [72, 132]]}, {"t": "path", "kind": "sight", "team": "me", "pts": [[104, 130], [124, 104]]}, {"t": "note", "at": [150, 158], "text": "3", "team": "ally"}, {"t": "note", "at": [196, 161], "text": "dégâts partagés", "team": "ally"}, {"t": "pawn", "at": [232, 118], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [286, 96], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [272, 142], "team": "enemy", "role": "dps"}]}}, {"title": "Ultime", "lead": "Pendant quelques secondes, les alliés morts reviennent à la vie près de toi. C'est l'ult la plus longue à charger du jeu, et l'une de celles qui retournent le plus de fights.", "ability": "Karmic Revival", "key": "Q", "kind": "default", "items": ["Les alliés reviennent avec **très peu de vie** : lance l'ult derrière un mur, hors de la ligne de tir adverse.", "Tu peux **mourir pendant l'incantation**. Mets-toi à l'abri avant d'appuyer.", "La portée se compte **autour de toi** et te suit : tu peux marcher vers un allié tombé plus loin pour l'inclure.", "Contre un combo d'ults que tu ne peux pas empêcher, **joue à l'écart et ressuscite après**.", "Ramener **un seul joueur clé** (un support, un allié qui a son ult) suffit souvent à gagner le fight."], "diagram": "", "scene": {"title": "Résurrection à couvert", "caption": "Les alliés reviennent près de toi avec très peu de vie : à découvert, ils meurent une seconde fois.", "steps": ["Tes alliés tombent sur le point.", "Tu te places derrière un mur et tu lances l'ult.", "Ils reviennent à l'abri, près de toi, le temps d'être soignés."], "els": [{"t": "cover", "at": [118, 56], "size": [14, 72], "label": "Mur"}, {"t": "pawn", "at": [176, 66], "team": "ally", "role": "tank", "ko": true}, {"t": "pawn", "at": [184, 116], "team": "ally", "role": "dps", "ko": true}, {"t": "note", "at": [164, 92], "text": "1", "team": "ally"}, {"t": "zone", "at": [78, 92], "r": 34, "team": "me", "n": 2}, {"t": "pawn", "at": [78, 92], "team": "me"}, {"t": "path", "kind": "move", "team": "ally", "pts": [[176, 66], [134, 24], [88, 58]], "n": 3}, {"t": "path", "kind": "move", "team": "ally", "pts": [[184, 116], [140, 160], [90, 126]], "n": 3}, {"t": "pawn", "at": [34, 118], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [228, 92], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [258, 58], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [258, 126], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [298, 74], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [298, 112], "team": "enemy", "role": "heal"}]}}, {"title": "Passif : auto-résurrection", "lead": "Après ta mort, ton âme reste libre de ses mouvements quelques secondes, puis tu peux te relever dans un cocon. Le passif a un long cooldown.", "ability": "Regenerative Cocoon", "key": "", "kind": "default", "items": ["Quand le cocon est disponible, tu peux prendre un angle **un cran plus agressif** : une erreur ne te coûte pas le fight.", "L'ennemi **voit ton âme** et peut attendre sur ton corps. Éloigne-toi et relève-toi derrière un mur.", "Si le fight est perdu, **ne te relève pas** : tu mourrais deux fois et tu n'aurais plus le cocon au fight suivant."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Rester **en retrait à soigner** au lieu de prendre un angle.", "Dépenser un soin sur un allié **presque plein**.", "Lancer le lien **trop tôt**, ou ne jamais oser le lancer.", "Poser la résurrection **à découvert**.", "Arriver au fight **sans munitions**."], "diagram": ""}], "combos": [{"note": "Bien placé, il élimine une cible fragile.", "steps": [{"key": "Clic G", "label": "tir"}, {"key": "Clic D", "label": "tir chargé"}, {"key": "Clic G", "label": "tir"}], "title": "Combo rapproché"}], "counters": [{"hero": "venom", "note": "Il te saute dessus et te force à dépenser tes deux soins sur toi. Reste près de ton autre support quand il est en face."}, {"hero": "captain-america", "note": "Il te colle en permanence et tu n'as aucun déplacement pour le semer. Joue plus près de ton équipe."}, {"hero": "groot", "note": "Ses murs coupent tes angles et tes lignes de vue de soin, et ils sont longs à détruire."}, {"hero": "hela", "note": "Elle gagne le duel à distance : ne reste pas à découvert dans sa ligne de tir."}], "synergies": [{"hero": "luna-snow", "note": "Son ult longue couvre les fights où tu joues sur ton angle, et son team-up renforce ton lien."}, {"hero": "star-lord", "note": "Deux sources de dégâts sur des angles différents : la backline adverse ne peut pas se cacher des deux."}, {"hero": "loki", "note": "Ses runes protègent ton équipe pendant que tu ressuscites, et vos deux ults ne se chevauchent pas."}], "sources": [{"url": "https://www.youtube.com/watch?v=GqRusLyDjL0", "title": "Adam Warlock Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Cosmic Cyclone", "partners": ["storm"], "key": "", "text": "Soul Bond donne un boost de vitesse (100 % en saison 11). **Amélioré :** Ajoute un boost de dégâts (8 % en saison 11)."}, {"name": "Duality Dance", "partners": ["luna-snow"], "key": "", "text": "Soul Bond relie et soigne ; Luna récupère 35 % des soins en saison 11. **Amélioré :** Les critiques réduisent les cooldowns."}, {"name": "Flawless Design", "partners": ["ultron"], "key": "", "text": "Les Cosmic Cluster d'Adam soignent les alliés (18 par projectile en 10.5). **Amélioré :** Explosion de soin à l'impact (7 en 10.5)."}, {"name": "Star-Soul", "partners": ["star-lord"], "key": "", "text": "Téléportation sur une balise et réapparition en cocon. **Amélioré :** Les kills réduisent le cooldown de la balise."}, {"name": "Vitality Pact", "partners": ["mantis"], "key": "", "text": "L'état d'âme soigne et reforge (fleur à 12 + 3 %/s depuis la saison 10). **Amélioré :** Soul Bond avec soin sur la durée."}], "changes": [{"season": "Saison 11", "text": "Avatar Life Stream : soin initial 95 → 55, rebonds 2 → 4, total par lancer 285 → 275."}, {"season": "Saison 11", "text": "Team-up avec Storm : boost de vitesse 67 % → 100 % ; boost de dégâts du Soul Bond amélioré 12 % → 8 %."}, {"season": "Saison 10.5", "text": "Team-up avec Ultron : 18 de soin par Cosmic Cluster, 7 de soin d'explosion en version améliorée."}, {"season": "Saison 10", "text": "Tous les Strategists : l'ult se charge un peu moins vite (65 % du soin et 50 % des dégâts convertis en énergie, au lieu de 70 % et 55 %)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'adam-warlock' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Angela est un Vanguard volant dont le métier est le pick : elle attrape une cible mal placée et la dépose au milieu de son équipe. Une fois la cible morte, elle passe aux haches et tient le combat rapproché en distribuant de la vie bonus à ses alliés.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["Ton rôle est de **ramener une cible** à ton équipe, pas de la tuer seule.", "Ne lance la charge que si tu as **une ligne de retour** vers tes alliés.", "Après le pick, pose ta **zone de jugement** et bats-toi groupée : toute l'équipe gagne de la vie bonus."], "difficulty": 2, "tags": ["Pick", "Déplacement d'ennemis", "Brawl", "Vol"], "strengths": ["Déplace jusqu'à deux ennemis d'un coup", "Sort un support de sa propre ult", "Vie bonus de groupe en brawl"], "weaknesses": ["Peu de dégâts seule", "Tout contrôle arrête sa charge", "Très bruyante en vol"], "playbook": [{"when": "Un DPS ou un heal adverse s'avance ou s'isole", "then": "**Charge** dessus en visant ton équipe : il doit atterrir au milieu de tes alliés au moment où ton énergie s'épuise."}, {"when": "Un support adverse lance son ult de zone (Cloak & Dagger, Invisible Woman, Luna)", "then": "Charge-le et **sors-le de sa zone** : son équipe perd le soin, la tienne n'a plus qu'à le tuer."}, {"when": "Tu viens de réussir ton pick", "then": "Plonge avec la **zone de jugement** au milieu du fight et passe aux haches : chaque coup donne de la vie bonus à tes alliés présents."}, {"when": "Tu approches un support qui peut te geler ou t'endormir", "then": "Avance **bouclier levé** : il bloque le contrôle qui arrêterait ta charge."}, {"when": "Un ennemi se tient près d'un vide", "then": "Garde un **coup de lance chargé** : sa projection suffit à l'éjecter de la carte."}, {"when": "Ta zone est en cooldown et tu as ton ult", "then": "Plante la lance au sol puis bondis dessus : le rebond crée une **seconde zone de jugement**."}], "sections": [{"title": "Philosophie de jeu", "lead": "Angela fait peu de dégâts seule. Sa valeur vient de sa capacité à déplacer un ennemi au mauvais endroit pour lui, au bon moment pour ton équipe.", "ability": "", "key": "", "kind": "tips", "items": ["Prends un **léger angle**, repère la cible la plus avancée ou la plus isolée, et ramène-la dans la portée de tes alliés.", "Un pick ne vaut rien si personne ne tire dessus : **annonce ta charge** et joue à portée de ton équipe.", "Contre une compo de dive, elle défend bien : regroupez-vous dans sa zone pour encaisser grâce à la vie bonus."], "diagram": "", "scene": {"title": "Le pick d'Angela", "caption": "La charge n'est pas une attaque : c'est un transport. Elle se juge à l'endroit où la cible atterrit.", "steps": ["Tu prends un léger angle, jauge chargée.", "Tu attrapes la cible isolée.", "Tu la déposes au milieu de ton équipe, qui la tue."], "els": [{"t": "zone", "at": [92, 96], "r": 44, "team": "ally", "label": "Ton équipe"}, {"t": "pawn", "at": [150, 40], "team": "me", "ghost": true}, {"t": "path", "kind": "move", "team": "me", "pts": [[150, 40], [200, 26], [244, 50]], "n": 1}, {"t": "pawn", "at": [252, 58], "team": "enemy", "role": "heal", "ghost": true}, {"t": "path", "kind": "pull", "team": "me", "pts": [[248, 58], [190, 60], [118, 92]], "n": 2}, {"t": "pawn", "at": [110, 96], "team": "enemy", "role": "heal", "label": "Cible"}, {"t": "pawn", "at": [140, 86], "team": "me", "label": "Toi", "above": true}, {"t": "pawn", "at": [70, 70], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [72, 124], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [46, 96], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [96, 136], "team": "ally", "role": "heal"}, {"t": "path", "kind": "shot", "team": "ally", "pts": [[70, 70], [110, 96]], "n": 3}, {"t": "path", "kind": "shot", "team": "ally", "pts": [[72, 124], [110, 96]], "n": 3}, {"t": "pawn", "at": [226, 104], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [262, 132], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [292, 92], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [250, 22], "team": "enemy", "role": "dps"}]}}, {"title": "Vol et lance", "lead": "Angela vole en permanence. Se déplacer remplit la jauge située sous ton viseur : plus elle est pleine, plus ton coup de lance frappe fort.", "ability": "Seraphic Sword · Spear of Ichor", "key": "", "kind": "default", "items": ["Pendant les phases de poke, vole **contre un mur** : la jauge se remplit sans que tu t'exposes.", "Ton vol s'entend de loin. Ne pars en flank que si tu as un chemin de retour : tu ne surprendras personne.", "Enchaînement de base : **coup de mêlée, coup de lance**, puis bouclier levé pour regagner de la jauge.", "La lance **transperce** : deux ennemis alignés prennent les mêmes dégâts.", "Le coup de lance chargé **projette** sa cible. Près d'un vide, c'est une élimination."], "diagram": ""}, {"title": "Charge de l'assassin", "lead": "Tu fonces et embarques jusqu'à deux ennemis avec toi. Porter une cible consomme vite ton énergie : la charge est courte, sa direction compte plus que sa durée.", "ability": "Assassin's Charge", "key": "Maj", "kind": "default", "items": ["Avant de charger, vérifie ta **ligne de retour** : la cible doit être lâchée chez tes alliés, pas à mi-chemin.", "N'ouvre pas le fight avec. Place-toi, dépense ta jauge en coups de lance, **puis** attrape.", "Porter une cible **recharge ta jauge de dégâts** : lance, charge, lance.", "Un gel, un étourdissement ou une projection **t'arrête net**. Attends que le contrôle adverse soit dépensé, ou lève le bouclier en approche.", "Le réglage **maintenir pour charger** donne plus de contrôle sur la distance : essaie-le dans les paramètres."], "diagram": ""}, {"title": "Zone de jugement et haches", "lead": "Tu plonges au sol, poses une zone et passes aux haches. Dans la zone, tu vas plus vite et chaque coup de hache donne de la vie bonus à toi et à tes alliés.", "ability": "Divine Judgment · Axes of Ichor", "key": "E", "kind": "default", "items": ["Les haches touchent **plusieurs ennemis** à la fois : c'est ton mode de combat sur un point contesté.", "Depuis la saison 11, vitesse et vie bonus **durent 6 secondes après la sortie de la zone** : tu peux poursuivre une cible aux haches sans rester dans le cercle. Reprendre ton vol annule ce bonus.", "Le cooldown de la zone ne démarre que lorsque tu **reprends ta forme de vol** : ne reste pas aux haches sans raison une fois le bonus terminé.", "Exception : si tu frappes trois ou quatre ennemis à la fois, continue, tu charges ton ult très vite."], "diagram": ""}, {"title": "Bouclier", "lead": "Un petit bouclier frontal qui ne te ralentit pas. Les dégâts qu'il absorbe remplissent ta jauge de dégâts.", "ability": "", "key": "Clic D", "kind": "default", "items": ["Laisse ta barre de vie absorber les petits dégâts : **garde le bouclier pour ce qui compte**.", "Il bloque les **contrôles** et les ults à projectile (Hela, Magneto, Doctor Strange).", "Lève-le en approchant un support : tu ne te fais pas geler ou endormir en route."], "diagram": ""}, {"title": "Ultime", "lead": "Tu plantes ta lance : les ennemis proches y sont attachés, fortement ralentis et privés de leurs déplacements. Réappuie pour bondir sur la lance et créer une zone de jugement.", "ability": "Heaven's Retribution", "key": "Q", "kind": "default", "items": ["Vise **le sol, un mur ou un plafond**. Lancée sur un ennemi en l'air, la lance le traverse et se perd.", "Les ennemis attachés ne peuvent plus s'échapper : c'est le moment des **ults de zone** de ton équipe (Moon Knight, Phoenix, Human Torch).", "Combo le plus rentable : **sortir un support de son ult** avec la charge, puis l'attacher pour que ton équipe le finisse.", "Le rebond donne une **zone gratuite** : utilise ta vraie zone tôt, garde l'ult pour la seconde vague du fight.", "Elle est longue à charger au vu de tes dégâts : frapper plusieurs cibles aux haches est ta meilleure source d'énergie."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Charger une cible **sans ligne de retour**.", "Utiliser la charge **pour ouvrir** le fight.", "Partir seule en flank alors que **tout le monde t'entend**.", "Lever le bouclier sur des **dégâts négligeables**.", "Lancer l'ult sur un **ennemi en l'air**."], "diagram": ""}], "combos": [{"note": "Lever le bouclier après le combo **regagne de la jauge**.", "steps": [{"key": "Mêlée", "label": ""}, {"key": "", "label": "Coup de lance"}, {"key": "Clic D", "label": "bouclier"}], "title": "Combo de base"}, {"note": "Porter une cible recharge vite ta jauge de dégâts.", "steps": [{"key": "", "label": "Coup de lance"}, {"key": "Maj", "label": "charge"}, {"key": "", "label": "Coup de lance"}], "title": "Recharger la jauge"}], "counters": [{"hero": "magneto", "note": "Sa bulle protège la cible que tu portes et annule ton pick. Attends qu'elle soit dépensée."}, {"hero": "hulk", "note": "Sa bulle de zone protège lui et ses alliés proches : ta cible survit à l'atterrissage."}, {"hero": "the-punisher", "note": "Ses dégâts continus font fondre ta vie pendant que tu voles vers lui."}, {"hero": "invisible-woman", "note": "Sa poussée te renvoie ou libère la cible que tu ramènes."}, {"hero": "luna-snow", "note": "Son gel arrête ta charge. Approche bouclier levé."}], "synergies": [{"hero": "emma-frost", "note": "Elle tient la ligne de front pendant que tu joues ton angle."}, {"hero": "magneto", "note": "Un tank qui garde le point à ta place, et une bulle pour couvrir ton retour."}, {"hero": "phoenix", "note": "Son burst tue la cible que tu déposes avant qu'elle soit soignée."}, {"hero": "jeff-the-land-shark", "note": "Sa bulle de vitesse te fait porter une cible beaucoup plus loin."}], "sources": [{"url": "https://www.youtube.com/watch?v=HRkY4e6CFow", "title": "Angela Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Asgardians of the Galaxy", "partners": ["star-lord"], "key": "", "text": "Révèle une zone et cloue les ennemis au sol avec un impact. **Amélioré :** Ajoute de la vie bonus."}, {"name": "Divine Armory", "partners": ["thor"], "key": "", "text": "La lance de foudre rend de la Thorforce. **Amélioré :** Vie bonus sur le saut."}, {"name": "Odin's Unacknowledged", "partners": ["loki"], "key": "", "text": "Une illusion d'estoc projette les ennemis (dégâts max encaissés : 150 depuis la saison 10). **Amélioré :** Deux charges."}], "changes": [{"season": "Saison 11", "text": "Axes of Ichors : 30 → 35 de dégâts sur les trois premiers coups ; vie bonus par coup (deux haches) 50 → 55."}, {"season": "Saison 11", "text": "Divine Judgement : dégâts continus 12,5 → 15/s ; les bonus de vitesse et de vie bonus durent 6 s après la sortie de la zone (Wingblade Ascent les retire)."}, {"season": "Saison 10", "text": "Team-up avec Loki : dégâts max encaissés par l'illusion 250 → 150."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'angela' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Black Cat est une Duelist de dive bâtie autour d'une ressource : la Fortune, son or. Elle en gagne en touchant ses capacités et le dépense en gadgets et en poursuite fantôme. Bien gérée, cette économie lui donne les engages les plus difficiles à contrer du jeu ; mal gérée, elle ne fait rien du fight.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["**Pas d'or, pas d'engage** : touche ton grappin sur un tank avant chaque fight.", "Enchaînement de base : **grappin, dash aux pieds, griffes, fouet, poursuite fantôme**.", "La poursuite fantôme **ignore les contrôles** : garde-la pour esquiver un gel ou finir une cible."], "difficulty": 3, "tags": ["Dive", "Économie d'or", "Duels", "Utilitaire"], "strengths": ["Gadgets pour chaque situation", "Vie bonus à chaque touche en duel", "Poursuite fantôme insensible aux contrôles"], "weaknesses": ["Inutile sans Fortune", "Perd de l'or en mourant", "Dashes longs à recharger"], "playbook": [{"when": "Le fight commence et tu manques d'or", "then": "**Grappin sur un tank** : il rapporte autant que sur une cible fragile, et tu ne peux pas le rater."}, {"when": "Tu engages un support mobile (Cloak & Dagger, Gambit)", "then": "Lance le **poisson** en entrant : la zone bloque ses déplacements et il ne peut plus fuir."}, {"when": "Un contrôle part sur toi (gel de Luna, sommeil de Mantis, flash de Cloak)", "then": "**Poursuite fantôme** : pendant le bond tu ignores les contrôles et tu encaisses moitié moins."}, {"when": "Tu vas mourir et il te reste de l'or", "then": "**Achète un gadget** avant de tomber : tu perds une partie de ton or à la mort, mais le gadget reste."}, {"when": "Ton équipe bute sur un passage étroit", "then": "Pose l'**anneau-portail** à travers le mur : toute ton équipe peut l'emprunter."}, {"when": "Tu as utilisé ton premier dash pour entrer", "then": "Le second sert **à sortir**. Si tu le dépenses pour poursuivre, assure-toi que le kill est certain."}], "sections": [{"title": "Philosophie de jeu", "lead": "Black Cat ne fait pas ses dégâts sur la durée. Elle prépare son or, force les cooldowns défensifs, puis frappe en rafale sur une cible qui n'a plus de réponse.", "ability": "", "key": "", "kind": "tips", "items": ["Entre deux dives, **reconstitue ton or**. Un engage riche est dangereux, un engage pauvre est un suicide.", "Garde de quoi payer **un fouet et une poursuite** avant d'entrer pour de bon.", "Mourir te coûte une partie de ta Fortune : quand la mort est certaine, dépense.", "En duel isolé, la **vie bonus** de tes coups te rend très difficile à tuer : cherche les 1 contre 1."], "diagram": "flank"}, {"title": "Gagner de l'or", "lead": "Chaque capacité qui touche rapporte de la Fortune. Le grappin en est la source principale : le rater, c'est passer le fight à regarder.", "ability": "Sticky Paws · Turn of Fortune", "key": "E", "kind": "default", "items": ["Le grappin rapporte **la même somme quelle que soit la cible**. En manque d'or, vise un tank : sa hitbox ne se rate pas et le cooldown est court.", "Il donne aussi un peu de **vie bonus** : en plein fight, un grappin sur une cible épaisse te laisse rester plus longtemps.", "Depuis la saison 11, tes **griffes rapportent davantage** par lancer (75 de Fortune au maximum contre 50) : un duel prolongé se finance tout seul.", "Tes coups **marquent** les ennemis : tu les vois à travers les murs, et leurs tirs à la tête sur toi ont une chance d'échouer."], "diagram": ""}, {"title": "Combat rapproché", "lead": "Griffes et fouet frappent en zone devant toi et donnent de la vie bonus à chaque touche. La poursuite fantôme est ton bond d'exécution.", "ability": "Feline Fury · Fortune's Favor", "key": "Clic G · Clic D", "kind": "default", "items": ["Alterne **griffes et fouet** : c'est ton meilleur rendement en dégâts, en or et en vie bonus.", "Le fouet frappe **en cône** : place-toi face à la cible. Sur un groupe, chaque ennemi touché rapporte de l'or.", "La **poursuite fantôme** te rend insensible aux contrôles et réduit de moitié les dégâts subis pendant le bond. Elle n'est plus invincible depuis la saison 10.", "Elle sert à **finir une cible qui fuit** ou à **esquiver** : ult de Doctor Strange, de Winter Soldier, gel de Luna. En duel simple, le fouet suffit.", "Pour esquiver une ult, vise **un espace dégagé** : l'animation dure plus longtemps."], "diagram": ""}, {"title": "Mobilité", "lead": "Deux dashes au cooldown long, un double saut et l'escalade des murs. Ta survie dépend de l'ordre dans lequel tu les dépenses.", "ability": "Cat's Cradle", "key": "Maj", "kind": "default", "items": ["Le dash **traverse** les cibles : vise leurs pieds pour t'arrêter sur elles.", "**Un dash pour entrer, un pour sortir.** Ils ne servent jamais à traverser la carte.", "Chaque capacité utilisée **recharge ton double saut** : saut, capacité, saut te garde en l'air au-dessus du fight.", "Accroche-toi au-dessus d'un passage et **tombe sur les supports** quand ils le franchissent."], "diagram": ""}, {"title": "Les gadgets", "lead": "Six objets à usage unique, achetés avec ta Fortune. Le bon gadget au bon moment décide du fight plus sûrement que tes dégâts.", "ability": "Gilded Deal", "key": "F", "kind": "default", "items": ["**Poisson** : zone qui ralentit, bloque les déplacements et cloue les volants au sol. C'est ton ouverture d'engage, et un très bon outil pour protéger tes supports.", "**Crâne enflammé** (peu cher) : révèle les ennemis à travers les murs pour toute ton équipe. Pose-le en hauteur, dans un coin.", "**Invisibilité** : pour entrer sans dépenser de dash et forcer les cooldowns adverses.", "**Anneau-portail** : un passage à travers un mur ou un plafond, pour toi et ton équipe. Décisif sur les cartes à goulots.", "**Cristal anti-contrôle** : à acheter d'avance contre Luna ou Mantis, pour casser un gel ou un sommeil.", "**Rune de jeu** : aléatoire, donc à éviter. Seule exception : juste avant une mort certaine."], "diagram": "", "scene": {"title": "Ouvrir avec le poisson", "caption": "Le poisson retire à la cible sa seule réponse : la fuite. L'engage qui suit n'a plus qu'à faire ses dégâts.", "steps": ["Grappin sur le tank : tu fais le plein d'or.", "Tu lances le poisson sur le support, puis tu dashes à ses pieds.", "Griffes, fouet, poursuite fantôme : il ne peut ni fuir ni être rejoint."], "els": [{"t": "pawn", "at": [120, 44], "team": "me", "ghost": true}, {"t": "path", "kind": "shot", "team": "me", "pts": [[120, 44], [206, 96]], "n": 1}, {"t": "zone", "at": [270, 64], "r": 26, "team": "me", "label": "Poisson"}, {"t": "path", "kind": "move", "team": "me", "pts": [[120, 44], [190, 18], [252, 58]], "n": 2}, {"t": "pawn", "at": [274, 66], "team": "enemy", "role": "heal", "label": "Cible"}, {"t": "pawn", "at": [250, 60], "team": "me", "label": "Toi", "above": true}, {"t": "cone", "at": [250, 60], "to": [284, 70], "spread": 70, "team": "me", "n": 3}, {"t": "pawn", "at": [206, 96], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [238, 130], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [292, 122], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [222, 28], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [96, 96], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [70, 132], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [46, 80], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [44, 120], "team": "ally", "role": "heal"}]}}, {"title": "Ultime", "lead": "Chaque ennemi reçoit une carte. Tu peux bondir derrière n'importe lequel d'entre eux et l'exécuter ; chaque élimination relance le bond.", "ability": "Calling Card", "key": "Q", "kind": "default", "items": ["Trois appuis : **activer, bondir, achever**. Le troisième est celui que les débutants oublient.", "La carte devient **rouge** quand la cible mourra au prochain appui : commence par celles-là.", "N'ouvre pas sur un héros très mobile (Scarlet Witch, White Fox) tant que son évasion est disponible.", "L'ult crée surtout de la panique et de l'espace : lance-la quand **ton équipe peut suivre**.", "Elle te fournit elle-même l'or nécessaire : inutile d'être riche pour la lancer."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Engager **sans or**.", "Rater le grappin d'ouverture et **entrer quand même**.", "Dépenser les deux dashes **pour se déplacer**.", "Lancer l'ult **sans équipe** derrière.", "Compter sur la **rune de jeu**."], "diagram": ""}], "combos": [], "counters": [{"hero": "the-thing", "note": "Il te verrouille au corps à corps et tu ne peux pas le déplacer. Ne dive pas dans sa portée."}, {"hero": "peni-parker", "note": "Son nid et ses mines punissent chaque entrée. Contourne-les avec l'anneau-portail."}, {"hero": "phoenix", "note": "Ses étourdissements coupent ton combo et elle se soigne en te frappant."}, {"hero": "invisible-woman", "note": "Sa poussée te sort de ta cible et son bouclier la protège : très difficile à diver."}], "synergies": [{"hero": "venom", "note": "Il entre en premier et attire les regards : tu arrives sur une backline déjà occupée."}, {"hero": "captain-america", "note": "Un second tank de dive qui reste sur la backline pendant que tu ressors."}, {"hero": "daredevil", "note": "Deux divers sur la même cible : aucun support ne survit aux deux."}, {"hero": "black-panther", "note": "Votre team-up te rend de la Fortune sur chaque ennemi touché, bien plus depuis la saison 11."}], "sources": [{"url": "https://www.youtube.com/watch?v=pL7mAWytrB0", "title": "Black Cat Guide", "author": "Paz (padswagger)"}, {"title": "Ultimate Black Cat Guide (Beginner/Advanced)", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=OZlJLd2sULs"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Binding Ties", "partners": ["spider-man"], "key": "", "text": "Un grappin de toile vole de la Fortune et marque la cible, qui prend plus de dégâts."}, {"name": "Feline Alliance", "partners": ["black-panther"], "key": "", "text": "Explosion de vibranium au-delà d'un seuil ; chaque ennemi touché rend 100 de Fortune (200 max) et la vie bonus passe à 50 en saison 11. **Amélioré :** Plus de seuil."}, {"name": "Lucky Loan", "partners": ["white-fox"], "key": "", "text": "Un orbe de vie alimente l'aura à neuf queues. **Amélioré :** Les queues spirituelles ne coûtent plus rien."}], "changes": [{"season": "Saison 11", "text": "Feline Fury : Fortune maximale par lancer 50 → 75."}, {"season": "Saison 11", "text": "Team-up avec Black Panther (Feline Alliance) : vie bonus 25 → 50, Fortune par ennemi touché 50 → 100, plafond 100 → 200."}, {"season": "Saison 10", "text": "Phantom Pursuit : plus d'invincibilité, mais 50 % de réduction des dégâts et Unstoppable ; coût en Fortune 300 → 250."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'black-cat' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Black Panther est un assassin qui vit de la surprise. Il approche sans être vu, marque une cible fragile, puis enchaîne des dashes qui se rechargent chaque fois qu'ils traversent une cible marquée. Repéré ou blessé avant d'entrer, il perd l'essentiel de sa valeur.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["Entre **plein de vie et sans être vu** : la surprise fait la moitié du travail.", "Un dash ne se recharge qu'en traversant une **cible marquée** : marque d'abord, dash ensuite.", "Vise les **héros fragiles**, et repars dès que tu as ton kill."], "difficulty": 3, "tags": ["Assassin", "Dive", "Burst", "Patience"], "strengths": ["Burst capable de tuer un support en une seconde", "Dashes illimités sur cibles marquées", "Voit ses cibles marquées à travers les murs"], "weaknesses": ["Très dépendant de la surprise", "Fragile si son combo est interrompu", "Faible contre les tanks et les bulles"], "playbook": [{"when": "Un support s'isole de son équipe", "then": "**Lance, dash, lance, dash** : la lance marque, le dash traverse et se recharge. Repars avec le dernier dash."}, {"when": "La cible reçoit une bulle ou des runes pendant ton combo", "then": "**Arrête et ressors.** Tu as forcé un gros cooldown défensif : l'échange est déjà gagné."}, {"when": "On te regarde avant que tu sois entré", "then": "Reste derrière ton mur. Ta seule présence sur le flanc met la pression ; entre quand ils regardent ailleurs."}, {"when": "Tu dois fuir", "then": "Utilise le **coup de pied**, pas le dash : le dash fait tes dégâts et reviendra moins vite sans cible marquée."}, {"when": "Tu n'as plus de dash disponible", "then": "**N'engage pas.** Sans dash, tu n'as ni dégâts ni sortie."}, {"when": "Ton combo laisse la cible à un fil", "then": "**Ult** : elle marque tout ce qu'elle touche et recharge ton dash pour finir."}], "sections": [{"title": "Philosophie de jeu", "lead": "Panther ne fait pas de demi-mesure : il s'engage entièrement ou il attend. Tout se décide dans les secondes qui précèdent l'entrée.", "ability": "", "key": "", "kind": "tips", "items": ["Avant l'engage, **ne prends aucun dégât et ne te montre pas**. Un Panther entamé ou repéré est un Panther mort.", "Sors par un flanc, attends qu'un support s'isole, frappe, puis **repars** : rester après le kill ne rapporte rien.", "Tu n'es **pas obligé de finir un combo**. Si la cible reçoit un soin massif ou si tu vas mourir, sors."], "diagram": "reset"}, {"title": "Dash et marques", "lead": "Le dash est ta principale source de dégâts. S'il traverse une cible marquée, il se recharge immédiatement et te donne de la vie bonus.", "ability": "Spear Rend", "key": "Maj", "kind": "default", "items": ["**N'ouvre jamais au dash** : sans marque, il ne se recharge pas et tu restes sans sortie.", "Le rythme : **une capacité qui marque, un dash**, et on recommence jusqu'au kill ou jusqu'à l'abri.", "Une marque tient quelques secondes. Si l'on te regarde, **patiente derrière un mur** : tu peux encore dasher sur la cible marquée.", "Tu vois les cibles marquées **à travers les murs** : sers-t'en pour choisir celle qui s'éloigne de son équipe.", "Ton passif augmente tes dégâts à bas PV. C'est un bonus de fin de combo, jamais une raison d'entrer blessé."], "diagram": "", "scene": {"title": "Marquer, puis traverser", "caption": "Chaque dash qui traverse une cible marquée revient aussitôt. Le combo ne s'arrête que si tu dashes dans le vide.", "steps": ["La lance marque la cible depuis ta cachette.", "Premier dash à travers elle : il se recharge.", "Seconde lance ou coup de pied, dash à nouveau, et tu ressors."], "els": [{"t": "cover", "at": [108, 26], "size": [14, 44], "label": "Mur"}, {"t": "pawn", "at": [140, 48], "team": "me", "ghost": true}, {"t": "path", "kind": "shot", "team": "me", "pts": [[140, 48], [204, 40], [232, 104]], "n": 1}, {"t": "pawn", "at": [232, 104], "team": "enemy", "role": "heal", "label": "Marquée"}, {"t": "path", "kind": "move", "team": "me", "pts": [[140, 48], [301, 146]], "n": 2}, {"t": "pawn", "at": [301, 146], "team": "me", "ghost": true}, {"t": "note", "at": [268, 164], "text": "dash rechargé", "team": "me"}, {"t": "path", "kind": "move", "team": "me", "pts": [[301, 146], [300, 40], [214, 34]], "n": 3}, {"t": "pawn", "at": [214, 34], "team": "me", "above": true}, {"t": "pawn", "at": [184, 146], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [308, 30], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [170, 100], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [84, 104], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [60, 64], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [40, 96], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [50, 140], "team": "ally", "role": "heal"}]}}, {"title": "Lances et coup de pied", "lead": "Les lances marquent à distance, le coup de pied marque en te déplaçant. Ce sont les deux outils qui préparent chaque dash.", "ability": "Spear Toss · Spinning Kick", "key": "", "kind": "default", "items": ["Les lances sont ta seule attaque à distance : lance-les **pour engager**, pas pour arroser.", "Lance en **tombant d'un mur**, puis dash dès que tu es à portée : l'approche et la marque se font en même temps.", "Le coup de pied est orientable mais pas instantané, et il te laisse sans échappatoire s'il rate.", "Toute **projection** pendant le coup de pied l'annule : attention à Invisible Woman et Magneto."], "diagram": ""}, {"title": "Déplacements discrets", "lead": "Tes pas s'entendent. L'escalade des murs et le double saut te permettent d'arriver sans bruit et par un angle inattendu.", "ability": "Subtle Step", "key": "", "kind": "default", "items": ["Approche **par les murs et les hauteurs** : c'est silencieux et personne ne regarde en l'air.", "Tes capacités font tes dégâts : ne les dépense pas pour le trajet."], "diagram": ""}, {"title": "Combos", "lead": "Ces enchaînements doivent sortir sans réfléchir. Glisse un coup de griffe entre deux capacités dès que tu en as le temps.", "ability": "", "key": "", "kind": "tips", "items": ["**De base** : lance, lance, dash, dash. Le plus rapide, mais parfois insuffisant sur un support soigné.", "**Plus de dégâts** : lance, dash, lance, dash, dash. À utiliser quand les soins adverses sont occupés ailleurs.", "**Avec coup de pied** : lance, dash, coup de pied, dash.", "**Tout dépenser** : lance, dash, coup de pied, dash, lance, double dash. Réservé au dernier ennemi debout."], "diagram": ""}, {"title": "Ultime", "lead": "Une panthère géante traverse la zone, frappe et marque tous les ennemis touchés, et recharge ton dash.", "ability": "Bast's Descent", "key": "Q", "kind": "default", "items": ["Elle ne sert pas à ouvrir : garde-la pour **achever** ou pour relancer un combo interrompu.", "Tu es **vulnérable pendant l'animation** : lance-la avec assez de vie.", "Quand les supports adverses n'ont pas leur ult, lance-la tôt : elle est longue à revenir.", "Avec l'ult prête, tu peux **insister** sur une cible même après une bulle : tu as de quoi relancer."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Engager **sans dash** disponible.", "Se faire **voir ou blesser** avant d'entrer.", "Diver sur **un tank**.", "**Rester** dans la backline après le kill.", "Ouvrir **au dash** sans avoir marqué."], "diagram": ""}], "combos": [{"note": "Rapide, mais juste contre un support qui reçoit des soins.", "steps": [{"key": "", "label": "Lance"}, {"key": "", "label": "Lance"}, {"key": "Maj", "label": "dash"}, {"key": "Maj", "label": "dash"}], "title": "De base"}, {"note": "Idéal en prolongation, quand les soins manquent.", "steps": [{"key": "", "label": "Lance"}, {"key": "Maj", "label": "dash"}, {"key": "", "label": "Lance"}, {"key": "Maj", "label": "dash"}, {"key": "Maj", "label": "dash"}], "title": "Plus de dégâts"}, {"note": "", "steps": [{"key": "", "label": "Lance"}, {"key": "Maj", "label": "dash"}, {"key": "", "label": "Coup de pied"}, {"key": "Maj", "label": "dash"}], "title": "Variante courante"}], "counters": [{"hero": "magneto", "note": "Sa bulle sur ta cible annule le kill et empêche ton dash de se recharger."}, {"hero": "the-thing", "note": "Son impact au sol t'arrête en plein combo. Attends qu'il l'ait utilisé."}, {"hero": "peni-parker", "note": "Toiles et mines autour des supports : chaque entrée te coûte la moitié de ta vie."}, {"hero": "invisible-woman", "note": "Sa poussée t'éjecte au milieu du combo et son bouclier sauve ta cible."}, {"hero": "ultron", "note": "Il vole hors de portée et son drone soigne la cible que tu attaques."}, {"hero": "namor", "note": "Ses tourelles te repèrent et t'entament avant ton entrée."}], "synergies": [{"hero": "venom", "note": "Il plonge en premier et entame les supports : tu n'as plus qu'à finir."}, {"hero": "captain-america", "note": "Il occupe la backline et attire les contrôles avant ton arrivée."}, {"hero": "star-lord", "note": "Un DPS qui tire sur ta cible pendant ton combo garantit le kill."}, {"hero": "luna-snow", "note": "Ses soins à longue portée te suivent pendant que tu ressors."}], "sources": [{"url": "https://www.youtube.com/watch?v=0AkMzA-n-EA", "title": "Black Panther Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Damisa-Yao", "partners": ["storm"], "key": "", "text": "Explosion élémentaire de l'armure qui ralentit et marque. **Amélioré :** Projette les ennemis vers Black Panther."}, {"name": "Dimensional Shortcut", "partners": ["magik"], "key": "", "text": "Un disque de Limbo ramène Black Panther à sa position précédente. **Amélioré :** Retour déclenchable à la main."}, {"name": "Feline Alliance", "partners": ["black-cat"], "key": "", "text": "Explosion de vibranium au-delà d'un seuil ; chaque ennemi touché rend 100 de Fortune (200 max) et la vie bonus passe à 50 en saison 11. **Amélioré :** Plus de seuil."}, {"name": "Vibranium Mech", "partners": ["peni-parker"], "key": "", "text": "Bouclier de vibranium frontal et vitesse d'attaque (cooldown 15 s depuis la saison 10). **Amélioré :** Bouclier plus grand."}], "changes": [{"season": "Saison 11", "text": "Team-up avec Black Cat (Feline Alliance) : vie bonus 25 → 50 ; elle récupère deux fois plus de Fortune."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'black-panther' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Black Widow est une sniper mobile qui interdit des zones entières à l'adversaire. Avec un bonus de dégâts allié (Mantis, Storm, Cloak & Dagger), un tir à la tête élimine la plupart des héros fragiles, y compris un support en pleine ult.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["Choisis un **angle sûr** : un tir pris sans pression se réussit bien plus souvent.", "**Sors de la lunette** entre deux tirs pour surveiller les divers.", "Ton coup de pied **étourdit** : garde-le pour couper une ult ou te défendre."], "difficulty": 2, "tags": ["Sniper", "Contrôle de zone", "Mobilité", "Pick"], "strengths": ["Portée illimitée sous lunette", "Change d'angle en quelques secondes", "Étourdissement qui coupe les ults"], "weaknesses": ["Vulnérable aux divers en visée", "Un seul vrai cooldown défensif", "Dépend d'un bonus de dégâts pour tuer en un tir"], "playbook": [{"when": "Un diver approche de tes supports", "then": "**Coup de pied** : le second impact l'étourdit. Enchaîne tir au corps, coup de pied, tir au corps pour le tuer."}, {"when": "Un support adverse lance son ult à mi-vie", "then": "**Tir à la tête**, surtout si tu as un bonus de dégâts : il peut mourir dans sa propre ult."}, {"when": "Ton angle ne donne plus rien, ou on vient te chercher", "then": "**Course** et change de position : ta mobilité est ce qui te distingue des autres snipers."}, {"when": "Un ennemi suit une trajectoire évidente (retour du spawn, retombée d'un saut)", "then": "Pose ton viseur sur l'arrivée et **attends-le** au lieu de le poursuivre."}, {"when": "Ton ult est chargée", "then": "**Lance-la** : sur un support en ult, un diver ou un groupe. Elle revient très vite, la garder est une perte."}], "sections": [{"title": "Philosophie de jeu", "lead": "Widow n'a pas besoin de tuer pour être utile : une ligne de tir tenue par une sniper est une zone où l'adversaire n'ose pas se placer, et cela ouvre le jeu pour ton second DPS.", "ability": "", "key": "", "kind": "tips", "items": ["Adapte ton angle à ta compo : **en brawl**, tire sur ce que ton équipe peut finir ; **en dive**, tiens-toi plus loin et entame les supports.", "Tu n'as **pas à tout toucher**. Tant que l'ennemi évite ta ligne, tu remplis ton rôle.", "Avec un **bonus de dégâts**, ton tir à la tête devient mortel sur la plupart des cibles : demande-le."], "diagram": "highground"}, {"title": "Le fusil", "lead": "Le fusil fait toujours plus de dégâts que les matraques. Le savoir-faire consiste à choisir entre visée à la lunette et tir à la hanche.", "ability": "Red Room Rifle · Straight Shooter", "key": "Clic G · Clic D", "kind": "default", "items": ["**De près, tire à la hanche. De loin, vise** : la lunette supprime la perte de dégâts à distance.", "Ne reste pas en lunette plusieurs tirs de suite : tu ne vois rien autour de toi et tu te déplaces lentement.", "Pour viser : **un mouvement rapide vers la cible, puis un ajustement** vers la tête. C'est plus régulier qu'un seul flick.", "Les matraques ne valent pas le fusil, même au contact."], "diagram": ""}, {"title": "Course", "lead": "Pendant quelques secondes, tu cours plus vite et tu sautes plus haut. C'est ton outil pour changer d'angle.", "ability": "Fleet Foot", "key": "Maj", "kind": "default", "items": ["Sers-t'en **entre deux fights** pour prendre une nouvelle position, ou dès qu'un diver te prend pour cible.", "Les tirs en plein saut vident ton énergie pour un résultat incertain : réserve-les aux situations désespérées.", "Un saut au bon moment **esquive les impacts au sol** de Venom ou de Captain America."], "diagram": ""}, {"title": "Coup de pied", "lead": "Un premier coup circulaire autour de toi, puis un second à distance qui étourdit. C'est ton seul vrai cooldown : chaque utilisation doit compter.", "ability": "Edge Dancer", "key": "E", "kind": "default", "items": ["Le second coup reste disponible **quelques secondes** après le premier : tu peux le charger sur un tank et le garder pour la vraie cible.", "Il **interrompt des ults** canalisées (Doctor Strange, Scarlet Witch) et sort Loki de sa copie.", "Sur une cible fragile, **tir au corps, coup de pied, tir au corps** tue sans avoir besoin de la tête.", "C'est l'un des meilleurs outils du jeu contre Black Panther : garde-le quand il est en face.", "Étourdir le tank qui fonce sur toi te donne le temps de reculer."], "diagram": "", "scene": {"title": "Protéger sa backline", "caption": "Le coup de pied transforme une sniper en garde du corps : le diver étourdi meurt avant d'avoir touché ton support.", "steps": ["Le diver saute sur ton support.", "Premier coup de pied, puis le second l'étourdit.", "Tir au corps pendant l'étourdissement : il est mort."], "els": [{"t": "pawn", "at": [214, 22], "team": "enemy", "role": "dps", "ghost": true}, {"t": "path", "kind": "move", "team": "enemy", "pts": [[214, 22], [150, 30], [92, 96]], "n": 1}, {"t": "pawn", "at": [86, 104], "team": "enemy", "hero": "black-panther"}, {"t": "pawn", "at": [40, 112], "team": "ally", "role": "heal", "label": "Visé"}, {"t": "pawn", "at": [152, 134], "team": "me"}, {"t": "path", "kind": "push", "team": "me", "pts": [[152, 134], [86, 104]], "n": 2}, {"t": "note", "at": [100, 74], "text": "3", "team": "me"}, {"t": "note", "at": [146, 68], "text": "étourdi : tu tires", "team": "me"}, {"t": "pawn", "at": [196, 104], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [196, 50], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [36, 60], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [240, 96], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [268, 132], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [294, 78], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [294, 124], "team": "enemy", "role": "heal"}]}}, {"title": "Ultime", "lead": "Un tir explosif qui ralentit les ennemis touchés et les rend plus vulnérables. Maintenir le tir augmente les dégâts. Elle se recharge très vite.", "ability": "Electro-Plasma Explosion", "key": "Q", "kind": "default", "items": ["Cibles idéales : un **support en ult** déjà entamé, un **diver** sur ta backline, ou un **groupe** serré.", "Elle **force les ults de support** adverses ; la vulnérabilité permet ensuite de les tuer dedans.", "Depuis la saison 11, l'explosion fait un peu plus de dégâts (55 à 75).", "La pire erreur est de **la garder** pour le moment parfait."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Rester **en lunette** et se faire diver.", "Tirer de loin **sans lunette**.", "Dépenser le coup de pied **avant** l'arrivée du diver.", "Enchaîner les **tirs sautés**.", "**Garder son ult**."], "diagram": ""}], "combos": [{"note": "Sur une cible fragile, **pas besoin de headshot**.", "steps": [{"key": "Clic G", "label": "tir au corps"}, {"key": "E", "label": "coup de pied"}, {"key": "Clic G", "label": "tir au corps"}], "title": "Mise à mort sûre"}], "counters": [{"hero": "psylocke", "note": "Elle t'atteint sans entrer dans la portée de ton coup de pied."}, {"hero": "captain-america", "note": "Il te rejoint en un bond et tu n'as pas les dégâts pour le tuer."}, {"hero": "venom", "note": "Il te force à quitter ton angle, surtout accompagné d'un second diver."}, {"hero": "magneto", "note": "Son bouclier coupe ta ligne de tir sur le point."}, {"hero": "luna-snow", "note": "Son ult la soigne trop vite pour ton tir : cherche une autre cible."}], "synergies": [{"hero": "mantis", "note": "Son bonus de dégâts rend ton tir à la tête mortel."}, {"hero": "storm", "note": "Son aura de dégâts a le même effet, à condition de rester dans sa zone."}, {"hero": "cloak-and-dagger", "note": "Son voile rend les ennemis vulnérables à ton prochain tir."}, {"hero": "hawkeye", "note": "Votre team-up te donne de la vie bonus en état de concentration depuis la saison 11."}], "sources": [{"url": "https://www.youtube.com/watch?v=LMej9-pVFek", "title": "Black Widow Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Allied Agents", "partners": ["hawkeye"], "key": "", "text": "Les cumuls de concentration donnent des balles renforcées (2 cumuls suffisent en saison 11) ; les critiques gardent la concentration active, et la moitié des dégâts en concentration devient de la vie bonus pour Black Widow (75 max)."}, {"name": "Burning Bullets", "partners": ["phoenix"], "key": "", "text": "Le Plasma Cannon devient un tir instantané (hitscan), 75 de dégâts en saison 11. **Amélioré :** Une charge en plus."}, {"name": "Devilish Affair", "partners": ["daredevil"], "key": "", "text": "Devil's Chain frappe en croix et ralentit. **Amélioré :** Plus large, et rend de la Fureur."}], "changes": [{"season": "Saison 11", "text": "Electro-Plasma Blast : dégâts 50–70 → 55–75 (75 avec le team-up de Phoenix, au lieu de 70)."}, {"season": "Saison 11", "text": "Team-up avec Hawkeye (Allied Agents) : 50 % des dégâts infligés en état de concentration deviennent de la vie bonus (75 max) ; 2 cumuls suffisent pour entrer en concentration, au lieu de 3."}, {"season": "Saison 10", "text": "Red Room Rifle : 65 % des dégâts à 40 m au lieu de 75 % ; ult plus chère (2800 → 3100)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'black-widow' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Blade est un Duelist de mi-distance, méthodique. Il entame au fusil, coupe les soins adverses avec son dash, pare les grosses menaces, puis bascule à l'épée quand sa rage est pleine pour finir le fight en volant de la vie.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["Le fusil se joue **à mi-distance**, pas au contact.", "La **parade** se garde pour une ult, un étourdissement ou un dive.", "Remplis ta **rage** avant de sortir l'épée : sans elle, l'épée ne fait rien."], "difficulty": 2, "tags": ["Mi-distance", "Anti-soin", "Parade", "Brawl"], "strengths": ["Anti-soin de zone", "Parade qui ignore les contrôles", "Vol de vie en forme de rage"], "weaknesses": ["Faible à l'épée sans rage", "Aucune réduction de dégâts en brawl", "Peu de portée"], "playbook": [{"when": "Un support adverse soigne un tank qui devrait mourir", "then": "**Dash au fusil** près de la cible : il pose l'anti-soin en zone. Tire ensuite."}, {"when": "Une ult ou un étourdissement part sur toi (Iron Man, Magneto, Phoenix, Emma Frost)", "then": "**Parade** au dernier moment : le tout début ignore les contrôles, puis tu encaisses bien moins."}, {"when": "Ta jauge de rage est pleine", "then": "Passe à l'**épée** et entre sur un support : le vol de vie te maintient en vie pendant que tu frappes."}, {"when": "Un diver saute sur tes supports", "then": "Dash à l'épée sur lui : il **ralentit, repousse et coupe son dash**."}, {"when": "L'adversaire vient de perdre ses boucliers et ses bulles", "then": "**Ult** : dégâts et zone d'anti-soin. Active ta rage juste avant pour ressortir à l'épée."}, {"when": "Tu es à l'épée sans rage", "then": "Reviens **au fusil** : hors rage, l'épée te fait tuer."}], "sections": [{"title": "Philosophie de jeu", "lead": "Blade n'est pas un assassin. Il grignote à mi-distance, prive l'adversaire de ses soins et attend que sa rage soit prête pour faire basculer le fight.", "ability": "", "key": "", "kind": "tips", "items": ["Joue **avec ton équipe**, en première ligne au fusil : c'est là que ta jauge de rage se remplit.", "Ton **anti-soin** décide des fights serrés : pose-le sur la cible que les supports adverses essaient de sauver.", "Tu n'as ni bouclier ni réduction de dégâts : ne reste pas à frapper un tank au corps à corps.", "Il est à son meilleur **face à deux boucliers**, dans une compo de dive, ou comme alternative à Magik quand elle est bannie."], "diagram": "brawl"}, {"title": "Fusil et épée", "lead": "Le fusil à pompe se joue comme une arme de mi-distance. L'épée, elle, n'a d'intérêt qu'en forme de rage.", "ability": "", "key": "", "kind": "default", "items": ["Le fusil fait ses meilleurs dégâts **autour de 10 mètres**, quand la gerbe de plombs couvre la cible.", "Enchaînement de base : **tir, dash, tir**. Le dash pose l'anti-soin entre les deux tirs.", "Passer à l'épée **annule la fin du rechargement** du fusil.", "Hors rage, l'épée fait peu de dégâts et t'expose : **ne la sors pas par défaut**."], "diagram": ""}, {"title": "Parade", "lead": "La parade bloque les dégâts venant de face. Pendant un court instant au début, elle ignore aussi tous les contrôles. Les dégâts bloqués rechargent ton dash.", "ability": "", "key": "Clic D", "kind": "default", "items": ["Pare ce qui décide d'un fight : **ult d'Iron Man ou de Magneto, étourdissement de Phoenix ou d'Hela, étranglement d'Emma Frost, ult de Jeff**.", "La fenêtre d'immunité aux contrôles est **au tout début** : c'est une question de réflexe, pas de durée.", "Une parade réussie **recharge ton dash** : elle relance ton combo au lieu de l'interrompre.", "Ne la dépense pas sur des dégâts mineurs. En rage, tu recules plus vite en parant."], "diagram": ""}, {"title": "Dash", "lead": "Deux charges. Au fusil, le dash pose l'anti-soin dans une large zone. À l'épée, il ralentit, repousse et frappe autour de toi.", "ability": "Daywalker Dash", "key": "Maj", "kind": "default", "items": ["Au fusil, c'est d'abord un **outil d'anti-soin** : sa zone est large, il suffit de viser près de la cible.", "À l'épée, il **interrompt les dashes adverses** (Black Panther) et remplit ta rage.", "**Un dash pour entrer, un pour sortir** : garde toujours une charge.", "En rage, maintenir l'attaque à l'épée fait plus de dégâts que d'enchaîner les dashes."], "diagram": "", "scene": {"title": "Couper les soins", "caption": "Un tank soigné par deux supports ne meurt pas. Le même tank sous anti-soin tombe en trois secondes.", "steps": ["Ton équipe concentre ses tirs sur le tank adverse.", "Tu dashes au fusil : la zone d'anti-soin le couvre.", "Les soins adverses ne passent plus : il tombe."], "els": [{"t": "pawn", "at": [204, 92], "team": "enemy", "role": "tank", "label": "Cible"}, {"t": "path", "kind": "shot", "team": "ally", "pts": [[128, 64], [204, 92]], "n": 1}, {"t": "path", "kind": "shot", "team": "ally", "pts": [[120, 126], [204, 92]], "n": 1}, {"t": "pawn", "at": [112, 96], "team": "me", "ghost": true}, {"t": "path", "kind": "move", "team": "me", "pts": [[112, 96], [164, 96]], "n": 2}, {"t": "zone", "at": [204, 92], "r": 26, "team": "me", "label": "Anti-soin"}, {"t": "pawn", "at": [164, 96], "team": "me", "label": "Toi"}, {"t": "path", "kind": "heal", "team": "enemy", "pts": [[278, 70], [212, 88]], "n": 3}, {"t": "path", "kind": "heal", "team": "enemy", "pts": [[280, 118], [212, 98]], "n": 3}, {"t": "note", "at": [250, 96], "text": "soins réduits", "team": "me"}, {"t": "pawn", "at": [278, 70], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [280, 118], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [246, 40], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [244, 146], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [128, 64], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [120, 126], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [66, 78], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [64, 116], "team": "ally", "role": "heal"}]}}, {"title": "Forme de rage", "lead": "En rage, tu voles de la vie et tu frappes plus vite à chaque charge accumulée. Les ennemis à bas PV deviennent visibles à travers les murs.", "ability": "Bloodline Awakening", "key": "E", "kind": "default", "items": ["Accumule tes charges **avant** de basculer : la rage est d'autant plus forte qu'elle démarre pleine.", "Change d'arme avec **la touche dédiée**, pas avec la molette.", "Le **vol de vie** te permet de rester dans un brawl où un autre Duelist mourrait.", "La vision à travers les murs sert à **poursuivre les cibles basses** qui se cachent."], "diagram": ""}, {"title": "Ultime", "lead": "Un coup d'épée à distance qui laisse une zone d'anti-soin. Appui bref pour une courte portée, maintien pour aller plus loin. Elle se recharge vite.", "ability": "Thousandfold Slash", "key": "Q", "kind": "default", "items": ["Lance-la **après la chute des boucliers et des bulles** : sinon elle est absorbée.", "Tu ressors dans la forme où tu étais : **active la rage avant** pour enchaîner à l'épée.", "Un contrôle peut t'en sortir : lance-la de côté, ou quand les étourdissements adverses sont dépensés.", "Elle **force les ults de soin** adverses, que ton équipe pourra punir au fight suivant.", "Très forte à la suite d'une ult de Groot. Seule, vise un tank : les supports s'en échappent trop facilement."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Jouer le fusil **au corps à corps**.", "Sortir l'épée **hors rage**.", "Parer des **dégâts mineurs**.", "Lancer l'ult **dans un bouclier**.", "Entrer **sans charges** de rage."], "diagram": ""}], "combos": [{"note": "Le dash au fusil applique l'**anti-soin** entre deux tirs.", "steps": [{"key": "", "label": "Tir"}, {"key": "Maj", "label": "dash"}, {"key": "", "label": "Tir"}], "title": "Combo de base"}], "counters": [{"hero": "the-thing", "note": "Il te verrouille au contact et encaisse tout ton fusil."}, {"hero": "human-torch", "note": "Il te frappe d'en haut, hors de portée du fusil comme de l'épée."}, {"hero": "hela", "note": "Elle t'entame à distance bien avant que tu sois à mi-portée."}, {"hero": "phoenix", "note": "Une parade ratée sur son étourdissement te coûte le fight."}, {"hero": "adam-warlock", "note": "Son lien et ses soins à rebonds compensent ton anti-soin."}, {"hero": "ultron", "note": "Il vole hors de portée et soigne ses alliés de loin."}], "synergies": [{"hero": "magneto", "note": "Un tank de ligne derrière lequel tu joues à mi-distance."}, {"hero": "emma-frost", "note": "Elle tient le front pendant que tu remplis ta rage."}, {"hero": "groot", "note": "Ses murs regroupent les ennemis pour ton ult."}, {"hero": "mantis", "note": "Son bonus de dégâts accélère tes kills."}, {"hero": "jubilee", "note": "Votre team-up crée un champ de vol de vie, renforcé en saison 11."}], "sources": [{"url": "https://www.youtube.com/watch?v=WPEDkYY4eGA", "title": "Blade Guide", "author": "Paz (padswagger)"}, {"title": "The Ultimate Blade Guide", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=Cy5ZReSGxDA"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Blade of Khonshu", "partners": ["moon-knight"], "key": "", "text": "Chaque Whirlwind Slash lance une lame lunaire en plus."}, {"name": "Bleed for Battle", "partners": ["captain-america"], "key": "", "text": "Donne des cumuls de Bloodline Awakening à Blade. **Amélioré :** Se déclenche aussi sur les dégâts critiques."}, {"name": "Blood Leech", "partners": ["venom"], "key": "", "text": "Cellular Corrosion vole de la vie. **Amélioré :** Ajoute un soin ponctuel."}, {"name": "Vampiric Kin", "partners": ["jubilee"], "key": "", "text": "Champ vampirique qui soigne et donne du vol de vie (40 % en saison 11). **Amélioré :** Soin supplémentaire."}], "changes": [{"season": "Saison 10", "text": "Team-up avec Captain America : 4 cumuls max en plus au lieu de 2."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'blade' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Captain America est un Vanguard de harcèlement. Il ne tient pas une ligne : il contourne l'équipe adverse, force ses cooldowns défensifs et prépare le dive de ses alliés, ou bien il revient intercepter le flanker qui menace ses supports. Rester devant à frapper les tanks est la seule façon de mal le jouer.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["Ton travail : **forcer les cooldowns défensifs** adverses, pour que l'engage suivant tue.", "Bouclier et charge servent à **esquiver les contrôles**, pas à bloquer chaque balle.", "Ton ult vaut une **petite ult de support** : elle engage, elle sauve, elle tient un point."], "difficulty": 2, "tags": ["Dive", "Pression", "Peel", "Mobilité"], "strengths": ["Sprint illimité : il rattrape n'importe qui", "Charge insensible aux contrôles", "Ult de vie bonus et de vitesse pour l'équipe"], "weaknesses": ["Peu de dégâts : il ne tue pas seul", "Impuissant face aux volants", "Saut écrasé long à revenir"], "playbook": [{"when": "Un diver arrive sur tes supports (Black Panther, Spider-Man, Magik)", "then": "Sprinte vers lui et **intercepte-le** : saut écrasé pour le projeter en l'air, puis coups. Il doit fuir ou mourir."}, {"when": "Un contrôle part sur toi (boule de neige de Luna, étourdissement d'Hela)", "then": "**Lève le bouclier** ou lance la **charge** : pendant la charge, tu ignores tous les contrôles."}, {"when": "Ton diver allié (Psylocke, Daredevil) va entrer", "then": "Entre **une seconde avant lui** sur la même cible : les cooldowns défensifs partent sur toi, pas sur lui."}, {"when": "Tu as utilisé le saut écrasé pour entrer", "then": "Il ne reviendra pas à temps : **garde la charge pour sortir**."}, {"when": "Une ult moyenne menace ton équipe (Star-Lord, Punisher), ou vous devez engager", "then": "**Ult près de tes alliés** : vie bonus et vitesse pour tout le monde."}, {"when": "Tu harcèles un support et il lâche son cooldown défensif", "then": "Objectif atteint : **ressors**, annonce-le, et reviens avec ton équipe."}], "sections": [{"title": "Philosophie de jeu", "lead": "Cap change de rôle selon ce dont ton équipe a besoin : il prépare le dive, ou il éteint l'incendie dans ta propre backline.", "ability": "", "key": "", "kind": "tips", "items": ["Avec un diver dans ton équipe, **tourne autour de l'équipe adverse** et arrive sur ses supports par le côté.", "Si tes propres supports se font attaquer, **reviens** : un Cap qui intercepte le diver vaut mieux qu'un Cap qui harcèle seul.", "Tu ne cherches pas le kill immédiat. Une bulle, un saut, une invisibilité dépensés pour toi sont **autant de réponses en moins** à l'engage de ton équipe.", "Dans un fight à trois supports adverses, concentre-toi sur les DPS : c'est là que se trouvent les picks."], "diagram": "", "scene": {"title": "Forcer avant d'engager", "caption": "Un support qui a dépensé son cooldown défensif pour toi n'a plus rien quand ton diver arrive.", "steps": ["Tu contournes l'équipe adverse en sprint.", "Tu harcèles un support : il dépense sa défense.", "Ton diver entre sur cette cible, qui n'a plus de réponse."], "els": [{"t": "pawn", "at": [120, 60], "team": "me", "ghost": true}, {"t": "path", "kind": "move", "team": "me", "pts": [[120, 60], [186, 4], [250, 40]], "n": 1}, {"t": "pawn", "at": [250, 42], "team": "me", "above": true}, {"t": "path", "kind": "shot", "team": "me", "pts": [[250, 42], [284, 80]], "n": 2}, {"t": "pawn", "at": [286, 84], "team": "enemy", "role": "heal", "label": "Cible"}, {"t": "pawn", "at": [110, 140], "team": "ally", "role": "dps", "ghost": true}, {"t": "path", "kind": "move", "team": "ally", "pts": [[110, 140], [200, 178], [290, 134]], "n": 3}, {"t": "pawn", "at": [296, 130], "team": "ally", "hero": "psylocke"}, {"t": "pawn", "at": [204, 92], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [232, 132], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [210, 46], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [246, 164], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [84, 96], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [44, 76], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [46, 120], "team": "ally", "role": "heal"}]}}, {"title": "Coups et boucliers lancés", "lead": "Deux coups de poing débloquent de petits lancers de bouclier, guidés vers la cible la plus proche de ton viseur.", "ability": "Sentinel Strike", "key": "Clic G", "kind": "default", "items": ["Le guidage est plus généreux quand tu **vises légèrement à droite** de la cible.", "Les deux coups peuvent se donner sur un **mur de Groot ou un clone de Loki** pour débloquer les lancers avant d'arriver.", "**Attends le son d'impact** du bouclier avant d'enchaîner un sprint ou un autre lancer : sinon l'attaque est annulée."], "diagram": ""}, {"title": "Sprint et saut écrasé", "lead": "Le sprint n'a ni cooldown ni jauge. Un saut pendant le sprint se termine par un impact au sol qui projette les ennemis en l'air.", "ability": "Leading Dash · Super-Soldier Slam", "key": "Maj", "kind": "default", "items": ["Sprinte **entre deux lancers** : une cible qui fuit ne te distance jamais.", "Le sprint s'entend. Pour un contournement discret, **marche**.", "Le saut écrasé **ouvre un combo** ou te permet de rejoindre un allié qui dive.", "Son cooldown est long : utilisé pour entrer, il ne te servira pas à sortir."], "diagram": ""}, {"title": "Bouclier", "lead": "Le bouclier renvoie les projectiles dans une direction aléatoire. Il se régénère une fois rangé, mais met longtemps à revenir s'il est brisé.", "ability": "Living Legend", "key": "Clic D", "kind": "default", "items": ["Son premier usage est d'**esquiver un contrôle** : boule de neige de Luna, étourdissement d'Hela.", "Il **protège un support** derrière toi : dagues d'Hela, ult d'Iron Man ou de Magneto.", "Les coups de mêlée et les rayons **ne sont pas renvoyés**.", "Ne le lève pas par habitude : un meilleur placement évite la plupart des dégâts, et tes supports soignent le reste."], "diagram": ""}, {"title": "Charge et lancer de bouclier", "lead": "La charge te rend insensible aux contrôles et s'arrête au contact d'une cible. Le gros lancer de bouclier ricoche d'un ennemi à l'autre.", "ability": "Liberty Rush · Vibranium Energy Saw", "key": "F · E", "kind": "default", "items": ["La charge **esquive** : boule de neige, ult de Doctor Strange, ult de Jeff.", "Elle sert à **finir** ou à **fuir**, rarement aux deux dans le même engage.", "Vise **les pieds** avec le gros lancer : même raté, il rebondit vers la cible. Depuis la saison 10, il ne perd plus de dégâts en rebondissant.", "Enchaînement complet : **sprint, saut, lancer de bouclier, impact au sol, charge, coups**."], "diagram": ""}, {"title": "Ultime", "lead": "Tu laisses un sillage qui donne de la vie bonus et de la vitesse, à toi et aux alliés qui le suivent.", "ability": "Freedom Charge", "key": "Q", "kind": "default", "items": ["**Pour engager** : ton équipe atteint la backline sans dépenser une ult de support.", "**Pour contrer** une menace moyenne : ult de Star-Lord, de Punisher, ou un diver au milieu de tes supports.", "**Pour tenir un point** : bouclier levé pendant l'ult, tu bouscules les ennemis et tu deviens très difficile à tuer.", "Lance-la **près de ton équipe** : la vie bonus ne sert à rien si tu es le seul à la recevoir.", "Coordonne-toi avec tes supports : si ton ult couvre ce fight, ils gardent les leurs pour le suivant."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Rester **devant à frapper les tanks**.", "Enchaîner sprint et lancers trop vite et **annuler ses attaques**.", "Lever le bouclier **sans raison**, puis ne plus l'avoir contre un contrôle.", "Entrer **sans moyen de sortir**.", "Chercher le kill au lieu de **forcer les cooldowns**."], "diagram": ""}], "combos": [{"note": "Attends le **son d'impact** du bouclier avant d'enchaîner, sinon tu annules ton attaque.", "steps": [{"key": "Maj", "label": "sprint"}, {"key": "Espace", "label": "saut"}, {"key": "E", "label": "lancer bouclier"}, {"key": "", "label": "Slam"}, {"key": "F", "label": "charge"}, {"key": "Clic G", "label": "coups"}], "title": "Combo complet"}], "counters": [{"hero": "ultron", "note": "Il vole hors de portée et ses dégâts percent la vie bonus de ton ult."}, {"hero": "iron-man", "note": "Tu ne peux presque jamais l'atteindre : laisse-le à tes tireurs."}, {"hero": "winter-soldier", "note": "Son crochet t'arrête et te ramène : il annule ta fuite."}, {"hero": "the-punisher", "note": "Son tir continu brise ton bouclier en une seconde."}, {"hero": "loki", "note": "Ses runes annulent ton engage : force-les avant que ton équipe entre."}, {"hero": "adam-warlock", "note": "Son lien d'âmes sauve la cible que tu harcèles. Fais-le dépenser d'abord."}], "synergies": [{"hero": "venom", "note": "Deux tanks qui arrivent par deux côtés sur la même backline : impossible à gérer."}, {"hero": "psylocke", "note": "Tu forces les cooldowns, elle tue la cible sans défense."}, {"hero": "black-panther", "note": "Même plan : tu attires les contrôles, il passe derrière."}, {"hero": "human-torch", "note": "Tes coups repoussent l'ennemi dans ses zones de feu."}, {"hero": "luna-snow", "note": "Ses soins à longue portée te suivent pendant que tu tournes autour de l'ennemi."}, {"hero": "mantis", "note": "Son bonus de dégâts compense ton manque de létalité."}], "sources": [{"url": "https://www.youtube.com/watch?v=HZrBVN4tuik", "title": "Captain America Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Bleed for Battle", "partners": ["blade"], "key": "", "text": "Donne des cumuls de Bloodline Awakening à Blade. **Amélioré :** Se déclenche aussi sur les dégâts critiques."}, {"name": "Savage Slam", "partners": ["hulk"], "key": "", "text": "Un saut écrasé réduit les cooldowns. **Amélioré :** Ajoute la vulnérabilité."}, {"name": "Stars Aligned", "partners": ["winter-soldier"], "key": "", "text": "Saut vers l'allié qui partage de la vie bonus. **Amélioré :** Ralliement mutuel."}, {"name": "Voltaic Union", "partners": ["thor"], "key": "", "text": "Projectile-bouclier de foudre (10 s depuis la saison 10). **Amélioré :** Explosion de zone à chaque touche."}], "changes": [{"season": "Saison 10", "text": "Vie de base 300 → 350."}, {"season": "Saison 10", "text": "Le lancer de bouclier ne perd plus de dégâts en rebondissant."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'captain-america' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Cloak & Dagger est le Strategist le plus simple à prendre en main, et l'un de ceux qui récompensent le plus la maîtrise. Dagger soigne en zone avec des projectiles guidés ; Cloak aveugle, rend vulnérable et rend toute son équipe intangible. La partie se gagne en chargeant l'ult plus vite que les supports adverses.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["Ta priorité : **charger ton ult plus vite** que les supports d'en face.", "Passe en Cloak pour **recharger Dagger** et lancer le voile qui rend les ennemis vulnérables.", "L'**intangibilité** se garde pour une vraie ult adverse."], "difficulty": 1, "tags": ["Soins de zone", "Utilitaire", "Anti-ult", "Accessible"], "strengths": ["Soins guidés qui ne se ratent pas", "Intangibilité de groupe : annule une ult", "Voile de vulnérabilité sur tout un groupe"], "weaknesses": ["Presque aucun auto-soin", "Immobile un instant après chaque dash de l'ult", "Vulnérable pendant le changement de forme"], "playbook": [{"when": "Une ult de burst arrive sur ton équipe (Psylocke, Magneto, Jeff, Iron Man)", "then": "Passe en Cloak et lance l'**intangibilité** sur tes alliés proches. Annonce-la : celui qui tire en sort."}, {"when": "Ton équipe s'apprête à tirer sur un groupe d'ennemis", "then": "**Voile de Cloak** à travers eux : ils sont aveuglés et prennent plus de dégâts. Lance-le dès qu'il est disponible."}, {"when": "Ton diver allié part en duel", "then": "Envoie les dagues **avant** qu'il prenne des dégâts : le projectile est lent."}, {"when": "Tout le monde est plein de vie", "then": "Passe en **Cloak** et fais des dégâts : c'est de la charge d'ult, et cela recharge les dagues plus vite."}, {"when": "Un diver te prend pour cible", "then": "**Dôme de soin** à tes pieds et reste dedans. Si cela ne suffit pas, intangibilité pour t'envoler vers ton équipe."}, {"when": "Tu viens de lancer ton ult", "then": "**Arrête de soigner** : les traînées s'en chargent. Passe en Cloak et tue."}], "sections": [{"title": "Philosophie de jeu", "lead": "Soigner ne suffit pas à porter une partie. Les meilleurs Cloak & Dagger utilisent chaque cooldown dès qu'il revient et glissent des dégâts à la moindre accalmie.", "ability": "", "key": "", "kind": "tips", "items": ["Plus tu montes en rang, plus **l'avance en ult** décide des fights : chaque soin de zone et chaque seconde de rayon comptent.", "Un ennemi tué tôt, ce sont des dégâts que ton équipe ne prendra pas : aide à finir les cibles basses.", "Joue **à couvert, près d'un pack de soin** : tu n'as presque aucun moyen de te soigner seul.", "Si les deux supports de ton équipe ont leur ult, vous pouvez **ouvrir le fight** avec l'une d'elles."], "diagram": "heal"}, {"title": "Soins de Dagger", "lead": "Des dagues à tête chercheuse qui soignent leur cible, puis éclatent pour soigner tous les alliés autour d'elle.", "ability": "", "key": "Clic G", "kind": "default", "items": ["La dague suit l'allié blessé **le plus proche de ton viseur**.", "L'éclat soigne **en zone** : vise les groupes, c'est ce qui charge ton ult.", "Tirer sur un ennemi soigne aussi les alliés autour de lui, mais deux fois moins.", "Le projectile est lent : **anticipe** les dégâts au lieu de les suivre."], "diagram": ""}, {"title": "Changer de forme", "lead": "Le changement est presque instantané, et il recharge les dagues plus vite qu'un rechargement classique.", "ability": "", "key": "Maj", "kind": "default", "items": ["Un **aller-retour** Dagger, Cloak, Dagger recharge plus vite qu'attendre.", "Le rayon de Cloak s'accroche à sa cible : il **finit les fuyards** et fait désormais un peu plus de dégâts (saison 11).", "Anticipe le passage en Cloak quand une ult adverse approche : la courte animation suffit à te faire tuer."], "diagram": ""}, {"title": "Les voiles", "lead": "Dagger lance un voile qui soigne et augmente les soins reçus. Cloak lance un voile qui aveugle les ennemis traversés et augmente les dégâts qu'ils subissent.", "ability": "Veil of Lightforce · Terror Cape", "key": "E", "kind": "default", "items": ["Le voile de **Cloak** est l'une des capacités les plus fortes de ton kit : toute une équipe vulnérable pendant que la tienne tire. Lance-le à chaque retour de cooldown.", "Il **aveugle** : une ult de Star-Lord ou de Scarlet Witch aveuglée ne verrouille plus ses cibles. L'effet ne dure plus qu'une seconde depuis la saison 11.", "Le voile de **Dagger** se lance quand ton équipe avance groupée ou recule sous la pression.", "Les voiles sont **bien plus rapides** depuis la saison 11, et chaque allié ou ennemi touché réduit le cooldown du dôme de soin : vise les couloirs où ils traversent le plus de monde.", "Un voile disparaît au contact d'un mur ou d'un bouclier ennemi."], "diagram": "", "scene": {"title": "Le voile avant le burst", "caption": "Le voile ne fait presque pas de dégâts lui-même : il multiplie ceux de toute ton équipe pendant quelques secondes.", "steps": ["Tu passes en Cloak et tu lances le voile à travers le groupe adverse.", "Les ennemis traversés sont aveuglés et vulnérables.", "Ton équipe tire à ce moment précis."], "els": [{"t": "pawn", "at": [70, 92], "team": "me"}, {"t": "path", "kind": "beam", "team": "me", "pts": [[70, 92], [306, 92]], "n": 1}, {"t": "pawn", "at": [204, 92], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [246, 84], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [284, 98], "team": "enemy", "role": "heal"}, {"t": "zone", "at": [244, 92], "r": 54, "team": "me", "label": "Vulnérables", "n": 2}, {"t": "pawn", "at": [128, 44], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [120, 146], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [56, 44], "team": "ally", "role": "tank"}, {"t": "path", "kind": "shot", "team": "ally", "pts": [[128, 44], [246, 84]], "n": 3}, {"t": "path", "kind": "shot", "team": "ally", "pts": [[120, 146], [204, 92]], "n": 3}, {"t": "pawn", "at": [36, 130], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [270, 152], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [296, 36], "team": "enemy", "role": "heal"}]}}, {"title": "Dôme de soin", "lead": "Une salve de dagues qui crée une zone de soin continu à l'endroit de l'impact.", "ability": "Dagger Storm", "key": "Clic D", "kind": "default", "items": ["Vise **les pieds** de tes alliés : leurs corps ne bloquent pas la salve.", "Pose-le, puis **passe en Cloak** : il soigne pendant que tu fais des dégâts.", "Son cooldown est passé à 15 secondes en saison 11 et il te soigne moins : compte sur tes voiles pour le faire revenir plus vite.", "Contre une compo de dive, **garde-le pour toi**."], "diagram": ""}, {"title": "Intangibilité", "lead": "Cloak enveloppe les alliés proches : pendant quelques instants, ils sont invulnérables et plus rapides, tant qu'ils n'attaquent pas.", "ability": "Dark Teleportation", "key": "Clic D", "kind": "default", "items": ["Elle **annule les ults** de Psylocke, de Magneto ou de Jeff. Les bons adversaires chercheront à te la faire dépenser avant.", "**Annonce-la** à voix haute : un allié qui tire en sort aussitôt.", "Tu voles pendant l'effet : sers-t'en pour **te replacer en hauteur** après un dive."], "diagram": ""}, {"title": "Ultime", "lead": "Quatre dashes rapides qui laissent au sol des traînées : elles soignent tes alliés et blessent les ennemis.", "ability": "Eternal Bond", "key": "Q", "kind": "default", "items": ["Trace-la **sur le point**, là où le fight se joue, en superposant les traînées.", "Tu restes **immobile un instant après chaque dash** : face à Hawkeye, Punisher, Magneto ou Iron Man en ult, trace à couvert.", "Une fois l'ult posée, les traînées soignent seules : **passe en Cloak** et fais des dégâts.", "Si une seule ult adverse reste à contrer et que ton autre support s'en charge, utilise la tienne **pour prendre le fight**.", "Tu ne peux pas monter pendant les dashes : attention aux bords de carte."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Ne **jamais passer en Cloak**.", "Oublier le **voile de Cloak**.", "Dépenser l'intangibilité **avant** l'ult qu'elle devait annuler.", "Continuer à soigner **pendant sa propre ult**.", "Tracer l'ult **à découvert** face à un sniper."], "diagram": ""}], "combos": [], "counters": [{"hero": "magneto", "note": "Son ult te tue pendant un temps d'arrêt de la tienne."}, {"hero": "hawkeye", "note": "Un tir à la tête entre deux dashes met fin à ton ult."}, {"hero": "iron-man", "note": "Son ult tombe exactement là où tu t'arrêtes : trace à couvert."}, {"hero": "venom", "note": "Tu n'as ni déplacement ni auto-soin fiable pour lui échapper."}], "synergies": [{"hero": "the-thing", "note": "Un brawl serré autour de lui : chaque dague soigne trois alliés."}, {"hero": "emma-frost", "note": "Même logique de compo groupée sur le point."}, {"hero": "black-widow", "note": "Un ennemi sous ton voile meurt d'un seul de ses tirs à la tête."}, {"hero": "iron-fist", "note": "Tes dagues guidées le suivent jusque dans la backline adverse."}, {"hero": "the-hood", "note": "Avec votre team-up, tes voiles repoussent aussi les ennemis depuis la saison 11."}], "sources": [{"url": "https://www.youtube.com/watch?v=E9lKTfRFJ6s", "title": "Cloak and Dagger Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Frozen Haven", "partners": ["luna-snow"], "key": "", "text": "L'état gelé émet une aura de soin (bouclier de 2 s depuis la saison 10). **Amélioré :** Aura renforcée."}, {"name": "Light & Dark Darts", "partners": ["psylocke"], "key": "", "text": "Fléchettes de lumière et domaine d'ombre. **Amélioré :** Domaine plus grand, fléchettes relancées."}, {"name": "Luminous Moon", "partners": ["moon-knight"], "key": "", "text": "Dash intangible avec une vague de soin. **Amélioré :** Plus long, avec un soin continu."}, {"name": "Moonlit Slash", "partners": ["hawkeye"], "key": "", "text": "Entaille lumineuse qui soigne les alliés, et Hawkeye se soigne d'autant (10.5). **Amélioré :** Combo en trois coups."}, {"name": "Oblivion Shroud", "partners": ["the-hood"], "key": "", "text": "Les voiles affaiblissent dégâts et soins ennemis, et repoussent les ennemis sur leur passage depuis la saison 11. **Amélioré :** Plus larges, avec un boost de dégâts."}], "changes": [{"season": "Saison 11", "text": "Dagger Storm : cooldown 12 → 15 s, auto-soin 50 → 35/s ; chaque allié ou ennemi touché par le voile réduit ce cooldown de 0,6 s."}, {"season": "Saison 11", "text": "Darkforce Cloak : 80 → 85 dégâts/s. Terror Cape : aveuglement 1,5 → 1 s."}, {"season": "Saison 11", "text": "Veil of Lightforce et Terror Cape : vitesse du voile 20 → 35 m/s."}, {"season": "Saison 11", "text": "Team-up avec The Hood : les voiles repoussent les ennemis sur leur passage."}, {"season": "Saison 10", "text": "Terror Cape : vulnérabilité 28 % → 20 % ; dague de lumière 25 → 20 de soin."}, {"season": "Saison 10", "text": "Tous les Strategists : l'ult se charge un peu moins vite (65 % du soin et 50 % des dégâts convertis en énergie, au lieu de 70 % et 55 %)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'cloak-and-dagger' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Cyclops est un tireur hitscan à longue portée, plus mobile qu'Hela ou Phoenix, mais sans aucun contrôle. Il vise la tête depuis une hauteur, arrose les groupes avec son rayon, se soigne en vie bonus avec Ricochet Force, et son ult efface une équipe alignée.", "patch_note": "Conseils issus d'un guide enregistré à la sortie du héros (saison 8.5), mis à jour avec les changements des saisons 10.5 et 11. Vérifie les détails en jeu.", "tldr": ["Joue en **hitscan** : sur un angle ou une hauteur, et vise la tête.", "**Ricochet Force** dès qu'elle est prête : elle achève et te donne de la vie bonus.", "Tu n'as aucun étourdissement : **fuis le corps à corps** avec tes deux mobilités."], "difficulty": 1, "tags": ["Hitscan", "Longue portée", "High ground", "Mobile"], "strengths": ["Plus longue portée effective des hitscans", "Deux capacités de mobilité", "Ult en pourcentage de la vie, sur 60 mètres"], "weaknesses": ["Aucun contrôle", "Perd les duels au contact", "Ult étroite, facile à éviter pour une équipe dispersée"], "playbook": [{"when": "Un tank tient son bouclier au centre", "then": "**Monte** (Optic Ascent ou hauteur) et tire à la tête sur la backline, par-dessus."}, {"when": "Tu viens de placer deux tirs sur une cible", "then": "**Ricochet Force** en la visant directement : les dégâts sont doublés sur elle, et tu gagnes de la vie bonus."}, {"when": "Un diver arrive au contact (Spider-Man, Black Panther, Magik)", "then": "**Propulsion Blast sur lui** pour le repousser, puis reprends de la distance. Ne reste pas en duel."}, {"when": "Deux ou trois ennemis sont proches les uns des autres", "then": "**Rayon concussif** : c'est là qu'il rapporte le plus."}, {"when": "Les ennemis sont alignés dans un couloir, ou pris dans une prison de Groot", "then": "**Ult dans l'axe**. Tu peux annuler la visée sans pénalité tant que tu n'as pas confirmé."}, {"when": "Tu attends d'être attaqué", "then": "Garde ta **vie bonus au maximum** avec Ricochet Force avant que le diver arrive."}], "sections": [{"title": "Philosophie de jeu", "lead": "Tu joues avec ton équipe comme un sniper mobile : tu prends un angle, tu sors une cible importante, et tu changes de position avant qu'on vienne te chercher.", "ability": "", "key": "", "kind": "tips", "items": ["La **hauteur** est ton meilleur allié : tu tires par-dessus les boucliers et les têtes sont plus faciles à toucher.", "Tu as plus de mobilité que les autres hitscans : **prends des angles qu'eux ne peuvent pas tenir**.", "Sans étourdissement, un duel au contact est perdu d'avance : la distance est ta défense."], "diagram": "highground"}, {"title": "Optic Blast", "lead": "Un tir instantané dont les dégâts ne baissent qu'à très longue distance.", "ability": "Optic Blast", "key": "Clic G", "kind": "default", "items": ["Deux **tirs à la tête** suffisent sur beaucoup de cibles.", "Chaque touche **réduit le cooldown de Ricochet Force**.", "Recharge entre deux échanges, jamais au moment de conclure."], "diagram": ""}, {"title": "Rayon concussif", "lead": "Un rayon continu qui touche tous les ennemis dans sa zone, avec plus de dégâts sur la cible visée. Il a sa propre jauge.", "ability": "Concussive Beam", "key": "Clic D", "kind": "default", "items": ["Il est optimal sur **deux ou trois ennemis** : au-delà, les dégâts se diluent.", "Il met la pression sur **tout un groupe**, pas seulement sur ta cible.", "Utilisé en tombant, il déclenche ton **vol plané** : avec Optic Ascent, tu arroses la backline d'en haut."], "diagram": ""}, {"title": "Ricochet Force", "lead": "Un tir qui rebondit sur les joueurs et les surfaces. Deux charges, et chaque utilisation te donne de la vie bonus.", "ability": "Ricochet Force", "key": "", "kind": "default", "items": ["Vise **directement une cible** : les dégâts sont doublés sur elle.", "Place-la **après deux Optic Blast** pour achever.", "En difficulté, lance-la même sans viser : la **vie bonus** peut te sauver."], "diagram": ""}, {"title": "Mobilité", "lead": "Propulsion Blast te propulse dans la direction choisie, en repoussant et en ralentissant les ennemis touchés. Optic Ascent t'envoie haut dans les airs.", "ability": "Propulsion Blast · Optic Ascent", "key": "", "kind": "default", "items": ["Propulsion Blast : **appui bref pour un petit dash, maintien pour une longue course** que tu orientes à la caméra.", "Visé sur un ennemi, il **le repousse**. Près d'un vide, il l'éjecte.", "Optic Ascent te met **en hauteur en un instant** : pour reprendre un angle ou préparer l'ult."], "diagram": ""}, {"title": "Ultime", "lead": "Tu vises, tu confirmes, et un rayon de plus de 60 mètres rend le sol explosif : tout ce qui se trouve sur la trajectoire subit d'énormes dégâts, en pourcentage de la vie.", "ability": "Ruby Rage", "key": "Q", "kind": "default", "items": ["Tant que tu n'as pas confirmé, tu peux **annuler sans rien perdre** : prends le temps d'aligner.", "Les dégâts en pourcentage font aussi très mal **aux tanks**.", "Le rayon suit le relief : une hauteur adverse n'est pas à l'abri.", "**Continue de tirer** pendant que le sol explose.", "Combos : prison de Groot, bonus de dégâts de Mantis ou de Rocket."], "diagram": "", "scene": {"title": "L'ult dans l'axe", "caption": "Le rayon est long et étroit. Sa valeur dépend entièrement de l'alignement des cibles au moment où tu confirmes.", "steps": ["Optic Ascent : tu prends de la hauteur.", "Tu alignes le rayon sur le groupe. Tu peux encore annuler.", "Tu confirmes : le sol explose sur toute la trajectoire."], "els": [{"t": "cover", "at": [60, 8], "size": [250, 20]}, {"t": "cover", "at": [60, 152], "size": [250, 20]}, {"t": "pawn", "at": [70, 124], "team": "me", "ghost": true}, {"t": "path", "kind": "move", "team": "me", "pts": [[70, 124], [60, 96], [82, 90]], "n": 1}, {"t": "pawn", "at": [86, 88], "team": "me", "above": true}, {"t": "area", "at": [110, 74], "size": [200, 30], "label": "Ruby Rage", "team": "me"}, {"t": "note", "at": [124, 62], "text": "2", "team": "me"}, {"t": "pawn", "at": [176, 88], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [214, 92], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [252, 86], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [286, 92], "team": "enemy", "role": "heal"}, {"t": "note", "at": [230, 124], "text": "3", "team": "me"}, {"t": "note", "at": [270, 127], "text": "sol explosif", "team": "me"}, {"t": "pawn", "at": [236, 46], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [120, 124], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [40, 60], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [36, 110], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [110, 44], "team": "ally", "role": "dps"}]}}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Accepter un **duel au contact**.", "Rester **au sol dans la mêlée**.", "Oublier **Ricochet Force**.", "Utiliser le rayon sur **un ennemi isolé** ou sur six à la fois.", "Cesser de tirer **pendant l'ult**."], "diagram": ""}], "combos": [], "counters": [{"hero": "spider-man", "note": "Il te rejoint sur n'importe quelle hauteur et tu n'as rien pour l'arrêter."}, {"hero": "black-panther", "note": "Il gagne le duel au contact en une seconde."}, {"hero": "magik", "note": "Elle arrive par portail sur ton angle."}, {"hero": "hela", "note": "Même rôle, avec un étourdissement et plus de burst."}, {"hero": "venom", "note": "Il t'oblige à dépenser tes deux mobilités pour survivre."}], "synergies": [{"hero": "groot", "note": "Sa prison aligne les ennemis sur la trajectoire de ton ult."}, {"hero": "mantis", "note": "Son bonus de dégâts rend tes tirs à la tête et ton ult mortels."}, {"hero": "wolverine", "note": "Votre team-up allonge ses griffes ; il occupe les tanks pendant que tu tires."}, {"hero": "gambit", "note": "Votre team-up te donne vitesse et hauteur de saut."}, {"hero": "phoenix", "note": "Votre team-up fait exploser ses étincelles."}], "sources": [{"title": "Ultimate Cyclops Guide (Beginner/Advanced)", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=oN9sOyaQYwA"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Blast Slash", "partners": ["wolverine"], "key": "", "text": "Griffes plus longues et Kinetic Claws. **Amélioré :** L'effet reste actif en permanence."}, {"name": "Kinetic Kin", "partners": ["gambit"], "key": "", "text": "Boost de vitesse et de saut (8 s en 10.5). **Amélioré :** Augmente la vitesse d'attaque."}, {"name": "Slim and Red", "partners": ["phoenix"], "key": "", "text": "Embrasement qui brûle et déclenche les étincelles (cooldown 10 s en 10.5). **Amélioré :** Les étincelles réduisent le cooldown de Ricochet Force."}], "changes": [{"season": "Saison 10.5", "text": "Optic Blast 22 → 23 par coup, -0,3 s de cooldown de Ricochet Force par touche (au lieu de 0,25 s), ult moins chère (3700 → 3400)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'cyclops' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Daredevil est un Duelist de mêlée capable de diver une cible isolée comme de tenir un brawl. Il perçoit les ennemis à travers les murs, marque sa proie pour la traquer, et son dash se recharge à chaque élimination : un premier kill en appelle un second.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["**Isole une cible, tue-la**, puis gagne le fight en surnombre avec ton équipe.", "Le dash est un pari : sans élimination pour le recharger, tu restes longtemps sans lui.", "Le grappin est d'abord ta **sortie**, pas ton entrée."], "difficulty": 3, "tags": ["Mêlée", "Dive", "Combos", "Renvoi"], "strengths": ["Voit tout le monde à travers les murs", "Dash rechargé à chaque élimination", "Renvoie les projectiles, ults comprises"], "weaknesses": ["Aucune portée", "Dash très long à revenir sans kill", "Démuni face aux volants"], "playbook": [{"when": "Un ennemi s'isole (tu le vois à travers le mur)", "then": "**Marque, lancer, dash, attaque bondissante, frappe au sol.** Le kill recharge ton dash pour la cible suivante."}, {"when": "Un projectile dangereux part sur toi (gel de Luna, sommeil de Mantis, ult de Magneto ou d'Iron Man)", "then": "**Renvoi** : face à lui, clic droit. Il repart vers l'ennemi."}, {"when": "Tu n'es pas certain d'obtenir le kill", "then": "**Ne dashe pas.** Reste sur un angle, fais pression au lancer et attends qu'un allié entame la cible."}, {"when": "Ton engage tourne mal", "then": "**Grappin sur un mur** derrière toi, puis attaque bondissante pour prendre de la distance."}, {"when": "Un support adverse lance une ult de zone (Invisible Woman, Cloak & Dagger)", "then": "**Grappin sur lui** pour l'en sortir, à condition qu'un allié soit prêt à le tuer."}, {"when": "Tes cooldowns sont dépensés", "then": "Frappe un tank en alternant coups et mêlée : tu remplis ta fureur en attendant le prochain dive."}], "sections": [{"title": "Philosophie de jeu", "lead": "Selon ta compo, tu attends dans l'ombre qu'un support s'écarte, ou tu joues un angle à mi-distance pour charger ton ult jusqu'au bon moment.", "ability": "", "key": "", "kind": "tips", "items": ["Ta vision à travers les murs te dit **qui est seul** : c'est ta cible.", "Quand entrer est trop risqué, reste sur un **angle décalé** et harcèle au lancer.", "Entre deux dives, tu es assez solide pour **te battre contre un tank** avec ton équipe.", "Contre une compo anti-dive (Emma Frost, Winter Soldier), change de cible : mets la pression sur les tanks, ou chasse leurs flankers que tu vois venir.", "La patience fait la différence : la plupart des morts de Daredevil viennent d'un dash de trop."], "diagram": "dive"}, {"title": "Passifs", "lead": "Daredevil voit moins loin que les autres héros, mais il perçoit tous les ennemis à travers les murs, même immobiles ou invisibles.", "ability": "", "key": "", "kind": "default", "items": ["Sa perception révèle **Invisible Woman, Loki et Psylocke** quand ils sont invisibles : préviens ton équipe.", "Il **court sur les murs** sans limite : passe au-dessus de l'ennemi pour arriver par où personne ne regarde.", "Dans les paramètres d'accessibilité, active l'**effet de balayage** pour distinguer alliés et ennemis.", "Baisse la luminosité de fond du radar dans les réglages du héros : les murs se lisent mieux quand tu dois fuir au grappin."], "diagram": ""}, {"title": "Matraques et fureur", "lead": "Une série de quatre coups qui remplit ta jauge de fureur. Après chaque capacité, tu disposes pendant quelques secondes d'une attaque bondissante plus puissante.", "ability": "", "key": "Clic G", "kind": "default", "items": ["Le réflexe central du héros : **une attaque bondissante après chaque capacité**.", "L'attaque bondissante te propulse : elle rattrape une cible mobile ou t'éloigne d'un danger.", "Termine ta série par un **coup de mêlée** : le premier frappe deux fois.", "Alterner coups et mêlée remplit la fureur plus vite : fais-le sur un tank pendant les temps morts."], "diagram": ""}, {"title": "Marque et dash", "lead": "Tu marques une cible à grande distance : tu cours plus vite et tu encaisses mieux tant qu'elle est marquée. Un second appui te fait foncer sur elle, l'aveugle et remplit ta fureur.", "ability": "Sonic Pursuit", "key": "F", "kind": "default", "items": ["Garde **toujours une marque active** : vitesse et résistance gratuites.", "Le dash se recharge si **n'importe quel ennemi meurt** juste après, même tué par un allié.", "Sans élimination, son cooldown est très long : **ne dashe que sur un kill probable**.", "L'aveuglement neutralise une ult à verrouillage comme celle de Star-Lord."], "diagram": "", "scene": {"title": "Le dash et sa recharge", "caption": "Chaque élimination te rend ton dash. Le premier kill doit donc être le plus sûr des deux.", "steps": ["Tu marques le support isolé, puis tu ouvres au lancer.", "Dash, attaque bondissante, frappe au sol : il meurt.", "Le dash est rechargé : tu enchaînes sur la cible voisine."], "els": [{"t": "cover", "at": [150, 20], "size": [16, 46], "label": "Mur"}, {"t": "pawn", "at": [128, 64], "team": "me", "ghost": true}, {"t": "path", "kind": "sight", "team": "me", "pts": [[128, 64], [238, 60]], "n": 1}, {"t": "path", "kind": "move", "team": "me", "pts": [[128, 64], [180, 96], [228, 66]], "n": 2}, {"t": "pawn", "at": [240, 60], "team": "enemy", "role": "heal", "ko": true}, {"t": "pawn", "at": [228, 78], "team": "me", "ghost": true}, {"t": "path", "kind": "move", "team": "me", "pts": [[228, 78], [252, 118], [282, 110]], "n": 3}, {"t": "pawn", "at": [270, 114], "team": "me"}, {"t": "pawn", "at": [292, 106], "team": "enemy", "role": "heal", "label": "Suivante", "above": true}, {"t": "pawn", "at": [196, 130], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [232, 160], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [296, 30], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [96, 110], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [70, 144], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [44, 84], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [46, 124], "team": "ally", "role": "heal"}]}}, {"title": "Attaques de fureur", "lead": "La fureur alimente deux attaques : une frappe au sol en croix qui te donne de la vie bonus, et un lancer de matraque qui ricoche entre les ennemis.", "ability": "Devil's Chain · Devil's Throw", "key": "E · Clic G / Clic D", "kind": "default", "items": ["La **frappe au sol** fait plus de dégâts si tu vises les pieds : c'est ton coup de grâce, celui qui te rend ton dash.", "Le **lancer** ricoche et ralentit : il ouvre le combo à distance et charge ton ult.", "Deux supports collés l'un à l'autre prennent le lancer **deux fois chacun**.", "Combo principal : **marque, lancer, dash, attaque bondissante, frappe au sol, attaque bondissante**."], "diagram": ""}, {"title": "Grappin", "lead": "Un grappin qui te tire vers un mur ou vers un ennemi. Son cooldown ne démarre que s'il accroche : le rater ne coûte rien.", "ability": "Devil's Latch", "key": "", "kind": "default", "items": ["C'est ton **outil de fuite** principal.", "Pour engager avec, il faut pouvoir **ressortir avec l'attaque bondissante** qu'il t'offre.", "Accrocher un ennemi vous déplace **tous les deux** entre les équipes : utile pour sortir un support de son ult, dangereux sans allié prêt.", "Ce n'est pas un étourdissement : il n'interrompt pas une ult."], "diagram": ""}, {"title": "Renvoi", "lead": "Tu fais tournoyer tes matraques : tous les projectiles venant de face repartent vers l'ennemi. Les rayons et la mêlée passent au travers.", "ability": "Objection", "key": "Clic D", "kind": "default", "items": ["À renvoyer : **boule de neige de Luna, sommeil de Mantis, ult de Groot, de Magneto ou d'Iron Man**.", "Il **bloque sans renvoyer** les ults de Doctor Strange, de Scarlet Witch et de The Thing.", "Les matraques font des dégâts pendant le renvoi : une Luna qui essaie de te geler meurt dedans.", "Il renvoie aussi les **soins en projectile** adverses, qui te soignent alors.", "Les bons joueurs chercheront à te le faire dépenser : **ne l'utilise que sur une vraie menace**."], "diagram": ""}, {"title": "Ultime", "lead": "Une aura de dégâts qui aveugle les ennemis qui te regardent. Son principal intérêt : ta fureur devient presque illimitée.", "ability": "Let the Devil Out", "key": "Q", "kind": "default", "items": ["Profite de la fureur illimitée pour **enchaîner frappes au sol et recharges de dash**.", "Ajoute le **renvoi** : l'ennemi doit te regarder pour te tuer, et te regarder l'aveugle.", "Elle **impose le tempo** : l'adversaire s'occupe de toi ou continue son plan, pas les deux.", "Comme toute ult de Duelist, elle se lance **avec ton équipe**, pas seul dans leur backline."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Dasher **sans chance d'élimination**.", "Engager **au grappin** sans sortie.", "Renvoyer trop tôt, puis **subir l'ult** qu'il fallait renvoyer.", "Oublier l'**attaque bondissante** après une capacité.", "Insister et **mourir seul**."], "diagram": ""}], "combos": [{"note": "Le lancer ricoche et ralentit : c'est ton ouvreur de loin.", "steps": [{"key": "F", "label": "marque"}, {"key": "", "label": "Lancer"}, {"key": "F", "label": "dash"}, {"key": "", "label": "Attaque bondissante"}, {"key": "", "label": "Frappe au sol"}, {"key": "", "label": "Attaque bondissante"}], "title": "Combo principal"}], "counters": [{"hero": "emma-frost", "note": "Son étranglement te retire du fight. Il peut se renvoyer si tu le vois venir."}, {"hero": "the-thing", "note": "Son impact au sol t'arrête, et il ne se renvoie pas."}, {"hero": "peni-parker", "note": "Mines et toiles couvrent la backline que tu veux diver."}, {"hero": "phoenix", "note": "Étourdissement, dash et auto-soin : elle gagne le duel."}, {"hero": "ultron", "note": "Il vole hors de portée et soigne la cible que tu attaques."}, {"hero": "iron-man", "note": "Tu n'as aucun moyen de l'atteindre."}], "synergies": [{"hero": "venom", "note": "Il entame la cible que tu as marquée : ton kill est assuré, ton dash aussi."}, {"hero": "captain-america", "note": "Il force les cooldowns défensifs juste avant ton entrée."}, {"hero": "emma-frost", "note": "En brawl, tu achèves la cible qu'elle vient de frapper."}, {"hero": "hela", "note": "Elle s'occupe des volants que tu ne peux pas toucher."}, {"hero": "luna-snow", "note": "Ses soins te suivent à longue distance pendant tes dives."}], "sources": [{"url": "https://www.youtube.com/watch?v=HRXsRdVXMVo", "title": "Daredevil Guide", "author": "Paz (padswagger)"}, {"title": "Ultimate Daredevil Guide (Beginner/Advanced)", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=w0jA0OauzfA"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Bestial Hunt", "partners": ["the-punisher"], "key": "", "text": "Balles perforantes avec bonus de dégâts. **Amélioré :** Détruit les murs plus vite."}, {"name": "Comprehensive Defense", "partners": ["iron-fist"], "key": "", "text": "Objection! touche tous les ennemis et renvoie les projectiles. **Amélioré :** Ajoute un soin passif."}, {"name": "Devilish Affair", "partners": ["black-widow"], "key": "", "text": "Devil's Chain frappe en croix et ralentit. **Amélioré :** Plus large, et rend de la Fureur."}], "changes": [], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'daredevil' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Deadpool se joue dans les trois rôles avec un kit presque identique : deux pistolets, deux katanas, une aura et des rebonds sur les têtes. Il gagne de l'expérience pendant la partie pour améliorer ses capacités, et charge son ult avec des points de style. Chaque rôle a son propre plan de jeu.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["**Le fight passe avant l'expérience** : les selfies se prennent quand tes cooldowns sont dépensés.", "Ton premier dash doit **toucher un ennemi** : c'est lui qui débloque les dashes bonus.", "Lance ton ult **tôt** : mourir avec l'ult chargée la fait perdre."], "difficulty": 2, "tags": ["Trois rôles", "Montée en niveau", "Polyvalent", "Rebonds"], "strengths": ["Trois rôles avec la même mécanique", "Passif de régénération contre le burst", "Ult rapide à charger"], "weaknesses": ["Faible tant qu'il n'a pas ses améliorations", "Perd toute sa jauge d'ult en mourant", "Pistolets peu efficaces à distance (Vanguard)"], "playbook": [{"when": "Tu viens d'achever un ennemi et le fight continue", "then": "Pas de selfie maintenant. Prends-le **quand tes cooldowns sont dépensés** ou une fois le fight gagné : tu es invulnérable pendant l'animation."}, {"when": "Tu sors les katanas", "then": "**Premier dash sur un ennemi** : il débloque les dashes bonus, qui servent ensuite à te déplacer."}, {"when": "Ton ult est chargée et tu es en danger", "then": "**Lance-la tout de suite** : la jauge de style retombe à zéro si tu meurs."}, {"when": "Une cible est protégée par une bulle", "then": "Ne dashe pas dessus : un dash sur une bulle compte comme raté et part en cooldown."}, {"when": "Tu joues Strategist et le fight va commencer", "then": "Avance **avec ton équipe dans ton aura** et lance l'ult aux katanas dès le début : elle doit durer plus longtemps que celle d'en face."}, {"when": "Tu joues Vanguard et une ult à projectile arrive (Magneto, Iron Man, Namor)", "then": "**Dôme** : il protège ce qui se trouve dedans et coupe aussi les soins d'un tank isolé."}], "sections": [{"title": "Philosophie de jeu", "lead": "Deadpool progresse en cours de partie : le temps, les dégâts et les selfies pris sur ses victimes lui donnent de l'expérience, à dépenser en améliorations. L'expérience est commune aux trois rôles.", "ability": "", "key": "", "kind": "tips", "items": ["Après un coup de grâce, la **touche de selfie** près de la victime rapporte beaucoup d'expérience et te rend invulnérable le temps de la pose.", "Raisonne comme dans un MOBA : **achète tes améliorations pendant les temps morts**, jamais en plein fight.", "Ta jauge d'ult monte de E à S selon ce que tu réussis, comme dans un jeu de combat. **Elle retombe à zéro à ta mort.**", "Ton **passif de régénération** se déclenche quand tu encaisses un gros burst : il te fait survivre à ce qui tuerait un autre héros.", "Pour un rebond, saute quand **tes pieds sont dans la tête** de la cible, pas au-dessus."], "diagram": "brawl"}, {"title": "Version Vanguard", "lead": "Un tank de harcèlement : il tient l'espace en étant assez pénible pour que l'adversaire soit obligé de s'occuper de lui.", "ability": "", "key": "", "kind": "tips", "items": ["Joue **près de l'ennemi** : même améliorés en saison 10, ses pistolets perdent des dégâts avec la distance.", "Le **dôme** coupe les soins d'un tank isolé, gagne le duel contre une Hela et protège d'une ult à projectile.", "L'**aura** accélère fortement ta cadence : allume-la pour ton engage ou pour gagner un duel.", "Depuis la saison 11, la **zone de provocation** ne donne plus de vie bonus à tes alliés, mais t'en donne davantage (400) : elle te protège toi, plus ton équipe.", "Améliorations : **zone de provocation, puis dash, puis l'ult aux katanas**. Monte le dôme plus tôt si tu es le seul tank.", "L'ult aux katanas est ton assurance-vie : elle te permet d'aller forcer les ults adverses."], "diagram": ""}, {"title": "Version Duelist", "lead": "Il use l'adversaire à distance au pistolet, puis sort les katanas pour achever.", "ability": "", "key": "", "kind": "tips", "items": ["Tiens-toi **un peu plus loin** qu'en tank : ses pistolets portent mieux dans ce rôle.", "Lance le **boomerang** comme une grenade, **aux pieds** : la zone tourne sur place avant de revenir.", "Première amélioration : **la tête lancée** (trois lancers, puis explosion). Fais coïncider ton dash avec le troisième lancer.", "Ensuite, les **dashes qui se relancent à chaque ennemi touché** : au contact, tu deviens presque intouchable. Gardes-en un pour le mini-jeu de l'ult.", "Les **rebonds sur les têtes** chargent l'ult et donnent de la vie bonus.", "L'ult aux pistolets rend sa cible vulnérable : à utiliser sur un support qui s'apprête à lancer la sienne."], "diagram": ""}, {"title": "Version Strategist", "lead": "La plus forte des trois : beaucoup de soins, une aura qui augmente les dégâts alliés et une ult qui se charge très vite.", "ability": "", "key": "", "kind": "tips", "items": ["Les pistolets soignent **sans perte à distance** : c'est ton soin principal.", "Le **boomerang** soigne les alliés et blesse les ennemis : lance-le entre les deux équipes.", "**Katanas et dash** soignent autour de toi : sors-les en brawl serré ou pour défendre ton autre support contre un diver.", "L'**aura améliorée** donne un bonus de dégâts à tes alliés : redoutable avec Phoenix ou Black Widow.", "Rebondir sur un **allié blessé** charge ton ult.", "Améliorations : **tête lancée**, puis **ult aux katanas**, puis zone de provocation pour ta sécurité."], "diagram": ""}, {"title": "Les katanas et le dash", "lead": "Maj alterne entre pistolets et katanas. Aux katanas, le clic droit lance un dash ; s'il touche un ennemi, tu gagnes des dashes bonus.", "ability": "", "key": "Maj · Clic D", "kind": "default", "items": ["**Premier dash sur un ennemi**, dashes bonus pour bouger : jamais l'inverse.", "Dépenser tous tes dashes avant l'ult t'empêche de **finir le mini-jeu**.", "Changer d'arme remet à zéro le compteur du tir explosif des pistolets améliorés."], "diagram": "", "scene": {"title": "Le premier dash", "caption": "Les dashes bonus ne se gagnent que sur un ennemi touché. Le premier dash décide donc de toute ta mobilité.", "steps": ["Ton premier dash traverse un ennemi : tu gagnes les dashes bonus.", "Tu frappes aux katanas.", "Les dashes bonus te sortent du fight."], "els": [{"t": "pawn", "at": [120, 96], "team": "me", "ghost": true}, {"t": "path", "kind": "move", "team": "me", "pts": [[120, 96], [236, 96]], "n": 1}, {"t": "pawn", "at": [196, 96], "team": "enemy", "role": "tank", "label": "Touché", "above": true}, {"t": "pawn", "at": [236, 96], "team": "me", "ghost": true}, {"t": "cone", "at": [236, 96], "to": [268, 84], "spread": 80, "team": "me", "n": 2}, {"t": "pawn", "at": [266, 84], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [270, 124], "team": "enemy", "role": "dps"}, {"t": "path", "kind": "move", "team": "me", "pts": [[236, 96], [200, 150], [140, 140]], "n": 3}, {"t": "pawn", "at": [140, 140], "team": "me"}, {"t": "note", "at": [206, 30], "text": "+ dashes bonus", "team": "me"}, {"t": "pawn", "at": [296, 50], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [230, 40], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [84, 70], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [70, 118], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [40, 80], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [40, 130], "team": "ally", "role": "heal"}]}}, {"title": "Les ultimes", "lead": "L'ult change selon l'arme en main. Celle des katanas lance un mini-jeu : rebonds, dashes ou boomerangs réussis la prolongent et la renforcent.", "ability": "", "key": "Q", "kind": "default", "items": ["Le mini-jeu se suit **en bas à droite** de l'écran.", "En **Vanguard et en Strategist**, l'ult aux katanas est presque toujours la bonne.", "En **Duelist**, l'ult aux pistolets sert à isoler un support clé.", "Mieux vaut la lancer trop tôt que **mourir avec**."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Prendre un selfie **en plein fight**.", "Dépenser le **premier dash pour se déplacer**.", "**Mourir avec l'ult** chargée.", "En Strategist, lancer l'ult **loin de son équipe**.", "En Vanguard, jouer **trop loin** de l'ennemi."], "diagram": ""}], "combos": [], "counters": [{"hero": "the-thing", "note": "Il gagne le corps à corps et empêche tes rebonds."}, {"hero": "hela", "note": "Elle te punit à distance tant que tu n'as pas tes améliorations."}, {"hero": "phoenix", "note": "Son burst passe à travers ta régénération dès qu'elle est consommée."}], "synergies": [{"hero": "phoenix", "note": "L'aura du Deadpool Strategist lui permet de tuer en une explosion."}, {"hero": "black-widow", "note": "Avec l'aura, son tir à la tête devient mortel."}, {"hero": "winter-soldier", "note": "Un brawler qui avance avec le Deadpool Vanguard."}, {"hero": "wolverine", "note": "Il profite de l'espace que tu ouvres au contact."}, {"hero": "groot", "note": "Ses murs créent les couloirs serrés où tes soins de zone valent le plus."}], "sources": [{"url": "https://www.youtube.com/watch?v=JfrdVuQ5mn0", "title": "Deadpool Guide", "author": "Paz (padswagger)"}, {"title": "Ultimate Deadpool Guide (Beginner/Advanced)", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=Lb-cnglbx3w"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Gumbo Chimichangas", "partners": ["gambit"], "key": "", "text": "Saut cinétique avec un anneau de chimichangas. **Amélioré :** Étourdit à l'atterrissage."}, {"name": "Hel-Yeah, Honey", "partners": ["hela"], "key": "", "text": "Deadpool débloque une amélioration en plus pour ses Desert Eagles et ses katanas."}, {"name": "Loudmouth Mercs", "partners": ["elsa-bloodstone"], "key": "", "text": "Munitions spéciales qui provoquent et ralentissent. **Amélioré :** Plus de gain d'instinct."}, {"name": "Mr. Pool's Interdimensional Toy Box", "partners": ["jeff-the-land-shark"], "key": "", "text": "Une peluche provoque les ennemis et soigne. **Amélioré :** Provocation et dégâts renforcés."}], "changes": [{"season": "Saison 11", "text": "Forme Vanguard, The Big Test : ne donne plus de vie bonus aux alliés proches ; vie bonus pour soi 300 → 400."}, {"season": "Saison 11", "text": "Forme Vanguard, The Big Test amélioré : plus de vie bonus aux alliés à chaque coup ; conversion dégâts → vie bonus pour soi 1 → 1,5."}, {"season": "Saison 10", "text": "Vanguard : Desert Eagles moins pénalisées à distance (75 % des dégâts à 30 m au lieu de 50 %), Ban Hammer soigne 35/s au lieu de 25/s, améliorations moins chères en XP."}, {"season": "Saison 10", "text": "Duelist : tir des Desert Eagles 38 → 42."}, {"season": "Saison 10", "text": "Strategist : vie de base 250 → 275, cooldown 12 s → 10 s."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'deadpool' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Devil Dinosaur est un Vanguard de brawl qui vit du saignement. Il mord, fait saigner, gagne de la vie bonus sur chaque dégât de saignement, et attrape les tanks adverses pour les jeter dans son équipe. Il ne peut pas être déplacé, et ses dégâts en pourcentage font fondre les autres Vanguards.", "patch_note": "Conseils issus d'un guide enregistré à la sortie du héros, mis à jour avec les nerfs de la saison 11 (attrape plus courte, barrière sans ralentissement, moins de vie bonus). Vérifie les détails en jeu.", "tldr": ["**Fais saigner le plus d'ennemis possible** : chaque saignement te rend de la vie bonus.", "Ta boucle : **morsure, attrape, jet dans ton équipe, Frenzied Feast**.", "**Harcèle le tank adverse** : s'il passe son temps à se sauver, il ne prend pas d'espace."], "difficulty": 1, "tags": ["Brawl", "Saignement", "Déplacement d'ennemis", "Anti-tank"], "strengths": ["Gagne presque tous les duels de tanks", "Ne peut être ni repoussé ni projeté", "Jette une cible dans son équipe"], "weaknesses": ["Énorme hitbox", "Une seule mobilité, qui est aussi son attrape", "Nerfé en saison 11 : moins de contrôle et de vie bonus"], "playbook": [{"when": "Le tank adverse est à portée", "then": "**Morsure** pour le faire saigner, puis **attrape** : s'il saigne, tu le soulèves et tu le jettes vers ton équipe."}, {"when": "Tu viens de jeter une cible dans ton équipe", "then": "**Frenzied Feast** immédiatement, placé entre elle et ses supports : ton corps bloque leurs soins."}, {"when": "Un volant domine le fight", "then": "**Rayon d'impact maintenu** une à deux secondes : il tombe au sol."}, {"when": "Une ult de dégâts vise ton équipe (Magneto, Iron Man)", "then": "**Barrière** : elle te suit et couvre ce qui est autour de toi. Elle ne dure plus que 4 secondes."}, {"when": "Tu es entouré et bas en vie", "then": "**Attrape en visant le sol loin de toi** : c'est aussi ta seule sortie."}, {"when": "Ton ult est prête", "then": "Engage à l'attrape, puis **ult** : Frenzied Feast se relance presque sans délai."}], "sections": [{"title": "Philosophie de jeu", "lead": "Tes dégâts en pourcentage et ta vie bonus te font gagner la plupart des duels de tanks. Ton travail est de rendre la vie impossible au Vanguard adverse.", "ability": "", "key": "", "kind": "tips", "items": ["Joue **au front** et répartis le saignement sur plusieurs ennemis.", "Concentre-toi sur **les tanks** : c'est sur eux que le pourcentage fait le plus mal.", "Ton attrape est aussi ta seule mobilité : hors ult, elle sert d'abord à **te replacer**.", "Tu es **insensible aux déplacements forcés** et tu encaisses moins à la tête.", "Depuis la saison 11, le saignement te rend moins de vie bonus : tu ne peux plus ignorer les soins de ton équipe."], "diagram": "brawl"}, {"title": "Morsure et queue", "lead": "Ta morsure applique le saignement : des dégâts en pourcentage de la vie, qui te rendent de la vie bonus.", "ability": "Morsure · coup de queue", "key": "Clic G", "kind": "default", "items": ["La morsure est le moyen **le plus rapide** de faire saigner.", "Ta mêlée est un **coup de queue** : elle frappe derrière et sur les côtés, pas ce que tu regardes.", "Place-toi **entre deux ennemis** : tu mords l'un et tu fouettes l'autre."], "diagram": ""}, {"title": "Rayon d'impact", "lead": "Un rayon perçant qui fait saigner, ralentit et cloue les volants au sol. Il consomme une jauge.", "ability": "Impact Beam", "key": "Clic D", "kind": "default", "items": ["**Maintiens-le une à deux secondes** sur la même cible : un appui bref n'applique presque rien.", "C'est ta seule réponse aux **volants**.", "C'est aussi ta seule attaque arrêtée par un **bouclier**."], "diagram": ""}, {"title": "Attraper et jeter", "lead": "Un bond suivi d'une morsure. Si la cible saigne déjà, tu la soulèves et tu la jettes.", "ability": "Savage Predation", "key": "", "kind": "default", "items": ["La distance du bond dépend de ta visée : **le sol pour un petit bond, le ciel pour le plus long**.", "Jette la cible **dans ton équipe**, puis Frenzied Feast.", "Ta silhouette **bloque les soins directs** destinés à ta cible : place-toi entre elle et ses supports.", "Le contrôle est plus court depuis la saison 11 : ton équipe doit tirer **au moment où la cible atterrit**."], "diagram": "", "scene": {"title": "Mordre, attraper, jeter", "caption": "L'attrape ne soulève que les cibles qui saignent déjà. La morsure passe donc toujours en premier.", "steps": ["Morsure : le tank adverse saigne.", "Attrape, puis tu le jettes dans ton équipe.", "Frenzied Feast, placé entre lui et ses supports."], "els": [{"t": "pawn", "at": [200, 118], "team": "me", "ghost": true}, {"t": "pawn", "at": [228, 96], "team": "enemy", "role": "tank", "ghost": true}, {"t": "note", "at": [252, 104], "text": "1", "team": "me"}, {"t": "path", "kind": "pull", "team": "me", "pts": [[222, 88], [170, 30], [114, 60]], "n": 2}, {"t": "pawn", "at": [104, 66], "team": "enemy", "role": "tank", "label": "Jeté"}, {"t": "path", "kind": "move", "team": "me", "pts": [[200, 118], [172, 132], [156, 96]], "n": 3}, {"t": "pawn", "at": [156, 84], "team": "me", "label": " "}, {"t": "path", "kind": "heal", "team": "enemy", "pts": [[290, 60], [168, 80]]}, {"t": "note", "at": [240, 46], "text": "soins bloqués", "team": "me"}, {"t": "pawn", "at": [64, 50], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [60, 100], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [96, 130], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [40, 140], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [290, 60], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [292, 124], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [250, 154], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [270, 20], "team": "enemy", "role": "dps"}]}}, {"title": "Barrière", "lead": "Un bouclier qui t'entoure et te suit. Depuis la saison 11, il ne ralentit plus les ennemis, dure 4 secondes et absorbe un peu moins.", "ability": "Buddy Barrier", "key": "", "kind": "default", "items": ["Avance avec lui pour **prendre un passage**.", "Il couvre ton équipe contre une **grosse ult de dégâts**, à condition de l'ouvrir au bon moment.", "Il ne retient plus personne : pour garder une cible chez toi, compte sur ton corps et sur Frenzied Feast."], "diagram": ""}, {"title": "Frenzied Feast", "lead": "Quatre morsures enchaînées, plus fortes sur une cible qui saigne, et converties en vie bonus.", "ability": "Frenzied Feast", "key": "", "kind": "default", "items": ["**Fais toujours saigner avant.**", "Juste après un jet dans ton équipe, c'est très souvent une élimination."], "diagram": ""}, {"title": "Ultime", "lead": "Tu entres en rage : tu vas beaucoup plus vite, et chaque seconde un piétinement projette, ralentit et fait saigner tout ce qui t'entoure.", "ability": "Devil Beast Rampage", "key": "Q", "kind": "default", "items": ["Frenzied Feast **se relance presque instantanément** pendant l'ult.", "L'attrape revient aussi très vite : si la cible s'échappe, tu la reprends.", "C'est le moment où tu peux **engager à l'attrape** sans arrière-pensée."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Utiliser le rayon **par petits appuis**.", "Engager à l'attrape **sans ult** et rester seul chez l'ennemi.", "Poursuivre les héros fragiles au lieu de **punir le tank**.", "Oublier que la queue **ne frappe pas devant**.", "Compter encore sur la barrière pour **ralentir**."], "diagram": ""}], "combos": [], "counters": [{"hero": "the-punisher", "note": "Tir continu sur la plus grosse hitbox du jeu."}, {"hero": "cyclops", "note": "Rayon et tirs à la tête sans effort sur ta silhouette."}, {"hero": "blade", "note": "Son anti-soin coupe les soins dont tu dépends davantage depuis la saison 11."}, {"hero": "hela", "note": "Elle t'use à une distance où tu ne peux rien."}, {"hero": "magneto", "note": "Son rideau arrête ton rayon et sa bulle protège la cible que tu attrapes."}], "synergies": [{"hero": "the-punisher", "note": "Votre team-up le fait monter sur ton dos (cooldown allongé à 18 secondes en saison 11)."}, {"hero": "elsa-bloodstone", "note": "Votre team-up renforce son piège, et vous écrasez ensemble le tank adverse."}, {"hero": "jeff-the-land-shark", "note": "Il te chevauche et vous vous soignez mutuellement."}, {"hero": "luna-snow", "note": "Sa marque sur toi : tu encaisses, son ult se charge."}, {"hero": "winter-soldier", "note": "Il attrape, tu jettes : leur front n'a plus de place."}], "sources": [{"title": "Ultimate Devil Dinosaur Guide (Beginner/Advanced)", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=Mu48nMPiYdI"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Prehistoric Trap", "partners": ["elsa-bloodstone"], "key": "", "text": "Smoky Snare immobilise et gaze (cooldown 12 s en saison 11). **Amélioré :** Charges de piège supplémentaires (une de moins en saison 11)."}, {"name": "Primal Punishment", "partners": ["the-punisher"], "key": "", "text": "Canons magnétiques qui font saigner (cooldown 18 s en saison 11). **Amélioré :** The Punisher chevauche Devil Dinosaur et partage les dégâts."}, {"name": "Surf & Turf", "partners": ["jeff-the-land-shark"], "key": "", "text": "Jet d'eau qui blesse et soigne. **Amélioré :** Jeff chevauche Devil Dinosaur, et les deux se soignent."}], "changes": [{"season": "Saison 11", "text": "Savage Predation : contrôle 0,8 → 0,6 s, projection qui suit 1,5 → 1,2 s."}, {"season": "Saison 11", "text": "Buddy Barrier : plus de ralentissement de 15 %, durée 6 → 4 s, bouclier 450 → 400."}, {"season": "Saison 11", "text": "Apex Advantage : vie bonus égale à 125 % des dégâts de saignement (au lieu de 150 %)."}, {"season": "Saison 11", "text": "Team-up avec The Punisher (Primal Punishment) : cooldown 12 → 18 s."}, {"season": "Saison 10", "text": "Saignement : cumuls de 1 s au lieu de 0,5 s, dégâts 0,75 % → 1,2 %."}, {"season": "Saison 10.5", "text": "Vie de base 850 → 825."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'devil-dinosaur' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Doctor Strange est le Vanguard le plus polyvalent : un grand bouclier pour couvrir son équipe, de vrais dégâts à distance, un portail qui ramène cinq joueurs sur un point et une ult qui étourdit un groupe entier. Il convient au brawl comme au poke, moins aux compos de dive.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["**Économise ton bouclier** : avance de couvert en couvert et garde-le pour le burst.", "Remplis ta **jauge de ténèbres**, puis libère-la avant qu'elle ne déborde.", "Ne te retourne pas pour peel : ta place est **devant**."], "difficulty": 2, "tags": ["Bouclier", "Portail", "Combos", "Contrôle de zone"], "strengths": ["Bouclier qui se lève et se range instantanément", "Portail : le meilleur outil de recontestation du jeu", "Ult d'étourdissement de zone"], "weaknesses": ["La mêlée traverse son bouclier", "Ult longue à incanter et facile à interrompre", "Portail au cooldown très long"], "playbook": [{"when": "Une ult à projectile vise tes supports (Iron Man, Magneto, Hela)", "then": "**Bouclier au dernier moment**, face à l'ult. Levé trop tôt, il est brisé avant qu'elle parte. Contre Hela, monte en lévitation pour bloquer de face."}, {"when": "Ta jauge de ténèbres est presque pleine", "then": "**Libère-la** au contact (tir, mêlée, explosion). Pleine trop longtemps, elle t'inflige un anti-soin."}, {"when": "Ton équipe est morte et le point est contesté", "then": "**Portail** depuis le spawn jusqu'au point, et passe **le premier**, bouclier levé."}, {"when": "Tu veux lancer ton ult", "then": "Fais d'abord dépenser les contrôles (gel de Luna, bulle de Magneto, poussée d'Invisible Woman), puis **tombe d'une hauteur ou d'un côté**, jauge chargée."}, {"when": "Un Punisher tire sur ton bouclier", "then": "**Range-le** et encaisse avec ta vie : il brise le bouclier vite mais te tue lentement."}, {"when": "Un tank adverse s'avance ou une Luna lance son ult", "then": "Place ton bouclier **entre la cible et ses soins** : tu coupes leur ligne de vue."}], "sections": [{"title": "Philosophie de jeu", "lead": "Strange s'adapte à ta compo : il protège un brawl, couvre des tireurs à distance ou tient une hauteur avec ses DPS.", "ability": "", "key": "", "kind": "tips", "items": ["L'erreur la plus répandue : **tenir le bouclier en permanence** et ne jamais tirer. Alterne tirs et courtes levées de bouclier.", "Si ta backline se fait diver, **ce n'est pas à toi de te retourner**. L'autre tank ou un DPS s'en charge : toi, tu tiens la ligne.", "Il est à son meilleur contre les compos **sans mêlée**. Face à une Emma Frost ou un Wolverine qui ignorent ton bouclier, The Thing ou Emma sont de meilleurs choix.", "Depuis la saison 11, le bouclier a un peu moins de vie et se régénère moins vite : chaque seconde où il reste levé pour rien se paie plus cher."], "diagram": "space"}, {"title": "Dagues et ténèbres", "lead": "Tes salves de dagues remplissent une jauge de ténèbres, que tu libères en explosion autour de toi. Plus elle est pleine, plus l'explosion fait mal.", "ability": "Daggers of Denak · Maelstrom of Madness", "key": "Clic G", "kind": "default", "items": ["Glisse un **coup de mêlée entre deux salves** : il ajoute des dégâts, remplit la jauge et raccourcit le rechargement.", "Les dagues tournoient : à distance, vise **légèrement à droite** de la cible.", "Combo d'exécution : **tir, mêlée, tir, explosion**, avec au moins la moitié de la jauge.", "Le rechargement est effectif **à la moitié de la barre** : annule la fin avec une mêlée ou une levée de bouclier.", "Une jauge pleine trop longtemps te pose un **anti-soin** : décharge-la avant, surtout à bas PV."], "diagram": ""}, {"title": "Bouclier", "lead": "Un grand bouclier qui se lève et se range instantanément. Il se régénère lentement une fois rangé : le tank qui garde le sien le plus longtemps gagne le fight.", "ability": "Shield of the Seraphim", "key": "Clic D", "kind": "default", "items": ["Bloque le **burst** : Hawkeye, Hela, Phoenix. Laisse passer les dégâts continus d'un Punisher.", "Contre une ult qui vise tes supports, lève-le **au moment où elle part**, pas avant.", "Offensivement, il **coupe les soins** : place-le entre un tank avancé et ses supports, ou en travers d'une ult de Luna.", "Joue-le par **petites levées**, comme un parapluie qu'on ouvre et qu'on referme, pas comme un mur."], "diagram": "", "scene": {"title": "Couper les soins avec le bouclier", "caption": "Le bouclier bloque les projectiles dans les deux sens : placé derrière un tank adverse, il arrête les soins qui lui sont destinés.", "steps": ["Le tank adverse s'avance.", "Tu passes à sa hauteur et tu lèves le bouclier entre lui et ses supports.", "Privé de soins, il meurt sous les tirs de ton équipe."], "els": [{"t": "pawn", "at": [176, 102], "team": "enemy", "role": "tank", "label": "Trop avancé", "above": true}, {"t": "note", "at": [176, 130], "text": "1", "team": "enemy"}, {"t": "pawn", "at": [124, 46], "team": "me", "ghost": true}, {"t": "path", "kind": "move", "team": "me", "pts": [[124, 46], [186, 30], [214, 86]], "n": 2}, {"t": "pawn", "at": [214, 98], "team": "me"}, {"t": "bar", "from": [236, 60], "to": [236, 136], "team": "me"}, {"t": "path", "kind": "heal", "team": "enemy", "pts": [[286, 78], [244, 90]]}, {"t": "path", "kind": "heal", "team": "enemy", "pts": [[286, 120], [244, 108]]}, {"t": "pawn", "at": [286, 78], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [286, 120], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [264, 34], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [268, 158], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [108, 112], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [104, 152], "team": "ally", "role": "dps"}, {"t": "path", "kind": "shot", "team": "ally", "pts": [[108, 112], [176, 102]], "n": 3}, {"t": "path", "kind": "shot", "team": "ally", "pts": [[104, 152], [176, 102]], "n": 3}, {"t": "pawn", "at": [54, 84], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [52, 128], "team": "ally", "role": "heal"}]}}, {"title": "Portail", "lead": "Deux portails reliés qui restent ouverts quelques secondes. Le cooldown est très long : chaque portail doit avoir un but.", "ability": "Pentagram of Farallah", "key": "F", "kind": "default", "items": ["**Revenir du spawn** pour recontester : la sortie en hauteur pour des tireurs, face au point pour des brawlers.", "**Passe toujours en premier.** Un support qui traverse avant toi arrive seul au milieu des ennemis.", "**Fermer un passage** : les deux extrémités se placent librement, et une boucle entre deux portes empêche l'ennemi de sortir de son spawn.", "**Préparer une ult**, la tienne ou celle d'un allié, en faisant arriver l'équipe par un angle inattendu.", "En défense, garde-le pour le retour. En attaque, tu peux le dépenser tôt : il reviendra avant la fin de la manche."], "diagram": "", "scene": {"title": "Le portail de retour", "caption": "Un portail ramène cinq joueurs sur le point en deux secondes. Sans lui, ils arrivent un par un.", "steps": ["Ton équipe réapparaît : tu ouvres l'entrée devant le spawn.", "Tu poses la sortie à couvert, près du point.", "Tu passes le premier, bouclier levé ; l'équipe suit groupée."], "els": [{"t": "area", "at": [6, 44], "size": [72, 96], "label": "Spawn", "team": "ally"}, {"t": "bar", "from": [94, 68], "to": [94, 116], "team": "me", "label": "Entrée", "n": 1}, {"t": "cover", "at": [200, 18], "size": [14, 54], "label": "Mur"}, {"t": "bar", "from": [178, 26], "to": [178, 66], "team": "me", "label": "Sortie", "n": 2}, {"t": "mark", "at": [240, 112], "kind": "objective", "team": "me", "label": "Point"}, {"t": "pawn", "at": [26, 76], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [26, 114], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [54, 66], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [54, 122], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [204, 108], "team": "me"}, {"t": "path", "kind": "move", "team": "me", "pts": [[180, 50], [176, 96], [204, 108]], "n": 3}, {"t": "pawn", "at": [276, 100], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [262, 50], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [268, 154], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [304, 122], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [302, 74], "team": "enemy", "role": "heal"}]}}, {"title": "Lévitation", "lead": "Un vol de quelques secondes. Le cooldown ne démarre qu'à la fin du vol.", "ability": "Cloak of Levitation", "key": "", "kind": "default", "items": ["Pour **menacer un DPS** installé en hauteur.", "Pour **feinter ton ult** : monte, redescends bouclier levé, et le gel de Luna part dans le vide.", "Pour **te faire soigner** hors de portée d'un brawler."], "diagram": ""}, {"title": "Ultime", "lead": "Après une longue incantation, tu étourdis tous les ennemis autour de toi et tu sépares leur âme de leur corps. Les dégâts infligés à l'âme sont reportés sur le corps.", "ability": "Eye of Agamotto", "key": "Q", "kind": "default", "items": ["Pendant l'incantation, un étourdissement, une poussée ou une attraction l'annule : **fais dépenser ces contrôles avant**.", "Entre avec **une jauge de ténèbres chargée** : tir, mêlée, explosion tue les héros fragiles.", "Toucher **l'âme et le corps** en même temps double les dégâts de l'explosion.", "N'entre pas en sautant au milieu : **tombe d'un flanc ou d'une hauteur**, hors de leur champ de vision.", "Laisse passer la première ult de soin adverse et **vise la suivante** : celle-là ne pourra pas être couverte."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Faire **briser son bouclier** par des dégâts sans importance.", "Laisser la jauge **déborder**.", "Se retourner pour **peel** et abandonner la ligne.", "Laisser un support **traverser le portail en premier**.", "Lancer l'ult **de face**, là où tout le monde l'attend."], "diagram": ""}], "combos": [{"note": "Avec **au moins la moitié de la jauge**.", "steps": [{"key": "Clic G", "label": "tir"}, {"key": "Mêlée", "label": ""}, {"key": "Clic G", "label": "tir"}, {"key": "", "label": "Explosion des ténèbres"}], "title": "Éliminer un fragile"}], "counters": [{"hero": "emma-frost", "note": "Elle traverse ton bouclier, t'étrangle et interrompt ton ult."}, {"hero": "hulk", "note": "Ses coups passent à travers le bouclier."}, {"hero": "the-thing", "note": "Au corps à corps, ton bouclier ne t'aide pas et il te met une pression constante."}, {"hero": "invisible-woman", "note": "Sa poussée t'éjecte pendant l'incantation de ton ult."}, {"hero": "wolverine", "note": "Il ignore le bouclier et t'emporte loin de tes soins."}], "synergies": [{"hero": "magneto", "note": "Il absorbe le tir continu, toi le burst : la paire de tanks classique."}, {"hero": "winter-soldier", "note": "Un DPS qui avance à l'abri de ton bouclier."}, {"hero": "the-punisher", "note": "Il tient sa ligne de tir derrière toi sans avoir à bouger."}, {"hero": "phoenix", "note": "Ton ult regroupe et immobilise les cibles pour son explosion."}, {"hero": "luna-snow", "note": "Elle soigne en sécurité derrière ton bouclier."}, {"hero": "hulk", "note": "Votre team-up charge ta jauge plus vite et ajoute des dégâts gamma."}], "sources": [{"url": "https://www.youtube.com/watch?v=8ZyNSU1fBAk", "title": "Doctor Strange Guide", "author": "Paz (padswagger)"}, {"title": "The Only Dr Strange Guide You'll Ever Need", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=sUEq8_2xjI0"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Chain of Cyttorak", "partners": ["magik"], "key": "", "text": "Une chaîne relie deux ennemis. **Amélioré :** Relie des groupes entiers."}, {"name": "Gamma Maelstrom", "partners": ["hulk"], "key": "", "text": "Le Maelstrom gamma accélère la charge. **Amélioré :** Garde et stocke l'énergie (25 au minimum en saison 11)."}, {"name": "Psionic Vortex", "partners": ["invisible-woman"], "key": "", "text": "Projette les ennemis et renforce le bouclier de Strange (+100 en saison 11). **Amélioré :** Vie bonus pour Strange selon ses dégâts ; plus de vie bonus pour les alliés."}, {"name": "Sorcerers Supreme", "partners": ["scarlet-witch"], "key": "", "text": "Salve de missiles mystiques. **Amélioré :** Devient activable à volonté."}], "changes": [{"season": "Saison 11", "text": "Shield of the Seraphim : bouclier 850 → 800, récupération 60 → 50/s."}, {"season": "Saison 11", "text": "Team-up avec Invisible Woman : bonus de bouclier 150 → 100 ; version améliorée sans vie bonus pour les alliés, conversion pour soi 0,5 → 0,7."}, {"season": "Saison 11", "text": "Team-up avec Hulk (Gamma Maelstrom amélioré) : énergie minimale conservée 50 → 25."}, {"season": "Saison 10", "text": "Daggers of Denak plus rapides (60 → 80 m/s) et cadence améliorée (0,9 s → 0,8 s)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'doctor-strange' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Elsa Bloodstone est une Duelist de courte portée qui commence le fight avec son front, puis glisse sur un angle pour finir. Chaque capacité lui donne quelques secondes de fusil à éléphant, dont les dégâts en pourcentage de la vie font fondre les tanks, et son passif réduit le cooldown de son dash au fil de la manche.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["Commence **avec ton équipe** pour remplir ton passif, puis prends un léger angle.", "**Un tir de fusil à éléphant après chaque capacité** : tes dégâts sont là.", "**Recharge entre chaque échange** : quatre tirs seulement dans le chargeur."], "difficulty": 2, "tags": ["Ligne de front", "Combos", "Anti-tank", "Mobilité"], "strengths": ["Dégâts en pourcentage : anti-tank", "Dash presque permanent une fois le passif plein", "Piège invisible et indestructible"], "weaknesses": ["Portée efficace très courte (10 m en saison 11)", "Quatre tirs par chargeur", "Perd un palier de passif à chaque mort"], "playbook": [{"when": "Le fight commence", "then": "Tire sur **le tank adverse** avec ton équipe : tu remplis ton passif et il recule."}, {"when": "Tu viens d'utiliser une capacité", "then": "**Tire** : pendant quelques secondes, ton arme est le fusil à éléphant."}, {"when": "Une cible fragile est à portée de charge", "then": "**Tir, E, tir, E, tir** : la charge la soulève, la détonation te ramène en arrière."}, {"when": "Un diver vient te chercher sur ton angle (Star-Lord, Psylocke)", "then": "**Piège à tes pieds** avant qu'il arrive, puis dash sur lui dès qu'il est immobilisé."}, {"when": "Une cible se cache derrière une bulle ou un bouclier", "then": "**Balle vivante** : elle fait plus de dégâts aux boucliers et à la vie bonus."}, {"when": "Un support adverse lance une ult de zone", "then": "**Ult depuis l'arrière de ton front** : la créature l'emporte hors de sa zone."}], "sections": [{"title": "Philosophie de jeu", "lead": "Elsa suit le schéma des Duelists de mêlée courte : au centre avec ses tanks pour ouvrir, puis sur un angle décalé pour chercher l'élimination.", "ability": "", "key": "", "kind": "tips", "items": ["Vise **les tanks d'abord** : tes dégâts en pourcentage les font reculer, ce qui libère l'accès à la backline.", "Un passif plein te donne un dash quasi permanent : **ta vie vaut plus que ton kill**.", "Après une élimination sur leur front, avance d'un cran : tes tanks n'ont plus besoin de toi.", "Tu n'es pas une sniper. Depuis la saison 11, ton arme de base perd des dégâts **dès 10 mètres** : joue comme une Psylocke, par angles courts.", "Contre une compo anti-dive, reste avec ton équipe et garde ton piège pour leurs flankers."], "diagram": "angle"}, {"title": "Les deux fusils", "lead": "Ton arme de base tire des rafales instantanées. Après chaque capacité, tu passes quelques secondes au fusil à éléphant : il transperce les ennemis et inflige des dégâts en pourcentage de leur vie.", "ability": "Double-Barrel Blaster · Monster Piercer", "key": "Clic G", "kind": "default", "items": ["L'arme de base se disperse vite : **approche-toi avant de tirer**, surtout depuis un flanc.", "Le fusil à éléphant **traverse les ennemis** (pas les boucliers) et s'étale à l'horizontale : aligne plusieurs cibles pour charger ton ult.", "Les capacités **ne rechargent pas** l'arme de base : surveille ton chargeur."], "diagram": ""}, {"title": "Passif et dash", "lead": "Ta jauge d'instinct se remplit avec tes dégâts et tes éliminations. Chaque palier réduit le cooldown de ton dash, qui donne de la vie bonus et un tir de fusil à éléphant.", "ability": "Inherited Instinct · Helix Advance", "key": "", "kind": "default", "items": ["Jauge pleine, le dash est **presque toujours disponible** : dash, tir, dash, tir.", "Le dash part **dans la direction de ton déplacement**, pas de ta caméra : tu recules ou tu esquives sans quitter ta cible des yeux.", "Il est purement horizontal et coupe ton élan.", "La jauge ne descend qu'à ta mort (d'un palier) et en fin de manche."], "diagram": ""}, {"title": "Charge et recul", "lead": "Une charge vers l'avant qui projette les ennemis en l'air, puis une détonation qui te propulse en arrière. Chacune des deux parties t'offre un tir de fusil à éléphant.", "ability": "Ruthless Pursuit", "key": "E", "kind": "default", "items": ["Enchaînement de base : **tir, charge, tir, détonation, tir**. Il tue un héros fragile.", "La charge sert à tenter l'élimination, la détonation à **revenir en sécurité**.", "La détonation te pousse **dans ton dos** : oriente-toi avant de la déclencher.", "The Thing, Invisible Woman et Winter Soldier peuvent t'arrêter en plein retour."], "diagram": "", "scene": {"title": "Charge, détonation, retour", "caption": "La charge t'emmène au contact ; la détonation te ramène. Trois tirs de fusil à éléphant partent entre-temps.", "steps": ["Tir, puis charge : la cible décolle.", "Tir au contact, puis détonation : tu repars en arrière.", "Dernier tir depuis ta position de départ."], "els": [{"t": "cover", "at": [92, 108], "size": [14, 50], "label": "Mur"}, {"t": "pawn", "at": [150, 66], "team": "me", "ghost": true}, {"t": "path", "kind": "move", "team": "me", "pts": [[150, 66], [224, 82]], "n": 1}, {"t": "pawn", "at": [248, 88], "team": "enemy", "role": "heal", "label": "Cible", "above": true}, {"t": "pawn", "at": [224, 84], "team": "me", "ghost": true}, {"t": "path", "kind": "push", "team": "me", "pts": [[224, 90], [196, 150], [128, 132]], "n": 2}, {"t": "pawn", "at": [128, 132], "team": "me"}, {"t": "path", "kind": "shot", "team": "me", "pts": [[128, 132], [248, 88]], "n": 3}, {"t": "pawn", "at": [210, 30], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [286, 132], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [296, 56], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [264, 164], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [90, 60], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [52, 100], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [40, 60], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [40, 140], "team": "ally", "role": "heal"}]}}, {"title": "Balle vivante", "lead": "Une balle qui, après son premier impact, ricoche d'ennemi en ennemi et les marque à travers les murs.", "ability": "Living Bullet", "key": "Clic D", "kind": "default", "items": ["Elle ne se met à chercher des cibles **qu'après avoir touché** quelque chose : tire près de ta cible.", "Elle inflige **plus de dégâts aux boucliers et à la vie bonus** : bulle de Magneto, Cloak & Dagger, bouclier d'Invisible Woman.", "Les marques révèlent les **héros invisibles** et permettent de vérifier un angle mort.", "Tirer sur une cible marquée te donne un court bonus de vitesse."], "diagram": ""}, {"title": "Piège", "lead": "Un piège qui devient invisible et indestructible une seconde après la pose. L'ennemi qui marche dessus est immobilisé.", "ability": "Smoky Snare", "key": "", "kind": "default", "items": ["Contre le dive, pose-le **près de tes supports**.", "Sur ton angle, pose-le **à tes pieds** : celui qui vient te chercher s'y prend.", "Près d'un **pack de soin**, il attrape les cibles basses qui viennent se soigner.", "Une cible immobilisée est un kill : **dash dessus** immédiatement."], "diagram": ""}, {"title": "Ultime", "lead": "Une créature charge en ligne droite, saisit les ennemis sur son passage et les emporte. Un second appui la fait revenir vers toi.", "ability": "Apex Predator", "key": "Q", "kind": "default", "items": ["Lance-la **depuis l'arrière de ton front, vers l'avant** : en ligne droite à travers leur équipe, elle attrape plusieurs cibles.", "Elle **sort un support de son ult de zone** (Invisible Woman, Cloak & Dagger).", "Elle **intercepte une ult de Duelist** en approche (Winter Soldier, Spider-Man) en emportant son lanceur.", "La créature a peu de vie : une ult de Phoenix la détruit aussitôt.", "Elle se charge vite : ne la garde pas trois fights pour le contre parfait."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Lancer un combo **avec un chargeur vide**.", "Tirer **de trop loin** à l'arme de base.", "Oublier le **tir de fusil à éléphant** après une capacité.", "Garder l'ult **plusieurs fights**.", "Lancer l'ult **depuis un flanc éloigné**."], "diagram": ""}], "combos": [{"note": "Garde assez de munitions pour le lancer en entier.", "steps": [{"key": "Clic G", "label": "tir"}, {"key": "E", "label": "charge"}, {"key": "Clic G", "label": "tir"}, {"key": "E", "label": "détonation"}, {"key": "Clic G", "label": "tir"}], "title": "Combo de base"}, {"note": "Élimine une cible et te laisse ta fuite.", "steps": [{"key": "Clic G", "label": "tir"}, {"key": "E", "label": "charge"}, {"key": "Clic D", "label": "balle vivante"}, {"key": "Clic G", "label": "tir"}], "title": "Avec la balle vivante"}], "counters": [{"hero": "the-thing", "note": "Il bloque ta charge et ton retour. Use-le à distance sans entrer dans sa portée."}, {"hero": "hela", "note": "Elle te domine sur toute carte ouverte : tu n'as pas la portée pour répondre."}, {"hero": "phoenix", "note": "Même rapport de portée, et son ult détruit ta créature."}, {"hero": "luna-snow", "note": "Son ult la suit : ta créature ne l'en sort pas."}, {"hero": "gambit", "note": "Il libère ses alliés de la prise de ta créature."}], "synergies": [{"hero": "magneto", "note": "Un tank qui avance et te laisse tirer depuis le front."}, {"hero": "emma-frost", "note": "Vous écrasez ensemble le tank adverse en brawl."}, {"hero": "groot", "note": "Ses murs alignent les ennemis pour ta créature."}, {"hero": "winter-soldier", "note": "Deux anti-tanks sur la même cible : le front adverse fond."}, {"hero": "devil-dinosaur", "note": "Votre team-up renforce ton piège, dont le cooldown baisse en saison 11."}], "sources": [{"url": "https://www.youtube.com/watch?v=XTUTGUIFfUY", "title": "Elsa Bloodstone Guide", "author": "Paz (padswagger)"}, {"title": "Ultimate Elsa Bloodstone Guide (Beginner/Advanced)", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=dQjvW-u1Mbs"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Blood Moon", "partners": ["moon-knight"], "key": "", "text": "L'ankh piège invoque des serres. **Amélioré :** En invoque plusieurs."}, {"name": "Expert Instinct", "partners": ["winter-soldier"], "key": "", "text": "Les kills donnent des cumuls d'instinct. **Amélioré :** Augmente la vie bonus de Ceaseless Charge (55 en saison 10)."}, {"name": "Loudmouth Mercs", "partners": ["deadpool"], "key": "", "text": "Munitions spéciales qui provoquent et ralentissent. **Amélioré :** Plus de gain d'instinct."}, {"name": "Prehistoric Trap", "partners": ["devil-dinosaur"], "key": "", "text": "Smoky Snare immobilise et gaze (cooldown 12 s en saison 11). **Amélioré :** Charges de piège supplémentaires (une de moins en saison 11)."}], "changes": [{"season": "Saison 11", "text": "Double-Barrel Blaster : la baisse de dégâts avec la distance commence à 10 m au lieu de 20."}, {"season": "Saison 11", "text": "Team-up avec Devil Dinosaur : la version améliorée perd une charge ; cooldown de Smoky Snare 15 → 12 s."}, {"season": "Saison 10", "text": "Monster-Piercer 13 → 12 de dégâts de base, Helix Advance 30 → 25 de vie bonus."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'elsa-bloodstone' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Emma Frost est le Vanguard le plus complet du jeu. Elle charge son rayon pendant la première moitié du fight, puis passe en forme de diamant pour étrangler une cible et la projeter contre un mur. Une Emma dont le rayon n'est pas chargé ne pèse rien : tout son plan de jeu commence par là.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["Priorité absolue : **charger ton rayon**, puis ne plus le laisser retomber.", "Ton bouclier est un **outil**, pas un mur : il bloque un angle ou une ult, pas un flux de dégâts.", "En diamant : **étranglement, deux coups, coup de pied contre un mur**."], "difficulty": 2, "tags": ["Rayon", "Brawl", "Contrôle", "Polyvalente"], "strengths": ["Étranglement : étourdit et annule les ults", "Rayon qui monte en puissance", "Bouclier posé à distance"], "weaknesses": ["Faible tant que le rayon n'est pas chargé", "Bouclier fragile (350 en saison 11)", "Impuissante face aux volants"], "playbook": [{"when": "Le fight commence", "then": "Tire au rayon sur **ce qui te charge le plus vite** : un tank, un bouclier, ou le cristal que tu viens d'extraire."}, {"when": "Ton rayon est chargé et une cible est proche d'un mur", "then": "**Diamant, étranglement, deux coups, coup de pied** vers le mur. Pose ton bouclier juste avant d'entrer."}, {"when": "Un ennemi canalise une ult (Doctor Strange, Scarlet Witch, Loki en copie)", "then": "**Étrangle-le** : l'étourdissement l'interrompt."}, {"when": "Un DPS te harcèle depuis un angle décalé", "then": "**Pose le bouclier** sur sa ligne de tir : il doit changer de place, et tu gagnes le front pendant ce temps."}, {"when": "Un tank adverse s'avance trop", "then": "Bouclier **entre lui et ses supports**, puis étranglement et coup de pied vers ton équipe."}, {"when": "Le fight est gagné", "then": "Avance vers la sortie du spawn adverse et **garde ton rayon chargé** sur le premier qui revient."}], "sections": [{"title": "Philosophie de jeu", "lead": "Le début d'un fight ne sert pas à tuer : il sert à charger ton rayon, exactement comme un Strategist charge son ult.", "ability": "", "key": "", "kind": "tips", "items": ["Tiens-toi **à portée de rayon** jusqu'à la charge maximale, puis rapproche-toi pour passer en diamant.", "Le rayon se décharge après quelques secondes sans toucher : **ne cesse jamais de tirer** sur quelque chose.", "Après un fight gagné, va chercher l'adversaire **à la sortie de son spawn** : tu arrives au fight suivant avec un rayon plein."], "diagram": "brawl"}, {"title": "Rayon télépathique", "lead": "Un rayon dont les dégâts augmentent avec sa charge. Il se charge sur les ennemis, les boucliers, les clones et tes propres cristaux.", "ability": "Telepathic Pulse", "key": "Clic G", "kind": "default", "items": ["Il se charge sur les **bulles de Magneto** et le **bouclier de Captain America**, mais pas sur le grand bouclier de Magneto ni sur les murs de Groot.", "Passer en diamant ou lancer ton ult **met la décharge en pause**.", "Dans un duel d'Emma, ne pose pas ton bouclier trop tôt : tu offres de la charge à l'autre."], "diagram": ""}, {"title": "Cristal d'âme", "lead": "Un projectile qui extrait un cristal de sa cible. Le briser inflige des dégâts à la cible, où qu'elle soit.", "ability": "Psychic Spear", "key": "E", "kind": "default", "items": ["C'est d'abord un **outil de charge** : tirer sur le cristal charge le rayon plus vite que tirer sur un ennemi.", "Ton rayon **traverse le cristal** : aligne-le avec une seconde cible pour toucher les deux.", "Depuis la saison 11, briser le cristal inflige **60 + 10 % de la vie max** de la cible (au lieu de 25 %) : plus de dégâts sur un héros fragile, moins sur un tank.", "Si la cible s'éloigne trop, le cristal disparaît sans dégâts.", "Il fonctionne sur **Venom et Jeff** même enfouis."], "diagram": ""}, {"title": "Bouclier", "lead": "Un bouclier que tu poses à distance et qui ne bloque qu'une fois en place. Il est fragile : c'est un outil pour avancer, pas pour encaisser.", "ability": "Mind's Aegis", "key": "Clic D", "kind": "default", "items": ["Pose-le sur la ligne de tir d'un **DPS sur un angle** : il doit se déplacer, et pendant ce temps tu gagnes le front.", "Il arrête les **grosses menaces à projectile** : ult d'Hela ou d'Iron Man, flèches de Hawkeye.", "Placé derrière un tank adverse, il **coupe ses soins**.", "Pose-le toujours **avant** de passer en diamant ou de lancer ton ult.", "Il a perdu de la vie et de la régénération en saison 11 : ne le laisse pas traîner sous le feu."], "diagram": ""}, {"title": "Forme de diamant", "lead": "Pendant quelques secondes, tu encaisses moins de dégâts et tu te bats aux poings, avec un étranglement et un coup de pied.", "ability": "Diamond Form", "key": "Maj", "kind": "default", "items": ["L'**étranglement** étourdit : il annule les ults canalisées et immobilise la cible pour ton équipe.", "Le **coup de pied** fait beaucoup plus de dégâts si la cible percute un mur. Un mur de Groot compte, un autre joueur non.", "Enchaînement : **étranglement, deux coups, coup de pied contre un mur**. Un troisième coup sécurise le kill.", "Avant d'entrer, utilise ton rayon pour pousser les héros fragiles vers un **espace fermé**.", "Dans un couloir, un coup de pied de zone en premier peut séparer la cible de ses soins."], "diagram": "", "scene": {"title": "Étrangler, puis projeter au mur", "caption": "Le coup de pied seul fait peu de dégâts. Contre un mur, il achève la cible que l'étranglement a immobilisée.", "steps": ["Bouclier posé, tu passes en diamant et tu avances.", "Étranglement : la cible est étourdie, tu places deux coups.", "Coup de pied vers le mur le plus proche."], "els": [{"t": "cover", "at": [256, 62], "size": [18, 70], "label": "Mur"}, {"t": "bar", "from": [150, 34], "to": [204, 26], "team": "me", "label": "Bouclier"}, {"t": "pawn", "at": [104, 98], "team": "me", "ghost": true}, {"t": "path", "kind": "move", "team": "me", "pts": [[104, 98], [166, 98]], "n": 1}, {"t": "pawn", "at": [168, 98], "team": "me"}, {"t": "pawn", "at": [200, 98], "team": "enemy", "role": "dps", "ghost": true}, {"t": "note", "at": [200, 74], "text": "2", "team": "me"}, {"t": "path", "kind": "push", "team": "me", "pts": [[206, 98], [236, 98]], "n": 3}, {"t": "pawn", "at": [240, 98], "team": "enemy", "role": "dps", "label": "Cible", "above": true}, {"t": "pawn", "at": [214, 150], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [296, 120], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [292, 160], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [296, 40], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [84, 140], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [76, 54], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [40, 80], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [40, 124], "team": "ally", "role": "heal"}]}}, {"title": "Ultime", "lead": "Un cône qui inflige des dégâts et prend le contrôle des ennemis touchés : ils marchent vers toi pendant quelques instants.", "ability": "Psionic Seduction", "key": "Q", "kind": "default", "items": ["Tu ne peux pas passer en diamant juste avant : **pose ton bouclier** ou attends que ton équipe te couvre.", "**Brise les boucliers** adverses d'abord, sinon ils s'abritent derrière.", "Meilleurs usages : sortir les ennemis d'une **ult de zone** (Invisible Woman), **casser un dive** sur tes supports, ou **désynchroniser un combo d'ults**.", "Tu n'as pas besoin de cinq cibles : attirer le bon ennemi au bon moment suffit."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Laisser le rayon **se décharger** entre deux fights.", "Utiliser le bouclier comme un **mur à encaisser**.", "Passer en diamant **sans bouclier** posé.", "Lancer l'ult **face à des boucliers intacts**.", "Coup de pied **sans mur** derrière la cible."], "diagram": ""}], "combos": [{"note": "Ajoute un coup de plus pour plus de sécurité.", "steps": [{"key": "Maj", "label": "forme diamant"}, {"key": "", "label": "Étranglement"}, {"key": "", "label": "Coup"}, {"key": "", "label": "Coup"}, {"key": "", "label": "Coup de pied au mur"}], "title": "Combo de base"}], "counters": [{"hero": "groot", "note": "Ses murs ne chargent pas ton rayon et te coupent de tes cibles."}, {"hero": "iron-man", "note": "Il reste hors de portée du rayon et te tire dessus de loin."}, {"hero": "human-torch", "note": "Même difficulté : tu n'as rien contre un volant."}, {"hero": "the-punisher", "note": "Ton bouclier fragile ne tient pas une seconde sous son tir."}], "synergies": [{"hero": "magneto", "note": "Il tient le grand bouclier ; tu prends le relais avec le tien quand il tombe."}, {"hero": "winter-soldier", "note": "Son crochet puis ton étranglement : la cible ne joue plus."}, {"hero": "psylocke", "note": "Elle profite de l'espace que tu ouvres en brawl."}, {"hero": "luna-snow", "note": "Des soins constants pendant ta phase de charge."}, {"hero": "groot", "note": "Ses murs te donnent le mur qu'il faut à ton coup de pied."}], "sources": [{"url": "https://www.youtube.com/watch?v=geqHn_q6k7w", "title": "Emma Frost Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Iced Out Diamond", "partners": ["luna-snow"], "key": "", "text": "Projectile de glace et barrière de diamant (bouclier de 300 en saison 11). **Amélioré :** Ajoute des ralentissements."}, {"name": "Magnetic Resonance", "partners": ["magneto"], "key": "", "text": "Une projection imite Magneto (50 % des dégâts, 6 s en 10.5). **Amélioré :** Beaucoup plus de vie, la projection dure."}, {"name": "Mental Projection", "partners": ["psylocke"], "key": "", "text": "Une illusion dashe et imite les frappes. **Amélioré :** Permet d'échanger de place avec l'illusion."}, {"name": "Spirit Breaker", "partners": ["mantis"], "key": "", "text": "Les dégâts de Sentience deviennent de la vie bonus. **Amélioré :** Vie bonus ponctuelle et cooldown de Psychic Spear réduit."}], "changes": [{"season": "Saison 11", "text": "Mind's Aegis : bouclier 400 → 350, récupération 80 → 65/s."}, {"season": "Saison 11", "text": "Psychic Spear : les dégâts de la Sentience extraite passent de 25 % de la vie max à 60 + 10 % de la vie max."}, {"season": "Saison 11", "text": "Team-up avec Luna Snow (Iced Out Diamond) : bouclier 350 → 300."}, {"season": "Saison 10", "text": "Vie de base 650 → 675, portée de Telepathic Pulse 18 m → 20 m, Carbon Crush porte à 8,5 m au lieu de 7 m."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'emma-frost' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Gambit est un Strategist agressif et autonome. Il soigne à mi-distance avec ses cartes, tient tête aux divers en duel et charge son ult avant tout le monde. Sa signature : une purification qui efface les contrôles et les ults adverses sur ses alliés, et un ultime qui transforme son équipe en rouleau compresseur.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["Sors le **paquet de dégâts** dès le début du fight : c'est lui qui charge ton ult.", "Quand une ult adverse approche, **garde deux cartes** pour la purifier.", "Lance ton ult **quand ton équipe est déjà sur l'ennemi**, pas de loin."], "difficulty": 3, "tags": ["Purification", "Dégâts", "Duels", "Économie d'ult"], "strengths": ["Purification : annule contrôles et ults", "Très bon en duel contre les divers", "Ult d'engage à travers les murs"], "weaknesses": ["Soigne mal de loin (cartes dispersées)", "Quatre cartes pour tout faire", "Fragile face au burst"], "playbook": [{"when": "L'adversaire a une ult de contrôle prête (Doctor Strange, Groot, Winter Soldier)", "then": "**Recule d'un pas** pour ne pas être pris dedans, garde deux cartes, puis dash dans ton équipe et **purifie**."}, {"when": "Un allié est attrapé (Angela, Wolverine) ou marqué", "then": "**Purification** s'il est étourdi ou marqué ; **volée de dégâts** pour projeter le ravisseur et lui faire lâcher prise."}, {"when": "Un diver vient sur toi ou sur ton autre support", "then": "Paquet de dégâts, tirs, **frappe au sol** pour te soigner : tu gagnes la plupart de ces duels."}, {"when": "Un allié lance son ult (Punisher, Star-Lord)", "then": "**Carte rebondissante** sur lui : ses soins reçus sont augmentés pendant toute la durée."}, {"when": "Ton équipe est au contact et ton ult est prête", "then": "Lance-la **depuis l'arrière du groupe** pour toucher tout le monde, puis passe aux dégâts."}, {"when": "Il te reste une seule carte", "then": "Tu peux encore **activer un paquet** (soin ou dégâts) sans rien lancer. Ne la dépense pas pour un lancer inutile."}], "sections": [{"title": "Philosophie de jeu", "lead": "Comme Luna Snow, Gambit gagne en ayant son ult avant les supports adverses. Mais il joue plus près de son équipe et cherche lui-même des éliminations.", "ability": "", "key": "", "kind": "tips", "items": ["Prends un **léger angle** pour tirer là où aucun bouclier ne te gêne, à portée de dash de ton équipe.", "Tes trois cartes s'écartent avec la distance, et davantage depuis la saison 11 : **reste à mi-portée**, quelques mètres plus près qu'avant.", "Tu es l'un des meilleurs supports pour **affronter un diver** en duel avant qu'il atteigne ta backline.", "À deux supports, tu soignes plus que tu ne tires. **À trois supports**, privilégie nettement les dégâts et l'anti-soin.", "Détruis les clones et les tourelles quand tu en as l'occasion : c'est de la charge d'ult gratuite."], "diagram": "pocket"}, {"title": "Cartes cinétiques", "lead": "Des salves de trois cartes qui soignent les alliés et blessent les ennemis. Elles ne perdent pas de dégâts avec la distance, mais elles s'écartent.", "ability": "", "key": "Clic G", "kind": "default", "items": ["Trop loin, une seule carte sur trois touche : **rapproche-toi** plutôt que d'insister.", "Elles se touchent facilement : sers-t'en pour **entamer** l'adversaire autant que pour soigner."], "diagram": ""}, {"title": "Dash et frappe au sol", "lead": "Un dash qui traverse les cibles, et une frappe au sol qui soigne les alliés (toi compris) et blesse les ennemis. Lancée pendant le dash, la frappe devient un dash tournoyant plus long.", "ability": "Cajun Charge · Bayou Bash", "key": "", "kind": "default", "items": ["Le **dash tournoyant** soigne ou blesse tout ce qu'il traverse : fais demi-tour en cours de route pour repasser sur le groupe.", "Pour faire des dégâts, démarre-le **collé à l'ennemi** : la première frappe part immédiatement.", "Contre des flankers, **garde la frappe au sol** pour te soigner en duel.", "Le dash part dans toutes les directions, y compris vers le haut : sers-t'en pour rejoindre une hauteur."], "diagram": ""}, {"title": "Les paquets de cartes", "lead": "Quatre charges communes. Sortir un paquet coûte une charge, jouer une carte spéciale en coûte une autre : avec quatre cartes, tu n'as que deux lancers.", "ability": "", "key": "", "kind": "tips", "items": ["Le **paquet de dégâts** augmente tous tes dégâts pendant quelques secondes : sors-le tôt, il charge ton ult.", "Le **paquet de soin** te régénère (moins qu'avant depuis la saison 11) : ne le sors que si tu comptes jouer une carte de soin.", "Une carte spéciale gâchée, ce sont **deux charges perdues**.", "Règle simple : besoin d'un **burst de soin**, paquet de soin puis carte rebondissante ; besoin d'un **burst de dégâts**, paquet de dégâts puis volée.", "Quand une ult adverse approche, **reste à deux cartes** : c'est le prix d'une purification."], "diagram": ""}, {"title": "Cartes de soin", "lead": "La carte rebondissante saute d'allié en allié et augmente leurs soins reçus. La purification est une volée de cartes qui soigne et efface les effets négatifs.", "ability": "Bridge Boost · Purifying Pickup", "key": "", "kind": "default", "items": ["La **purification** efface étourdissements, marques et anti-soin : ult de Winter Soldier, de Doctor Strange, prises d'Angela ou de Wolverine.", "Elle ne protège pas d'avance : **sors le paquet avant l'ult**, purifie juste après l'impact.", "La **carte rebondissante** accompagne un allié qui lance son ult. Elle peut rebondir sur le sol pour atteindre un allié hors de vue.", "Annuler une ult adverse avec deux cartes est le meilleur échange possible : plus tu montes en rang, plus il faut le guetter."], "diagram": "", "scene": {"title": "Purifier une ult", "caption": "Une ult de contrôle gagne un fight si ses cibles restent étourdies trois secondes. Purifiées, elles se battent normalement.", "steps": ["Tu vois l'ult arriver : tu restes un pas à l'écart du groupe.", "Elle étourdit ton équipe, pas toi.", "Tu purifies : tes alliés sont libres avant le burst adverse."], "els": [{"t": "zone", "at": [130, 92], "r": 46, "team": "enemy", "label": "Ult de Strange", "n": 2}, {"t": "pawn", "at": [186, 80], "team": "enemy", "hero": "doctor-strange", "above": true}, {"t": "pawn", "at": [120, 70], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [146, 112], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [106, 116], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [96, 84], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [40, 140], "team": "me"}, {"t": "note", "at": [40, 110], "text": "1", "team": "me"}, {"t": "path", "kind": "beam", "team": "me", "pts": [[40, 140], [112, 108]], "n": 3}, {"t": "pawn", "at": [236, 60], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [238, 132], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [288, 80], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [288, 120], "team": "enemy", "role": "heal"}]}}, {"title": "Cartes de dégâts", "lead": "La carte explosive applique un anti-soin. La volée projette les ennemis en l'air.", "ability": "Explosive Trick · Bidding Barrage", "key": "", "kind": "default", "items": ["L'**anti-soin** permet de tuer à travers une ult de soin, à condition que ton équipe tire sur la même cible.", "La **projection** interrompt une prise d'Angela ou de Wolverine, un saut de Hulk, un balancement de Venom.", "Combo d'élimination : **paquet de dégâts, tir, dash tournoyant, tir, carte explosive**."], "diagram": ""}, {"title": "Ultime", "lead": "Tous les alliés dans un large cône sont purifiés, soignés, accélérés, chargent leur ult plus vite et infligent plus de dégâts. Elle traverse les murs.", "ability": "Ragin' Royal Flush", "key": "Q", "kind": "default", "items": ["**Pour engager** : charge-la avant tout le monde et lance-la quand ton équipe est au contact.", "**En réponse** à une ult adverse : elle purifie et soigne tout le groupe, même à travers un mur.", "Lance-la **depuis l'arrière** du groupe pour que le cône couvre tout le monde.", "En retard sur le support adverse ? Sois la **seconde ult** du fight plutôt que la première.", "Sa portée de recherche a été réduite en saison 10.5 : vérifie que tes alliés sont bien devant toi."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Rester à l'arrière à **soigner tout le fight**.", "Sortir un paquet **sans savoir quelle carte jouer**.", "Ne plus avoir **deux cartes** quand l'ult adverse tombe.", "Lancer l'ult **de trop loin**.", "Tirer **hors de portée utile**, cartes dispersées."], "diagram": ""}], "combos": [{"note": "", "steps": [{"key": "", "label": "Paquet dégâts"}, {"key": "Clic G", "label": "tir"}, {"key": "", "label": "Dash renforcé"}, {"key": "Clic G", "label": "tir"}, {"key": "", "label": "Carte anti-soin"}], "title": "Combo pick"}], "counters": [{"hero": "daredevil", "note": "Son burst te tue avant que ta frappe au sol ne te soigne."}, {"hero": "hela", "note": "Deux tirs à la tête à une distance où tes cartes ne touchent pas."}, {"hero": "black-widow", "note": "Elle te punit à longue portée, là où tu soignes mal."}, {"hero": "elsa-bloodstone", "note": "Sa créature emporte tes alliés hors de ton cône."}], "synergies": [{"hero": "magneto", "note": "Un tank de brawl qui avance avec toi, et un team-up qui projette les ennemis."}, {"hero": "psylocke", "note": "Ton anti-soin sur un support lui offre le kill."}, {"hero": "captain-america", "note": "Ta mobilité te permet de suivre son dive."}, {"hero": "rogue", "note": "Votre team-up revient deux fois plus vite depuis la saison 11."}, {"hero": "luna-snow", "note": "Deux supports qui se soignent mutuellement : la backline devient très difficile à tuer."}], "sources": [{"url": "https://www.youtube.com/watch?v=WIHDdJujzUs", "title": "Gambit Guide", "author": "Paz (padswagger)"}, {"title": "Ultimate Gambit Guide (Beginner/Advanced)", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=mYUUUKAQplM"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Favorable Odds", "partners": ["magneto"], "key": "", "text": "Cartes magnétiques qui soignent et projettent (une seule fois, à l'explosion, depuis la saison 10). **Amélioré :** Explosion finale en plus."}, {"name": "Gumbo Chimichangas", "partners": ["deadpool"], "key": "", "text": "Saut cinétique avec un anneau de chimichangas. **Amélioré :** Étourdit à l'atterrissage."}, {"name": "Kinetic Kin", "partners": ["cyclops"], "key": "", "text": "Boost de vitesse et de saut (8 s en 10.5). **Amélioré :** Augmente la vitesse d'attaque."}, {"name": "Mr. & Mrs. X", "partners": ["rogue"], "key": "", "text": "Explosions cinétiques sur les attaques (cooldown 15 s en saison 11, explosions et soins un peu réduits). **Amélioré :** Verrouille Hearts as One."}, {"name": "Pair of Threes", "partners": ["wolverine"], "key": "", "text": "Amélioration cinétique avec des particules qui explosent. **Amélioré :** Ajoute un soin continu."}, {"name": "Sparkling Staff", "partners": ["jubilee"], "key": "", "text": "Un bâton qui soigne et bloque les projectiles (2 s en 10.5). **Amélioré :** Ajoute des auras de soin continu."}], "changes": [{"season": "Saison 11", "text": "Kinetic Cards : dispersion extérieure 2° → 3° (il faut se rapprocher de 3 à 5 m pour toucher toutes les cartes)."}, {"season": "Saison 11", "text": "Healing Hearts : auto-soin 30 → 20/s."}, {"season": "Saison 10", "text": "Team-up avec Magneto : la projection ne se déclenche plus qu'une fois, à l'explosion."}, {"season": "Saison 10.5", "text": "Paquets de soin et de dégâts : 7 s par charge au lieu de 8 s."}, {"season": "Saison 10.5", "text": "Ult : portée de recherche 40 m → 30 m, boost de saut 500 → 300."}, {"season": "Saison 10", "text": "Tous les Strategists : l'ult se charge un peu moins vite (65 % du soin et 50 % des dégâts convertis en énergie, au lieu de 70 % et 55 %)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'gambit' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Gorr est un Duelist de mêlée qui se bat entouré de Berserkers, des créatures symbiotes qu'il invoque. Il les envoie sur sa cible, plonge sur elle sous une forme invincible, puis se téléporte sur un Berserker pour repartir. Chaque élimination lui en offre un nouveau : en tête, il devient très difficile à arrêter.", "patch_note": "Guide rédigé à partir de guides écrits publiés à la sortie de Gorr (saison 10). Il n'a pas été modifié en saison 11. Les chiffres précis ne sont pas indiqués : vérifie-les en jeu.", "tldr": ["**Pose un Berserker avant d'engager** : c'est ton point de retour.", "**Living Abyss sert à entrer**, Shadow Harvest à sortir. Ne dépense pas les deux pour poursuivre.", "Vise les **cibles isolées** : chaque kill invoque un Berserker de plus."], "difficulty": 3, "tags": ["Mêlée", "Dive", "Invocations", "Effet boule de neige"], "strengths": ["Plongeon invincible (Living Abyss)", "Vie bonus continue grâce aux Berserkers", "Fait boule de neige à chaque élimination"], "weaknesses": ["Large hitbox pour un Duelist", "Ni double saut ni escalade", "Peu utile quand son équipe est menée"], "playbook": [{"when": "Avant d'engager", "then": "**Berserker (E) dans un endroit sûr**, ou lance Living Abyss depuis ta position de repli : il laisse un Berserker au point de départ."}, {"when": "Une cible fragile est isolée", "then": "**Living Abyss** dessus, **Necro-Power** pour envoyer tes Berserkers, puis coups d'épée."}, {"when": "Ton engage tourne mal", "then": "**Shadow Harvest** sur le Berserker resté en arrière : tu te téléportes, tu gagnes de la vie bonus."}, {"when": "Tu as deux Berserkers ou plus sur le terrain", "then": "**Necro-Power** sur la cible prioritaire : ils s'y téléportent tous et la projettent en l'air."}, {"when": "Tu viens de sacrifier un Berserker", "then": "Ton épée est une **faux** pour quelques coups : c'est ta fenêtre de dégâts."}, {"when": "Les ennemis sont groupés et ton équipe est là", "then": "**Ult** : un Berserker frénétique apparaît près de chaque ennemi, et tes coups frappent en pourcentage de leur vie."}], "sections": [{"title": "Philosophie de jeu", "lead": "Gorr suit un cycle : préparer, engager, encaisser grâce à la vie bonus, ressortir, recommencer. Il ne plonge jamais sans avoir prévu son retour.", "ability": "", "key": "", "kind": "default", "items": ["**Prépare ta sortie d'abord** : un Berserker à l'abri vaut plus qu'un Berserker au front.", "Cherche les **erreurs de placement** : un support écarté, un Duelist sans défense. N'engage pas simplement parce que tes cooldowns sont prêts.", "Il se rapproche de Magik : fort en tête, médiocre quand l'équipe est menée.", "Il n'a ni double saut ni escalade : un engage raté ne se rattrape qu'avec Shadow Harvest."], "diagram": "reset"}, {"title": "Épée et Berserkers", "lead": "Ton attaque de base est un enchaînement de quatre coups d'épée. Les Berserkers tirent sur l'ennemi le plus proche, et leurs dégâts te donnent de la vie bonus.", "ability": "All-Black · Black Berserker · Symbiote Swarm", "key": "Clic G · E", "kind": "default", "items": ["Frappe une cible **déjà ralentie ou projetée** : tu n'as aucune portée pour la rattraper.", "Chaque **élimination invoque un Berserker** à l'endroit du kill.", "Le Berserker lancé avec E apparaît là où la masse retombe : **vise ton futur point de repli**.", "Plus tu as de Berserkers, plus ta vie bonus se renouvelle."], "diagram": ""}, {"title": "Necro-Power", "lead": "Tu charges puis tu lances une masse de symbiote. La cible touchée est ralentie, et les Berserkers proches se téléportent sur elle pour une double frappe qui la projette en l'air.", "ability": "Necro-Power", "key": "Clic D", "kind": "default", "items": ["C'est ton **outil d'engage à distance** : il ouvre la cible avant ton arrivée.", "Sans Berserker à proximité, il en invoque un sur la cible.", "Garde-le pour le moment où **plusieurs Berserkers** sont en place : l'effet se multiplie."], "diagram": ""}, {"title": "Living Abyss", "lead": "Tu fonces sous la forme d'une masse de symbiote, invincible pendant le déplacement. Tu laisses un Berserker au point de départ, et à l'arrivée une zone blesse les ennemis et convertit ces dégâts en vie bonus.", "ability": "Living Abyss", "key": "Maj", "kind": "default", "items": ["Il est fait pour **entrer**, pas pour fuir.", "Lance-le **depuis un endroit sûr** : le Berserker laissé derrière toi est ta sortie.", "L'invincibilité traverse un burst ou une ult à projectile.", "Tes Berserkers actifs passent en état **frénétique**."], "diagram": "", "scene": {"title": "Entrer, puis revenir sur un Berserker", "caption": "Living Abyss laisse un Berserker au départ. Shadow Harvest t'y ramène : l'aller et le retour sont préparés par la même capacité.", "steps": ["Living Abyss depuis ta position de repli : un Berserker y reste.", "Tu arrives invincible sur la cible : zone de dégâts, vie bonus.", "Shadow Harvest : tu te téléportes sur le Berserker."], "els": [{"t": "cover", "at": [96, 40], "size": [16, 60], "label": "Mur"}, {"t": "mark", "at": [150, 60], "kind": "clone", "team": "me", "label": "Berserker"}, {"t": "pawn", "at": [138, 110], "team": "me"}, {"t": "path", "kind": "move", "team": "me", "pts": [[138, 110], [200, 156], [246, 100]], "n": 1}, {"t": "zone", "at": [266, 88], "r": 24, "team": "me"}, {"t": "note", "at": [292, 62], "text": "2", "team": "me"}, {"t": "pawn", "at": [278, 84], "team": "enemy", "role": "heal", "label": "Cible"}, {"t": "pawn", "at": [250, 92], "team": "me", "ghost": true}, {"t": "path", "kind": "move", "team": "me", "pts": [[246, 82], [206, 26], [162, 58]], "n": 3}, {"t": "pawn", "at": [230, 160], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [266, 150], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [300, 128], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [296, 30], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [60, 70], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [64, 120], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [30, 90], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [40, 148], "team": "ally", "role": "heal"}]}}, {"title": "Shadow Harvest", "lead": "Tu te téléportes sur un Berserker et tu le sacrifies : tu gagnes de la vie bonus (la moitié de sa vie), il explose, et ton épée devient une faux pour quelques coups.", "ability": "Shadow Harvest", "key": "F", "kind": "default", "items": ["**Offensif** : sur un Berserker que Necro-Power vient d'envoyer sur la cible.", "**Défensif** : sur le Berserker resté en arrière.", "La faux frappe plus loin et plus fort : enchaîne tes coups aussitôt.", "Ne dépense pas Living Abyss **et** Shadow Harvest pour poursuivre une cible basse : tu n'aurais plus de retour."], "diagram": ""}, {"title": "Ultime", "lead": "Ton épée devient l'Annihilablade. Un Berserker frénétique apparaît près de chaque ennemi à portée, et tes coups infligent des dégâts en pourcentage de la vie maximale.", "ability": "Twilight of the Gods", "key": "Q", "kind": "default", "items": ["Les dégâts en pourcentage font très mal **aux tanks**.", "Lance-la sur un **groupe**, quand ton équipe attaque avec toi, pas quand tu es acculé.", "Enchaînement : **Berserker, Necro-Power, ult, coups d'épée**.", "Les Berserkers invoqués occupent les supports adverses pendant que tu frappes."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "default", "items": ["Engager **sans Berserker** de repli.", "Utiliser Living Abyss **pour fuir**.", "Plonger **en premier**, avant son équipe.", "Lancer Necro-Power **sans Berserker** à envoyer.", "Garder l'ult pour **se sauver**."], "diagram": ""}], "combos": [{"title": "Engage de base", "steps": [{"key": "E", "label": "Berserker"}, {"key": "Clic D", "label": "Necro-Power"}, {"key": "Clic G", "label": "épée"}], "note": "Le plus sûr : tu n'as dépensé aucune mobilité."}, {"title": "Plongeon", "steps": [{"key": "E", "label": "Berserker"}, {"key": "Maj", "label": "Living Abyss"}, {"key": "Clic D", "label": "Necro-Power"}, {"key": "Clic G", "label": "épée"}, {"key": "F", "label": "retour"}], "note": "Garde **Shadow Harvest** pour le retour sur le Berserker de départ."}, {"title": "Avec l'ult", "steps": [{"key": "E", "label": "Berserker"}, {"key": "Clic D", "label": "Necro-Power"}, {"key": "Q", "label": "ult"}, {"key": "Clic G", "label": "épée"}], "note": "Sur un groupe, avec ton équipe prête."}], "counters": [{"hero": "hela", "note": "Ta large hitbox est une cible facile pour ses tirs."}, {"hero": "iron-man", "note": "En l'air, il est hors de portée de tout ton kit."}, {"hero": "namor", "note": "Ses tourelles gardent la backline que tu veux atteindre."}, {"hero": "peni-parker", "note": "Ses mines et sa toile punissent ton arrivée."}, {"hero": "luna-snow", "note": "Elle te gèle à la sortie de Living Abyss."}], "synergies": [{"hero": "hela", "note": "Votre team-up te donne un coup de faux sans sacrifier de Berserker."}, {"hero": "venom", "note": "Votre team-up ajoute une griffe qui attire les ennemis, et il plonge avec toi."}, {"hero": "peni-parker", "note": "Elle tient ton front pendant que tu plonges."}, {"hero": "ultron", "note": "Son drone te suit dans la backline adverse."}, {"hero": "magneto", "note": "Sa bulle couvre ton engage."}], "sources": [{"title": "Marvel Rivals Gorr Guide", "author": "Beebom", "url": "https://beebom.com/marvel-rivals-gorr-guide/"}, {"title": "Marvel Rivals Gorr Guide: Abilities, Combos, Ranked Tips", "author": "RankForge", "url": "https://rankforge.gg/blog/marvel-rivals-gorr-guide-abilities-combos-ranked-tips"}, {"title": "Gorr the God Butcher Guide (Season 10)", "author": "TimeSaver", "url": "https://timesaver.gg/blog/marvel-rivals-gorr-god-butcher-guide-season-10"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Hive Mind", "partners": ["venom"], "key": "C", "text": "Une griffe de symbiote attire les ennemis. **Amélioré :** Ajoute un boost de dégâts et un ralentissement."}, {"name": "Ragnarök", "partners": ["hela"], "key": "C", "text": "Coup de faux qui cloue les ennemis au sol. **Amélioré :** Plus de portée et vie bonus."}], "changes": [], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'gorr-the-god-butcher' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Groot est un Vanguard de ligne de front qui redessine la carte avec ses murs. Il isole une cible de ses soins pour que son équipe la tue, ferme les passages, et son ult regroupe les ennemis pour les combos d'ults les plus destructeurs du jeu.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["**Coupe une cible de ses heals** avec un mur, puis tue-la avec ton équipe.", "Le **mur de bois de fer** se garde pour un vrai engage.", "Avant ton ult, vérifie que **ton partenaire de combo** a la sienne."], "difficulty": 2, "tags": ["Murs", "Combos d'ult", "Couloirs", "Ligne de front"], "strengths": ["Isole n'importe quelle cible de ses soins", "Ult de regroupement : la base des combos", "Très fort dans les couloirs"], "weaknesses": ["Aucune mobilité", "Peu d'options une fois les murs posés", "Ses murs chargent le rayon d'Emma Frost"], "playbook": [{"when": "Le tank adverse s'avance", "then": "**Mur derrière lui**, entre lui et ses supports. Privé de soins, il meurt sous les tirs de ton équipe."}, {"when": "La cible que tu veux isoler a encore son évasion (saut, lévitation)", "then": "**Attends.** Force d'abord l'évasion, isole ensuite : sinon ton mur ne sert à rien."}, {"when": "L'ennemi doit passer par un couloir", "then": "Un grand mur en travers et un petit au-dessus : le passage est fermé le temps que ton équipe s'installe."}, {"when": "Un diver saute sur ta backline", "then": "Mur **devant le front adverse** : il se retrouve seul chez toi, coupé de ses soins."}, {"when": "Ton ult est prête, celle de ton partenaire aussi", "then": "**Annonce le combo**, lance la prison, et pose un mur pour couper les supports restés dehors."}, {"when": "Ton engage est terminé", "then": "**Récupère le grand mur** avec F : son cooldown est plus court s'il a peu souffert."}], "sections": [{"title": "Philosophie de jeu", "lead": "Sans ses murs, Groot n'a presque aucune option. Tout son jeu tient au choix du bon mur, au bon endroit, au bon moment.", "ability": "", "key": "", "kind": "tips", "items": ["Rejoins ta position **à couvert**, sans dépenser de mur pour le trajet.", "Cherche les **couloirs étroits** : c'est là que tes murs ferment tout.", "Tu peux aussi **protéger une ult alliée** derrière un mur : l'amplificateur de Rocket, un support visé par Hawkeye.", "Contre une compo de dive, tes murs servent à **séparer le diver de son équipe**, pas à le bloquer."], "diagram": "", "scene": {"title": "Couper le tank de ses heals", "caption": "Un mur ne fait presque pas de dégâts. Il retire à la cible la seule chose qui la gardait en vie.", "steps": ["Le tank adverse s'avance pour prendre de l'espace.", "Tu poses le mur dans son dos : ses supports ne le voient plus.", "Ton équipe concentre ses tirs : il tombe sans soin."], "els": [{"t": "pawn", "at": [178, 92], "team": "enemy", "role": "tank", "label": "Isolé"}, {"t": "note", "at": [178, 62], "text": "1", "team": "enemy"}, {"t": "pawn", "at": [124, 92], "team": "me"}, {"t": "bar", "from": [214, 44], "to": [214, 140], "team": "me", "label": "Mur", "n": 2}, {"t": "path", "kind": "heal", "team": "enemy", "pts": [[282, 74], [222, 84]]}, {"t": "path", "kind": "heal", "team": "enemy", "pts": [[282, 114], [222, 102]]}, {"t": "pawn", "at": [282, 74], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [282, 114], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [250, 36], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [252, 152], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [112, 46], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [110, 140], "team": "ally", "role": "dps"}, {"t": "path", "kind": "shot", "team": "ally", "pts": [[112, 46], [178, 92]], "n": 3}, {"t": "path", "kind": "shot", "team": "ally", "pts": [[110, 140], [178, 92]], "n": 3}, {"t": "pawn", "at": [56, 74], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [54, 118], "team": "ally", "role": "heal"}]}}, {"title": "Dégâts", "lead": "De gros projectiles faciles à toucher, une série de trois coups de mêlée et une bombe de spores qui se lance comme une grenade.", "ability": "Vine Strike · Spore Bomb", "key": "Clic G", "kind": "default", "items": ["Tes tirs ne font pas de dégâts critiques : vise **les jambes**, la cible y est plus large.", "Intercale des **coups de mêlée** : le troisième repousse et projette en l'air.", "La **bombe** punit les groupes serrés et gêne les supports adverses pendant qu'ils soignent."], "diagram": ""}, {"title": "Murs d'épines", "lead": "Deux murs en réserve, vite rechargés. Chaque appui change leur orientation : vertical, en diagonale ou à l'horizontale.", "ability": "Thornlash Wall", "key": "Maj", "kind": "default", "items": ["**Vertical** pour séparer, **diagonal** pour créer un escalier vers une hauteur, **horizontal** pour fermer le dessus d'un passage.", "Les murs **blessent les ennemis proches** chaque fois que ton équipe leur inflige des dégâts ; cet effet frappe un peu plus fort depuis la saison 11.", "Leur cooldown démarre à la pose : **laisse-les en place**.", "Ils tombent vite face à Punisher, Loki ou Iron Man."], "diagram": ""}, {"title": "Mur de bois de fer", "lead": "Un grand mur très solide, posé plus près de toi. Près de lui, les dégâts de ton équipe te donnent de la vie bonus.", "ability": "Ironwood Wall", "key": "", "kind": "default", "items": ["C'est ton **outil d'engage** : il sert à isoler une vraie cible ou à forcer un gros cooldown défensif.", "Ne le pose pas par réflexe : sans lui, tu restes vulnérable un long moment.", "Il a perdu un peu de vie en saison 11 (550) : ne compte plus sur lui pour tenir tout un fight.", "Ne laisse aucun mur à portée d'une **Emma Frost** adverse : elle s'en sert pour charger son rayon."], "diagram": ""}, {"title": "Ultime", "lead": "Un projectile qui attire les ennemis proches et les retient au centre. Sa valeur vient des ults lancées par-dessus : elles tuent même à travers une ult de soin.", "ability": "Strangling Prison", "key": "Q", "kind": "default", "items": ["Elle se charge **très vite** : au premier fight, lance-la si l'adversaire n'a pas encore d'ult de support.", "Partenaires classiques : **Moon Knight, Namor, Winter Soldier, Human Torch**, avec le voile de Cloak en supplément.", "Consulte le **tableau des scores** entre les fights pour savoir qui a son ult.", "Pendant la prison, **pose un mur** pour couper les supports restés à l'extérieur.", "Le **bouclier de Magneto** arrête le projectile, et la résurrection d'**Adam Warlock** annule le combo."], "diagram": "ultcombo"}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Poser ses murs **sans objectif**.", "Laisser le grand mur en place **après l'engage**.", "Lancer l'ult **sans partenaire** prêt.", "Tirer l'ult **dans le bouclier** de Magneto.", "Laisser un mur **à portée d'une Emma** adverse."], "diagram": ""}], "combos": [], "counters": [{"hero": "wolverine", "note": "Il t'attrape et t'emporte loin de tes soins. Garde le grand mur pour lui couper la route."}, {"hero": "iron-man", "note": "Il reste hors de portée et détruit tes murs depuis les airs."}, {"hero": "winter-soldier", "note": "Son crochet te sort de ta position."}, {"hero": "emma-frost", "note": "Elle charge son rayon sur tes murs."}, {"hero": "captain-america", "note": "Il passe par-dessus tes murs et harcèle ta backline."}, {"hero": "loki", "note": "Il détruit tes murs à distance sans se mettre en danger."}], "synergies": [{"hero": "magneto", "note": "Un second tank flexible, pour avancer ou pour protéger la backline."}, {"hero": "moon-knight", "note": "Le combo d'ults de référence : sa main frappe tout ce que tu regroupes."}, {"hero": "namor", "note": "Son ult achève les ennemis retenus dans ta prison."}, {"hero": "human-torch", "note": "Ses zones de feu brûlent toute la prison."}, {"hero": "cloak-and-dagger", "note": "Le voile de Cloak rend vulnérable la cible que tu viens d'isoler."}, {"hero": "mantis", "note": "Votre team-up donne à ton mur un soin, et le passif de tes murs depuis la saison 11."}], "sources": [{"url": "https://www.youtube.com/watch?v=l6xG6WAsYMU", "title": "Groot Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Bubble Buddies", "partners": ["jeff-the-land-shark"], "key": "", "text": "Une bulle-bouclier rend invincible et soigne. **Amélioré :** Ajoute de la vie bonus."}, {"name": "Flora Munitions", "partners": ["star-lord"], "key": "", "text": "Pièges d'épines qui immobilisent. **Amélioré :** Plus de pièges et de dégâts."}, {"name": "Planet X Pals", "partners": ["rocket-raccoon"], "key": "", "text": "Spores épineuses qui blessent et soignent. **Amélioré :** Rocket peut monter sur Groot."}, {"name": "Wild Wall", "partners": ["mantis"], "key": "", "text": "Le Wild Wall soigne et donne de la vie bonus ; il profite du passif Flora Colossus depuis la saison 11. **Amélioré :** Le mur évolue après avoir soigné."}], "changes": [{"season": "Saison 11", "text": "Thornlash Wall : dégâts de Flora Colossus 60 → 65. Ironwood Wall : vie 600 → 550."}, {"season": "Saison 11", "text": "Team-up avec Mantis : le Wild Wall profite désormais du passif Flora Colossus."}, {"season": "Saison 10", "text": "Ironwood Wall : vie bonus 40 → 50."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'groot' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Hawkeye est le Duelist au risque et à la récompense les plus élevés. Une flèche chargée tue d'un tir à la tête, ce qui lui permet d'abattre seul un support en pleine ult. En contrepartie, il n'a presque aucune mobilité et souffre face au dive.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["**Garde ton viseur sur la cible** pour charger tes flèches : deux tirs au corps suffisent souvent.", "Rejoins ton angle **en marchant** : le saut se garde pour survivre.", "Au moment de tirer, **arrête de bouger** : ta visée devient plus simple."], "difficulty": 3, "tags": ["Sniper", "One-shot", "Anti-ult", "Parade"], "strengths": ["Tue en un tir à la tête", "Abat un support dans sa propre ult", "Parade des projectiles"], "weaknesses": ["Une seule évasion", "Ralenti quand il charge une flèche", "Dépend entièrement de sa visée"], "playbook": [{"when": "Un support adverse lance son ult (Luna, Cloak & Dagger, Mantis)", "then": "**Flèche chargée à la tête** : tu es l'un des seuls héros à pouvoir le tuer dedans."}, {"when": "Un diver te saute dessus (Venom, Captain America)", "then": "Attends qu'il ait atterri, **coup d'épée de zone** pour le repousser, puis flèche au corps. Si cela ne suffit pas, saute vers ton équipe."}, {"when": "Un volant domine le fight (Iron Man, Angela, Ultron)", "then": "**Flèche hypersonique** : elle le fait tomber."}, {"when": "Les ennemis sont groupés dans un couloir", "then": "Flèche hypersonique à travers le groupe : chaque cible touchée charge ton ult."}, {"when": "Tu as l'avantage sur un duel à distance", "then": "**Deux tirs au corps** plutôt qu'un tir à la tête incertain."}, {"when": "Un projectile simple arrive (flèche adverse, boule de neige de Luna)", "then": "**Parade** au coup de mêlée, puis flèche pendant qu'il recharge."}], "sections": [{"title": "Philosophie de jeu", "lead": "Hawkeye vit de sa visée, mais il n'a pas besoin de ne tirer qu'à la tête : des tirs au corps réguliers suffisent à peser sur un fight.", "ability": "", "key": "", "kind": "tips", "items": ["Ce que lui seul sait faire : **tuer un support à travers son ult**. Contre trois supports, c'est décisif.", "Charge tes flèches **à couvert**, en ne montrant qu'une épaule : tu vois ta cible, elle te touche à peine.", "Charger une flèche **te ralentit** : ne reste pas armé quand un diver approche."], "diagram": "", "scene": {"title": "Charger à couvert", "caption": "Ton passif monte tant que ton viseur reste sur un ennemi, même si tu ne tires pas. Fais-le à l'abri.", "steps": ["À l'angle du mur, viseur sur le tank : ton passif monte.", "Tu bascules sur la vraie cible et tu lâches la flèche chargée.", "Tu repasses derrière le mur avant la riposte."], "els": [{"t": "cover", "at": [110, 30], "size": [18, 62], "label": "Mur"}, {"t": "pawn", "at": [140, 100], "team": "me"}, {"t": "path", "kind": "sight", "team": "me", "pts": [[140, 100], [212, 112]], "n": 1}, {"t": "path", "kind": "shot", "team": "me", "pts": [[140, 100], [286, 70]], "n": 2}, {"t": "path", "kind": "move", "team": "me", "pts": [[128, 104], [104, 108], [96, 80]]}, {"t": "pawn", "at": [94, 68], "team": "me", "ghost": true}, {"t": "note", "at": [76, 96], "text": "3", "team": "me"}, {"t": "pawn", "at": [286, 70], "team": "enemy", "role": "heal", "label": "Cible", "above": true}, {"t": "pawn", "at": [214, 112], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [250, 36], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [250, 150], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [292, 124], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [160, 148], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [96, 150], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [40, 104], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [46, 144], "team": "ally", "role": "heal"}]}}, {"title": "Flèches", "lead": "Plus une flèche est bandée, plus elle fait mal. Ton passif ajoute des dégâts tant que ton viseur reste posé sur un ennemi.", "ability": "", "key": "Clic G", "kind": "default", "items": ["Les flèches sont très rapides : **l'anticipation est minime**.", "Tu peux monter ton passif **sur un tank** au front, puis basculer sur la cible éloignée.", "Les **flèches explosives** servent contre le décor, les clones de Loki ou une cible que tu ne peux pas viser longtemps."], "diagram": ""}, {"title": "Flèche hypersonique", "lead": "Une flèche qui traverse les ennemis, les ralentit et fait tomber les volants. Elle est plus large depuis la saison 10.5.", "ability": "Hypersonic Arrow", "key": "", "kind": "default", "items": ["Dans un **groupe**, elle charge ton ult d'un seul tir.", "Elle **cloue au sol** Iron Man, Angela et Ultron.", "Suivie d'une **flèche chargée au corps**, elle tue un héros fragile.", "C'est la capacité que les Hawkeye oublient le plus : mets-la dans ta rotation."], "diagram": ""}, {"title": "Coup d'épée et parade", "lead": "Un coup d'épée de zone qui repousse les ennemis, et un coup de mêlée qui pare les projectiles s'il est bien synchronisé.", "ability": "Crescent Slash · Ronin Slash", "key": "", "kind": "default", "items": ["Le coup de zone est ta **défense contre les divers** : lance-le après leur atterrissage, pas avant.", "Au contact : **deux coups de mêlée, coup de zone, flèche chargée au corps**.", "La **parade** arrête les projectiles non explosifs : flèches, coups à distance, boule de neige de Luna.", "Les meilleurs Hawkeye parent, laissent l'adversaire recharger, puis placent leur flèche."], "diagram": ""}, {"title": "Saut", "lead": "Un double saut dans la direction de ton choix. C'est ta seule vraie sortie.", "ability": "Skyward Leap", "key": "", "kind": "default", "items": ["Ne le dépense pas pour **monter sur ton angle** : installe-toi en marchant, ou après un fight gagné.", "Quand on te dive, **descends vers ton équipe**. Tu remonteras en sautant quand il te suivra en bas."], "diagram": ""}, {"title": "Ultime", "lead": "Tes flèches se chargent presque instantanément, et les ennemis laissent derrière eux des images rémanentes que tu peux toucher.", "ability": "Hunter's Sight", "key": "Q", "kind": "default", "items": ["Elle est aussi redoutée que celles de Star-Lord ou de Punisher : **tu seras la cible prioritaire**.", "Lance-la dans un **espace ouvert**, quand l'adversaire n'a plus de quoi y répondre.", "Un seul kill, ou une ult de support forcée, suffit à la rentabiliser.", "Contre l'ult de Magneto, saute : elle ne se pare pas.", "Elle se charge vite : tu l'auras à presque chaque fight."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Rester **flèche bandée** face à un diver.", "Utiliser le **saut pour s'installer**.", "Chercher la tête **à tout prix**.", "Oublier la **flèche hypersonique**.", "Lancer l'ult **sans équipe** autour."], "diagram": ""}], "combos": [{"note": "La flèche chargée au corps suffit.", "steps": [{"key": "", "label": "Flèche hypersonique"}, {"key": "Clic G", "label": "flèche chargée"}], "title": "Tuer un fragile"}, {"note": "", "steps": [{"key": "Mêlée", "label": ""}, {"key": "Mêlée", "label": ""}, {"key": "", "label": "Coup de zone"}, {"key": "Clic G", "label": "flèche chargée"}], "title": "Au contact"}], "counters": [{"hero": "venom", "note": "Il te déloge de ton angle à chaque fight."}, {"hero": "captain-america", "note": "Il te rejoint en sprint et ton coup d'épée ne suffit pas à le tenir à distance."}, {"hero": "iron-fist", "note": "Il pare tes flèches et te colle sans que tu puisses fuir."}, {"hero": "psylocke", "note": "Invisible, elle arrive au contact avant que tu l'aies vue."}, {"hero": "magneto", "note": "Son bouclier te prive de cibles sur le point."}], "synergies": [{"hero": "luna-snow", "note": "Le support près duquel jouer ton angle : elle te soigne de loin et gèle le diver."}, {"hero": "invisible-woman", "note": "Son bouclier te couvre pendant que tu tires."}, {"hero": "venom", "note": "Tu entames au corps, il achève dans la backline."}, {"hero": "black-widow", "note": "Votre team-up est renforcé en saison 11."}, {"hero": "namor", "note": "Ses tourelles gardent ton angle contre les divers."}], "sources": [{"url": "https://www.youtube.com/watch?v=L10v3F9r5Hs", "title": "Hawkeye Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Allied Agents", "partners": ["black-widow"], "key": "", "text": "Les cumuls de concentration donnent des balles renforcées (2 cumuls suffisent en saison 11) ; les critiques gardent la concentration active, et la moitié des dégâts en concentration devient de la vie bonus pour Black Widow (75 max)."}, {"name": "Moonlit Slash", "partners": ["cloak-and-dagger"], "key": "", "text": "Entaille lumineuse qui soigne les alliés, et Hawkeye se soigne d'autant (10.5). **Amélioré :** Combo en trois coups."}, {"name": "Senbonzakura Strike", "partners": ["psylocke"], "key": "", "text": "Hawkeye stocke des flèches psioniques (33 dégâts en 10.5) et les tire ensemble. **Amélioré :** Encochage plus rapide et explosions."}], "changes": [{"season": "Saison 11", "text": "Team-up avec Black Widow (Allied Agents) : elle gagne de la vie bonus en concentration, qui s'active à 2 cumuls au lieu de 3."}, {"season": "Saison 10.5", "text": "Piercing Arrow plus rapide (140 à 210 m/s), Hypersonic Arrow plus large (3 m → 5 m), Crescent Slash récupère un peu plus vite."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'hawkeye' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Hela est une tireuse hitscan qui élimine un héros fragile en deux tirs à la tête. Sa force ne vient pas seulement de la visée : elle vient du choix d'angles décalés où les tirs deviennent faciles, et d'une forme de corbeau invulnérable qui lui permet d'en repartir.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["Prends des **angles décalés** : un tir sur une cible qui ne te regarde pas est un tir facile.", "Le **corbeau est une sortie**, jamais une entrée : rejoins ton angle à pied.", "Lance ton ult **là où l'ennemi ne peut pas se cacher**, après avoir forcé ses réponses."], "difficulty": 2, "tags": ["Hitscan", "Angles décalés", "Burst", "Invulnérabilité"], "strengths": ["Deux tirs à la tête pour tuer", "Invulnérable en corbeau", "Étourdissement à distance"], "weaknesses": ["Vulnérable une fois le corbeau dépensé", "Dégâts réduits à longue distance", "Sans angle, un bouclier la neutralise"], "playbook": [{"when": "Une cible fragile est sur ta ligne de tir", "then": "**Tête, étourdissement, tête.** L'étourdissement l'immobilise pour le second tir."}, {"when": "Un diver te saute dessus (Black Panther, Magik, Iron Fist)", "then": "**Étourdis-le en plein déplacement** : sa capacité est annulée. Puis deux tirs."}, {"when": "Une ult part sur toi (Doctor Strange, Magneto, Storm, Winter Soldier)", "then": "**Corbeau** : tu es invulnérable. Anticipe, la transformation a un court délai."}, {"when": "Tu viens de tuer une cible près d'un autre ennemi", "then": "Attire le second dans l'**explosion du corbeau** avec ton étourdissement : il lui reste un tir à vivre."}, {"when": "Ton angle ne donne plus rien après quelques tirs", "then": "**Change d'angle** au lieu d'insister : ne sacrifie pas ta position pour un kill."}, {"when": "L'adversaire n'a plus de bouclier ni d'ult défensive, et se bat sur le point", "then": "**Ult** : il n'a nulle part où aller."}], "sections": [{"title": "Philosophie de jeu", "lead": "Les meilleures Hela ne sont pas celles qui touchent tout : ce sont celles qui se créent des tirs faciles.", "ability": "", "key": "", "kind": "tips", "items": ["Prends un angle, **fais des dégâts vite**, puis déplace-toi avant que l'on vienne te chercher.", "Un DPS sert d'abord à **chasser l'adversaire des bonnes positions**. Un tir à la tête qui force un repli vaut presque un kill.", "Travaille ta visée par clics, sur cibles fixes puis mobiles : c'est exactement le geste que demande Hela."], "diagram": "angle"}, {"title": "Dagues", "lead": "Des dagues instantanées qui tuent un héros fragile en deux tirs à la tête, et une volée de dagues explosives qui se plantent dans leur cible.", "ability": "Nightsword Thorn · Piercing Night", "key": "Clic G · Clic D", "kind": "default", "items": ["À longue distance, les dégâts baissent : il faut alors **un tir de plus**.", "La **volée explosive** s'utilise sur un groupe, sur un bouclier, ou pour finir une cible entamée.", "Les dagues **restent plantées** : la cible emporte l'explosion au milieu de son équipe."], "diagram": ""}, {"title": "Étourdissement", "lead": "Un projectile qui attire légèrement sa cible et l'étourdit un court instant : assez pour un tir à la tête sans effort.", "ability": "Soul Drainer", "key": "E", "kind": "default", "items": ["Il **interrompt une incantation**, par exemple celle de l'ult de Doctor Strange.", "Face aux divers, **garde-le** : ils attendent que tu le dépenses pour te sauter dessus.", "Touché en plein dash ou en plein saut, l'ennemi **perd sa capacité**."], "diagram": ""}, {"title": "Corbeau", "lead": "Tu te transformes en nuée de corbeaux, invulnérable, et tu files dans la direction visée.", "ability": "Astral Flock", "key": "", "kind": "default", "items": ["L'erreur la plus répandue est de s'en servir **pour entrer**. Sans lui, tu n'as plus aucune défense.", "Ne t'envole pas au-dessus des boucliers sans raison : tu deviens la cible la plus visible du fight.", "Il **esquive les ults**, à condition d'anticiper le court délai de transformation.", "Si tu en sors à bas PV, **signale-le** à tes supports."], "diagram": "", "scene": {"title": "Le corbeau sert à repartir", "caption": "Une Hela qui a dépensé son corbeau pour arriver n'a plus rien quand le diver se retourne vers elle.", "steps": ["Tu rejoins ton angle à pied, corbeau disponible.", "Un diver arrive : tu l'étourdis en plein bond.", "S'il survit, corbeau vers ton équipe."], "els": [{"t": "area", "at": [110, 8], "size": [96, 50], "label": "Hauteur"}, {"t": "pawn", "at": [88, 120], "team": "me", "ghost": true}, {"t": "path", "kind": "move", "team": "me", "pts": [[88, 120], [92, 60], [150, 34]], "n": 1}, {"t": "pawn", "at": [158, 34], "team": "me", "ghost": true}, {"t": "pawn", "at": [232, 44], "team": "enemy", "role": "dps", "ghost": true}, {"t": "path", "kind": "move", "team": "enemy", "pts": [[232, 44], [200, 30]]}, {"t": "pawn", "at": [196, 30], "team": "enemy", "hero": "black-panther", "above": true}, {"t": "note", "at": [178, 52], "text": "2", "team": "me"}, {"t": "path", "kind": "move", "team": "me", "pts": [[158, 40], [150, 100], [100, 132]], "n": 3}, {"t": "pawn", "at": [98, 134], "team": "me"}, {"t": "pawn", "at": [130, 108], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [60, 96], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [56, 144], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [150, 150], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [226, 108], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [262, 140], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [292, 84], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [292, 124], "team": "enemy", "role": "heal"}]}}, {"title": "Passifs", "lead": "Chaque élimination fait apparaître un corbeau qui explose peu après. Hela peut aussi planer en maintenant le saut.", "ability": "Nastrond Crowstorm · Hel's Descent", "key": "", "kind": "default", "items": ["L'explosion **entame les ennemis voisins** : il ne leur faut plus qu'un tir à la tête et un au corps.", "Planer depuis ton angle après un kill permet d'enchaîner, mais t'expose aux autres tireurs."], "diagram": ""}, {"title": "Ultime", "lead": "Tu t'élèves et tu lances des corbeaux explosifs. Tu vois les ennemis à travers les murs, et seul un gros burst peut te faire redescendre.", "ability": "Goddess of Death", "key": "Q", "kind": "default", "items": ["Contre une compo de mêlée (**Magik, The Thing, Invisible Woman**), lance-la sans hésiter : personne ne peut t'atteindre.", "Contre des tireurs, **élimine-les ou force leurs cooldowns** d'abord.", "Entame le bouclier de **Doctor Strange** avant : il viendra se placer devant toi.", "Lance-la **sur le point ou en prolongation**, là où l'adversaire ne peut pas reculer."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["**Insister** sur un angle qui ne donne plus rien.", "Dépenser le **corbeau pour entrer**.", "Lancer l'étourdissement **avant** l'arrivée du diver.", "Lancer l'ult quand l'ennemi **peut s'abriter**.", "Oublier l'**explosion du corbeau** après un kill."], "diagram": ""}], "combos": [{"note": "L'étourdissement en plein déplacement **annule aussi leur capacité**.", "steps": [{"key": "Clic G", "label": "tête"}, {"key": "E", "label": "étourdir"}, {"key": "Clic G", "label": "tête"}], "title": "Combo de base"}], "counters": [{"hero": "hulk", "note": "Il saute sur ton angle et te force à le quitter."}, {"hero": "venom", "note": "Même pression, pire encore avec un second diver."}, {"hero": "captain-america", "note": "Il te rejoint en quelques secondes et encaisse tes deux tirs."}, {"hero": "doctor-strange", "note": "Sur une carte sans angle, son bouclier absorbe tout ton fight."}, {"hero": "invisible-woman", "note": "Son bouclier protège la cible que tu allais finir."}, {"hero": "rocket-raccoon", "note": "Ses packs d'armure font passer tes kills de deux à trois tirs."}], "synergies": [{"hero": "thor", "note": "Un tank qui revient te protéger des divers, et un team-up qui te ramène à la vie."}, {"hero": "loki", "note": "Il peut tenir ton angle avec toi et poser ses runes sous tes pieds."}, {"hero": "namor", "note": "Ses tourelles gardent ton angle."}, {"hero": "mantis", "note": "Son bonus de dégâts réduit tes kills à un tir à la tête et un au corps."}, {"hero": "adam-warlock", "note": "Deux hitscans sur la même cible : elle ne survit pas."}], "sources": [{"url": "https://www.youtube.com/watch?v=KD6ORSun0ZE", "title": "Hela Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Circle of Life", "partners": ["phoenix"], "key": "", "text": "Les tirs de Netherfire posent des étincelles et étourdissent. **Amélioré :** Plus d'étincelles."}, {"name": "Deep Wrath", "partners": ["namor"], "key": "", "text": "Les kills de Hela font apparaître des monstros morts-vivants. **Amélioré :** Ils apparaissent à chaque attaque."}, {"name": "Hel Tendrils", "partners": ["venom"], "key": "", "text": "Des tentacules attirent et ralentissent les ennemis. **Amélioré :** Les Nightsword Thorns soignent en plus."}, {"name": "Hel-Yeah, Honey", "partners": ["deadpool"], "key": "", "text": "Deadpool débloque une amélioration en plus pour ses Desert Eagles et ses katanas."}, {"name": "Ragnarok Rebirth", "partners": ["thor"], "key": "", "text": "Une vie bonus empêche la mort et permet de revenir sur un kill. **Amélioré :** Résurrection instantanée."}, {"name": "Ragnarök", "partners": ["gorr-the-god-butcher"], "key": "", "text": "Coup de faux qui cloue les ennemis au sol. **Amélioré :** Plus de portée et vie bonus."}, {"name": "Villain's Illusion", "partners": ["loki"], "key": "", "text": "Prend la forme d'un héros tombé. Depuis la saison 11, une illusion détruite met Doppelganger et Devious Exchange 1 s en cooldown. **Amélioré :** Dure plus longtemps et empêche la mort."}], "changes": [{"season": "Saison 11", "text": "Team-up avec Loki : une illusion détruite met Doppelganger et Devious Exchange 1 s en cooldown."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'hela' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Hulk est l'un des Vanguards les plus exigeants. Il se bat au front, saute sur les tireurs perchés et protège ses alliés avec des bulles posées au bon moment. Tout son jeu repose sur une distinction : l'engage léger qui force les cooldowns, et l'engage total qui tue.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["**Charge ton saut en permanence**, même en frappant.", "Tes **bulles sont pour tes alliés** autant que pour toi.", "Ton **exil** doit retirer une ult adverse du fight : décide de sa cible avant qu'il commence."], "difficulty": 3, "tags": ["Dive", "Bulles", "Contrôle", "Exigeant"], "strengths": ["Bulles de groupe contre les ults de burst", "Saut qui attrape les volants", "Exil : deux secondes hors du jeu pour une cible"], "weaknesses": ["Redevient Bruce Banner à sa mort", "Saut annulé par le moindre contrôle", "Grosse hitbox, facile à user de loin"], "playbook": [{"when": "Un tireur adverse tient un angle en hauteur", "then": "**Saute dessus sans bulle ni ult** : il dépense son évasion, tu reviens. C'est un engage léger."}, {"when": "L'ennemi vient de dépenser ses cooldowns défensifs", "then": "**Engage total** : saut, coups, clap, bulle sur toi. Cette fois, la cible meurt."}, {"when": "Un diver saute sur ton DPS ou tes supports", "then": "Saute sur ton allié et **bulle-le**, puis frappe le diver."}, {"when": "Une ult de burst part sur ton équipe (Doctor Strange, Magneto, Psylocke)", "then": "**Bulle de groupe** au moment de l'impact. Contre Iron Man, saute et intercepte le projectile sous bulle."}, {"when": "Une ult adverse menace de gagner le fight (Psylocke, Iron Man qui vise ta Luna)", "then": "**Exil** sur le lanceur : deux secondes hors du jeu suffisent à la gâcher."}, {"when": "Un volant lance son ult (Star-Lord, Iron Man, Human Torch)", "then": "**Saut chargé sur lui** : tu l'attrapes et tu le ramènes au sol."}], "sections": [{"title": "Philosophie de jeu", "lead": "Hulk s'adapte à la compo adverse : il brawle au front contre une équipe groupée, et saute sur les angles contre une équipe à distance.", "ability": "", "key": "", "kind": "tips", "items": ["**Engage léger** : un saut sur un angle, sans bulle ni ult, pour attirer l'attention et faire dépenser les cooldowns. Tu reviens ensuite.", "**Engage total** : une fois ces cooldowns dépensés, tu reviens pour tuer ou pour prendre la position.", "Ne perds pas de temps sur une cible que tu ne peux pas tuer. Mais quand le kill est possible, **va au bout**.", "Après une élimination, profite du surnombre pour passer sur la backline."], "diagram": "dive"}, {"title": "Coups et clap", "lead": "Des coups de poing à bonne allonge, et un clap qui envoie une onde traversante.", "ability": "Heavy Blow · Gamma Burst", "key": "Clic G", "kind": "default", "items": ["Le **clap** en début de fight charge ton ult et déloge une cible de sa position.", "**Coup de poing puis clap** pour finir une cible basse.", "Clappe **pendant ton saut** : l'onde part dès l'atterrissage.", "Aligne le clap sur plusieurs ennemis, puis saute sur celui qui reste en arrière."], "diagram": ""}, {"title": "Bulles", "lead": "Une bulle qui protège tous les alliés proches pendant quelques instants. Les dégâts absorbés par la tienne chargent ton ult.", "ability": "Indestructible Guard", "key": "", "kind": "default", "items": ["**Sauver un allié** : saute sur ta Hela ou ton support en difficulté et bulle-le.", "**Couvrir une poussée** : bulle tout le groupe au moment où il avance.", "**Annuler une ult** de burst : Doctor Strange, Magneto, Psylocke.", "L'erreur la plus fréquente est de ne jamais bulle que soi-même."], "diagram": "", "scene": {"title": "La bulle pour un allié", "caption": "Un saut et une bulle transforment un duel perdu par ton DPS en un 2 contre 1 gagné.", "steps": ["Un diver saute sur ta tireuse.", "Tu sautes sur elle, saut déjà chargé.", "Bulle sur vous deux, puis tu frappes le diver."], "els": [{"t": "area", "at": [30, 8], "size": [124, 76], "label": "Hauteur"}, {"t": "pawn", "at": [214, 26], "team": "enemy", "role": "dps", "ghost": true}, {"t": "path", "kind": "move", "team": "enemy", "pts": [[214, 26], [170, 14], [126, 40]], "n": 1}, {"t": "pawn", "at": [70, 46], "team": "ally", "hero": "hela", "above": true}, {"t": "pawn", "at": [118, 46], "team": "enemy", "hero": "black-panther", "above": true}, {"t": "pawn", "at": [166, 124], "team": "me", "ghost": true}, {"t": "path", "kind": "move", "team": "me", "pts": [[166, 124], [112, 120], [94, 78]], "n": 2}, {"t": "zone", "at": [90, 56], "r": 30, "team": "me"}, {"t": "pawn", "at": [92, 72], "team": "me"}, {"t": "note", "at": [44, 70], "text": "3", "team": "me"}, {"t": "pawn", "at": [52, 116], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [56, 154], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [120, 150], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [232, 100], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [266, 132], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [292, 84], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [292, 124], "team": "enemy", "role": "heal"}]}}, {"title": "Saut prodigieux", "lead": "Maintiens la touche pour charger le saut, relâche pour partir. Tu peux t'accrocher aux murs et attraper les volants.", "ability": "Incredible Leap", "key": "", "kind": "default", "items": ["**Charge-le tout le temps**, pendant que tu frappes et que tu bulles.", "Tout contrôle (poussée, étourdissement) **annule la charge** : méfie-toi d'Invisible Woman et de Magneto.", "Toucher un **volant** l'attrape et le ramène au sol, ult comprise.", "Dans un brawl miroir, saute en l'air pour **te faire soigner hors de portée**."], "diagram": ""}, {"title": "Exil", "lead": "Un projectile lent qui retire sa cible du jeu pendant deux secondes : elle ne peut ni agir, ni subir de dégâts, ni contester l'objectif.", "ability": "Radioactive Lockdown", "key": "", "kind": "default", "items": ["Il sert à **retirer une menace précise** : la Psylocke en ult, l'Iron Man qui vise ta backline, le Doctor Strange qui sort de son portail.", "Une cible exilée **survit aux ults de ton équipe**. Seuls tes coups peuvent la libérer plus tôt.", "Ne le dépense pas pour un coup d'éclat sur un volant sans conséquence."], "diagram": ""}, {"title": "Ultime", "lead": "Tu deviens Monster Hulk : beaucoup de vie, des coups qui repoussent, un clap très rapide et un exil plus fréquent. Tu n'as plus de bulles.", "ability": "Hulk Smash · World Breaker", "key": "Q", "kind": "default", "items": ["**Jongle** : projette un ennemi en l'air, puis saute dessus pour l'étourdir. C'est plus facile contre un mur.", "**Coup, clap, coup** tue rapidement un héros fragile.", "World Breaker t'immobilise avec ta cible : sers-t'en pour **interrompre une ult** (un Loki en pleine copie).", "L'ult sert à **prolonger un engage** ou à **tenir le point**.", "Si tu meurs, tu redeviens **Bruce Banner** : tire et lance tes grenades à tes pieds pour recharger ta transformation."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["**Ne pas charger** son saut entre deux actions.", "Ne bulle **que soi**.", "Exiler une cible que **ton équipe allait tuer**.", "Engager à fond **avant** que les cooldowns adverses soient dépensés.", "S'acharner sur une cible **inatteignable**."], "diagram": ""}], "combos": [{"note": "", "steps": [{"key": "Clic G", "label": "coup de poing"}, {"key": "", "label": "Clap"}], "title": "Finir une cible"}], "counters": [{"hero": "emma-frost", "note": "Elle charge son rayon sur toi et t'étrangle. Saute dès qu'elle extrait ton cristal."}, {"hero": "groot", "note": "Ses murs te séparent de tes soins : saute par-dessus ou casse-les."}, {"hero": "the-punisher", "note": "Il vide ta barre de vie de loin, sans que tu puisses t'approcher."}, {"hero": "iron-man", "note": "Il te tire dessus d'en haut tant que ton saut n'est pas chargé."}, {"hero": "invisible-woman", "note": "Sa poussée annule ton saut et son attraction te ramène quand tu fuis."}], "synergies": [{"hero": "magneto", "note": "Il couvre de sa bulle et de son bouclier ce que tu ne peux pas gérer."}, {"hero": "psylocke", "note": "Elle entre avec toi, puis revient brawler au centre."}, {"hero": "namor", "note": "Ses tourelles et tes bulles rendent ta backline très difficile à diver."}, {"hero": "wolverine", "note": "Votre team-up te permet de le lancer sur une cible."}, {"hero": "luna-snow", "note": "Ses soins à longue portée te suivent pendant tes sauts."}], "sources": [{"url": "https://www.youtube.com/watch?v=YZf3psRKPmE", "title": "Hulk Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Gamma Charge", "partners": ["iron-man"], "key": "", "text": "Gamma Overdrive avec un bouclier. **Amélioré :** Crée un canon à impulsion gamma."}, {"name": "Gamma Fastball", "partners": ["wolverine"], "key": "", "text": "État furieux et Scars of Rage (+25 % vitesse d'attaque et de déplacement en 10.5). **Amélioré :** Débloque le Fastball Special (Unstoppable : seuil 400, cooldown 45 s en 10.5)."}, {"name": "Gamma Maelstrom", "partners": ["doctor-strange"], "key": "", "text": "Le Maelstrom gamma accélère la charge. **Amélioré :** Garde et stocke l'énergie (25 au minimum en saison 11)."}, {"name": "Gamma Monstro", "partners": ["namor"], "key": "", "text": "Un monstro gamma en plus (cooldown 25 s depuis la saison 10). **Amélioré :** Ajoute une barrière d'eau gamma."}, {"name": "Savage Slam", "partners": ["captain-america"], "key": "", "text": "Un saut écrasé réduit les cooldowns. **Amélioré :** Ajoute la vulnérabilité."}], "changes": [{"season": "Saison 11", "text": "Team-up avec Doctor Strange (Gamma Maelstrom amélioré) : énergie minimale conservée 50 → 25."}, {"season": "Saison 10.5", "text": "Banner : Gamma Ray Gun plus rapide (80 → 120 m/s), Gamma Grenade rend 100 d'énergie gamma au lieu de 50."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'hulk' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Human Torch n'est pas un chasseur d'éliminations : c'est un contrôleur de zone volant. Ses boules de feu et ses murs de flammes découpent l'équipe adverse et empêchent ses supports de soigner tranquillement ; son plongeon fait ensuite exploser ces zones sur les cibles affaiblies.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["**Pose tes zones d'abord** : la pression vient avant le kill.", "**Fusil et plongeon** servent à finir le fight, pas à l'ouvrir.", "Avant ton ult : à couvert, dans la ligne de vue de tes supports, une boule de feu prête à partir."], "difficulty": 2, "tags": ["Contrôle de zone", "Vol", "Dégâts sur la durée", "Combos d'ult"], "strengths": ["Interdit des zones entières", "Plongeon qui fait exploser ses zones", "Ult qui traverse les ults de soin"], "weaknesses": ["Cible facile pour les hitscans", "Plongeon long à revenir", "Peu de dégâts sans préparation"], "playbook": [{"when": "Les supports adverses soignent à l'abri sous un toit", "then": "**Boules de feu sur eux** : ils doivent sortir à découvert ou brûler."}, {"when": "Une cible reste dans deux zones de feu", "then": "**Plongeon** sur l'une d'elles : chaque zone proche explose. Deux zones tuent un héros fragile, trois tuent bien plus solide."}, {"when": "Un allié est pris dans l'ult de Doctor Strange, ou un support adverse est dans son ult de zone", "then": "**Plongeon** : il repousse les ennemis à l'opposé de ton arrivée."}, {"when": "Tu défends, ou tu viens de gagner un fight", "then": "**Pose tes boules à l'avance** sur le passage et ne relie la prison que lorsque l'ennemi est dedans."}, {"when": "Tu veux lancer ton ult", "then": "Lance une boule de feu **juste avant** : elle devient une tornade. Celles déjà au sol ne se transforment pas."}, {"when": "Ta jauge de vol est presque vide", "then": "**Rejoins un couvert maintenant.** À sec en terrain découvert, tu es mort."}], "sections": [{"title": "Philosophie de jeu", "lead": "Là où Iron Man pèse par ses dégâts bruts, Johnny décide des endroits où l'adversaire a le droit de se tenir.", "ability": "", "key": "", "kind": "tips", "items": ["Travaille en trois temps : **grande prison** depuis une hauteur ou un flanc, repérage de la cible que les soins négligent, puis **double zone et plongeon**.", "Vole **près du décor**, de couvert en couvert : en plein ciel, tes supports ne te voient pas et les hitscans te descendent.", "Joue à **moyenne portée** : assez loin pour poser tes zones, assez près pour que le fusil touche.", "Avant de plonger, garde **des munitions et un peu de vol** pour repartir, et vérifie que tes supports te voient.", "Avec le flocon de Luna Snow ou le bouclier d'Invisible Woman sur toi, tu peux prendre nettement plus de risques."], "diagram": "highground"}, {"title": "Fusil de feu", "lead": "Un fusil à projectiles sans rechargement : les munitions reviennent d'elles-mêmes quand tu cesses de tirer.", "ability": "Fire Cluster", "key": "Clic G", "kind": "default", "items": ["Au-delà de la mi-distance, il se disperse : **c'est une arme de fin de fight**, au contact des cibles entamées.", "Depuis la saison 11, la dispersion est **fixe** et non plus aléatoire : à distance égale, tes rafales touchent de façon régulière.", "Un **coup de mêlée** accélère le retour des munitions.", "Alterne **rafales et boules de feu** : tu gardes des munitions tout en maintenant tes dégâts."], "diagram": ""}, {"title": "Boules de feu", "lead": "Trois charges. Chaque boule laisse une zone brûlante au sol : c'est ton outil de poke à distance.", "ability": "Blazing Blast", "key": "Clic D", "kind": "default", "items": ["Lance-les sur **les tanks et les supports**, là où ils veulent se tenir.", "Avant de plonger sur un support : **une boule derrière lui, une sur lui**.", "En terrain ouvert, un pas de côté suffit à les éviter : vise les couloirs et les abris.", "Contre une cible très mobile (Spider-Man, Storm), elles touchent plus facilement que le fusil. Contre un autre volant en duel, c'est l'inverse."], "diagram": ""}, {"title": "Prison de flammes", "lead": "Trois zones de feu au sol ou plus peuvent être reliées par des murs de flammes qui enferment et brûlent ce qui se trouve à l'intérieur.", "ability": "Pyro-Prison", "key": "", "kind": "default", "items": ["Un rectangle posé à la vue de tous est évité : **pose les boules d'abord, relie au dernier moment**.", "En attaque, enferme **le point**. En défense, enferme **le passage** par lequel ils arrivent.", "Les murs ne se forment que s'il n'y a **aucun obstacle** entre deux zones : payload, mur de Groot, marche trop haute.", "Deux zones peuvent être reliées jusqu'à 40 mètres : un point entier peut brûler.", "Un mur bien placé **sépare les deux supports** adverses."], "diagram": "", "scene": {"title": "Prison, puis plongeon", "caption": "Les murs de flammes retiennent la cible ; le plongeon fait exploser chaque zone proche d'elle.", "steps": ["Tu poses trois boules de feu autour des supports.", "Tu relies les zones : ils sont enfermés et brûlent.", "Tu plonges sur une zone : toutes celles à proximité explosent."], "els": [{"t": "area", "at": [96, 6], "size": [96, 44], "label": "Hauteur"}, {"t": "zone", "at": [232, 56], "r": 12, "team": "me"}, {"t": "zone", "at": [296, 80], "r": 12, "team": "me"}, {"t": "zone", "at": [248, 130], "r": 12, "team": "me"}, {"t": "note", "at": [206, 56], "text": "1", "team": "me"}, {"t": "bar", "from": [232, 56], "to": [296, 80], "team": "me", "n": 2}, {"t": "bar", "from": [296, 80], "to": [248, 130], "team": "me"}, {"t": "bar", "from": [248, 130], "to": [232, 56], "team": "me"}, {"t": "pawn", "at": [258, 84], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [272, 104], "team": "enemy", "role": "heal"}, {"t": "note", "at": [288, 124], "text": "enfermés", "team": "enemy"}, {"t": "pawn", "at": [150, 28], "team": "me", "ghost": true}, {"t": "path", "kind": "move", "team": "me", "pts": [[150, 28], [176, 110], [236, 138]], "n": 3}, {"t": "pawn", "at": [232, 142], "team": "me"}, {"t": "pawn", "at": [196, 84], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [206, 28], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [292, 160], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [110, 96], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [80, 136], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [46, 80], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [46, 124], "team": "ally", "role": "heal"}]}}, {"title": "Plongeon", "lead": "Tu t'écrases au sol, tu repousses les ennemis et tu gagnes de la vie bonus. Chaque zone de feu proche explose à l'impact.", "ability": "Flaming Meteor", "key": "", "kind": "default", "items": ["La poussée part **à l'opposé de ton arrivée** : choisis ton angle pour envoyer la cible dans une autre zone, vers ton équipe ou dans le vide.", "Il **sort un support de son ult de zone** (Cloak & Dagger, Invisible Woman) et libère un allié de l'ult de Strange.", "Son cooldown est long : c'est une **action de fin de fight**, avec ton équipe prête à suivre.", "Il interrompt aussi l'engage d'un Spider-Man sur toi."], "diagram": ""}, {"title": "Vol rapide", "lead": "Maintiens la touche pour voler beaucoup plus vite, tant que ta jauge le permet.", "ability": "Plasma Body", "key": "Maj", "kind": "default", "items": ["Ne tombe **jamais à sec** en terrain découvert.", "Sers-t'en pour **te placer avant l'ult**, pas pour chercher ta position pendant."], "diagram": ""}, {"title": "Ultime", "lead": "Une onde de choc autour de toi, puis tes boules de feu deviennent des tornades enflammées qui se cumulent. Tu encaisses moins de dégâts pendant la durée.", "ability": "Supernova", "key": "Q", "kind": "default", "items": ["Deux ou trois tornades au même endroit **tuent à travers une ult de soin**.", "Avec une ult de Groot, lance la tienne **juste avant** : tu es prêt quand les ennemis sont regroupés.", "Place les tornades sur **les entrées du point** pour l'interdire.", "Tire au fusil entre deux tornades. Évite de plonger : tu repousserais les ennemis hors de tes tornades.", "Ordre le plus rentable : **prison, plongeon sur double zone, ult** pour finir."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Plonger sur les supports **en début de fight**.", "Lancer des boules de feu en duel **contre un volant**.", "Tomber **à court de vol** à découvert.", "Lancer l'ult **hors de vue** de ses supports.", "Relier la prison **avant** que l'ennemi soit dedans.", "Rester **en plein ciel**."], "diagram": ""}], "combos": [], "counters": [{"hero": "hulk", "note": "Son saut t'attrape et te ramène au sol, ult comprise."}, {"hero": "star-lord", "note": "Il te poursuit en l'air et t'empêche de t'installer."}, {"hero": "iron-man", "note": "Il gagne à longue distance : ne l'affronte que de près."}, {"hero": "magneto", "note": "Son ult absorbe tes tornades."}, {"hero": "hela", "note": "Deux tirs à la tête dès que tu quittes le décor."}, {"hero": "luna-snow", "note": "Elle te touche en l'air et te gèle après ton plongeon."}], "synergies": [{"hero": "groot", "note": "Sa prison regroupe les ennemis sous tes tornades : l'un des meilleurs combos d'ults."}, {"hero": "captain-america", "note": "Ses coups repoussent les ennemis dans tes zones."}, {"hero": "psylocke", "note": "Elle achève les cibles que tes zones ont entamées."}, {"hero": "invisible-woman", "note": "Son bouclier sur toi et votre team-up te gardent en vie en l'air."}, {"hero": "luna-snow", "note": "Son flocon te soigne à distance pendant tes plongeons."}], "sources": [{"url": "https://www.youtube.com/watch?v=P9NvGuL_cho", "title": "Human Torch Guide", "author": "Paz (padswagger)"}, {"title": "Ultimate Human Torch Guide (Beginner/Advanced)", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=p_2z3BujAyQ"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Fiery Sparks", "partners": ["jubilee"], "key": "", "text": "Étincelles de feu d'artifice à tête chercheuse. **Amélioré :** Vie bonus à l'atterrissage."}, {"name": "Storming Ignition", "partners": ["storm"], "key": "", "text": "Un vortex de feu attire les ennemis. **Amélioré :** Allume des ouragans enflammés."}, {"name": "Two-in-One", "partners": ["the-thing"], "key": "", "text": "Poings enflammés (cooldown 18 s, 8 s de durée depuis la saison 10). **Amélioré :** Soulève et écrase avec étourdissement."}, {"name": "United Siblings", "partners": ["invisible-woman"], "key": "", "text": "Bouclier de flammes avec une aura de soin. **Amélioré :** Plus grand, bouclier renforcé."}], "changes": [{"season": "Saison 11", "text": "Fire Cluster : dispersion des projectiles fixe au lieu d'aléatoire."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'human-torch' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Invisible Woman est la Strategist des compos groupées. Ses orbes traversent tout ce qui se trouve sur leur ligne, alliés comme ennemis, ce qui charge son ult très vite. Sa poussée et son attraction déplacent les ennemis là où son équipe les veut, et son bouclier protège l'allié qui compte au moment où il compte.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["**Aligne alliés et ennemis** sur la même ligne : chaque orbe soigne les uns et blesse les autres, à l'aller et au retour.", "**Pousser ou attirer** au bon moment vaut un kill ou un sauvetage.", "Ton ult ne bouge pas : pose-la **sur le point**, de préférence en seconde ult."], "difficulty": 2, "tags": ["Brawl", "Déplacement d'ennemis", "Bouclier", "Charge d'ult"], "strengths": ["Orbes qui traversent un nombre illimité de cibles", "Déplace les ennemis à volonté", "Bouclier posé sur un allié à distance"], "weaknesses": ["Faible contre les compos dispersées et le dive", "Portée de soin limitée", "Ult annulée si elle meurt"], "playbook": [{"when": "Ton équipe se bat dans un couloir", "then": "Place-toi **dans l'axe** : tes alliés puis les ennemis sur la même ligne. Chaque orbe soigne et blesse tout le monde, deux fois."}, {"when": "L'équipe adverse pousse sur vous, ou un tank charge ta backline", "then": "**E + clic gauche : repousse-les.** Ils perdent leur élan et se retrouvent à découvert devant ton équipe."}, {"when": "Un DPS est perché, ou un tank s'est trop avancé", "then": "**E + clic droit : attire-le** au milieu de ton équipe. Annonce-le pour que tout le monde tire."}, {"when": "Un diver te saute dessus (Spider-Man, Magik, Black Panther)", "then": "**Double saut** pour devenir invisible. Ne le repousse qu'une fois son déplacement dépensé, sinon il revient aussitôt."}, {"when": "Un allié va prendre un burst mortel (ult de Magneto, dagues d'Hela, flèche de Hawkeye)", "then": "**Bouclier sur lui.** Rappelle-le avec F avant qu'il ne casse : il revient bien plus vite."}, {"when": "Wolverine emporte un allié", "then": "**Attire Wolverine** : il lâche sa prise."}, {"when": "Le Doctor Strange adverse a son ult", "then": "**Garde ta poussée** : tu l'éjectes pendant son incantation."}], "sections": [{"title": "Philosophie de jeu", "lead": "Tu n'as pas les dégâts pour tuer seule. Ton rôle est de placer les bonnes cibles devant ton équipe, de protéger l'allié décisif et d'avoir ton ult avant les supports adverses.", "ability": "", "key": "", "kind": "tips", "items": ["Elle est forte quand **les deux équipes sont groupées**, faible quand l'adversaire attaque par plusieurs angles.", "Dans une compo de dive, Luna Snow ou Cloak & Dagger feront mieux.", "Joue **près de ton autre support** : vous vous protégez mutuellement, et ton saut reste disponible pour les urgences."], "diagram": "peel"}, {"title": "Orbes", "lead": "Tes orbes partent en ligne droite, puis reviennent vers toi. Ils traversent tout : chaque allié touché est soigné, chaque ennemi blessé, à l'aller comme au retour.", "ability": "Orb Projection", "key": "Clic G", "kind": "default", "items": ["Cherche en permanence **la ligne qui traverse le plus de monde** : ton tank, ton DPS, leur tank, leur DPS. C'est ta charge d'ult.", "Décale-toi latéralement pour **garder tes cibles alignées** quand le fight bouge.", "Vise **le sol à la hauteur de la dernière cible** : l'orbe fait demi-tour plus tôt et repasse plus vite.", "Tiens-toi **légèrement en retrait** : le retour de l'orbe touche plus de cibles."], "diagram": "", "scene": {"title": "Le couloir d'orbes", "caption": "Un orbe bien aligné soigne deux alliés et blesse deux ennemis, puis recommence au retour : quatre effets doublés pour un seul tir.", "steps": ["Tu te places dans l'axe du fight, derrière tes alliés.", "L'orbe traverse tes alliés (soin) puis les ennemis (dégâts).", "Il revient par le même chemin et touche tout le monde une seconde fois."], "els": [{"t": "cover", "at": [60, 10], "size": [240, 26]}, {"t": "cover", "at": [60, 144], "size": [240, 26]}, {"t": "pawn", "at": [44, 90], "team": "me"}, {"t": "note", "at": [44, 60], "text": "1", "team": "me"}, {"t": "pawn", "at": [104, 90], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [150, 90], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [214, 90], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [262, 90], "team": "enemy", "role": "dps"}, {"t": "path", "kind": "beam", "team": "me", "pts": [[56, 84], [290, 84]], "n": 2}, {"t": "path", "kind": "beam", "team": "me", "pts": [[290, 98], [58, 98]], "n": 3}, {"t": "note", "at": [127, 68], "text": "soin", "team": "ally"}, {"t": "note", "at": [238, 68], "text": "dégâts", "team": "enemy"}, {"t": "pawn", "at": [86, 126], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [296, 122], "team": "enemy", "role": "heal"}]}}, {"title": "Bouclier gardien", "lead": "Un bouclier personnel que tu poses sur un allié à distance. Il le protège et le soigne. C'est une protection ciblée, pas un mur.", "ability": "Guardian Shield", "key": "Clic D", "kind": "default", "items": ["Il sert contre **le burst** : ult de Magneto ou de Doctor Strange, dagues d'Hela, flèches de Hawkeye. Il ne tient pas face au tir continu d'un Punisher.", "Posé sur un **DPS en ult** (Star-Lord, Punisher) ou sur une Hela repérée, il le rend intouchable pendant les secondes qui comptent.", "**Rappelle-le avec F** avant qu'il ne soit brisé : le cooldown est beaucoup plus court.", "Il **ralentit** les ennemis qui le traversent.", "Quand ton autre support est en difficulté, pose-le sur le groupe et place-toi derrière : tu profites aussi du couvert et du soin."], "diagram": ""}, {"title": "Poussée et attraction", "lead": "Un champ de force qui repousse ou attire les ennemis dans la zone visée. C'est la capacité qui distingue une bonne Invisible Woman.", "ability": "Force Physics", "key": "E · Clic G / Clic D", "kind": "default", "items": ["**Repousser** casse une poussée adverse : les ennemis qui avançaient sur vous repartent en arrière, sans leur élan.", "**Attirer** amène une cible dans ton équipe : un DPS perché, un tank trop avancé, un support qui recule.", "Contre un diver, attends qu'il ait **dépensé son déplacement** avant de le repousser.", "Près d'un bord de carte, la poussée **éjecte**.", "N'attire jamais un ennemi **dans une équipe en difficulté**, et ne repousse pas une cible que tes alliés allaient tuer."], "diagram": "", "scene": {"title": "Attirer, repousser", "caption": "La même capacité fait deux choses opposées : amener une cible à ton équipe, ou éloigner celle qui menace ta backline.", "steps": ["Un tireur est perché : tu l'attires au milieu de ton équipe.", "Leur tank charge : tu le repousses à découvert."], "els": [{"t": "area", "at": [196, 8], "size": [96, 46], "label": "Hauteur"}, {"t": "pawn", "at": [236, 34], "team": "enemy", "role": "dps", "ghost": true}, {"t": "path", "kind": "pull", "team": "me", "pts": [[236, 34], [184, 30], [130, 52]], "n": 1}, {"t": "pawn", "at": [124, 56], "team": "enemy", "role": "dps", "label": "Attiré", "above": true}, {"t": "pawn", "at": [70, 96], "team": "me"}, {"t": "pawn", "at": [110, 96], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [92, 40], "team": "ally", "role": "dps"}, {"t": "path", "kind": "shot", "team": "ally", "pts": [[92, 40], [124, 56]]}, {"t": "path", "kind": "shot", "team": "ally", "pts": [[110, 96], [124, 56]]}, {"t": "pawn", "at": [134, 132], "team": "enemy", "role": "tank", "ghost": true}, {"t": "path", "kind": "push", "team": "me", "pts": [[134, 132], [210, 136]], "n": 2}, {"t": "pawn", "at": [216, 136], "team": "enemy", "role": "tank", "label": "Repoussé"}, {"t": "pawn", "at": [52, 142], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [96, 150], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [278, 100], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [282, 142], "team": "enemy", "role": "heal"}]}}, {"title": "Vortex", "lead": "Une sphère qui crée une zone de ralentissement et d'attraction. Un second appui la fait éclater où tu veux.", "ability": "Psionic Vortex", "key": "Maj", "kind": "default", "items": ["Dans un brawl, pose-la **sur les tanks adverses** au moment où ils avancent.", "Elle **retient un DPS** sur son angle le temps que le tien le tue.", "Contre un diver : vortex **à tes pieds**, double saut, puis poussée pour le renvoyer dedans.", "Depuis la saison 11, elle ralentit un peu moins au centre mais ralentit aussi **en bordure** : il est plus difficile d'en sortir.", "Elle n'éclate pas d'elle-même sur le bouclier de Magneto : déclenche-la manuellement."], "diagram": ""}, {"title": "Saut et invisibilité", "lead": "Sans attaquer ni subir de dégâts, tu deviens invisible et tu te soignes. Le double saut te rend invisible immédiatement.", "ability": "Veiled Step · Covert Advance", "key": "", "kind": "default", "items": ["Le double saut est un **outil de survie** : son cooldown est passé à 8 secondes en saison 11, ne le dépense plus pour te déplacer.", "Un dive sur toi, une ult de Magneto : **saute**, puis occupe-toi de ton autre support.", "Invisible, tes **pas s'entendent** toujours."], "diagram": ""}, {"title": "Ultime", "lead": "Une zone fixe qui soigne tes alliés et les rend invisibles tant qu'ils sont à l'intérieur. Les ennemis qui la traversent sont fortement ralentis.", "ability": "Invisible Boundary", "key": "Q", "kind": "default", "items": ["Pose-la **sur le point** : l'adversaire doit entrer dedans ou abandonner l'objectif.", "Elle peut **couper l'équipe adverse en deux** : leurs supports ne voient plus leurs tanks.", "Elle ne se déplace pas : c'est une ult **de réponse**, pas d'engage.", "Elle disparaît à ta mort : méfie-toi des ults de Magneto et de Punisher, et des tirs de Hawkeye."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Tirer **sans aligner** ses cibles.", "Laisser le bouclier **se briser** au lieu de le rappeler.", "Repousser un diver **qui a encore son déplacement**.", "Dépenser le double saut **pour se déplacer**.", "Poser l'ult **loin du point**.", "Attirer un ennemi dans une équipe **déjà en difficulté**."], "diagram": ""}], "combos": [], "counters": [{"hero": "spider-man", "note": "Une compo de dive dispersée ne te laisse rien à aligner, et il revient après chaque poussée."}, {"hero": "venom", "note": "Il plonge sur toi et encaisse assez pour ignorer ta poussée."}, {"hero": "iron-man", "note": "Hors d'atteinte de tes orbes comme de ton attraction."}, {"hero": "hela", "note": "Elle te bat à distance tant que tu ne peux pas l'attirer."}, {"hero": "hawkeye", "note": "Il peut te tuer dans ta propre ult, ce qui la fait disparaître."}], "synergies": [{"hero": "the-thing", "note": "Tu attires les cibles dans sa portée ; votre team-up lui donne de la vie bonus."}, {"hero": "doctor-strange", "note": "Un tank de brawl derrière lequel aligner tes orbes."}, {"hero": "groot", "note": "Tu attires une cible, il ferme le mur derrière elle."}, {"hero": "winter-soldier", "note": "Un DPS de contact qui reste sur ta ligne d'orbes."}, {"hero": "wolverine", "note": "Tu lui amènes ses cibles au lieu qu'il aille les chercher."}, {"hero": "human-torch", "note": "Ton bouclier le garde en vie pendant ses plongeons."}], "sources": [{"url": "https://www.youtube.com/watch?v=mRt2zFGqrws", "title": "Invisible Woman Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "First Family", "partners": ["mister-fantastic"], "key": "", "text": "Invisibilité avec soin et vitesse. **Amélioré :** Version renforcée."}, {"name": "Psionic Vortex", "partners": ["doctor-strange"], "key": "", "text": "Projette les ennemis et renforce le bouclier de Strange (+100 en saison 11). **Amélioré :** Vie bonus pour Strange selon ses dégâts ; plus de vie bonus pour les alliés."}, {"name": "Unbreakable Forces", "partners": ["the-thing"], "key": "", "text": "Armure psionique qui donne de la vie bonus (cooldown 15 s en 10.5). **Amélioré :** Impulsions de soin de zone (seuil de 125 dégâts en 10.5)."}, {"name": "United Siblings", "partners": ["human-torch"], "key": "", "text": "Bouclier de flammes avec une aura de soin. **Amélioré :** Plus grand, bouclier renforcé."}], "changes": [{"season": "Saison 11", "text": "Veiled Step : cooldown 6 → 8 s."}, {"season": "Saison 11", "text": "Psionic Vortex : ralentissement au centre 50 % → 40 %, en bordure 0 % → 20 %."}, {"season": "Saison 10", "text": "Retour de l'orbe : 45 → 40 de soin ; l'invisibilité tient 1 s après avoir pris des dégâts."}, {"season": "Saison 10", "text": "Tous les Strategists : l'ult se charge un peu moins vite (65 % du soin et 50 % des dégâts convertis en énergie, au lieu de 70 % et 55 %)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'invisible-woman' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Iron Fist est un Duelist de mêlée qui dive ou brawle selon le fight. Il harcèle avec ses coups de base pour faire dépenser les contrôles adverses, pare l'attaque qui devait le tuer, puis déchaîne des coups renforcés dont les dégâts en pourcentage font fondre les tanks.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["**Harcèle, pare, frappe** : c'est la parade qui débloque tes vrais dégâts.", "Les coups renforcés font **plus mal aux tanks** : ils chargent ton ult très vite.", "Reste **en hauteur** (murs, triple saut) pour repérer la cible isolée."], "difficulty": 3, "tags": ["Mêlée", "Parade", "Anti-volant", "Anti-tank"], "strengths": ["Parade qui bloque tout, ults comprises", "Dégâts en pourcentage contre les tanks", "Triple saut et course sur les murs"], "weaknesses": ["Inoffensif si sa parade est dépensée à vide", "Aucune portée", "Vulnérable aux contrôles hors parade"], "playbook": [{"when": "Le fight commence à 6 contre 6", "then": "**Coups de base** sur un support pour lui faire dépenser son contrôle. Ne pare pas encore."}, {"when": "Une grosse attaque part sur toi (boule de neige, bulle de Magneto, ult de Jeff ou d'Iron Man)", "then": "**Parade** : tu bloques tout, les dégâts deviennent de la vie bonus, et tes coups renforcés sont prêts."}, {"when": "Ta parade a réussi", "then": "**Colle ta cible** en te déplaçant avec elle : si tu te détaches, tu perds des coups renforcés."}, {"when": "Une cible passe sous la moitié de sa vie", "then": "**Coup de pied** : le second impact double ses dégâts."}, {"when": "Un volant domine le fight", "then": "Prépare ta série sur un mur et garde le **dernier coup** pour lui : il le fait tomber."}, {"when": "Tes cooldowns sont dépensés", "then": "Ressors avec ta vie bonus, **médite à couvert**, et reviens."}], "sections": [{"title": "Philosophie de jeu", "lead": "Iron Fist se joue comme Daredevil : dive ou brawl selon les besoins. Dans le doute, médite, force des cooldowns, pare, puis bats-toi avec ton équipe.", "ability": "", "key": "", "kind": "tips", "items": ["La parade est **ta seule ressource** : dépensée au mauvais moment, tu n'as plus ni défense ni dégâts.", "Dans un fight équilibré, **fais d'abord sortir les contrôles** avec tes coups de base.", "Avec une élimination d'avance, tu peux parer immédiatement et faire boule de neige.", "Un cycle efficace : parer, **ressortir avec la vie bonus**, revenir sur un support quand l'équipe adverse se disperse."], "diagram": "reset"}, {"title": "Mobilité", "lead": "Trois sauts consécutifs et la course sur les murs : Iron Fist reste en l'air presque indéfiniment.", "ability": "Crane Leap · Wall Runner", "key": "", "kind": "default", "items": ["Les sauts ne se rechargent qu'**au contact d'une surface** : alterne sauts et course murale.", "La hauteur te donne **la vue d'ensemble** : tu vois quel support s'est écarté.", "Un saut au bon moment **esquive** les dégâts de zone et l'ult de The Thing."], "diagram": ""}, {"title": "Coups de base", "lead": "Une série de six coups qui te propulse vers la cible la plus proche. Le dernier projette en l'air, et chaque coup réduit le cooldown de ta parade.", "ability": "", "key": "Clic G", "kind": "default", "items": ["Leur rôle est de **harceler** et de faire dépenser les contrôles, pas de tuer.", "Le dernier coup **fait tomber les volants** : commence la série sur un mur ou un tank, termine-la sur lui.", "Le verrouillage fonctionne sans ligne de vue, mais pas à travers un bouclier.", "Frapper dans le vide **ralentit ta chute**."], "diagram": ""}, {"title": "Parade et coups renforcés", "lead": "Pendant un instant, tu bloques tout ce qui vient de face et tu convertis les dégâts en vie bonus. Tu gagnes ensuite une série de coups très rapides, aux dégâts en pourcentage de la vie de la cible.", "ability": "Dragon's Defense", "key": "Clic D", "kind": "default", "items": ["Elle bloque **tout** : boule de neige, capacités de Magneto ou d'Iron Man, ult de Jeff.", "Les coups renforcés brillent **contre les tanks**, et restent très forts sur un héros fragile.", "Avant de frapper un tank, **force son évasion** (lévitation de Strange, balancement de Venom).", "**Suis ta cible** : chaque pas de retard te coûte un coup."], "diagram": "", "scene": {"title": "Harceler, parer, frapper", "caption": "Les coups de base ne tuent pas : ils provoquent l'attaque que ta parade va transformer en dégâts.", "steps": ["Tu harcèles le support aux coups de base.", "Il riposte : tu pares, et ses dégâts deviennent ta vie bonus.", "Coups renforcés, collé à lui."], "els": [{"t": "pawn", "at": [140, 70], "team": "me", "ghost": true}, {"t": "path", "kind": "move", "team": "me", "pts": [[140, 70], [190, 24], [230, 58]], "n": 1}, {"t": "pawn", "at": [288, 72], "team": "enemy", "hero": "luna-snow", "above": true}, {"t": "zone", "at": [234, 72], "r": 21, "team": "me"}, {"t": "pawn", "at": [234, 72], "team": "me", "label": " "}, {"t": "path", "kind": "beam", "team": "enemy", "pts": [[288, 72], [248, 72]]}, {"t": "note", "at": [262, 50], "text": "2", "team": "me"}, {"t": "note", "at": [212, 106], "text": "parade", "team": "me"}, {"t": "cone", "at": [244, 84], "to": [284, 100], "spread": 50, "team": "me"}, {"t": "note", "at": [270, 114], "text": "3", "team": "me"}, {"t": "pawn", "at": [204, 140], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [296, 140], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [250, 160], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [302, 26], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [104, 104], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [80, 144], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [44, 80], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [44, 124], "team": "ally", "role": "heal"}]}}, {"title": "Coup de pied", "lead": "Un coup de pied tournoyant qui te propulse en avant. Le second impact inflige le double de dégâts à une cible sous la moitié de sa vie.", "ability": "", "key": "Maj", "kind": "default", "items": ["C'est ton **coup de grâce** : anticipe si le premier impact fera passer la cible sous la moitié.", "Il sert aussi à **rejoindre un volant** ou à fuir.", "Il **s'arrête au contact** : pour fuir, vise à l'opposé des ennemis.", "Un saut juste avant en allonge la portée."], "diagram": ""}, {"title": "Méditation", "lead": "Tu te soignes rapidement et tu gagnes de la vie bonus, mais tu restes immobile et tu fais du bruit.", "ability": "Harmony Recovery", "key": "", "kind": "default", "items": ["Médite **avant le fight**, à couvert ou au-dessus d'un passage.", "Le cycle : **dive, cooldowns forcés, sortie, méditation**, et on recommence.", "Tu flottes pendant la méditation : cela permet de s'installer à des endroits où personne ne regarde."], "diagram": ""}, {"title": "Ultime", "lead": "Plus de dégâts, plus de vitesse, une portée doublée, des coups renforcés en permanence et une parade presque toujours disponible.", "ability": "Living Chi", "key": "Q", "kind": "default", "items": ["Tu n'as plus besoin de parer pour frapper fort : la parade ne sert plus qu'à **bloquer et à te soigner**.", "Tu deviens la cible prioritaire : **pare la première grosse réponse**.", "Elle **force les ults de support** adverses, et se recharge vite sur les tanks.", "Après ta première élimination, **ressors** : ne meurs pas en cherchant la seconde."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Parer **avant** que les contrôles adverses soient sortis.", "Mal **suivre sa cible** pendant les coups renforcés.", "Méditer **à découvert**.", "Dépenser le coup de pied alors qu'il fallait **le garder pour fuir**.", "Rester **trop longtemps** après un kill."], "diagram": ""}], "combos": [], "counters": [{"hero": "magneto", "note": "Sa bulle protège la cible sur laquelle tu viens de dépenser ta parade."}, {"hero": "emma-frost", "note": "Son étranglement t'arrête en plein enchaînement."}, {"hero": "peni-parker", "note": "Toiles et mines te ralentissent avant le contact."}, {"hero": "namor", "note": "Ses tourelles t'usent et tu ne peux pas les verrouiller."}, {"hero": "winter-soldier", "note": "Crochet, uppercut et burst : il te punit dès que la parade est dépensée."}, {"hero": "adam-warlock", "note": "Son lien d'âmes répartit ton burst sur toute son équipe."}], "synergies": [{"hero": "luna-snow", "note": "Ses soins à longue portée te suivent jusque dans la backline adverse."}, {"hero": "venom", "note": "Vous arrivez à deux sur les supports : ils ne peuvent pas contrôler les deux."}, {"hero": "captain-america", "note": "Il fait sortir les contrôles avant ton entrée."}, {"hero": "psylocke", "note": "Deux divers sur la même cible."}, {"hero": "cloak-and-dagger", "note": "Ses dagues guidées te soignent où que tu sois."}], "sources": [{"url": "https://www.youtube.com/watch?v=xfZl57O8_OQ", "title": "Iron Fist Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Comprehensive Defense", "partners": ["daredevil"], "key": "", "text": "Objection! touche tous les ennemis et renvoie les projectiles. **Amélioré :** Ajoute un soin passif."}, {"name": "Iron & Stone", "partners": ["the-thing"], "key": "", "text": "Uppercut qui projette en l'air puis coup de pied (fonctionne même sans The Thing, cooldown 12 s depuis la saison 10). **Amélioré :** Enchaînements et dégâts en plus."}, {"name": "Kumiho Palm", "partners": ["white-fox"], "key": "", "text": "Yat Jee Chung Kuen soigne les alliés. **Amélioré :** Portée de verrouillage augmentée."}], "changes": [{"season": "Saison 10", "text": "Jeet Kune Do 35 → 38 par coup (cinquième coup 55 → 60), ult moins chère (3400 → 3100)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'iron-fist' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Iron Man n'est pas un Duelist ordinaire : son ult se charge très vite et peut tuer à travers une ult de soin. Il entame les groupes aux répulseurs pour la charger, passe en surcharge pour faire fondre une cible isolée au rayon, et attend le moment où son canon décide du fight.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["Sur un **groupe**, les répulseurs ; sur une **cible isolée**, le rayon.", "Active la **surcharge derrière un mur**, jamais à découvert.", "Ton ult **punit les ults de support** : mets-toi à l'abri avant de tirer."], "difficulty": 2, "tags": ["Vol", "Charge d'ult", "Anti-ult", "Poke"], "strengths": ["Ult très rapide à charger", "Tue à travers une ult de soin", "Hors de portée de la mêlée"], "weaknesses": ["Cible idéale des hitscans", "Vol très bruyant", "Immobile pendant le tir de l'ult"], "playbook": [{"when": "Un support adverse lance son ult de soin (Luna, Cloak & Dagger)", "then": "À couvert, **tire ton ult au sol, au centre** de la zone : le cœur de l'explosion tue même à travers les soins."}, {"when": "Des ennemis sont groupés", "then": "**Répulseurs aux pieds** : les dégâts de zone chargent ton ult."}, {"when": "Une cible est isolée à portée de rayon", "then": "Recharge, puis **Uni-Beam** : un seul adversaire, dégâts maximaux."}, {"when": "Tu veux activer la surcharge", "then": "**Derrière un mur.** Et repasse derrière un mur juste avant qu'elle se termine."}, {"when": "Hela, Hawkeye ou Punisher te visent", "then": "**Reviens près du décor**, devant tes supports. En plein ciel, tu es mort en deux secondes."}, {"when": "Magneto garde sa bulle ou son ult", "then": "**Attends qu'il les dépense** : il absorbe ton canon."}], "sections": [{"title": "Philosophie de jeu", "lead": "Iron Man demande de la patience : il charge son ult plus vite que presque tout le monde et attend l'instant précis où elle renverse le fight.", "ability": "", "key": "", "kind": "tips", "items": ["Garde un **temps de tir maximal** : il y a toujours quelqu'un à toucher.", "Tiens-toi **à la portée maximale du rayon** : la cible est plus facile à suivre et tu es plus difficile à atteindre.", "Ne reste pas perché à l'autre bout de la carte : **redescends devant tes supports** et tourne autour du décor.", "Ne flanque pas en volant : ton vol rapide est la capacité **la plus bruyante** du jeu.", "Tirer au rayon sur un tank soigné par deux supports charge surtout leurs ults."], "diagram": "highground"}, {"title": "Répulseurs", "lead": "Des projectiles explosifs tirés par séries de trois. L'essentiel des dégâts vient de l'explosion.", "ability": "Repulsor Blast", "key": "Clic G", "kind": "default", "items": ["Vise **les pieds** : même raté, le tir touche en zone.", "Ils servent d'abord à **charger ton ult** sur des ennemis groupés.", "Tire dans une **ult de support adverse** : tu charges la tienne pour y répondre.", "Le troisième tir de la série part plus vite."], "diagram": ""}, {"title": "Uni-Beam", "lead": "Un rayon instantané qui utilise les mêmes munitions que les répulseurs. C'est lui qui tue une cible isolée.", "ability": "", "key": "Clic D", "kind": "default", "items": ["**Recharge avant** d'aller chercher une cible.", "Sa portée dépasse celle du rayon d'Emma Frost.", "Entame aux répulseurs, **achève au rayon**."], "diagram": ""}, {"title": "Surcharge", "lead": "Après une courte animation, tes attaques sont renforcées, tes munitions illimitées et tu gagnes de la vie bonus.", "ability": "Armor Overdrive", "key": "E", "kind": "default", "items": ["L'animation te rend vulnérable : **toujours derrière un mur**.", "Avant de l'activer, vérifie que tu peux **vraiment menacer une cible** sans te faire punir.", "Elle ne recharge pas tes munitions en se terminant, et la sortie t'expose : **abrite-toi juste avant la fin**.", "Depuis la saison 10.5, les micro-missiles suivent les ennemis proches : un complément de dégâts, pas une priorité."], "diagram": ""}, {"title": "Vol rapide", "lead": "Un vol très rapide qui consomme de l'énergie. La surcharge la recharge.", "ability": "Hyper-Velocity", "key": "Maj", "kind": "default", "items": ["Il sert à **rejoindre un angle** ou à **fuir**.", "Utilise-le pour te placer en sécurité **avant** ton ult.", "Tout le monde t'entend arriver : inutile d'espérer surprendre."], "diagram": ""}, {"title": "Ultime", "lead": "Un gros projectile lent qui explose et tue presque tout ce qui se trouve au centre de sa zone.", "ability": "Invincible Pulse Cannon", "key": "Q", "kind": "default", "items": ["Cible prioritaire : **une ult de support**, surtout celle de Luna. Ne tire pas de trop loin, ils auraient le temps de sortir.", "Le centre tue, le bord beaucoup moins : **vise le sol près de la cible**.", "Tu restes **immobile une à deux secondes** : demande une bulle de Magneto, un bouclier d'Emma ou d'Invisible Woman.", "N'arrive pas en vol rapide pour tirer aussitôt : attends quelques secondes qu'on t'oublie.", "Même sans kill, elle **force runes, bulles et murs**, et cela suffit souvent à gagner le fight.", "Anticipe la fuite du support et vise l'endroit où il va, pas celui où il est."], "diagram": "", "scene": {"title": "Le canon sur une ult de soin", "caption": "Une ult de soin regroupe toute l'équipe adverse dans un cercle. C'est exactement la forme de ton explosion.", "steps": ["Luna lance son ult : son équipe se serre dans la zone.", "À couvert et sous bulle, tu tires au sol, au centre.", "Le cœur de l'explosion tue malgré les soins."], "els": [{"t": "zone", "at": [238, 96], "r": 46, "team": "enemy", "label": "Ult de Luna", "n": 1}, {"t": "pawn", "at": [238, 88], "team": "enemy", "hero": "luna-snow"}, {"t": "pawn", "at": [228, 60], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [268, 70], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [200, 124], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [276, 126], "team": "enemy", "role": "heal"}, {"t": "cover", "at": [52, 84], "size": [60, 14], "label": "Mur"}, {"t": "zone", "at": [84, 50], "r": 19, "team": "ally", "label": "Bulle"}, {"t": "pawn", "at": [84, 50], "team": "me", "label": " "}, {"t": "pawn", "at": [40, 130], "team": "ally", "hero": "magneto"}, {"t": "path", "kind": "beam", "team": "me", "pts": [[84, 50], [238, 98]], "n": 2}, {"t": "note", "at": [238, 128], "text": "3", "team": "me"}, {"t": "pawn", "at": [130, 140], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [96, 150], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [30, 60], "team": "ally", "role": "heal"}]}}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Activer la surcharge **à découvert**.", "Viser au rayon un **tank soigné** par deux supports.", "Partir au rayon **sans munitions**.", "Tirer l'ult **juste après** une arrivée bruyante.", "**Garder l'ult** alors qu'elle revient vite."], "diagram": ""}], "combos": [], "counters": [{"hero": "hela", "note": "Deux tirs à la tête et tu tombes. Joue collé au décor."}, {"hero": "hawkeye", "note": "Sa flèche hypersonique te cloue au sol, et un tir chargé te tue."}, {"hero": "the-punisher", "note": "Tir continu dès que tu quittes un couvert."}, {"hero": "spider-man", "note": "Il te rejoint partout dans les airs."}, {"hero": "magneto", "note": "Sa bulle et son ult absorbent ton canon."}, {"hero": "adam-warlock", "note": "Un hitscan de plus qui te punit en l'air."}, {"hero": "hulk", "note": "Son saut t'attrape et annule ton ult."}], "synergies": [{"hero": "ultron", "note": "Son drone te soigne en l'air : vous restez tous deux hors de portée."}, {"hero": "magneto", "note": "Sa bulle sur toi pendant que tu tires ton ult."}, {"hero": "emma-frost", "note": "Son bouclier posé devant toi couvre le tir."}, {"hero": "invisible-woman", "note": "Son bouclier te rend intouchable le temps du canon."}, {"hero": "psylocke", "note": "Elle va chercher les hitscans qui te visent."}], "sources": [{"url": "https://www.youtube.com/watch?v=3hV4kz3Repc", "title": "Iron Man Guide", "author": "Paz (padswagger)"}, {"title": "The Best Iron Man Guide (Season 2.5)", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=Rg-etuOgUNY"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Gamma Charge", "partners": ["hulk"], "key": "", "text": "Gamma Overdrive avec un bouclier. **Amélioré :** Crée un canon à impulsion gamma."}, {"name": "Squirrel Missile", "partners": ["squirrel-girl"], "key": "", "text": "Un missile-écureuil à tête chercheuse. **Amélioré :** En tire un avec Squirrel Blockade."}, {"name": "Stark Protocol", "partners": ["ultron"], "key": "", "text": "Nano-rayon qui soigne et blesse. **Amélioré :** Tire des missiles à tête chercheuse."}, {"name": "Thunder Overdrive", "partners": ["thor"], "key": "", "text": "Armor Overdrive gagne en dégâts (anneau de l'Unibeam à 80/s en 10.5). **Amélioré :** Anneau à 90/s en 10.5."}], "changes": [{"season": "Saison 10.5", "text": "Micro-Missile Barrage : les missiles suivent les ennemis proches (5 max par cible), 60 m/s au lieu de 15, mais 10 de dégâts par missile au lieu de 20 (15 en Armor Overdrive)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'iron-man' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Jeff se joue comme un flanker qui harcèle la backline adverse : il attire l'attention loin de son équipe, survit grâce à la nage et aux bulles, et son ult retire des ennemis du fight, voire de la carte. Le cantonner au rôle de soigneur, c'est renoncer à ce qui le rend fort.", "patch_note": "Plan de jeu issu d'un guide enregistré en saison 2 : le kit de Jeff a été retouché depuis, vérifie les détails en jeu. Team-ups et derniers changements sont à jour de la saison 11 en bas de page.", "tldr": ["Prends un **angle de flanc** et tire sur les **supports et les DPS**, jamais sur les tanks.", "**Garde toujours une ou deux bulles** pour fuir.", "Une ult qui retire **un ou deux ennemis clés** suffit."], "difficulty": 2, "tags": ["Flanc", "Pression", "Mobilité", "Ult de pick"], "strengths": ["Presque intuable sous terre", "Ult qui retire des ennemis du fight", "Bulles de soin et de vitesse durables"], "weaknesses": ["Soins faibles en volume", "Grosse hitbox hors de l'eau", "Ne conteste pas l'objectif en nageant"], "playbook": [{"when": "Le fight commence", "then": "Laisse **deux ou trois bulles** à ton autre support, puis nage vers ton angle."}, {"when": "Tu es sur le flanc de la backline adverse", "then": "**Tirs aux pieds** des supports et des DPS. Dès qu'ils se retournent, plonge et repars."}, {"when": "Un allié lance son ult, ou ton autre support se fait diver", "then": "**Reviens soigner** : c'est le moment où ton jet compte."}, {"when": "Les supports adverses lancent leur ult", "then": "**Ult** : ils sont groupés et immobiles, tu en avales au moins un."}, {"when": "Un combo d'ults adverse va tomber sur ton équipe", "then": "**Avale tes alliés** : ils sont intouchables le temps que le combo passe."}, {"when": "Tu tiens des ennemis dans ta gueule", "then": "Nage vers **le vide le plus proche** par ton chemin de bulles et recrache-les face au bord."}], "sections": [{"title": "Philosophie de jeu", "lead": "Ton meilleur soin, c'est d'attirer sur toi les dégâts et l'attention qui seraient allés sur ton équipe. Cela ne se lit pas au tableau des scores, mais au résultat du fight.", "ability": "", "key": "", "kind": "tips", "items": ["Nage jusqu'à un **angle décalé**, harcèle la backline, repars dès qu'elle réagit.", "Depuis ton flanc, **détruis les tourelles et les amplificateurs** adverses.", "Reste sur des positions **difficiles d'accès** : ta survie compte plus qu'un kill.", "À trois supports, tu peux te consacrer encore davantage aux dégâts."], "diagram": "flank"}, {"title": "Soin et dégâts", "lead": "Un jet d'eau qui soigne et traverse les alliés, et des projectiles d'eau qui explosent à l'impact.", "ability": "Joyful Splash · Aqua Burst", "key": "Clic G · Clic D", "kind": "default", "items": ["Le jet est un projectile : **soigne en avance** sur les dégâts.", "Vise **les pieds** avec les projectiles : l'explosion rattrape un tir imprécis.", "Contre un volant, vise **le mur derrière lui**.", "Ne tire **jamais sur les tanks** : tu offres de l'ult à leurs supports."], "diagram": ""}, {"title": "Nage", "lead": "Sous terre, tu vas plus vite, tu te soignes, ta tête n'est plus touchable et tu peux nager sur les murs.", "ability": "Hide and Seek", "key": "Maj", "kind": "default", "items": ["Départ type : **bulle, passage dedans, plongée**, et tu files vers ton angle.", "Tu peux **attendre sur un mur** et surgir quand un ennemi passe.", "Sous terre, tu **ne contestes pas** l'objectif.", "Dans les paramètres, la nage murale peut passer en appui simple."], "diagram": ""}, {"title": "Bulles", "lead": "Des bulles posées au sol, qui soignent, accélèrent et augmentent les soins reçus. Elles restent longtemps en place.", "ability": "Healing Bubble", "key": "E", "kind": "default", "items": ["L'accélération ne se cumule pas : **ne les empile pas**.", "Avant le fight, trace un **chemin de bulles vers le bord de la carte** : c'est ta route pour l'ult.", "Un Jeff qui gère ses bulles **ne meurt presque jamais**.", "Déplace-toi en huit : ta hitbox est large, ton mouvement doit compenser."], "diagram": ""}, {"title": "Ultime", "lead": "Tu plonges, puis tu avales tous les ennemis et alliés dans la zone. Tu les recraches où tu veux, de préférence hors de la carte.", "ability": "It's Jeff!", "key": "Q", "kind": "default", "items": ["Recrache **face au vide, à angle franc** : les héros mobiles (Invisible Woman, Doctor Strange, Wolverine, Psylocke) reviennent sinon.", "Attention à ne pas emporter **tes alliés** hors du point, surtout en prolongation.", "Un Magneto garde souvent son ult pour toi : fais-la dépenser d'abord.", "Défensivement, **avaler ton équipe** lui fait esquiver un combo d'ults."], "diagram": "", "scene": {"title": "Du point jusqu'au vide", "caption": "L'ult ne tue personne par elle-même : c'est l'endroit où tu recraches qui fait le kill.", "steps": ["Avant le fight, tu traces un chemin de bulles vers le bord.", "Tu avales les ennemis regroupés.", "Tu suis tes bulles et tu les recraches dans le vide."], "els": [{"t": "area", "at": [0, 0], "size": [320, 26], "label": "Vide"}, {"t": "zone", "at": [218, 112], "r": 30, "team": "me", "label": "It's Jeff!", "n": 2}, {"t": "pawn", "at": [206, 104], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [230, 104], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [218, 128], "team": "enemy", "role": "heal"}, {"t": "zone", "at": [170, 76], "r": 7, "team": "ally"}, {"t": "zone", "at": [140, 56], "r": 7, "team": "ally"}, {"t": "zone", "at": [110, 46], "r": 7, "team": "ally"}, {"t": "note", "at": [140, 80], "text": "1", "team": "ally"}, {"t": "path", "kind": "move", "team": "me", "pts": [[214, 104], [170, 50], [92, 44]], "n": 3}, {"t": "pawn", "at": [86, 48], "team": "me"}, {"t": "path", "kind": "push", "team": "me", "pts": [[86, 48], [78, 14]]}, {"t": "pawn", "at": [276, 70], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [288, 136], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [120, 132], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [70, 110], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [50, 150], "team": "ally", "role": "heal"}]}}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Rester derrière à **ne faire que soigner**.", "Tirer **sur les tanks**.", "Dépenser toutes ses bulles et **ne plus pouvoir fuir**.", "Emporter **ses alliés** hors du point.", "Lancer l'ult quand **Magneto a la sienne**."], "diagram": ""}], "combos": [{"note": "", "steps": [{"key": "E", "label": "bulle"}, {"key": "", "label": "Passe dedans"}, {"key": "Maj", "label": "plonge"}], "title": "Filer à ton angle"}], "counters": [{"hero": "captain-america", "note": "Il te suit sur ton flanc et t'en chasse."}, {"hero": "star-lord", "note": "Mobile, il vide son chargeur sur ta large hitbox."}, {"hero": "iron-man", "note": "Ses explosions te touchent même quand tu te déplaces en huit."}, {"hero": "loki", "note": "Ses runes annulent ton harcèlement et ses clones te tirent dessus de partout."}, {"hero": "magneto", "note": "Son ult te tue pendant la tienne."}], "synergies": [{"hero": "captain-america", "note": "Vous refermez le cercle autour de la backline adverse."}, {"hero": "venom", "note": "Il plonge sur les supports que tu harcèles déjà."}, {"hero": "human-torch", "note": "Ses zones retiennent les supports, tu les empêches de fuir."}, {"hero": "black-panther", "note": "Il achève les cibles que tu as entamées."}, {"hero": "luna-snow", "note": "Elle tient les soins de l'équipe pendant que tu flanques."}], "sources": [{"url": "https://www.youtube.com/watch?v=bEtshLmrVyw", "title": "Jeff the Land Shark Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Bubble Buddies", "partners": ["groot"], "key": "", "text": "Une bulle-bouclier rend invincible et soigne. **Amélioré :** Ajoute de la vie bonus."}, {"name": "Guardian of the Deep", "partners": ["venom"], "key": "", "text": "Tentacules de soin qui donnent de la vie bonus. **Amélioré :** Ajoute des coups de fouet qui blessent."}, {"name": "Jaws of Fate", "partners": ["storm"], "key": "", "text": "Averse qui soigne. **Amélioré :** Jeff peut nager dans une tornade (Jeff-nado)."}, {"name": "Mr. Pool's Interdimensional Toy Box", "partners": ["deadpool"], "key": "", "text": "Une peluche provoque les ennemis et soigne. **Amélioré :** Provocation et dégâts renforcés."}, {"name": "Surf & Turf", "partners": ["devil-dinosaur"], "key": "", "text": "Jet d'eau qui blesse et soigne. **Amélioré :** Jeff chevauche Devil Dinosaur, et les deux se soignent."}], "changes": [{"season": "Saison 10", "text": "Joyful Splash 130/s → 140/s de soin, Aqua Burst 25 → 30 de dégâts, zone de soin de l'ult 100/s → 130/s."}, {"season": "Saison 10", "text": "Tous les Strategists : l'ult se charge un peu moins vite (65 % du soin et 50 % des dégâts convertis en énergie, au lieu de 70 % et 55 %)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'jeff-the-land-shark' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Jubilee est une Strategist hybride à portée illimitée. Ses orbes suivent une cible, soignent les alliés et blessent les ennemis autour d'elle ; les faire exploser marque tout le monde dans la zone, et tirer sur une marque déclenche un mode de tir rapide. Tout son niveau tient à la gestion des orbes et des marques.", "patch_note": "Conseils issus d'un guide enregistré à la sortie de l'héroïne (saison 9), mis à jour avec les saisons 10.5 et 11 : en saison 11, consommer une marque ne donne plus de bonus de soin aux alliés, et l'ult soigne un peu plus.", "tldr": ["**Jamais d'orbe en cooldown** : récupère-la avant qu'elle expire et relance-la.", "Fais exploser une orbe **améliorée** pour marquer le plus de joueurs possible, puis tire sur les marques.", "Tu es un **second soin avec du burst** : contre le dive, reste près de ton équipe."], "difficulty": 2, "tags": ["Soin hybride", "Portée infinie", "Marques", "Burst"], "strengths": ["Portée illimitée, presque sans perte", "Orbes qui soignent seules en suivant leur cible", "Mode étincelles à très haute cadence"], "weaknesses": ["Volume de soins moyen", "Vulnérable aux divers", "Ult interruptible"], "playbook": [{"when": "Le fight commence", "then": "**Orbe au sol près de ton tank** : elle le suit et grossit. Seconde orbe dans la mêlée."}, {"when": "Ton orbe est améliorée et plusieurs joueurs sont dedans", "then": "**Détonation** : tout le monde est marqué. Tire sur les marques pour entrer en mode étincelles."}, {"when": "Une orbe va expirer", "then": "**Récupère-la** (pas besoin de la voir) et relance-la : son cooldown repart plus court."}, {"when": "Un diver te prend pour cible", "then": "**Sprint** vers tes alliés : il te soigne en continu et active le mode étincelles."}, {"when": "Tu es seule et entamée", "then": "Lance une orbe à tes pieds et **tire dessus** : elle s'améliore et te soigne."}, {"when": "Ton équipe tient le point sous pression", "then": "**Ult**, cercle resserré : les orbes tournent plus vite et soignent davantage ceux qu'elles touchent."}], "sections": [{"title": "Philosophie de jeu", "lead": "Tu soignes et tu blesses en même temps. Ce qui sépare une bonne Jubilee d'une mauvaise, c'est le temps passé en mode étincelles.", "ability": "", "key": "", "kind": "tips", "items": ["Ta portée est **illimitée** : choisis ta position pour ta sécurité.", "Contre une compo de dive, reste **près de ton équipe**. Pour échapper à un diver, cours vers tes alliés, pas à l'opposé.", "Ton soin est correct sans être massif : tu es faite pour accompagner un vrai soigneur."], "diagram": "heal"}, {"title": "Tir de lumière", "lead": "Un tir rapide qui blesse les ennemis et soigne les alliés, sans limite de portée et presque sans perte de dégâts.", "ability": "", "key": "Clic G", "kind": "default", "items": ["C'est un **projectile** : anticipe sur les cibles lointaines.", "Hors mode étincelles, il n'inflige pas de dégâts critiques : vise le corps."], "diagram": ""}, {"title": "Orbes", "lead": "Une orbe qui suit la cible la plus proche : elle soigne les alliés et blesse les ennemis dans sa bulle. Deux charges. Elle s'améliore à mesure qu'elle soigne ou blesse.", "ability": "Blooming Ball", "key": "", "kind": "default", "items": ["Lance-la **au sol, à côté** du joueur visé : elle le suivra.", "Améliorée, elle est **plus grande, plus forte**, et repart pour une durée complète.", "Tu peux la **récupérer sans ligne de vue**.", "Tirer dessus l'améliore : utile quand elle n'a personne à suivre."], "diagram": "", "scene": {"title": "Orbe, détonation, étincelles", "caption": "Une orbe améliorée couvre une large zone. Sa détonation marque tous ceux qui s'y trouvent, alliés comme ennemis.", "steps": ["Orbe au sol près de ton tank : elle le suit et grossit.", "Détonation : tous les joueurs dans la zone sont marqués.", "Tu tires sur les marques : mode étincelles."], "els": [{"t": "pawn", "at": [52, 60], "team": "me"}, {"t": "zone", "at": [170, 96], "r": 44, "team": "me", "label": "Orbe améliorée", "n": 2}, {"t": "pawn", "at": [150, 96], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [146, 126], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [196, 84], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [200, 118], "team": "enemy", "role": "dps"}, {"t": "path", "kind": "sight", "team": "me", "pts": [[52, 60], [150, 96]], "n": 1}, {"t": "path", "kind": "shot", "team": "me", "pts": [[52, 60], [196, 84]], "n": 3}, {"t": "path", "kind": "shot", "team": "me", "pts": [[52, 60], [146, 126]], "n": 3}, {"t": "pawn", "at": [48, 124], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [96, 150], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [262, 60], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [290, 100], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [286, 142], "team": "enemy", "role": "heal"}]}}, {"title": "Détonation et marques", "lead": "Tu fais exploser une orbe : soin et vitesse pour les alliés, dégâts et vulnérabilité pour les ennemis. Tous ceux qui se trouvent dans la zone reçoivent une marque d'étincelles.", "ability": "Dazzling Detonation", "key": "", "kind": "default", "items": ["Attends que l'orbe soit **améliorée** : la zone est plus grande, tu marques plus de monde.", "Tirer sur un joueur marqué **consomme la marque** : de la vie bonus pour un allié, des dégâts supplémentaires sur un ennemi. Depuis la saison 11, l'allié ne reçoit plus de bonus de soin.", "Consommer une marque déclenche le **mode étincelles** : cadence très élevée, sans munitions."], "diagram": ""}, {"title": "Sprint", "lead": "Vitesse et hauteur de saut augmentées, mode étincelles actif. En sortant, tu libères une explosion qui soigne et repousse.", "ability": "Sparking Sprint", "key": "", "kind": "default", "items": ["Il consomme une **jauge** et part en cooldown dès l'activation.", "Depuis la saison 10.5, il **te soigne en continu** : c'est ton outil de survie.", "Quand tu sais qu'un diver arrive, garde le sprint ou une marque en réserve."], "diagram": ""}, {"title": "Ultime", "lead": "Un anneau d'énergie qui soigne les alliés, repousse les ennemis et marque tout le monde. Des orbes tournent autour de toi et soignent ou blessent ce qu'elles touchent.", "ability": "Firework Finale", "key": "Q", "kind": "default", "items": ["**Cercle resserré** : les orbes tournent plus vite, le soin est plus concentré.", "**Cercle élargi** : il repousse les ennemis, pour dégager un point ou protéger ta backline.", "Elle soigne un peu plus en saison 11, et les orbes extérieures tournent plus vite : elle reste en dessous de celle de Luna.", "Tu peux être **étourdie ou déplacée** pendant l'ult."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Laisser une orbe **expirer**.", "Lancer l'orbe **sur le joueur** au lieu du sol.", "Faire exploser une orbe **non améliorée**.", "Jouer **loin de son équipe** contre le dive.", "Rester immobile en ult face à un tank qui peut **t'étourdir**."], "diagram": ""}], "combos": [], "counters": [{"hero": "venom", "note": "Il plonge sur toi et interrompt ton mode étincelles."}, {"hero": "spider-man", "note": "Il te tue dès que tu es à plus de quelques mètres de ton équipe."}, {"hero": "doctor-strange", "note": "Il entre dans ton ult et l'interrompt avec la sienne."}, {"hero": "black-panther", "note": "Ton sprint ne suffit pas contre son burst."}, {"hero": "emma-frost", "note": "Son étranglement interrompt ton ult."}], "synergies": [{"hero": "the-hood", "note": "Votre team-up rend ton tir hitscan, avec vol de vie."}, {"hero": "blade", "note": "Votre champ vampirique soigne l'équipe ; le vol de vie monte à 40 % en saison 11."}, {"hero": "human-torch", "note": "Votre team-up lui donne des étincelles guidées."}, {"hero": "gambit", "note": "Votre team-up crée un bâton qui soigne et bloque les projectiles."}, {"hero": "luna-snow", "note": "Elle apporte le soin massif, toi le burst."}], "sources": [{"title": "Ultimate Jubilee Guide (Beginner/Advanced)", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=XuEoj9TR284"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Fiery Sparks", "partners": ["human-torch"], "key": "", "text": "Étincelles de feu d'artifice à tête chercheuse. **Amélioré :** Vie bonus à l'atterrissage."}, {"name": "Hellfire Sparks", "partners": ["the-hood"], "key": "", "text": "Forme hitscan avec auto-soin. **Amélioré :** Garde la marque de magie du vide."}, {"name": "Hex Fireworks", "partners": ["scarlet-witch"], "key": "", "text": "Détonation de sceau plasmoïde. **Amélioré :** Ajoute un soin continu."}, {"name": "Sparkling Staff", "partners": ["gambit"], "key": "", "text": "Un bâton qui soigne et bloque les projectiles (2 s en 10.5). **Amélioré :** Ajoute des auras de soin continu."}, {"name": "Vampiric Kin", "partners": ["blade"], "key": "", "text": "Champ vampirique qui soigne et donne du vol de vie (40 % en saison 11). **Amélioré :** Soin supplémentaire."}], "changes": [{"season": "Saison 11", "text": "Sparkle Mark : la détonation ne donne plus 20 % de bonus de soin aux alliés."}, {"season": "Saison 11", "text": "Firework Finale : soin 180 → 190/s ; plasmoïdes extérieurs plus rapides (20 → 25 m/s)."}, {"season": "Saison 11", "text": "Team-up avec Blade (Vampiric Kin) : vol de vie 30 % → 40 %."}, {"season": "Saison 10.5", "text": "Sparking Sprint soigne 25/s ; aveuglement de Dazzling Detonation 1,5 s → 0,8 s ; ult 150/s → 180/s de soin."}, {"season": "Saison 10", "text": "Tous les Strategists : l'ult se charge un peu moins vite (65 % du soin et 50 % des dégâts convertis en énergie, au lieu de 70 % et 55 %)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'jubilee' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Loki est un Strategist de placement. Ses clones tirent et lancent ses capacités en même temps que lui, ce qui multiplie ses soins ; ses runes transforment en soin les dégâts subis par ses alliés ; et son ult copie n'importe quel héros, ult comprise. Bien joué, il offre à son équipe deux ults de support par fight.", "patch_note": "Guide rédigé à partir du kit de Loki et des notes de patch de la saison 11, sans vidéo de référence. Loki a été retiré de plusieurs modes pendant la saison 10 : vérifie sa disponibilité et les détails en jeu.", "tldr": ["**Pose tes clones avant le fight**, sur des angles différents : ils tirent quand tu tires.", "Les **runes** se gardent pour l'ult ou le burst adverse.", "Ton ult **copie une ult** : celle de ton autre support, ou la meilleure d'en face."], "difficulty": 3, "tags": ["Clones", "Anti-ult", "Copie d'ult", "Placement"], "strengths": ["Runes qui annulent une ult de dégâts", "Soins multipliés par les clones", "Copie de n'importe quelle ult"], "weaknesses": ["Faible sans clones posés", "Clones utilisés par l'ennemi (ricochets, charge, relances)", "Aucune mobilité hors échange de place"], "playbook": [{"when": "Avant le fight", "then": "**Deux clones** : un près de ton front, un à l'abri. Le second est ta sortie."}, {"when": "Une ult de dégâts tombe sur ton équipe (Iron Man, Magneto, Psylocke, Star-Lord)", "then": "**Runes** sous tes alliés : tant qu'ils restent dedans, les dégâts deviennent du soin. Chaque clone en pose aussi."}, {"when": "Un diver te saute dessus", "then": "**Échange de place** avec ton clone à l'abri, ou **Deception** pour disparaître. Le cooldown de Deception est de 18 secondes en saison 11."}, {"when": "Ton équipe est groupée et entamée", "then": "Tire **au sol entre tes alliés** : l'explosion soigne en zone, et tes clones font de même."}, {"when": "Ton autre support vient de lancer son ult", "then": "Attends qu'elle se termine, puis **copie-le et relance la même** : le fight dure deux fois plus longtemps en votre faveur."}, {"when": "L'adversaire a une ult décisive (Luna, Mantis, Invisible Woman)", "then": "**Copie son porteur** et lance-la pour ton équipe."}], "sections": [{"title": "Philosophie de jeu", "lead": "Loki se prépare avant de se battre. Un Loki sans clones est un Strategist médiocre ; un Loki avec deux clones bien placés soigne comme trois.", "ability": "", "key": "", "kind": "default", "items": ["**Installe tes clones** là où ils voient ton équipe sans être exposés : en hauteur, derrière un angle.", "Garde les **runes pour répondre** : posées trop tôt, elles ne servent à rien quand l'ult adverse tombe.", "Détruis les soucis à distance : tes projectiles explosifs nettoient **murs de Groot, tourelles et ankhs**.", "Sois conscient de ce que tes clones offrent à l'ennemi : charge du rayon d'Emma Frost, ricochets de Moon Knight, relances de l'ult de Winter Soldier."], "diagram": "heal"}, {"title": "Projectiles mystiques", "lead": "Des projectiles qui explosent à l'impact : ils soignent les alliés et blessent les ennemis dans une petite zone.", "ability": "Mystical Missile", "key": "Clic G", "kind": "default", "items": ["Vise **le sol ou un mur près de la cible** : l'explosion compte autant que l'impact.", "Tes clones tirent **en même temps que toi**, depuis leur position : deux clones bien placés triplent ta cadence.", "Sur un allié isolé, tire directement ; sur un groupe, tire au milieu."], "diagram": ""}, {"title": "Clones", "lead": "Tu projettes une illusion à l'endroit visé. Elle reproduit tes tirs et certaines de tes capacités. Deux clones peuvent être actifs.", "ability": "Doppelganger", "key": "Clic D", "kind": "default", "items": ["Un clone **près du fight** pour les soins, un clone **à l'abri** pour l'échange de place.", "Un clone sur un flanc **attire des tirs** et révèle les divers.", "Ils ont peu de vie : remplace-les dès qu'ils tombent.", "Avec le team-up d'Hela, un clone détruit met désormais tes capacités de clone une seconde en cooldown (saison 11)."], "diagram": ""}, {"title": "Runes", "lead": "Tu poses un champ de runes : tant qu'un allié s'y trouve, les dégâts qu'il subit sont convertis en soin. Chaque clone pose le sien au même moment.", "ability": "Regeneration Domain", "key": "Maj", "kind": "default", "items": ["C'est l'une des meilleures **réponses à une ult de dégâts** du jeu : annonce-la et demande à ton équipe de rester dedans.", "Les champs des clones **élargissent la zone** : place-les pour couvrir le point.", "Elles ne protègent pas d'un **déplacement forcé** : un allié sorti du champ redevient vulnérable.", "L'onde de choc de **Phoenix** détruit les runes.", "Depuis la saison 11, le team-up de Mantis ne donne plus de bonus de dégâts dans le champ."], "diagram": "", "scene": {"title": "Clones et runes", "caption": "Chaque clone pose son propre champ de runes. Deux clones bien placés couvrent toute ton équipe.", "steps": ["Deux clones posés avant le fight, sur des angles différents.", "Une ult de dégâts arrive : runes. Chaque clone pose les siennes.", "Les dégâts subis dans les champs deviennent du soin."], "els": [{"t": "pawn", "at": [52, 96], "team": "me"}, {"t": "mark", "at": [120, 60], "kind": "clone", "team": "me", "label": "Clone"}, {"t": "mark", "at": [124, 134], "kind": "clone", "team": "me", "label": "Clone"}, {"t": "note", "at": [88, 60], "text": "1", "team": "me"}, {"t": "zone", "at": [52, 96], "r": 24, "team": "me"}, {"t": "zone", "at": [124, 62], "r": 26, "team": "me", "n": 2}, {"t": "zone", "at": [126, 132], "r": 26, "team": "me"}, {"t": "pawn", "at": [146, 72], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [150, 122], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [100, 100], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [70, 140], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [258, 50], "team": "enemy", "hero": "iron-man", "above": true}, {"t": "path", "kind": "beam", "team": "enemy", "pts": [[258, 50], [150, 100]]}, {"t": "note", "at": [228, 104], "text": "dégâts convertis en soin", "team": "me"}, {"t": "note", "at": [228, 120], "text": "3", "team": "me"}, {"t": "pawn", "at": [254, 148], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [300, 90], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [294, 140], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [214, 160], "team": "enemy", "role": "dps"}]}}, {"title": "Invisibilité et échange", "lead": "Deception te rend invisible et laisse une illusion à ta place. Devious Exchange échange ta position avec celle d'un clone.", "ability": "Deception · Devious Exchange", "key": "E · F", "kind": "default", "items": ["**L'échange est ta seule vraie mobilité** : garde toujours un clone hors de danger.", "L'invisibilité se dissipe si tu attaques : sers-t'en pour **sortir**, pas pour entrer.", "Un coup de mêlée dans le dos en sortant de l'invisibilité inflige des dégâts bonus : utile pour achever, pas pour engager.", "Daredevil et les marques d'Elsa Bloodstone te voient invisible."], "diagram": ""}, {"title": "Ultime", "lead": "Tu prends l'apparence d'un héros, allié ou ennemi, pendant quelques secondes. Tu disposes de tout son kit, et son ult est immédiatement chargée.", "ability": "God of Mischief", "key": "Q", "kind": "default", "items": ["**Copier ton autre support** après son ult : deux ults de soin à la suite, presque impossibles à traverser.", "**Copier un support adverse** pour lui prendre son ult quand ton équipe n'en a pas.", "**Copier un Duelist** n'a d'intérêt que si tu sais le jouer : un Punisher ou un Star-Lord, pour finir un fight.", "Pendant l'incantation, un étourdissement t'interrompt (étranglement d'Emma Frost, coup de pied de Black Widow).", "Tu redeviens Loki à la fin : assure-toi d'avoir un clone pour ressortir."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "default", "items": ["Se battre **sans clones** posés.", "Poser les runes **avant** l'ult adverse.", "Mettre ses deux clones **au même endroit**.", "Copier un héros **qu'on ne sait pas jouer**.", "Dépenser l'échange de place **pour avancer**."], "diagram": ""}], "combos": [], "counters": [{"hero": "moon-knight", "note": "Ses tirs ricochent sur tes clones et chargent son ult."}, {"hero": "emma-frost", "note": "Elle charge son rayon sur tes clones, et son étranglement interrompt ton ult."}, {"hero": "winter-soldier", "note": "Tes clones comptent pour relancer son ult."}, {"hero": "phoenix", "note": "Son ult détruit clones et runes d'un coup, et ses chaînes rebondissent sur eux."}, {"hero": "iron-man", "note": "Ses explosions nettoient tes clones à distance."}, {"hero": "black-widow", "note": "Son coup de pied t'interrompt en pleine copie."}], "synergies": [{"hero": "luna-snow", "note": "Tu copies son ult : deux zones de soin à la suite."}, {"hero": "mantis", "note": "Votre team-up renforce ton champ de runes."}, {"hero": "hela", "note": "Tu tiens son angle avec un clone et des runes sous ses pieds."}, {"hero": "adam-warlock", "note": "Tes runes protègent son équipe pendant qu'il ressuscite."}, {"hero": "doctor-strange", "note": "Derrière son bouclier, tes clones restent en vie tout le fight."}], "sources": [{"title": "Notes d'équilibrage de la saison 11", "author": "GameRiv", "url": "https://gameriv.com/marvel-rivals-season-11-balance-patch-notes/"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Odin's Unacknowledged", "partners": ["angela"], "key": "", "text": "Une illusion d'estoc projette les ennemis (dégâts max encaissés : 150 depuis la saison 10). **Amélioré :** Deux charges."}, {"name": "Vibrant Vitality", "partners": ["mantis"], "key": "", "text": "Domaine de régénération renforcé, sans bonus de dégâts pour les alliés depuis la saison 11. **Amélioré :** Onde de choc qui projette en blessant."}, {"name": "Villain's Illusion", "partners": ["hela"], "key": "", "text": "Prend la forme d'un héros tombé. Depuis la saison 11, une illusion détruite met Doppelganger et Devious Exchange 1 s en cooldown. **Amélioré :** Dure plus longtemps et empêche la mort."}], "changes": [{"season": "Saison 11", "text": "Deception : cooldown 15 → 18 s."}, {"season": "Saison 11", "text": "Team-up avec Hela : quand une illusion est détruite, Doppelganger et Devious Exchange passent 1 s en cooldown."}, {"season": "Saison 11", "text": "Team-up avec Mantis : plus de bonus de dégâts pour les alliés dans le Regeneration Domain."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'loki' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Luna Snow est simple à prendre en main. Ce qui distingue les bonnes Luna, c'est la vitesse à laquelle elles chargent leur ult et leur capacité à rester en vie : son ultime rend toute l'équipe presque impossible à tuer pendant de longues secondes.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["Ta mission : **rester en vie et avoir ton ult** avant la Luna adverse.", "Entre deux soins, **fais des dégâts utiles** : cibles basses, tourelles, volants.", "Ta **marque** suit l'allié qui va prendre des dégâts, pas toujours le même."], "difficulty": 1, "tags": ["Soins", "Charge d'ult", "Anti-ult", "Polyvalente"], "strengths": ["Ult de soin la plus longue du jeu", "Soins hitscan sans perte à distance", "Gel qui interrompt les ults"], "weaknesses": ["Peu de mobilité défensive", "Gel raccourci à 1,5 s en saison 11", "Ult bloquée par les boucliers et le décor"], "playbook": [{"when": "Un diver fonce sur toi en ligne droite", "then": "**Boule de neige**, puis rafale à la tête immédiatement : le gel ne dure plus que 1,5 seconde."}, {"when": "Un ennemi canalise une ult (Doctor Strange, Storm)", "then": "**Boule de neige** : elle l'interrompt."}, {"when": "Ton tank part loin, ou ton DPS s'active sur un angle", "then": "**Marque sur lui avant** qu'il prenne des dégâts : il est soigné chaque fois que tu soignes quelqu'un d'autre."}, {"when": "Tes tanks sont à mi-vie, ou ton équipe engage", "then": "**Clap** en alignant le plus d'alliés et d'ennemis possible."}, {"when": "Tu es à 100 PV avec l'ult prête, ou une ult de dégâts arrive", "then": "**Ult maintenant.** Mourir avec elle est la pire issue."}, {"when": "Un allié lance une ult de dégâts pendant la tienne (Venom, Namor)", "then": "Passe en **bonus de dégâts** quelques secondes, puis reviens au soin."}], "sections": [{"title": "Philosophie de jeu", "lead": "Soigner ne suffit pas. Les bonnes Luna glissent des dégâts utiles entre deux soins et arrivent à chaque fight important avec leur ult.", "ability": "", "key": "", "kind": "tips", "items": ["Entre deux fights, **entame l'adversaire** pour charger ton ult, sans t'exposer à un sniper.", "Une fois l'ult prête, cesse d'arroser les tanks : tu chargerais celles des supports adverses.", "Tu as souvent la meilleure vue du fight : **détruis les ankhs de Moon Knight et les tourelles de Namor**.", "**Achève les cibles basses** et repousse les flankers avant leur entrée : retirer de la pression vaut parfois mieux qu'une barre de vie pleine.", "Ton passif te soigne quand tu utilises une capacité : en duel, sers-t'en au lieu de seulement tirer."], "diagram": "heal"}, {"title": "Tir principal", "lead": "Des rafales instantanées qui soignent les alliés et blessent les ennemis. Les soins ne perdent rien avec la distance.", "ability": "", "key": "Clic G", "kind": "default", "items": ["Tu peux soigner **de très loin** : choisis ta position pour ta sécurité, pas pour la portée.", "En dégâts, **vise la tête** : c'est la condition pour tuer un héros fragile.", "En patinant, oriente-toi **avec la caméra** pour conserver ta vitesse ; sauter ne la coupe pas."], "diagram": ""}, {"title": "Clap", "lead": "Pendant quelques secondes, tes tirs deviennent des stalactites qui traversent alliés et ennemis : ils soignent les uns, blessent les autres, et te soignent un peu.", "ability": "Ice Arts", "key": "Maj", "kind": "default", "items": ["Aligne **le plus de cibles possible** : c'est ta meilleure source de charge d'ult.", "Trop tôt, personne n'en a besoin ; trop tard, un allié meurt pendant l'animation. Le bon moment : **tanks à mi-vie** ou **équipe qui engage**.", "Lance-le **au moment où tu devrais recharger** : tu ne perds aucun temps de soin.", "Contre un dive, il soigne ton autre support tout en blessant le diver."], "diagram": ""}, {"title": "Boule de neige", "lead": "Un projectile qui gèle sa cible. Depuis la saison 11, le gel ne dure plus que 1,5 seconde : la suite doit partir immédiatement.", "ability": "Absolute Zero", "key": "", "kind": "default", "items": ["Elle **interrompt les ults canalisées**.", "Contre un diver, lance-la **au moment où il fonce** : en ligne droite, il ne peut pas l'esquiver.", "Elle **crée une élimination** : un Punisher gelé au milieu de sa rafale meurt si ton équipe tire.", "Tant qu'un diver peut encore te sauter dessus, **garde-la**.", "Geler un tank à bouclier en le contournant lui fait lâcher son bouclier."], "diagram": "", "scene": {"title": "Geler le diver", "caption": "Le gel est court : il ne tue pas, il offre une seconde et demie de cible immobile à toi et à ton autre support.", "steps": ["Le diver fonce sur toi en ligne droite.", "Boule de neige au moment du bond : il est gelé.", "Rafales à la tête, à deux, avant qu'il se libère."], "els": [{"t": "pawn", "at": [220, 40], "team": "enemy", "role": "dps", "ghost": true}, {"t": "path", "kind": "move", "team": "enemy", "pts": [[220, 40], [150, 70]], "n": 1}, {"t": "pawn", "at": [140, 76], "team": "enemy", "hero": "magik", "label": "Gelée", "above": true}, {"t": "pawn", "at": [70, 112], "team": "me"}, {"t": "path", "kind": "beam", "team": "me", "pts": [[70, 112], [140, 76]], "n": 2}, {"t": "pawn", "at": [60, 50], "team": "ally", "role": "heal"}, {"t": "path", "kind": "shot", "team": "ally", "pts": [[60, 50], [140, 76]], "n": 3}, {"t": "path", "kind": "shot", "team": "me", "pts": [[76, 124], [148, 90]], "n": 3}, {"t": "pawn", "at": [150, 130], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [120, 160], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [232, 104], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [268, 136], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [292, 76], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [292, 120], "team": "enemy", "role": "heal"}]}}, {"title": "Marque", "lead": "Une marque posée sur un allié : tes soins sur lui sont augmentés, et il est soigné chaque fois que tu soignes quelqu'un d'autre.", "ability": "Share the Stage", "key": "", "kind": "default", "items": ["**Fais-la tourner** : elle va sur l'allié qui s'apprête à agir, pas sur le même toute la partie.", "Sur un **tank agressif** (Hulk, Venom, Captain America, The Thing), elle charge ton ult très vite.", "Garde-la toujours sur quelqu'un : un flanker, une Hela sur son angle, un volant.", "Sur un allié qui encaisse beaucoup, **pose la marque avant de le soigner** : les deux soins se cumulent."], "diagram": ""}, {"title": "Ultime", "lead": "Une grande zone de soin autour de toi, qui dure longtemps. Un second appui la fait basculer en bonus de dégâts pour tes alliés.", "ability": "Fate of Both Worlds", "key": "Q", "kind": "default", "items": ["**Annonce-la** : son compte à rebours se perd facilement de vue.", "Tu ne peux pas être étourdie, mais tu peux être immobilisée : **reste en mouvement**.", "Ce n'est pas une invulnérabilité : une flèche de Hawkeye, l'ult de Magneto, d'Iron Man ou de Scarlet Witch peuvent te tuer dedans.", "**Boucliers et décor bloquent tes soins** : place-toi là où tu vois tout le monde.", "Ne la lance pas pendant que l'équipe marche vers le fight : attends qu'elle soit en position.", "Mets le changement de mode sur la molette pour alterner soin et dégâts sans délai."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Ne faire **que soigner**.", "Oublier la **boule de neige**.", "Laisser la marque **sur le même allié** toute la partie.", "**Mourir avec l'ult** prête.", "Rester trop longtemps en **bonus de dégâts**."], "diagram": ""}], "combos": [], "counters": [{"hero": "hela", "note": "Elle te tue de loin si tu soignes à découvert."}, {"hero": "star-lord", "note": "Il vole, esquive ta boule de neige et te force à dépenser tes cooldowns."}, {"hero": "black-panther", "note": "Il attend ta boule de neige ratée pour entrer."}, {"hero": "magik", "note": "Même danger : une boule manquée, et elle te tue."}, {"hero": "doctor-strange", "note": "Son bouclier coupe les soins de ton ult."}, {"hero": "iron-man", "note": "Son canon tue au centre de ta zone d'ult."}], "synergies": [{"hero": "loki", "note": "Il copie ton ult : deux fois plus de secondes où ton équipe ne peut pas mourir."}, {"hero": "namor", "note": "Ton bonus de dégâts rend son ult mortelle."}, {"hero": "venom", "note": "Marque sur lui pendant ses plongeons : ton ult se charge toute seule."}, {"hero": "iron-fist", "note": "Un diver que tes soins suivent à n'importe quelle distance."}, {"hero": "adam-warlock", "note": "Votre team-up te rend davantage de soins en saison 11."}], "sources": [{"url": "https://www.youtube.com/watch?v=jzICK22y7Is", "title": "Luna Snow Guide", "author": "Paz (padswagger)"}, {"title": "Ultimate Luna Snow Guide (Beginner/Advanced)", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=MbmlCd9u18M"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Atlas Bond", "partners": ["white-fox"], "key": "", "text": "Un renard spirituel soigne les alliés (80) et blesse les ennemis (45). Il ne charme plus depuis la saison 11. **Amélioré :** Le renard revient tout seul."}, {"name": "Chilling Charisma", "partners": ["namor"], "key": "", "text": "Frost Tide ralentit les ennemis. **Amélioré :** Une charge en plus et un impact au bout de la course."}, {"name": "Duality Dance", "partners": ["adam-warlock"], "key": "", "text": "Soul Bond relie et soigne ; Luna récupère 35 % des soins en saison 11. **Amélioré :** Les critiques réduisent les cooldowns."}, {"name": "Frozen Haven", "partners": ["cloak-and-dagger"], "key": "", "text": "L'état gelé émet une aura de soin (bouclier de 2 s depuis la saison 10). **Amélioré :** Aura renforcée."}, {"name": "Iced Out Diamond", "partners": ["emma-frost"], "key": "", "text": "Projectile de glace et barrière de diamant (bouclier de 300 en saison 11). **Amélioré :** Ajoute des ralentissements."}], "changes": [{"season": "Saison 11", "text": "Absolute Zero : durée du gel 2,7 → 1,5 s."}, {"season": "Saison 11", "text": "Team-up avec White Fox : le renard spirituel ne charme plus ; soin 70 → 80, dégâts 35 → 45."}, {"season": "Saison 11", "text": "Team-up avec Adam Warlock : part d'auto-soin 25 % → 35 %."}, {"season": "Saison 10", "text": "Cryo Heart : auto-soin 30/s → 35/s."}, {"season": "Saison 10", "text": "Tous les Strategists : l'ult se charge un peu moins vite (65 % du soin et 50 % des dégâts convertis en énergie, au lieu de 70 % et 55 %)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'luna-snow' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Magik est une Duelist de mêlée à combos, aussi à l'aise pour diver une cible isolée que pour se battre au cœur d'un brawl. Ses portails la rendent intouchable le temps d'un passage, ses capacités lui donnent de la vie bonus, et son ult en fait une version surpuissante d'elle-même.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["**N'entre pas avant ton équipe** : un dash trop tôt est un dash perdu.", "Travaille **un combo à la fois** en entraînement.", "Tes **portails sont ta survie** : garde-en toujours un pour ressortir."], "difficulty": 3, "tags": ["Mêlée", "Combos", "Dive", "Vie bonus"], "strengths": ["Invulnérable pendant un portail", "Meilleure brawleuse des Duelists", "Ult qui force les ults de soin adverses"], "weaknesses": ["Aucune portée réelle", "Combos exigeants à exécuter", "Fragile une fois les portails dépensés"], "playbook": [{"when": "Une cible fragile est à portée de dash", "then": "**Projectile chargé, puis dash, puis épée.** Jamais le dash avant le projectile."}, {"when": "Un contrôle part sur toi (boule de neige, étourdissement)", "then": "**Portail** : tu es invulnérable une fois à l'intérieur."}, {"when": "Ton combo n'a pas tué", "then": "**Portail vers un coin**, puis **démon** entre toi et tes poursuivants. Ne retraverse pas le fight pour revenir."}, {"when": "Tu te bats contre un groupe serré", "then": "**Épée sans mêlée** : tu touches plus de monde, donc plus de vie bonus et d'ult."}, {"when": "Un support adverse lance son ult de soin", "then": "Continue de frapper dans le brawl : **ton ult se charge**, la leur ne leur rapporte rien."}, {"when": "Ton équipe est en position et ton ult est prête", "then": "Annonce « 3, 2, 1 », puis **Darkchild** : pendant que leurs supports te regardent, ton équipe frappe."}], "sections": [{"title": "Philosophie de jeu", "lead": "Selon ta compo, tu isoles une cible depuis un angle, ou tu te bats au centre avec tes tanks. Dans les deux cas, les Magik patientes tuent davantage en dashant moins.", "ability": "", "key": "", "kind": "tips", "items": ["**En dive** : pars de ton angle, exécute ton combo sur une cible, puis reviens récupérer tes cooldowns.", "**En brawl** : ton projectile traverse les ennemis, charge ton ult et réduit le cooldown de tes portails.", "Joue **dans les coins** : celui de la backline adverse, celui du brawl. Jamais de face sur les tanks.", "Sur ton angle, reste **dans la ligne de vue d'un support** : soignée, tu gagnes presque tous les duels.", "Une mort qui force une **ult de soin** adverse n'est pas une erreur : c'est un échange favorable.", "Ne laisse personne tenir une hauteur gratuitement : dash dessus dès que le cooldown le permet."], "diagram": "reset"}, {"title": "Épée et projectile", "lead": "Des coups d'épée lents et puissants, et un projectile chargé qui traverse les ennemis.", "ability": "Soul Sword · Magik Slash", "key": "Clic G · Clic D", "kind": "default", "items": ["L'épée perd jusqu'aux **deux tiers** de ses dégâts en bout de portée : frappe de près.", "En duel, **un coup de mêlée après chaque coup d'épée**. Contre un groupe, épée seule.", "La mêlée porte moins loin que l'épée : si la cible recule, elle rate et te ralentit.", "Chaque ennemi touché par le projectile **réduit le cooldown des portails**.", "Un projectile chargé mais non tiré **reste disponible** après un portail."], "diagram": ""}, {"title": "Portails", "lead": "Deux charges. Tu es invulnérable pendant la traversée, et chaque portail débloque au choix un tourbillon ou un démon.", "ability": "Stepping Discs", "key": "", "kind": "default", "items": ["L'invulnérabilité commence **une fois dans le portail**, pas pendant que tu y entres.", "Ne dépense pas les deux charges **pour approcher** : marche ou dash pour entrer, portail pour prolonger ou sortir.", "Le **démon** (clic droit après un portail) frappe devant lui et bloque tes poursuivants. Tu as quelques secondes pour le placer : pose-le **derrière les supports**, là où ils voudront reculer.", "Le **tourbillon** frappe autour de toi : il ouvre un combo ou nettoie un brawl. En sortie de portail, le démon reste le meilleur choix dans la plupart des cas.", "Un portail donne un **léger gain de hauteur** : il atteint certaines positions sans dépenser le dash."], "diagram": "", "scene": {"title": "Entrer au dash, sortir au portail", "caption": "Le dash t'amène sur la cible. Le portail et le démon décident si tu en reviens.", "steps": ["Projectile chargé à travers le groupe, puis dash sur le support.", "Coups d'épée : le kill, ou un gros cooldown forcé.", "Portail vers un coin, démon entre toi et tes poursuivants."], "els": [{"t": "cover", "at": [300, 100], "size": [16, 64], "label": "Coin"}, {"t": "pawn", "at": [150, 60], "team": "me", "ghost": true}, {"t": "path", "kind": "beam", "team": "me", "pts": [[150, 60], [272, 82]]}, {"t": "path", "kind": "move", "team": "me", "pts": [[150, 66], [200, 100], [246, 90]], "n": 1}, {"t": "pawn", "at": [266, 84], "team": "enemy", "role": "heal", "ko": true}, {"t": "note", "at": [266, 58], "text": "2", "team": "me"}, {"t": "pawn", "at": [248, 98], "team": "me", "ghost": true}, {"t": "path", "kind": "move", "team": "me", "pts": [[248, 102], [296, 100], [280, 134]], "n": 3}, {"t": "pawn", "at": [278, 138], "team": "me"}, {"t": "mark", "at": [232, 132], "kind": "clone", "team": "me", "label": "Démon"}, {"t": "pawn", "at": [196, 120], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [214, 34], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [298, 40], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [180, 158], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [96, 96], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [70, 136], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [46, 76], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [46, 120], "team": "ally", "role": "heal"}]}}, {"title": "Dash", "lead": "Un dash rapide qui projette la cible en l'air, et toi avec. C'est l'ouverture de tes combos.", "ability": "Umbral Incursion", "key": "E", "kind": "default", "items": ["Vise **légèrement à droite** de la cible : il touche plus régulièrement.", "Trop tôt, ton équipe ne suit pas. Trop tard, elle a déjà perdu le fight à cinq contre six.", "Tu peux dasher **pendant le tourbillon** : tout ce qui se trouve sur le trajet est touché."], "diagram": ""}, {"title": "Combos", "lead": "Du plus simple au plus exigeant. Apprends-les un par un, puis choisis selon la distance et la cible.", "ability": "", "key": "", "kind": "tips", "items": ["**Simple** : projectile chargé, dash, épée. Prévisible, mais il force les cooldowns.", "**Avec portail** : projectile, portail, dash, épée. Plus difficile à lire, et le portail esquive une boule de neige.", "**Discret** : dash, épée, projectile non chargé, épée, mêlée.", "**Au contact** : épée, mêlée, projectile, épée, dash pour achever.", "**Élimination** : portail, tourbillon, dash, épée, mêlée, projectile.", "**Tuer dans une ult de soin** : projectile chargé et dash doivent toucher au même instant. Demande à ton équipe de viser la même cible, ou pose un démon dessus.", "Place la mêlée sur un **bouton latéral de la souris** : tu l'enchaînes sans lâcher tes déplacements."], "diagram": ""}, {"title": "Ultime", "lead": "Tu deviens Darkchild : toutes tes capacités frappent beaucoup plus fort, les portails reviennent bien plus vite, et tes capacités sont réinitialisées à la sortie.", "ability": "Darkchild", "key": "Q", "kind": "default", "items": ["Son vrai rôle : **forcer l'ult de soin adverse**. Tu la recharges vite en brawl, et l'équipe qui gagne le cycle d'ults gagne le fight suivant.", "**Portail, tourbillon, dash** : l'enchaînement de base, avec d'énormes dégâts de zone.", "**Projectile chargé puis dash** tue un héros fragile, même soigné, si tu as un bonus de dégâts.", "Le dash peut partir **à la dernière seconde** de l'ult : un dernier uppercut achève souvent une cible.", "Tu restes fragile et tu deviens la cible prioritaire : ne t'enfonce pas seule."], "diagram": ""}, {"title": "Team-up avec The Hood", "lead": "Avec The Hood dans l'équipe, chaque portail invoque un démon supplémentaire. Bien placé, c'est l'un des meilleurs outils de zone du jeu (cooldown de 20 secondes).", "ability": "Void Pentagram", "key": "", "kind": "default", "items": ["Pose les démons **entre le support et le tank** adverses : ils avancent dans ton équipe ou reculent dans les démons.", "Trois ou quatre démons sur un passage **le ferment**, même pendant une ult de soin.", "La position des démons compte plus que la tienne : pense zone avant de penser kill.", "Si tu débutes sur Magik, apprends-la d'abord sans ce team-up : il ne remplace pas les combos."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Dasher **avant** le projectile chargé.", "Dépenser les **deux portails** pour entrer.", "Oublier le **démon**.", "Engager **avant son équipe**.", "Jouer **de face sur les tanks**.", "Mêlée après chaque coup **contre un groupe**.", "Lancer l'ult **seule**, pour un 1 contre 6."], "diagram": ""}], "combos": [{"note": "Ne dash **jamais avant** le projectile.", "steps": [{"key": "Clic D", "label": "projectile chargé"}, {"key": "E", "label": "dash"}, {"key": "Clic G", "label": "épée"}], "title": "Simple"}, {"note": "Plus imprévisible, et esquive une boule de neige.", "steps": [{"key": "Clic D", "label": "projectile"}, {"key": "", "label": "Portail"}, {"key": "E", "label": "dash"}, {"key": "Clic G", "label": "épée"}], "title": "Avec portail"}, {"note": "", "steps": [{"key": "", "label": "Portail"}, {"key": "", "label": "Tourbillon"}, {"key": "E", "label": "dash"}, {"key": "Clic G", "label": "épée"}, {"key": "Mêlée", "label": ""}, {"key": "Clic D", "label": "projectile"}], "title": "Élimination"}], "counters": [{"hero": "emma-frost", "note": "En diamant, elle t'étrangle à l'entrée comme à la sortie."}, {"hero": "peni-parker", "note": "Tu n'as aucun moyen fiable de détruire son nid et ses mines."}, {"hero": "the-thing", "note": "Son impact au sol interrompt tes combos."}, {"hero": "human-torch", "note": "Un volant rapide que tu ne peux pas atteindre."}, {"hero": "namor", "note": "Ses tourelles t'entament avant ton entrée."}, {"hero": "winter-soldier", "note": "Crochet et uppercut : il te punit dès que tu dashes à sa portée."}, {"hero": "loki", "note": "Ses runes annulent ton combo : fais-les dépenser d'abord."}, {"hero": "ultron", "note": "Son drone soigne la cible juste assez pour qu'elle survive."}], "synergies": [{"hero": "magneto", "note": "Sa bulle sur toi pendant le combo : tu achèves sans risque."}, {"hero": "doctor-strange", "note": "Un tank polyvalent, et un team-up qui enchaîne deux ennemis."}, {"hero": "hela", "note": "Elle s'occupe des volants et des tireurs que tu n'atteins pas."}, {"hero": "the-hood", "note": "Votre team-up ajoute un démon à chaque portail."}, {"hero": "luna-snow", "note": "Son bonus de dégâts rend tes combos mortels dans une ult de soin."}, {"hero": "nightcrawler", "note": "Nouveau team-up de la saison 11 : ses téléportations lui donnent de la vie bonus."}], "sources": [{"url": "https://www.youtube.com/watch?v=4vilAy9tSwY", "title": "Magik Guide", "author": "Paz (padswagger)"}, {"title": "The Ultimate Magik Guide (From the #1 Magik)", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=WPe_Fce3k8w"}, {"title": "How to Dominate Top 500 as Magik", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=uy-heXjN8nA"}, {"title": "The Ultimate Magik Game Sense Guide", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=2jwUDTGkzyY"}, {"title": "The Best Magik Guide for Season 10", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=8ipk_Ggdj3I"}, {"title": "I VOD Reviewed Your Magik Games", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=JVK6xsG4vAY"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Chain of Cyttorak", "partners": ["doctor-strange"], "key": "", "text": "Une chaîne relie deux ennemis. **Amélioré :** Relie des groupes entiers."}, {"name": "Demon Disciple", "partners": ["nightcrawler"], "key": "", "text": "Chaque téléportation de Nightcrawler laisse un champ magique qui blesse les ennemis et soigne les alliés. **Amélioré :** Chaque téléportation lui donne aussi de la vie bonus."}, {"name": "Dimensional Shortcut", "partners": ["black-panther"], "key": "", "text": "Un disque de Limbo ramène Black Panther à sa position précédente. **Amélioré :** Retour déclenchable à la main."}, {"name": "Void Pentagram", "partners": ["the-hood"], "key": "", "text": "Les Stepping Discs rendent de l'énergie et invoquent des démons du Limbo (cooldown 20 s depuis la saison 10). **Amélioré :** Démons plus solides, plus de portée."}], "changes": [{"season": "Saison 11", "text": "Nouveau team-up avec Nightcrawler : Demon Disciple."}, {"season": "Saison 10", "text": "Démon du Limbo : bonus de vie 100 → 25."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'magik' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Magneto est le Vanguard le plus flexible du jeu. Face au dive, il protège sa backline avec ses bulles ; face au brawl, il se bulle lui-même pour frapper plus fort. Son ult, l'une des plus décisives, punit les ults de support et absorbe les projectiles adverses.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["**Consulte le tableau des scores** entre chaque fight : c'est à toi de savoir à qui ira ta bulle.", "Contre des divers, la bulle va **sur tes supports**. Sinon, **sur toi**.", "Ton ult vise d'abord **les supports en ult**."], "difficulty": 2, "tags": ["Bulles", "Bouclier", "Anti-ult", "Flexible"], "strengths": ["Bulle sur un allié à distance", "Rideau qui absorbe capacités et ults", "Ult qui tue à travers une ult de soin"], "weaknesses": ["Aucune mobilité", "Bouclier très bref", "Ult annulée par runes, bulles et lien d'âmes"], "playbook": [{"when": "Un diver saute sur un de tes supports", "then": "**E : bulle sur le support**, puis canon chargé pour repousser le diver hors de ta backline."}, {"when": "Personne ne menace ta backline", "then": "**F : bulle sur toi** et avance. Tire au canon pendant la bulle : si elle casse, il est rechargé d'un coup."}, {"when": "Un allié lance une ult vulnérable (Iron Man, Punisher, Star-Lord)", "then": "**Bulle sur lui** pour qu'il la termine."}, {"when": "Un gros burst ou une capacité précise arrive (dagues d'Hela, vortex, ult de Punisher ou d'Iron Man)", "then": "**Rideau magnétique** au moment exact : il absorbe tout ce qui le touche."}, {"when": "Un support adverse lance son ult", "then": "**Météore sur lui.** Contre Cloak & Dagger, tire au troisième dash ; contre Luna, brise d'abord son bouclier."}, {"when": "Un tank adverse est isolé devant toi", "then": "Canon au dernier palier : tu le renvoies dans son équipe, ou contre un mur."}], "sections": [{"title": "Philosophie de jeu", "lead": "Magneto s'adapte à tout, à condition de savoir ce que jouent les deux équipes. C'est le tank qui demande le plus de lecture de compo.", "ability": "", "key": "", "kind": "tips", "items": ["Avance **de couvert en couvert** : ton rideau ne dure qu'un instant, il ne remplace pas un mur.", "Tirer au centre pour **charger ton ult** vaut souvent mieux que chercher une élimination.", "N'attends pas que tes supports réclament une bulle : **c'est à toi de surveiller les divers**."], "diagram": "space"}, {"title": "Tir et canon", "lead": "Un projectile qui explose à l'impact, et un canon qui se charge par paliers. Au dernier palier, il repousse violemment.", "ability": "Iron Volley · Mag-Cannon", "key": "Clic G · Clic D", "kind": "default", "items": ["Enchaînement rapide : **tir, mêlée, canon, mêlée**. Mets la mêlée sur un bouton de souris.", "Le canon au premier palier est trop faible : **attends au moins le deuxième**.", "Le **repoussement** renvoie un tank dans son équipe, ou chasse un diver (Spider-Man, Iron Fist, Wolverine) de ta backline.", "À distance, l'explosion du tir est plus large, pas plus forte."], "diagram": ""}, {"title": "Bulles", "lead": "E pose une bulle sur un allié, F sur toi. Elles partagent le même cooldown. Une bulle brisée recharge instantanément ton canon.", "ability": "Metallic Chaos", "key": "E · F", "kind": "default", "items": ["**Règle 1** : face à des divers (Black Panther, Psylocke, Iron Fist, Spider-Man), la bulle est pour **ta backline**.", "**Règle 2** : sinon, **bulle-toi** pour avancer et frapper.", "**Règle 3** : garde-la pour **les ults**, celles qui visent tes supports comme celles de tes alliés.", "La bulle absorbe aussi la prise d'un Wolverine ou d'une Angela si elle est posée à temps."], "diagram": "", "scene": {"title": "La bulle sur ta backline", "caption": "Un diver compte tuer en deux secondes. La bulle lui en prend deux et demie, et le canon le renvoie d'où il vient.", "steps": ["Le diver saute sur ton support.", "Tu poses la bulle sur le support : le burst est absorbé.", "Canon chargé : tu repousses le diver vers son équipe."], "els": [{"t": "pawn", "at": [214, 30], "team": "enemy", "role": "dps", "ghost": true}, {"t": "path", "kind": "move", "team": "enemy", "pts": [[214, 30], [150, 30], [104, 106]], "n": 1}, {"t": "zone", "at": [54, 128], "r": 18, "team": "me", "n": 2}, {"t": "note", "at": [54, 160], "text": "bulle", "team": "me"}, {"t": "pawn", "at": [54, 128], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [104, 114], "team": "enemy", "hero": "black-panther", "above": true}, {"t": "pawn", "at": [156, 96], "team": "me"}, {"t": "path", "kind": "sight", "team": "me", "pts": [[156, 96], [54, 128]]}, {"t": "path", "kind": "push", "team": "me", "pts": [[112, 120], [160, 158], [214, 146]], "n": 3}, {"t": "pawn", "at": [222, 144], "team": "enemy", "role": "dps", "ghost": true}, {"t": "pawn", "at": [40, 64], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [132, 44], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [190, 62], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [246, 92], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [284, 60], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [288, 116], "team": "enemy", "role": "heal"}]}}, {"title": "Rideau magnétique", "lead": "Un bouclier d'énergie qui ne tient qu'un instant, mais absorbe tout ce qui le touche, capacités et ults comprises.", "ability": "Magnetic Curtain", "key": "Maj", "kind": "default", "items": ["Il se lève **pour une chose précise** : les dagues d'Hela, le vortex d'Invisible Woman, un étourdissement.", "Face à l'**ult de Punisher**, il le neutralise le temps que ton équipe le tue.", "Il absorbe le canon d'**Iron Man** et le météore d'un autre **Magneto**.", "Ce n'est pas un bouclier pour avancer : décide à l'avance de ce que tu veux bloquer."], "diagram": ""}, {"title": "Ultime", "lead": "Tu t'élèves et tu absorbes les projectiles ennemis autour de toi pendant quelques secondes, puis tu lances un météore.", "ability": "Meteor M", "key": "Q", "kind": "default", "items": ["Cible prioritaire : **un support en pleine ult**. Le tuer suffit souvent à gagner le fight.", "Fais d'abord dépenser les **runes de Loki**, le **lien d'Adam** et la **bulle** du Magneto adverse.", "Il **répond** aux ults à projectiles de Star-Lord, Punisher, Iron Man ou Ultron. Mais si ton rideau suffit, garde le météore.", "Les **rayons** traversent l'absorption.", "Contre Cloak & Dagger, n'attends pas le dernier dash : **tire au troisième**."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Ne **jamais regarder** la compo adverse.", "Garder la bulle pour soi alors qu'un **diver** est sur ses supports.", "Tirer le canon **au premier palier**.", "Dépenser le météore sur une ult **déjà contrée**.", "Lancer le météore **dans des runes ou une bulle**."], "diagram": ""}], "combos": [{"note": "Mets la mêlée sur un bouton de souris.", "steps": [{"key": "Clic G", "label": "tir"}, {"key": "Mêlée", "label": ""}, {"key": "Clic D", "label": "canon"}, {"key": "Mêlée", "label": ""}], "title": "Combo rapide"}], "counters": [{"hero": "emma-frost", "note": "Elle charge son rayon sur tes bulles et t'étrangle. Bloque son cristal avec le rideau."}, {"hero": "groot", "note": "Ses murs te séparent de ton équipe et tu n'as aucun déplacement pour les contourner."}, {"hero": "loki", "note": "Ses runes annulent ton météore."}, {"hero": "adam-warlock", "note": "Son lien d'âmes répartit les dégâts du météore."}, {"hero": "wolverine", "note": "Il t'emporte loin de tes soins : garde la bulle pour toi quand il est en face."}], "synergies": [{"hero": "emma-frost", "note": "La paire de tanks de référence : ton rideau et tes bulles, son bouclier et son contrôle."}, {"hero": "magik", "note": "Ta bulle lui permet de finir son combo sans risque."}, {"hero": "star-lord", "note": "Sous bulle, il tourne au milieu de l'équipe adverse pendant son ult."}, {"hero": "the-punisher", "note": "Bulle sur lui pendant son ult : il ne peut plus être arrêté."}, {"hero": "iron-man", "note": "Bulle sur lui le temps qu'il tire son canon."}, {"hero": "luna-snow", "note": "Derrière toi, elle soigne sans être inquiétée."}], "sources": [{"url": "https://www.youtube.com/watch?v=7qG9KH9UkNc", "title": "Magneto Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Explosive Entanglement", "partners": ["rogue"], "key": "", "text": "Un champ magnétique renforce la posture défensive de Rogue. **Amélioré :** Ajoute un recul et des dégâts aux murs."}, {"name": "Favorable Odds", "partners": ["gambit"], "key": "", "text": "Cartes magnétiques qui soignent et projettent (une seule fois, à l'explosion, depuis la saison 10). **Amélioré :** Explosion finale en plus."}, {"name": "Magnetic Resonance", "partners": ["emma-frost"], "key": "", "text": "Une projection imite Magneto (50 % des dégâts, 6 s en 10.5). **Amélioré :** Beaucoup plus de vie, la projection dure."}, {"name": "Metallic Chaos", "partners": ["scarlet-witch"], "key": "", "text": "Coup d'épée du chaos (cooldown 18 s depuis la saison 10). **Amélioré :** Le Mag-Cannon devient des épées chargées."}], "changes": [{"season": "Saison 10", "text": "Vie de base 650 → 600, bouclier 250 → 200, tir du Mag-Cannon 20 → 10."}, {"season": "Saison 10.5", "text": "Team-up avec Emma Frost : la projection fait 50 % des dégâts et dure 6 s."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'magneto' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Mantis est une tireuse déguisée en Strategist. Ses tirs lui rendent des orbes de vie, qu'elle dépense en soins ou en bonus de dégâts. Elle fait gagner son équipe en trouvant elle-même des éliminations et en plaçant son bonus de dégâts sur l'allié qui va décider du fight.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["**Tire à la tête** : chaque tir critique rend un orbe entier.", "Le **bonus de dégâts** va sur le DPS qui s'engage, au moment où il s'engage.", "Ton ult se lance **en premier**, pour pousser."], "difficulty": 2, "tags": ["Dégâts", "Bonus de dégâts", "Sommeil", "Angles"], "strengths": ["Dégâts de Duelist", "Bonus de dégâts pour un allié", "Soin qui continue hors de vue"], "weaknesses": ["Soins faibles en volume", "Dépend de sa précision pour ses orbes", "Sommeil réduit à 1,5 s en saison 11"], "playbook": [{"when": "Un DPS allié va s'engager (Star-Lord en duel, Punisher qui arrose, Namor avant son ult)", "then": "**Bonus de dégâts sur lui, juste avant.** Il coûte deux orbes depuis la saison 11 : réserve-le à ce moment-là."}, {"when": "Un flanker va sortir de ta vue pour un duel", "then": "**Fleur de soin** sur lui : elle continue de le soigner derrière le mur."}, {"when": "Un flanker te saute dessus (Black Panther, Psylocke, Spider-Man)", "then": "**Sommeil** à ses pieds, bonus sur toi, puis maintiens le tir : deux projectiles partent d'un coup à la tête. Tu as 1,5 seconde."}, {"when": "Un ennemi canalise une ult (Doctor Strange, Scarlet Witch, Storm)", "then": "**Sommeil** : il l'interrompt."}, {"when": "Tu n'as plus d'orbes", "then": "Tire, même au corps : depuis la saison 11, un tir non critique rapporte un tiers d'orbe."}, {"when": "Ton équipe veut prendre le point", "then": "**Ult, et avance avec elle.** Pendant l'ult, tu ne soignes plus : tu boostes et tu tires."}], "sections": [{"title": "Philosophie de jeu", "lead": "Un ennemi mort ne blesse plus personne : tes dégâts sont une forme de soin. Si tu ne comptes que soigner, un autre Strategist le fera mieux.", "ability": "", "key": "", "kind": "tips", "items": ["Prends des **angles** et mets la pression : ton économie d'orbes dépend de tes tirs.", "Les tirs à la tête **sur les tanks** rechargent aussi tes orbes.", "Surveille **en bas à droite** qui porte déjà ta fleur ou ton bonus.", "Elle donne son meilleur **à trois supports**, où elle joue presque comme un DPS."], "diagram": "angle"}, {"title": "Tirs", "lead": "Des projectiles rapides : deux tirs à la tête et un au corps tuent un héros fragile.", "ability": "", "key": "Clic G", "kind": "default", "items": ["Les tirs partent de ton personnage, pas de ton viseur : **de près, vise au-dessus et à droite** de la tête.", "À distance, **anticipe légèrement** le déplacement de la cible.", "Depuis la saison 11, un tir **non critique** rapporte 0,3 orbe : tu n'es plus à sec après une série de tirs au corps."], "diagram": ""}, {"title": "Fleur de soin", "lead": "Un soin immédiat suivi d'un soin continu. Le volume est modeste, mais il se poursuit même quand l'allié n'est plus en vue.", "ability": "Healing Flower", "key": "Clic D", "kind": "default", "items": ["Priorité : **ton autre support**, puis tes DPS. Les tanks seulement si tu as des orbes en trop.", "Attends que l'allié ait **perdu de la vie** : sur une barre pleine, l'orbe est gaspillé.", "Ton propre soin passif a baissé en saison 11 : ne compte pas dessus pour gagner un duel.", "Si tu rates tes cibles alliées, baisse la sensibilité de visée des soins dans les paramètres."], "diagram": ""}, {"title": "Bonus de dégâts", "lead": "Un bonus de dégâts durable, pour un allié ou pour toi. Il s'applique au moment où le tir part, pas à l'impact.", "ability": "Allied Inspiration · Natural Anger", "key": "E", "kind": "default", "items": ["C'est **ta capacité la plus importante**. Sur un allié, il coûte désormais **deux orbes** : il se place, il ne se distribue plus.", "Il **accélère aussi la charge d'ult** de celui qui le porte.", "Pose-le **avant** l'ult d'un Namor ou d'un Star-Lord, pas pendant.", "Ne le relance pas sur un allié qui l'a déjà : attends la dernière seconde.", "Sur toi, il te permet de **tuer une Luna** avec ton combo."], "diagram": ""}, {"title": "Sommeil", "lead": "Une spore qui endort l'ennemi le plus proche de l'impact. Il se réveille au premier dégât. Depuis la saison 11, le sommeil ne dure plus que 1,5 seconde.", "ability": "Spore Slumber", "key": "", "kind": "default", "items": ["Face à des flankers, **garde-le pour toi**.", "Il **interrompt les ults canalisées**.", "Sur une cible endormie, **maintiens le tir** : deux projectiles partent ensemble.", "Tirer dans l'**illusion violette** derrière la cible la réveille aussi."], "diagram": "", "scene": {"title": "Le sommeil contre un flanker", "caption": "Le sommeil ne dure qu'une seconde et demie : il faut que le bonus soit déjà sur toi quand la cible s'endort.", "steps": ["Le flanker arrive sur ton angle.", "Spore à ses pieds : il s'endort.", "Bonus sur toi, tir maintenu : deux projectiles à la tête."], "els": [{"t": "area", "at": [40, 10], "size": [124, 74], "label": "Ton angle"}, {"t": "pawn", "at": [236, 24], "team": "enemy", "role": "dps", "ghost": true}, {"t": "path", "kind": "move", "team": "enemy", "pts": [[236, 24], [190, 16], [150, 44]], "n": 1}, {"t": "pawn", "at": [144, 48], "team": "enemy", "hero": "psylocke", "label": "Endormie"}, {"t": "zone", "at": [144, 48], "r": 16, "team": "me"}, {"t": "note", "at": [144, 22], "text": "2", "team": "me"}, {"t": "pawn", "at": [72, 48], "team": "me"}, {"t": "path", "kind": "shot", "team": "me", "pts": [[72, 48], [144, 48]], "n": 3}, {"t": "pawn", "at": [120, 122], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [70, 130], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [150, 156], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [40, 160], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [226, 108], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [262, 140], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [290, 84], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [292, 126], "team": "enemy", "role": "heal"}]}}, {"title": "Ultime", "lead": "Une zone qui te suit : elle soigne, donne de la vie bonus au-delà du maximum et accélère ton équipe.", "ability": "Soul Resurgence", "key": "Q", "kind": "default", "items": ["Lance-la **pour pousser**, en première ult ; ton autre support garde la sienne pour répondre.", "Si tu es la seule à avoir une ult de support, garde-la pour la défense.", "**Avance avec ton équipe** : la zone est centrée sur toi.", "Pendant l'ult, cesse de soigner : **booste et tire**.", "Boucliers et décor bloquent tes soins."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Jouer Mantis **en simple soigneuse**.", "Relancer un bonus **déjà actif**.", "Dépenser le sommeil **avant** l'arrivée du flanker.", "Soigner **pendant sa propre ult**.", "**Distancer son équipe** pendant l'ult."], "diagram": ""}], "combos": [], "counters": [{"hero": "black-panther", "note": "Accompagné d'un tank qui dive, ton sommeil ne suffit plus."}, {"hero": "venom", "note": "Il encaisse le sommeil et te force à quitter ton angle."}, {"hero": "the-thing", "note": "Un brawl collé ne te laisse aucun angle."}, {"hero": "magik", "note": "Elle esquive ta spore dans un portail, puis te tue."}], "synergies": [{"hero": "black-widow", "note": "Avec ton bonus, son tir à la tête tue."}, {"hero": "star-lord", "note": "Ton bonus avant son ult la rend bien plus meurtrière."}, {"hero": "namor", "note": "Booste-le au lancement de sa baleine."}, {"hero": "psylocke", "note": "Une diver à booster à l'entrée, et une fleur qui la suit."}, {"hero": "luna-snow", "note": "Elle assure le volume de soins qui te manque."}, {"hero": "groot", "note": "Votre team-up donne un soin à son mur."}], "sources": [{"url": "https://www.youtube.com/watch?v=Fifg2W8-PO4", "title": "Mantis Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Spirit Breaker", "partners": ["emma-frost"], "key": "", "text": "Les dégâts de Sentience deviennent de la vie bonus. **Amélioré :** Vie bonus ponctuelle et cooldown de Psychic Spear réduit."}, {"name": "Star Blossom", "partners": ["star-lord"], "key": "", "text": "Relancer la fleur de soin propage le soin (10 + 3 %/s depuis la saison 10). **Amélioré :** Déclenchement immédiat."}, {"name": "Vibrant Vitality", "partners": ["loki"], "key": "", "text": "Domaine de régénération renforcé, sans bonus de dégâts pour les alliés depuis la saison 11. **Amélioré :** Onde de choc qui projette en blessant."}, {"name": "Vitality Pact", "partners": ["adam-warlock"], "key": "", "text": "L'état d'âme soigne et reforge (fleur à 12 + 3 %/s depuis la saison 10). **Amélioré :** Soul Bond avec soin sur la durée."}, {"name": "Wild Wall", "partners": ["groot"], "key": "", "text": "Le Wild Wall soigne et donne de la vie bonus ; il profite du passif Flora Colossus depuis la saison 11. **Amélioré :** Le mur évolue après avoir soigné."}], "changes": [{"season": "Saison 11", "text": "Life Energy Blast : un tir non critique rapporte 0,3 orbe de vie."}, {"season": "Saison 11", "text": "Spore Slumber : sommeil 3,5 → 1,5 s."}, {"season": "Saison 11", "text": "Allied Inspiration : coûte 2 orbes au lieu de 1. Nature's Favor : auto-soin 12,5 → 8/s."}, {"season": "Saison 10", "text": "Life Orb se charge en 4 s au lieu de 3 s, soin de zone en forme d'âme 5/s → 30/s, fleur renforcée 15 + 3,5 % → 10 + 3,5 %."}, {"season": "Saison 10", "text": "Tous les Strategists : l'ult se charge un peu moins vite (65 % du soin et 50 % des dégâts convertis en énergie, au lieu de 70 % et 55 %)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'mantis' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Mister Fantastic est un hybride entre Duelist et Vanguard. Il protège sa backline contre les divers, remplit sa jauge en utilisant tout son kit, puis gonfle pour enfoncer le front adverse. Tout son jeu consiste à choisir entre protéger, avancer et gonfler.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["Contre le **dive**, protège tes supports avec tes capacités : cela remplit aussi ta jauge.", "Contre un **brawl**, gonfle en même temps qu'une ult alliée.", "Frappe **à portée de bras**, pas au contact : ton allonge est ton avantage."], "difficulty": 2, "tags": ["Brawl", "Peel", "Contrôle", "Hybride"], "strengths": ["Meilleure survie parmi les Duelists", "Agrippement qui bloque les fuites", "Forme invulnérable qui renvoie les dégâts"], "weaknesses": ["Aucun burst : il ne tue pas seul", "Contrôlable même gonflé", "Ne peut plus protéger ses alliés une fois gonflé"], "playbook": [{"when": "Un diver vient de dépenser son déplacement sur ta backline", "then": "**Agrippement** : il ne peut plus fuir. Puis élongation sur lui pour le ralentir."}, {"when": "Ton support se fait attaquer et tu ne peux pas arrêter le diver", "then": "**Élongation vers ton support** : vous gagnez tous les deux de la vie bonus."}, {"when": "Une ult à projectiles vise un support (Magneto, Iron Man, Punisher)", "then": "**Élongation vers lui, puis forme réfrigérateur** : tu absorbes l'ult et tu la renvoies."}, {"when": "Ta jauge est presque pleine et le front adverse est à portée", "then": "Élongation sur un ennemi : **tu gonfles en arrivant**. Vérifie d'abord que tes supports suivent."}, {"when": "Une ult alliée part (Gambit, Luna, Mantis)", "then": "**Gonfle maintenant** : tes coups traversent les boucliers et tu es soigné pendant toute ta forme."}, {"when": "Ta forme gonflée se termine et tu es entamé", "then": "**Ult** : tu regonfles et tu récupères de la vie bonus à chaque rebond réussi."}], "sections": [{"title": "Philosophie de jeu", "lead": "Il sait à la fois protéger sa backline et écraser le front adverse. Les meilleurs choisissent le bon rôle au bon moment, et en changent en cours de fight.", "ability": "", "key": "", "kind": "tips", "items": ["Vois-le comme un **second tank** : idéal dans une compo à un seul Vanguard, et le meilleur Duelist pour protéger ses supports.", "Contre des divers, **force leurs cooldowns** en défendant, puis gonfle et avance.", "Choisis **où te battre** : prends les couloirs et les passages étroits avant l'adversaire.", "Il n'a aucun burst : il lui faut des DPS à ses côtés pour conclure.", "Il enchaîne forme normale et forme gonflée : c'est souvent le dernier debout."], "diagram": "brawl"}, {"title": "Forme gonflée", "lead": "Coups, agrippements et élongations remplissent une jauge. Pleine, tu gonfles : plus de vie, des coups plus rapides et plus forts, un déplacement plus rapide.", "ability": "Elastic Strength", "key": "", "kind": "default", "items": ["Gonflé, tes coups **traversent les boucliers** : la backline est à portée.", "La jauge redescend si tu restes inactif : **fais tourner tout ton kit** pour la remplir, et l'agrippement pour la maintenir.", "Gonflé, tu ne peux **plus protéger tes alliés** avec tes capacités.", "Tu restes **sensible aux contrôles** : prise, étourdissement, projection."], "diagram": ""}, {"title": "Coups allongés", "lead": "Des coups à longue portée qui frappent plusieurs ennemis si tu balaies ton viseur pendant l'extension du bras.", "ability": "Stretch Punch", "key": "Clic G", "kind": "default", "items": ["Balaie **dans le sens du bras** pour toucher tout un groupe.", "Frappe **depuis un couvert**, à distance de bras : coller l'ennemi te fait perdre ton seul avantage.", "Toucher un groupe ne remplit pas la jauge plus vite qu'une cible seule, mais charge ton ult."], "diagram": ""}, {"title": "Agrippement", "lead": "Un projectile lent qui saisit une cible : tu peux l'attirer, ou la projeter contre un autre ennemi. Pendant un instant, elle ne peut plus utiliser ses déplacements.", "ability": "Distended Grip", "key": "Clic D", "kind": "default", "items": ["Son vrai intérêt est de **bloquer une fuite** : saisis Venom après ses boucliers, Gambit après son premier dash.", "Il est lent et court : **rapproche-toi** avant de le lancer.", "Deux ennemis projetés l'un contre l'autre sont **immobilisés tous les deux**.", "Près d'un bord, il **éjecte**."], "diagram": ""}, {"title": "Élongation", "lead": "Tu t'étires vers un allié ou un ennemi et tu gagnes de la vie bonus. Sur un ennemi, tu le ralentis ; un volant touché tombe.", "ability": "Flexible Elongation", "key": "", "kind": "default", "items": ["Après un agrippement, **élongation sur la cible** : ralentie, elle ne s'échappe plus.", "Vers un **allié attaqué**, elle lui donne de la vie bonus.", "Deux charges : ne les laisse jamais **toutes les deux pleines**."], "diagram": "", "scene": {"title": "Protéger, puis gonfler", "caption": "Chaque capacité utilisée pour défendre remplit la jauge. Le diver repoussé, tu arrives gonflé sur leur front.", "steps": ["Le diver a dépensé son déplacement : tu l'agrippes.", "Élongation vers ton support : vie bonus pour vous deux.", "Jauge pleine : tu gonfles et tu avances sur leur front."], "els": [{"t": "pawn", "at": [96, 60], "team": "enemy", "hero": "black-panther", "above": true}, {"t": "pawn", "at": [56, 62], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [140, 110], "team": "me", "ghost": true}, {"t": "path", "kind": "pull", "team": "me", "pts": [[96, 60], [124, 92]], "n": 1}, {"t": "path", "kind": "move", "team": "me", "pts": [[140, 110], [100, 110], [66, 84]], "n": 2}, {"t": "pawn", "at": [72, 92], "team": "me", "ghost": true}, {"t": "path", "kind": "move", "team": "me", "pts": [[80, 96], [140, 150], [190, 110]], "n": 3}, {"t": "pawn", "at": [194, 104], "team": "me"}, {"t": "zone", "at": [194, 104], "r": 24, "team": "me", "label": "Gonflé"}, {"t": "pawn", "at": [236, 96], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [262, 56], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [290, 110], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [280, 148], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [48, 130], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [176, 40], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [120, 160], "team": "ally", "role": "dps"}]}}, {"title": "Forme réfrigérateur", "lead": "Tu deviens invulnérable et insensible aux contrôles, tu absorbes les dégâts, puis tu en renvoies une partie. Pendant ce temps, tu es lent et sans capacités.", "ability": "Reflexive Rubber", "key": "", "kind": "default", "items": ["Tu **contestes le point** tout en étant invulnérable.", "**Élongation puis réfrigérateur** sur un support : tu bloques pour lui une ult de Magneto, d'Iron Man ou de Punisher.", "Tu peux **l'annuler tôt** pour riposter plus vite.", "Ne la lance pas quand un simple couvert suffisait."], "diagram": ""}, {"title": "Ultime", "lead": "Tu gonfles instantanément et tu rebondis. Chaque rebond qui touche relance le suivant (six au maximum), frappe plus fort et ralentit davantage.", "ability": "Brainiac Bounce", "key": "Q", "kind": "default", "items": ["Idéale **à la fin de ta forme gonflée** : tu regagnes de la vie et tu maintiens la pression.", "Vise **un groupe** : un rebond manqué arrête la série.", "Sous un **plafond bas** ou un pont, les rebonds s'enchaînent bien plus vite.", "Elle **force l'ult de soin adverse** : avec ta vie bonus, on ne te tue presque jamais pendant.", "Elle répond à une ult de Jeff ou de Gambit si ton équipe suit."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Gonfler alors qu'un **diver** est sur ses supports.", "**Coller** l'ennemi au lieu d'utiliser son allonge.", "Agripper une cible **avant** qu'elle ait dépensé son déplacement.", "Réfrigérateur **trop tôt**.", "Avancer **sans ses supports**."], "diagram": ""}], "combos": [], "counters": [{"hero": "emma-frost", "note": "Elle charge son rayon sur ta large hitbox, puis t'étrangle."}, {"hero": "groot", "note": "Son grand mur te sépare de tes soins quand tu avances gonflé."}, {"hero": "the-punisher", "note": "Il te fait fondre à distance, hors de portée de bras."}, {"hero": "moon-knight", "note": "Même problème : ses ricochets te touchent de loin."}, {"hero": "hela", "note": "Elle te force en réfrigérateur, puis attend que tu en sortes."}, {"hero": "phoenix", "note": "Son burst à distance te prive de ta forme gonflée."}], "synergies": [{"hero": "magneto", "note": "Tu tiens sa backline : il peut avancer et jouer agressif."}, {"hero": "the-thing", "note": "Deux brawlers qui protègent et frappent ; votre team-up te donne un coup chargé."}, {"hero": "winter-soldier", "note": "Tu ouvres l'espace, il fait les dégâts."}, {"hero": "gambit", "note": "Son ult pendant ta forme gonflée : rien ne t'arrête."}, {"hero": "invisible-woman", "note": "Son bouclier et votre team-up te maintiennent en vie pendant tes engages."}], "sources": [{"url": "https://www.youtube.com/watch?v=V4DFywKwdFk", "title": "Mister Fantastic Guide", "author": "Paz (padswagger)"}, {"title": "This Guide Is Fantastic!", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=ZwH1aVlfGyw"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Clobberin' Research Dept.", "partners": ["the-thing"], "key": "", "text": "Posture de bagarre avec un coup de poing chargé (activable à volonté depuis la saison 10). **Amélioré :** Ajoute un coup de marteau chargé."}, {"name": "Fantastic Amplifier", "partners": ["rocket-raccoon"], "key": "", "text": "Un amplificateur augmente l'élasticité et le gonflement. **Amélioré :** Les coups projettent les ennemis."}, {"name": "First Family", "partners": ["invisible-woman"], "key": "", "text": "Invisibilité avec soin et vitesse. **Amélioré :** Version renforcée."}], "changes": [{"season": "Saison 10", "text": "Brawling Punch se charge en 0,75 s au lieu de 1 s, 65 de dégâts sans charge au lieu de 55."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'mister-fantastic' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Moon Knight est une machine à dégâts de zone. Ses tirs ricochent entre les ennemis proches les uns des autres et chargent son ult à grande vitesse : contre une équipe sans bouclier, il en a une à presque chaque fight. En échange, il est lent et fragile.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["Vise les **groupes** : chaque ricochet charge ton ult.", "Ne tire **pas sur l'ankh** : tire sur l'ennemi à côté.", "Choisis ta **position avant le fight** : ta mobilité sert à fuir, pas à t'installer."], "difficulty": 1, "tags": ["Dégâts de zone", "Ricochets", "Charge d'ult", "Combos d'ult"], "strengths": ["Dégâts de zone par ricochets", "Ult très rapide à charger", "Ankh qui attire les ennemis"], "weaknesses": ["Peu de mobilité", "Neutralisé par les boucliers", "Inefficace contre les volants"], "playbook": [{"when": "Les ennemis sont regroupés", "then": "**Ankh au milieu**, puis tire sur l'ennemi le plus proche de l'ankh : les ricochets touchent tout le groupe."}, {"when": "Une cible fragile est isolée", "then": "**Ankh, rafale au corps, lame lunaire.** Vise la cible, pas l'ankh."}, {"when": "Un flanker te saute dessus (Star-Lord, Psylocke)", "then": "**Ankh à tes pieds** : l'attraction gêne ses déplacements et tes tirs ricochent sur lui."}, {"when": "Ton ult est prête", "then": "**Cesse d'arroser les tanks** : tu chargerais les ults de soin adverses."}, {"when": "Groot ou Angela lance son ult", "then": "**Main de Khonshu** par-dessus : les ennemis retenus ne peuvent pas en sortir."}, {"when": "Une ult de Magneto ou un diver arrive", "then": "**Grappin** vers une hauteur. C'est ta seule vraie fuite."}], "sections": [{"title": "Philosophie de jeu", "lead": "Fais des dégâts, charge ton ult, lance-la, recommence. La seule subtilité : ne pas nourrir les ults de soin adverses une fois la tienne prête.", "ability": "", "key": "", "kind": "tips", "items": ["**Choisis ton angle avant le fight** et rejoins-le à pied : tu es trop lent pour corriger une mauvaise position.", "Tiens-toi **à bonne distance** : ne sacrifie pas ton placement pour des tirs plus faciles.", "Avec un ankh, tu gagnes la plupart des duels : tu peux prendre un léger angle, puis revenir vers ton équipe."], "diagram": "poke"}, {"title": "Fléchettes", "lead": "Des rafales de trois projectiles qui ricochent entre les ennemis proches les uns des autres. Chaque rebond fait un peu moins de dégâts.", "ability": "Crescent Dart", "key": "Clic G", "kind": "default", "items": ["Les ricochets demandent des ennemis **serrés** : cherche les couloirs et les objectifs.", "Pour achever une cible isolée, **vise-la directement** : le premier impact est le plus fort.", "Leur vitesse est celle des tirs de Storm et de Namor : ta visée se transfère d'un héros à l'autre."], "diagram": ""}, {"title": "Lame lunaire", "lead": "Une grande lame qui ricoche elle aussi, et te donne de la vie bonus à chaque rebond. Deux charges.", "ability": "Moon Blade", "key": "Clic D", "kind": "default", "items": ["**Une lame pour ouvrir** (vie bonus), **une pour achever**.", "De près, vise au-dessus de la tête pour toucher la tête.", "Elle est un peu plus lente que les fléchettes."], "diagram": ""}, {"title": "Ankh", "lead": "Un ankh qui se fixe au décor, attire les ennemis proches et sert de point de rebond à tes tirs.", "ability": "Ancient Ankh", "key": "", "kind": "default", "items": ["**L'attraction** est sa vraie force : elle regroupe les cibles et les retient dans ton ult.", "Tirer sur l'ankh te fait **perdre les dégâts du premier impact** : tire sur l'ennemi à côté.", "Tu peux en avoir **deux** : en défense, pose-les à l'avance sur les passages."], "diagram": "", "scene": {"title": "L'ankh et les ricochets", "caption": "L'ankh regroupe les cibles et ajoute un point de rebond : une rafale en touche alors trois.", "steps": ["Tu poses l'ankh au milieu du groupe : il attire.", "Tu tires sur l'ennemi le plus proche, pas sur l'ankh.", "Les ricochets passent de l'un à l'autre."], "els": [{"t": "mark", "at": [240, 96], "kind": "trap", "team": "me", "label": "Ankh"}, {"t": "zone", "at": [240, 96], "r": 34, "team": "me"}, {"t": "note", "at": [240, 142], "text": "1", "team": "me"}, {"t": "pawn", "at": [212, 76], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [266, 72], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [260, 122], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [104, 62], "team": "me"}, {"t": "path", "kind": "shot", "team": "me", "pts": [[104, 62], [212, 76]], "n": 2}, {"t": "path", "kind": "sight", "team": "me", "pts": [[212, 76], [266, 72]], "n": 3}, {"t": "path", "kind": "sight", "team": "me", "pts": [[266, 72], [260, 122]]}, {"t": "path", "kind": "sight", "team": "me", "pts": [[260, 122], [212, 76]]}, {"t": "pawn", "at": [304, 104], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [196, 156], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [130, 112], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [84, 130], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [46, 80], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [46, 124], "team": "ally", "role": "heal"}]}}, {"title": "Combo", "lead": "Le seul enchaînement dont tu as besoin pour tuer un héros fragile.", "ability": "", "key": "", "kind": "tips", "items": ["**Ankh, rafale au corps, lame lunaire.**", "Avec un tir à la tête dans la rafale, la cible tombe presque à coup sûr.", "Ne vise pas trop bas : tu toucherais l'ankh au lieu de la cible."], "diagram": ""}, {"title": "Mobilité", "lead": "Double saut, planeur et grappin. Le grappin est lent à partir, rapide une fois accroché.", "ability": "Night Glider · Moon Knight Hook", "key": "Maj · F", "kind": "default", "items": ["Le grappin est ta **fuite** : ne le dépense pas là où un saut suffit.", "Vise **le flanc d'un mur** au grappin, puis saute : tu montes plus haut.", "Le planeur sert à passer d'une hauteur à l'autre, pas à esquiver des tirs.", "Un grappin bien anticipé esquive le météore de Magneto."], "diagram": ""}, {"title": "Ultime", "lead": "Pendant plusieurs secondes, des mains explosives s'abattent en triangle autour du point visé.", "ability": "Hand of Khonshu", "key": "Q", "kind": "default", "items": ["Le centre fait le plus de dégâts : vise **là où la cible va**, légèrement devant elle.", "Combos de référence : **prison de Groot** et **lance d'Angela**, qui retiennent les ennemis dessous.", "Sans combo, lance-la quand même : elle revient très vite.", "Sortir l'ult (l'ankh au-dessus de ta tête) peut suffire à **faire dépenser une ult de support**. À utiliser avec parcimonie."], "diagram": "ultcombo"}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Tirer **sur l'ankh**.", "Dépenser le **grappin pour se déplacer**.", "S'approcher pour **toucher plus facilement**.", "Arroser les tanks **avec l'ult déjà prête**.", "Lancer l'ult **toujours de la même façon**."], "diagram": ""}], "combos": [{"note": "Vise la cible, pas l'ankh : tu perdrais les dégâts du premier impact.", "steps": [{"key": "", "label": "Ankh"}, {"key": "Clic G", "label": "rafale au corps"}, {"key": "Clic D", "label": "lame lunaire"}], "title": "Le combo"}], "counters": [{"hero": "magneto", "note": "Son rideau coupe tes ricochets et son ult absorbe la tienne."}, {"hero": "doctor-strange", "note": "Son bouclier arrête tes tirs avant le premier rebond."}, {"hero": "captain-america", "note": "Il te colle et ton grappin ne suffit pas à le semer."}, {"hero": "iron-man", "note": "En l'air, rien ne ricoche vers lui."}, {"hero": "psylocke", "note": "Elle évite ton ankh et punit ton manque de mobilité."}, {"hero": "ultron", "note": "Un autre volant hors de tes ricochets."}], "synergies": [{"hero": "groot", "note": "Sa prison regroupe l'équipe adverse sous tes mains."}, {"hero": "angela", "note": "Sa lance retient les ennemis dans ta zone."}, {"hero": "magneto", "note": "Sa bulle te laisse tirer plus longtemps."}, {"hero": "hela", "note": "Elle prend en charge les volants."}, {"hero": "mantis", "note": "Son bonus de dégâts accélère encore la charge de ton ult."}], "sources": [{"url": "https://www.youtube.com/watch?v=yHH6KBvciPg", "title": "Moon Knight Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Blade of Khonshu", "partners": ["blade"], "key": "", "text": "Chaque Whirlwind Slash lance une lame lunaire en plus."}, {"name": "Blood Moon", "partners": ["elsa-bloodstone"], "key": "", "text": "L'ankh piège invoque des serres. **Amélioré :** En invoque plusieurs."}, {"name": "Luminous Moon", "partners": ["cloak-and-dagger"], "key": "", "text": "Dash intangible avec une vague de soin. **Amélioré :** Plus long, avec un soin continu."}, {"name": "New Moon's Shadow", "partners": ["the-hood"], "key": "", "text": "Une barrière lunaire explose (détection des rebonds à 6 m depuis la saison 10). **Amélioré :** Les attaques rebondissent."}], "changes": [], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'moon-knight' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Namor est un Duelist à tourelles. Il garde d'abord sa backline contre les divers, puis menace les supports adverses depuis un angle décalé, tridents et tourelles tirant ensemble. Sans tourelles bien placées et sans précision, il n'apporte presque rien.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["D'abord **gérer les divers**, ensuite seulement prendre un angle.", "**Pose une tourelle avant de tirer** : tes tridents réduisent leur cooldown.", "Le trident explosif n'a pas besoin de toucher : **vise les pieds**."], "difficulty": 1, "tags": ["Tourelles", "Anti-dive", "Angles décalés", "Combos d'ult"], "strengths": ["Tourelles qui gardent la backline seules", "Ult qui bloque les déplacements", "Bulle invulnérable"], "weaknesses": ["Aucune fuite hors de la bulle", "Demande une vraie précision", "Tourelles fragiles à découvert"], "playbook": [{"when": "L'équipe adverse joue un ou deux divers", "then": "**Tourelles dans un coin de ta backline**, en hauteur. Elles les repèrent et les entament avant l'engage."}, {"when": "Un diver saute sur tes supports", "then": "**Trident explosif à ses pieds** : tes tourelles passent en mode frénétique sur lui."}, {"when": "Ta backline est tranquille", "then": "Prends un **angle décalé**, lance une tourelle sur un mur juste avant de te montrer, et tire sur les supports."}, {"when": "Une ult ou un burst part sur toi", "then": "**Bulle** : deux secondes d'invulnérabilité, et tes tourelles continuent de tirer."}, {"when": "Groot lance sa prison, ou les ennemis sont groupés sur le point", "then": "**Baleine** : dans la zone, ils ne peuvent plus utiliser leurs déplacements."}, {"when": "Cloak & Dagger trace son ult", "then": "Baleine sur la fin de son quatrième dash : elle ne peut plus s'échapper."}], "sections": [{"title": "Philosophie de jeu", "lead": "Pose-toi la question dans l'ordre : y a-t-il un flanker dans ma backline ? Si oui, je m'en occupe. Sinon, je prends un angle agressif.", "ability": "", "key": "", "kind": "tips", "items": ["Contre des divers (**Black Panther, Magik, Psylocke**), tes tourelles restent avec tes supports.", "Une fois la menace écartée, prends un **angle décalé** sur leurs supports.", "N'engage pas **tes deux tourelles** sans être sûr de l'élimination.", "Tes pas s'entendent, et tu n'as aucune fuite hors de la bulle : à haut niveau, le flanc est un risque à mesurer.", "Chaque trident qui touche réduit le cooldown des tourelles : **sans précision, pas de tourelles**."], "diagram": "choke"}, {"title": "Tridents", "lead": "Des tridents qui tuent un héros fragile en deux tirs à la tête, et un trident explosif qui déclenche une attaque renforcée de toutes tes tourelles.", "ability": "Trident of Neptune · Wrath of the Seven Seas", "key": "Clic G · Clic D", "kind": "default", "items": ["Joue à **mi-distance**.", "Un tir à la tête rend tes tourelles **frénétiques**.", "Le trident explosif agit en zone : **vise les pieds**, même raté il déclenche tes tourelles.", "Enchaînement : **tourelles posées, tir à la tête, trident explosif**, en annulant l'animation du premier tir avec le second."], "diagram": ""}, {"title": "Tourelles", "lead": "De petites tourelles qui se fixent au décor et verrouillent la première cible visible. Deux au maximum.", "ability": "Aquatic Dominion", "key": "E", "kind": "default", "items": ["Place-les **là où on ne peut pas les viser facilement** : sur un mur, en hauteur, dans un angle.", "**Pour défendre** : dans un coin de ta backline. Elles protègent tes supports pendant que tu tires devant.", "**Pour repérer** : une tourelle sur un flanc habituel révèle le diver avant son entrée.", "**Pour attaquer** : lance-les sur un mur juste avant de sortir, elles tirent en même temps que toi.", "Trop loin, elles verrouillent la mauvaise cible et laissent tes supports seuls."], "diagram": "", "scene": {"title": "Les tourelles gardent la backline", "caption": "Deux tourelles dans un coin tirent sur le diver dès qu'il apparaît. Ton trident explosif les rend frénétiques.", "steps": ["Avant le fight, deux tourelles en hauteur dans ta backline.", "Le diver entre : elles le verrouillent aussitôt.", "Trident explosif à ses pieds : tourelles frénétiques."], "els": [{"t": "cover", "at": [20, 20], "size": [60, 14], "label": "Mur"}, {"t": "mark", "at": [40, 44], "kind": "turret", "team": "me"}, {"t": "mark", "at": [70, 44], "kind": "turret", "team": "me"}, {"t": "note", "at": [96, 40], "text": "1", "team": "me"}, {"t": "pawn", "at": [220, 24], "team": "enemy", "role": "dps", "ghost": true}, {"t": "path", "kind": "move", "team": "enemy", "pts": [[220, 24], [160, 30], [104, 98]], "n": 2}, {"t": "pawn", "at": [98, 106], "team": "enemy", "hero": "magik"}, {"t": "pawn", "at": [54, 100], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [60, 146], "team": "ally", "role": "heal"}, {"t": "path", "kind": "shot", "team": "me", "pts": [[40, 44], [90, 96]]}, {"t": "path", "kind": "shot", "team": "me", "pts": [[70, 44], [96, 94]]}, {"t": "pawn", "at": [160, 124], "team": "me"}, {"t": "path", "kind": "beam", "team": "me", "pts": [[160, 124], [110, 110]], "n": 3}, {"t": "pawn", "at": [196, 80], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [180, 156], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [244, 96], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [274, 136], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [294, 70], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [296, 112], "team": "enemy", "role": "heal"}]}}, {"title": "Bulle", "lead": "Tu t'enfermes dans une bulle invulnérable et insensible aux contrôles. Son cooldown est long.", "ability": "Blessing of the Deep", "key": "", "kind": "default", "items": ["Les bons adversaires chercheront à **te la faire dépenser** avant leur ult.", "Ne la gaspille pas pour gagner une hauteur.", "Tes **tourelles continuent de tirer**, et tes supports peuvent te soigner à travers.", "Elle bloque le **météore de Magneto** : place-toi devant tes supports."], "diagram": ""}, {"title": "Ultime", "lead": "Une baleine géante s'écrase sur une zone. Les ennemis touchés ne peuvent plus utiliser leurs capacités de déplacement.", "ability": "Horn of Proteus", "key": "Q", "kind": "default", "items": ["Le **cercle central** fait d'énormes dégâts. Avec un bonus de dégâts, le cercle extérieur tue aussi les héros fragiles.", "Elle **bloque les déplacements** : portails de Magik, patinage de Luna, intangibilité de Cloak.", "Après une **prison de Groot**, aucune ult de soin ne sauve l'équipe adverse.", "Runes de Loki, bulles et boucliers la bloquent : fais-les dépenser d'abord.", "Elle se charge vite : **utilise-la souvent**."], "diagram": "ultcombo"}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Partir sur un flanc alors qu'un **diver** menace ta backline.", "Poser ses tourelles **à découvert** ou trop loin.", "Chercher à **toucher** avec le trident explosif.", "Dépenser la **bulle** pour un déplacement.", "Engager **ses deux tourelles** sur un coup incertain."], "diagram": ""}], "combos": [{"note": "Annule l'animation du premier tir avec le trident.", "steps": [{"key": "E", "label": "tourelles"}, {"key": "Clic G", "label": "tête"}, {"key": "Clic D", "label": "trident"}], "title": "Tête et trident"}], "counters": [{"hero": "emma-frost", "note": "Elle entretient la charge de son rayon sur tes tourelles."}, {"hero": "hela", "note": "Elle te domine à distance et détruit tes tourelles en un tir."}, {"hero": "luna-snow", "note": "Deux rafales suffisent pour une tourelle."}, {"hero": "magneto", "note": "Une compo à bouclier au centre t'oblige à partir sur un flanc risqué."}, {"hero": "iron-man", "note": "Ses explosions détruisent tes tourelles hors de leur portée."}], "synergies": [{"hero": "hulk", "note": "Ses bulles et tes tourelles : la backline devient presque impossible à diver."}, {"hero": "groot", "note": "Sa prison sous ta baleine : le combo d'ults le plus sûr."}, {"hero": "winter-soldier", "note": "Son crochet ramène les cibles dans la portée de tes tourelles."}, {"hero": "luna-snow", "note": "Son bonus de dégâts rend ta baleine mortelle jusqu'au bord."}, {"hero": "mantis", "note": "Demande son bonus au moment où tu lances l'ult."}], "sources": [{"url": "https://www.youtube.com/watch?v=FPPs-i1ee-g", "title": "Namor Guide", "author": "Paz (padswagger)"}, {"title": "The King of the Seas", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=l_51Gk4iULk"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Chilling Charisma", "partners": ["luna-snow"], "key": "", "text": "Frost Tide ralentit les ennemis. **Amélioré :** Une charge en plus et un impact au bout de la course."}, {"name": "Deep Wrath", "partners": ["hela"], "key": "", "text": "Les kills de Hela font apparaître des monstros morts-vivants. **Amélioré :** Ils apparaissent à chaque attaque."}, {"name": "Gamma Monstro", "partners": ["hulk"], "key": "", "text": "Un monstro gamma en plus (cooldown 25 s depuis la saison 10). **Amélioré :** Ajoute une barrière d'eau gamma."}], "changes": [{"season": "Saison 10", "text": "Trident of Neptune 75 → 80 par tir."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'namor' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Nightcrawler est le Strategist de la saison 11. Il soigne à distance avec des grenades, se téléporte sur un allié pour le soigner, peut le ramener à l'abri avec lui, et son ult déplace toute son équipe d'un coup. C'est un support de sauvetage et de repositionnement, au plafond de maîtrise élevé.", "patch_note": "Guide de lancement : Nightcrawler est sorti avec la saison 11, le 13 novembre 2026. Il est rédigé à partir de la description officielle de ses capacités, sans chiffres ni recul compétitif. Il sera à affiner après quelques semaines de jeu.", "tldr": ["Tes **téléportations soignent** : chacune doit arriver sur l'allié qui en a besoin.", "**Tandem Teleport ramène un allié** à ta position de départ : choisis-la sûre.", "Ton ult **déplace ton équipe**, puis attire les ennemis vers toi."], "difficulty": 3, "tags": ["Téléportation", "Sauvetage", "Soin de zone", "Repositionnement"], "strengths": ["Sauve un allié trop avancé", "Téléportations qui soignent", "Ult de repositionnement d'équipe"], "weaknesses": ["Fragile une fois ses téléportations dépensées", "Tandem Teleport dépend de l'accord de l'allié", "Héros tout neuf : équilibrage incertain"], "playbook": [{"when": "Un allié est entamé loin de toi", "then": "**Swift Intervention** : tu te téléportes à ses côtés, il reçoit un soin immédiat, un soin continu et un bonus de soins reçus."}, {"when": "Ton tank ou ton diver est allé trop loin", "then": "**Tandem Teleport** : s'il accepte, tu vas sur lui et tu le ramènes à ton point de départ, soignés et accélérés tous les deux."}, {"when": "Ton équipe est groupée et prend des dégâts", "then": "**Grenades au milieu du groupe** : elles soignent les alliés et blessent les ennemis dans l'explosion."}, {"when": "Un ennemi te colle", "then": "**Smoke Shift** : la fumée le projette et te soigne. La troisième activation te ramène au point de départ."}, {"when": "Ton équipe doit prendre un point ou une hauteur", "then": "**Ult** sur la destination : bonus de dégâts, soin et vie bonus, puis tout le monde y est téléporté."}, {"when": "Des ennemis sont dans la zone de fumée de ton ult", "then": "**Relance l'ult** : tu les frappes et tu les attires vers toi, loin de leurs soins ou vers un vide."}], "sections": [{"title": "Plan de jeu", "lead": "Nightcrawler ne soigne pas depuis une position fixe : il va là où le soin est nécessaire, puis il en revient. Ses téléportations sont à la fois ses soins et sa survie.", "ability": "", "key": "", "kind": "default", "items": ["Chaque téléportation dépensée est **un soin donné et une sortie en moins** : garde-en toujours une.", "Ta position de départ compte : c'est là que **Tandem Teleport** ramène ton allié, et là que **Smoke Shift** te ramène.", "Préviens tes alliés : Tandem Teleport ne fonctionne que si l'allié **accepte l'invitation**.", "Il grimpe aux murs : sers-t'en pour te placer hors de portée entre deux interventions."], "diagram": ""}, {"title": "Grenades", "lead": "Tu lances trois grenades à la suite. Elles explosent à l'impact : dégâts pour les ennemis, soin pour les alliés.", "ability": "Forged Brimstone", "key": "Clic G", "kind": "default", "items": ["Vise **le groupe**, pas un joueur : c'est un soin de zone.", "Trois grenades par salve : **répartis-les** si tes alliés sont écartés.", "Elles soignent aussi à travers l'explosion au sol : vise les pieds."], "diagram": ""}, {"title": "Trois épées", "lead": "Une série d'estocs vers l'avant, avec ses deux sabres et l'épée tenue par sa queue. Elle peut infliger des dégâts critiques.", "ability": "Three-Sword Style", "key": "", "kind": "default", "items": ["C'est ton outil de duel : contre un diver isolé, pas contre un tank.", "Elle t'oblige à être au contact : ne la préfère pas à tes grenades quand ton équipe a besoin de soins."], "diagram": ""}, {"title": "Téléportation de soutien", "lead": "Tu te téléportes aux côtés d'un allié : il reçoit un soin immédiat, un bonus de soins reçus et un soin continu.", "ability": "Swift Intervention", "key": "Maj", "kind": "default", "items": ["Lance-la **juste avant** que l'allié prenne le burst : le bonus de soins reçus renforce aussi ton autre support.", "Tu arrives **là où il est** : vérifie que tu survivras à l'endroit.", "Enchaîne avec des grenades à vos pieds."], "diagram": ""}, {"title": "Fumée", "lead": "Tu marques ton point de départ, puis tu fonces en tournoyant. La fumée laissée derrière toi blesse et projette les ennemis, et soigne les alliés. Deux relances possibles ; la troisième te ramène à la marque.", "ability": "Smoke Shift", "key": "E", "kind": "default", "items": ["**Défensif** : un ou deux passages pour repousser un diver, puis retour à la marque.", "**Offensif** : traverse le brawl pour soigner et projeter, et reviens en sécurité.", "La projection **interrompt un déplacement** adverse si elle tombe au bon moment."], "diagram": ""}, {"title": "Téléportation à deux", "lead": "Tu envoies une invitation à un allié. S'il accepte, tu te téléportes à ses côtés et tu le ramènes à ta position de départ. Vous recevez tous les deux un soin immédiat, un soin continu et un bonus de vitesse.", "ability": "Tandem Teleport", "key": "F", "kind": "default", "items": ["C'est **la capacité de sauvetage** du héros : un tank isolé, un diver qui n'a plus de sortie.", "Lance-la **depuis un couvert** : c'est là que vous réapparaissez.", "Elle demande un accord : annonce-la, et ne compte pas dessus avec un allié qui ne t'écoute pas.", "Elle sert aussi à ramener un allié **avant** une ult adverse annoncée."], "diagram": "", "scene": {"title": "Ramener un allié", "caption": "Le point où tu lances la capacité est celui où vous réapparaissez. Lance-la à couvert.", "steps": ["Ton tank est isolé et entamé au milieu des ennemis.", "Tu l'invites : tu te téléportes à ses côtés.", "Vous revenez tous les deux à ton point de départ, soignés."], "els": [{"t": "cover", "at": [108, 80], "size": [14, 48], "label": "Mur"}, {"t": "path", "kind": "move", "team": "me", "pts": [[80, 96], [150, 20], [210, 84]], "n": 2}, {"t": "pawn", "at": [226, 92], "team": "ally", "role": "tank", "ghost": true}, {"t": "note", "at": [226, 66], "text": "1", "team": "ally"}, {"t": "pawn", "at": [206, 96], "team": "me", "ghost": true}, {"t": "path", "kind": "pull", "team": "me", "pts": [[212, 106], [150, 186], [84, 116]], "n": 3}, {"t": "pawn", "at": [72, 108], "team": "me"}, {"t": "pawn", "at": [66, 74], "team": "ally", "role": "tank", "label": "Sauvé", "above": true}, {"t": "pawn", "at": [256, 62], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [258, 122], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [292, 92], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [296, 136], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [294, 34], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [36, 134], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [58, 162], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [30, 56], "team": "ally", "role": "dps"}]}}, {"title": "Ultime", "lead": "Tu choisis une destination. Toi et les alliés proches recevez un bonus de dégâts, un soin continu et de la vie bonus, puis vous y êtes téléportés un par un. Une zone de fumée se forme à l'arrivée ; en relançant, tu frappes les ennemis qui s'y trouvent et tu les attires vers toi.", "ability": "Phasing Finale", "key": "Q", "kind": "default", "items": ["**Pour engager** : toute ton équipe arrive sur leur backline ou sur une hauteur, déjà boostée.", "**Pour s'échapper** : une destination en arrière sort ton équipe d'une ult adverse.", "La relance **attire les ennemis** : près d'un bord de carte, elle les y emmène.", "Les alliés arrivent **un par un** : ne choisis pas une destination où le premier arrivé meurt seul.", "Elle n'aide que les alliés proches de toi au lancement : regroupe-toi avant."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "default", "items": ["Dépenser **toutes ses téléportations** et ne plus avoir de sortie.", "Lancer Tandem Teleport **à découvert**.", "Se téléporter sur un allié **déjà perdu**.", "Lancer l'ult **loin de son équipe**.", "Se battre aux épées quand l'équipe **a besoin de soins**."], "diagram": ""}], "combos": [], "counters": [{"hero": "winter-soldier", "note": "Son crochet t'attrape à l'arrivée d'une téléportation."}, {"hero": "emma-frost", "note": "Son étranglement te prive de tes sorties."}, {"hero": "the-thing", "note": "Sa zone interdit les déplacements : tes téléportations aussi, probablement."}, {"hero": "hela", "note": "Tu arrives à découvert à côté de ton allié : elle t'attend."}], "synergies": [{"hero": "rogue", "note": "Votre team-up : après ta frappe, elle projette les ennemis vers toi."}, {"hero": "magik", "note": "Votre team-up : chacune de tes téléportations te donne de la vie bonus."}, {"hero": "venom", "note": "Un tank de dive que tu peux aller chercher quand il n'a plus de sortie."}, {"hero": "black-panther", "note": "Tu le ramènes après son combo."}, {"hero": "luna-snow", "note": "Elle assure le soin de fond pendant tes interventions."}], "sources": [{"title": "Notes d'équilibrage de la saison 11", "author": "GameRiv", "url": "https://gameriv.com/marvel-rivals-season-11-balance-patch-notes/"}, {"title": "Nightcrawler Is Here: Character Abilities Guide", "author": "esportnow.gg", "url": "https://esportnow.gg/games/news/nightcrawler-is-here-marvel-rivals-character-abilities-guide"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Demon Disciple", "partners": ["magik"], "key": "", "text": "Chaque téléportation de Nightcrawler laisse un champ magique qui blesse les ennemis et soigne les alliés. **Amélioré :** Chaque téléportation lui donne aussi de la vie bonus."}, {"name": "Protective Siblings", "partners": ["rogue"], "key": "", "text": "Nightcrawler disparaît, blesse les ennemis et soigne les alliés, puis retombe en frappant avec ses trois épées (ralentissement). **Amélioré :** Rogue rappelle son énergie après l'impact : soin, dégâts et ennemis projetés vers Nightcrawler."}], "changes": [], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'nightcrawler' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Peni Parker contrôle le terrain avec son nid, ses toiles et ses mines. En défense, elle garde sa backline contre les divers ; en attaque, elle installe une position avancée que l'adversaire doit venir déloger à plusieurs. C'est d'abord un contre, ensuite un soutien pour ses DPS.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["**Déplace ton nid** selon la menace : en backline contre le dive, près du front contre le brawl, sur un angle en attaque.", "Pose tes mines **par groupes**, dans une toile, et garde-en toujours une en rechargement.", "Ta toile étourdissante **interrompt une ult** en cours d'incantation."], "difficulty": 2, "tags": ["Contrôle de zone", "Anti-dive", "Pièges", "Défense"], "strengths": ["Zone presque impossible à diver", "Étourdissement à distance", "Toiles qui soignent et accélèrent ses alliés"], "weaknesses": ["Large hitbox, vulnérable au tir continu", "Nid détruit dès qu'il est à découvert", "Faible quand le fight se déplace"], "playbook": [{"when": "L'équipe adverse joue un ou deux divers", "then": "**Nid derrière un coin de ta backline**, mines groupées dans la toile. Reste à proximité."}, {"when": "Un diver entre dans ta zone", "then": "**Toile étourdissante** sur lui : immobilisé sur tes mines, il meurt."}, {"when": "Un ennemi canalise une ult (Doctor Strange, Iron Man, Scarlet Witch)", "then": "**Toile étourdissante** : elle interrompt l'incantation."}, {"when": "L'adversaire recule après un fight perdu", "then": "**Avance ton nid** sur la position qu'il vient de quitter : il n'a plus de coin sûr où revenir."}, {"when": "Cloak & Dagger trace souvent son ult dans ta backline", "then": "**Mine les murs et les coins** derrière ton équipe : elle explose en dashant."}, {"when": "Une ult de zone arrive sur ton nid avancé (Gambit, Phoenix)", "then": "**Récupère le nid** et repose-le derrière ton équipe : intact, il revient immédiatement."}], "sections": [{"title": "Philosophie de jeu", "lead": "En défense comme en attaque, ton rôle est de donner à tes supports et à tes DPS une position que l'adversaire ne peut pas leur prendre.", "ability": "", "key": "", "kind": "tips", "items": ["**En défense**, tu gardes la backline : chaque seconde qu'un flanker perd dans ta zone est une seconde gagnée par ton équipe.", "**En attaque**, un nid sur un angle décalé oblige l'adversaire à envoyer deux joueurs pour te déloger. Ton équipe gagne alors au centre.", "Face aux gros DPS, ton seul abri est ton **grappin** : apprends ses trajectoires.", "Tes dégâts ont un peu baissé en saison 11 : ta valeur vient de ta zone, pas de tes tirs."], "diagram": "choke"}, {"title": "Tir et snare", "lead": "Des projectiles explosifs sans rechargement, et une toile lente qui étourdit sa cible ou, si elle la manque, reste au sol.", "ability": "Cyber-Web Cluster · Cyber-Web Snare", "key": "Clic G · Clic D", "kind": "default", "items": ["Vise **les pieds** pour la régularité.", "Les **toiles au sol** soignent, donnent de la vie bonus et accélèrent toi et tes alliés.", "Trois toiles au maximum : le compteur est en bas à gauche.", "Prolonge la toile de ton nid avec des snares volontairement tirés au sol."], "diagram": ""}, {"title": "Grappin", "lead": "Tu te tires vers le décor et tu y restes attachée. En relâchant ton déplacement, tu reviens en fronde vers le point d'accroche.", "ability": "Cyber-Bond", "key": "", "kind": "default", "items": ["Sers-t'en pour **menacer la backline**, puis revenir vers ton équipe.", "Détachée, tu traverses la carte : nid, grappin, récupération du nid, et tu recommences plus loin.", "Ne reste jamais accrochée **au milieu des ennemis**.", "Baisse la sensibilité de ciblage dans les paramètres pour mieux le contrôler."], "diagram": ""}, {"title": "Mines", "lead": "Des mines qui explosent au passage d'un ennemi. Posées dans une toile, elles sont invisibles.", "ability": "Arachno-Mine", "key": "", "kind": "default", "items": ["Il en faut **trois ou quatre ensemble** pour tuer un héros fragile.", "Contre une **Hela**, mine ses hauteurs habituelles. Contre un **Black Panther**, mine ta backline.", "Elles explosent un peu plus tard depuis la saison 11 : un ennemi qui traverse vite en réchappe. **Étourdis-le dessus.**", "En attaque, lance-les sur les supports quand ton équipe les presse."], "diagram": ""}, {"title": "Nid d'araignées", "lead": "Un nid qui étend une grande toile et envoie des araignées qui blessent et ralentissent. Tu peux le récupérer à tout moment.", "ability": "Bionic Spider-Nest", "key": "", "kind": "default", "items": ["Pose-le **derrière un coin** : pour le détruire, l'ennemi doit s'exposer.", "Contre le **dive**, en backline. Contre le **brawl**, près du front : la toile accélère toute ton équipe.", "Un nid intact **revient tout de suite** : ne le laisse jamais mourir sur place.", "Un nid qui reste au même endroit alors que la menace a changé ne sert plus à rien."], "diagram": "", "scene": {"title": "La zone de Peni", "caption": "Un diver compte sur sa vitesse. Dans la toile, il est ralenti, étourdi, puis il marche sur trois mines.", "steps": ["Nid derrière un coin, mines groupées dans la toile.", "Le diver entre : la toile le ralentit.", "Snare : étourdi sur les mines, il meurt."], "els": [{"t": "cover", "at": [92, 36], "size": [14, 50], "label": "Coin"}, {"t": "zone", "at": [72, 104], "r": 44, "team": "me", "label": "Toile"}, {"t": "mark", "at": [72, 70], "kind": "turret", "team": "me"}, {"t": "note", "at": [46, 60], "text": "nid", "team": "me"}, {"t": "mark", "at": [98, 110], "kind": "trap", "team": "me"}, {"t": "mark", "at": [84, 128], "kind": "trap", "team": "me"}, {"t": "mark", "at": [108, 128], "kind": "trap", "team": "me"}, {"t": "note", "at": [124, 150], "text": "1", "team": "me"}, {"t": "pawn", "at": [226, 30], "team": "enemy", "role": "dps", "ghost": true}, {"t": "path", "kind": "move", "team": "enemy", "pts": [[226, 30], [170, 50], [108, 108]], "n": 2}, {"t": "pawn", "at": [102, 104], "team": "enemy", "hero": "black-panther", "above": true}, {"t": "pawn", "at": [160, 124], "team": "me"}, {"t": "path", "kind": "beam", "team": "me", "pts": [[160, 124], [112, 110]], "n": 3}, {"t": "pawn", "at": [44, 96], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [50, 138], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [206, 96], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [190, 156], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [250, 100], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [280, 140], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [296, 66], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [298, 108], "team": "enemy", "role": "heal"}]}}, {"title": "Ultime", "lead": "Beaucoup de vie bonus et de vitesse, des coups qui projettent, des mines à lancer et des araignées en continu.", "ability": "Spider-Sweeper", "key": "Q", "kind": "default", "items": ["N'ouvre pas le fight avec : tu deviens **la cible prioritaire**.", "En plein fight, elle **étend tes toiles sur tout le point**.", "Avance **avec ton équipe**, pas seule par un passage latéral.", "Si l'adversaire a une ult à interrompre, **garde ton snare** avant de lancer la tienne."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["**Oublier ses mines** pendant tout un fight.", "Poser le nid **à découvert**.", "Lancer l'ult **en ouverture**.", "Rester accrochée au grappin **au milieu des ennemis**.", "Laisser le nid **au même endroit** quand la menace a changé."], "diagram": ""}], "combos": [], "counters": [{"hero": "emma-frost", "note": "Elle charge son rayon sur ton nid et sur toi."}, {"hero": "groot", "note": "Un mur posé sur ton nid le détruit."}, {"hero": "the-punisher", "note": "Son tir continu ne manque pas ta large hitbox."}, {"hero": "moon-knight", "note": "Ses ricochets passent de tes araignées à toi."}, {"hero": "phoenix", "note": "Son ult détruit ton nid, tes mines et ta vie bonus d'un coup."}, {"hero": "ultron", "note": "Il détruit ton nid depuis les airs, hors de ta portée."}], "synergies": [{"hero": "rocket-raccoon", "note": "Votre team-up fait larguer des kits d'armure à ton nid."}, {"hero": "doctor-strange", "note": "Son bouclier absorbe les DPS qui te contrent."}, {"hero": "magneto", "note": "Sa bulle te protège quand tu avances ton nid."}, {"hero": "hela", "note": "Un nid sur son angle la met à l'abri des divers."}, {"hero": "namor", "note": "Tourelles et nid : la backline la mieux gardée du jeu."}], "sources": [{"url": "https://www.youtube.com/watch?v=fHwTq8w2FVU", "title": "Peni Parker Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Parker Power-Up", "partners": ["spider-man"], "key": "", "text": "Bombe-araignée collante qui marque les ennemis (cooldown 10 s depuis la saison 10). **Amélioré :** Vie bonus à la détonation."}, {"name": "Rocket Network", "partners": ["rocket-raccoon"], "key": "", "text": "Le nid d'araignées largue des drones et des kits d'armure. **Amélioré :** Régénération et plus d'unités."}, {"name": "SP//DR Sync", "partners": ["ultron"], "key": "", "text": "Imperative: Patch s'applique aux alliés. **Amélioré :** Les drones cumulent les effets de Firewall."}, {"name": "Vibranium Mech", "partners": ["black-panther"], "key": "", "text": "Bouclier de vibranium frontal et vitesse d'attaque (cooldown 15 s depuis la saison 10). **Amélioré :** Bouclier plus grand."}], "changes": [{"season": "Saison 11", "text": "Cyber-Web Cluster : explosion 15 → 12 de dégâts. Arachno-Mine : délai de détonation 0,6 → 0,7 s."}, {"season": "Saison 10", "text": "Cyber-Web plus rapide (0,3 s → 0,25 s entre deux tirs), plus de ralentissement quand elle tire."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'peni-parker' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Phoenix est une tireuse hitscan dont les dégâts viennent des réactions en chaîne : ses tirs posent des étincelles, trois étincelles font exploser la cible et marquent ses voisins. Elle ne gagne pas un duel à longue distance comme Hela ; elle domine quand les ennemis sont groupés.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["Commence **au centre** pour poser tes étincelles, puis vole vers un angle en cours de fight.", "Reste **à mi-distance** : ses dégâts chutent nettement de loin.", "Avant ton ult, pose **deux étincelles** sur les héros fragiles : l'impact les fait exploser."], "difficulty": 2, "tags": ["Hitscan", "Marques", "Brawl", "Anti-bouclier"], "strengths": ["Explosions en chaîne sur les groupes", "Ult qui détruit boucliers, bulles et invocations", "Étourdissement et dash intouchable"], "weaknesses": ["Perd le duel à longue portée", "Peu efficace contre une équipe dispersée", "Vol bruyant"], "playbook": [{"when": "Deux ennemis sont proches l'un de l'autre", "then": "**Corps sur A, tête sur B, tête sur A** : A explose et marque B, qui explose à son tour."}, {"when": "Un diver te saute dessus", "then": "**Explosion télékinétique à tes pieds** : il est étourdi en arrivant. Garde le dash pour sa seconde tentative."}, {"when": "Une ult part sur toi (Iron Man, Magneto)", "then": "**Dash** : tu es insensible aux dégâts pendant le déplacement."}, {"when": "Un ennemi canalise une ult (Doctor Strange, Scarlet Witch)", "then": "**Explosion télékinétique** : la première détonation étourdit."}, {"when": "L'adversaire s'abrite derrière boucliers, bulles ou runes", "then": "**Ult en premier** : l'onde de choc détruit tout, les ults de ton équipe passent ensuite."}, {"when": "Une ult de soin adverse est active et tu n'as pas la tienne", "then": "Tire **sur les tanks** : les explosions rebondissent sur leurs voisins et chargent ton ult."}], "sections": [{"title": "Philosophie de jeu", "lead": "Phoenix demande plus de réflexion qu'un tireur classique : il ne suffit pas de toucher, il faut toucher des ennemis proches les uns des autres.", "ability": "", "key": "", "kind": "tips", "items": ["Avec des tanks de brawl, **joue au centre**, lance tes chaînes, puis vole vers un angle décalé.", "Avec des tanks de dive, **guette le moment où les supports adverses se regroupent** pour se défendre : c'est là que tu les fais exploser.", "Tu es aussi une **anti-dive** : reste près de ta backline et punis chaque entrée.", "Contre une Hela à longue distance, tu perds : rapproche le duel ou change d'angle.", "Ses étincelles font un peu moins de dégâts depuis la saison 11 : la chaîne compte plus que jamais."], "diagram": "angle"}, {"title": "Flammes et marques", "lead": "Des tirs instantanés qui posent des étincelles. À trois étincelles, la cible explose et ses voisins sont marqués à leur tour.", "ability": "Cosmic Flames", "key": "Clic G", "kind": "default", "items": ["Un tir à la tête pose **deux étincelles** : trois tirs à la tête d'affilée provoquent deux explosions.", "Les étincelles **disparaissent** après quelques secondes : ne laisse pas une cible à deux marques.", "Chaque explosion te donne un peu de **vie bonus**.", "Les **clones de Loki** servent de relais pour tes chaînes.", "Ta mêlée pose aussi une étincelle : utile sur un groupe collé à toi, sous une prison de Groot par exemple."], "diagram": "", "scene": {"title": "La réaction en chaîne", "caption": "Trois étincelles font exploser une cible, et l'explosion en pose sur ses voisins. Sur un groupe serré, un kill en déclenche un autre.", "steps": ["Corps sur A (une étincelle), tête sur B (deux).", "Tête sur A : trois étincelles, A explose.", "L'explosion marque B : trois étincelles, B explose aussi."], "els": [{"t": "pawn", "at": [96, 80], "team": "me"}, {"t": "pawn", "at": [226, 70], "team": "enemy", "role": "dps", "label": "A", "above": true}, {"t": "pawn", "at": [256, 100], "team": "enemy", "role": "heal", "label": "B"}, {"t": "path", "kind": "shot", "team": "me", "pts": [[96, 80], [226, 70]], "n": 1}, {"t": "path", "kind": "shot", "team": "me", "pts": [[96, 80], [256, 100]], "n": 1}, {"t": "zone", "at": [226, 70], "r": 26, "team": "me", "n": 2}, {"t": "path", "kind": "push", "team": "me", "pts": [[232, 76], [250, 94]], "n": 3}, {"t": "pawn", "at": [210, 120], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [290, 60], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [292, 140], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [140, 120], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [110, 150], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [46, 76], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [46, 124], "team": "ally", "role": "heal"}]}}, {"title": "Dash", "lead": "Un dash qui laisse derrière toi une illusion explosive. Tu es insensible aux dégâts pendant le déplacement.", "ability": "Telepathic Illusion", "key": "", "kind": "default", "items": ["Il part **dans la direction de ton déplacement**, sans tourner la caméra : c'est l'un des meilleurs outils de repositionnement contre le dive.", "Il **esquive les ults** d'Iron Man ou de Magneto.", "Un diver cherche à te le faire dépenser à sa première approche : **attends la seconde**.", "Ne t'en sers pas pour monter : c'est le rôle du vol."], "diagram": ""}, {"title": "Vol", "lead": "Quelques secondes de vol rapide, qui rechargent aussi tes munitions. Il s'entend de loin.", "ability": "Dark Ascent", "key": "", "kind": "default", "items": ["Il sert à **passer sur un angle en plein fight**, une fois tes chaînes lancées au centre.", "Tirer ou lancer une capacité **l'interrompt** : attention au-dessus du vide.", "On t'entend arriver : ne t'isole pas, une Psylocke n'attend que cela."], "diagram": ""}, {"title": "Explosion télékinétique", "lead": "Trois détonations en ligne. La première étourdit brièvement, les deux suivantes ralentissent. Chacune pose une étincelle.", "ability": "Telekinesis Burst", "key": "Clic D", "kind": "default", "items": ["C'est un **contrôle dur** : il interrompt un dash, un grappin, une ult en cours de lancement.", "Contre un diver, lance-la **à tes pieds**.", "Après un crochet de **Winter Soldier**, elle prolonge le contrôle de la cible.", "Son cooldown est long : réserve-la à un diver ou à une ult."], "diagram": ""}, {"title": "Ultime", "lead": "Tu t'élèves, tu t'écrases sur une zone, puis une onde de choc détruit boucliers, invocations et vie bonus adverses, même à travers les murs.", "ability": "Endsong Inferno", "key": "Q", "kind": "default", "items": ["L'onde de choc **détruit** le bouclier de Strange, les bulles de Magneto, la vie bonus de Venom, les runes et clones de Loki, l'amplificateur de Rocket.", "C'est **la meilleure ult d'ouverture de combo** : elle retire les protections, les autres ults concluent.", "Depuis la saison 11, l'onde ne pose plus qu'**une** étincelle : il en faut déjà deux sur la cible pour qu'elle explose.", "Tu ressors avec la vie que tu avais : ne t'écrase pas **au milieu du front adverse**.", "En l'air, tu peux être **abattue** par un tir précis : contre une équipe prête, écrase-toi derrière un mur et laisse l'onde faire le travail."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Jouer **à longue distance**, comme une Hela.", "Dépenser le dash **pour monter**.", "Voler et **s'isoler**.", "S'écraser **au milieu de l'équipe adverse**.", "Laisser les étincelles **expirer**."], "diagram": ""}], "combos": [{"note": "Le dash final annule l'animation.", "steps": [{"key": "Clic D", "label": "explosion"}, {"key": "Clic G", "label": "tir"}, {"key": "Mêlée", "label": ""}, {"key": "", "label": "Dash"}], "title": "Presque un kill"}], "counters": [{"hero": "hela", "note": "À longue distance, elle te tue avant que tes étincelles comptent."}, {"hero": "captain-america", "note": "Petite cible, toujours loin de son équipe : aucune chaîne possible."}, {"hero": "psylocke", "note": "Elle te fait dépenser dash et vol, puis revient."}, {"hero": "rocket-raccoon", "note": "Ses soins et ses kits d'armure cassent tes seuils d'explosion."}, {"hero": "the-thing", "note": "Il saute pour intercepter ton ult."}, {"hero": "the-punisher", "note": "Son tir continu t'abat pendant l'ascension de l'ult."}], "synergies": [{"hero": "magneto", "note": "Un brawl au centre : tous les ennemis sont à portée de chaîne."}, {"hero": "black-panther", "note": "Les supports qu'il attaque se regroupent, et tu les fais exploser."}, {"hero": "winter-soldier", "note": "Ton étourdissement prolonge son crochet."}, {"hero": "invisible-woman", "note": "Son attraction regroupe les cibles pour tes chaînes."}, {"hero": "groot", "note": "Sa prison serre l'équipe adverse : une explosion en déclenche quatre."}], "sources": [{"url": "https://www.youtube.com/watch?v=OoQyu_WzbBY", "title": "Phoenix Guide", "author": "Paz (padswagger)"}, {"title": "The Ultimate Phoenix Guide", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=j2OSEOO0RUU"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Abyssal Flames", "partners": ["venom"], "key": "", "text": "Les griffes de Venom posent des étincelles de Phoenix, qui explosent à 3 cumuls."}, {"name": "Burning Bullets", "partners": ["black-widow"], "key": "", "text": "Le Plasma Cannon devient un tir instantané (hitscan), 75 de dégâts en saison 11. **Amélioré :** Une charge en plus."}, {"name": "Circle of Life", "partners": ["hela"], "key": "", "text": "Les tirs de Netherfire posent des étincelles et étourdissent. **Amélioré :** Plus d'étincelles."}, {"name": "Slim and Red", "partners": ["cyclops"], "key": "", "text": "Embrasement qui brûle et déclenche les étincelles (cooldown 10 s en 10.5). **Amélioré :** Les étincelles réduisent le cooldown de Ricochet Force."}, {"name": "Telekinetic Beatdown", "partners": ["rogue"], "key": "", "text": "Coups télékinétiques qui sautent d'une cible à l'autre. **Amélioré :** Étincelles et frappes en plus."}], "changes": [{"season": "Saison 11", "text": "Détonation des étincelles : dégâts directs 45 → 40, dégâts de zone 20 → 15."}, {"season": "Saison 11", "text": "Endsong Inferno : l'onde de choc pose 1 étincelle au lieu de 2."}, {"season": "Saison 10.5", "text": "Cosmic Flames 60 → 65, étincelles : 45 de dégâts directs et 20 d'explosion."}, {"season": "Saison 10.5", "text": "L'explosion des étincelles ne soigne plus : elle donne 5 de vie bonus pendant 4 s (25 max)."}, {"season": "Saison 10.5", "text": "Ult : 2 étincelles par touche au lieu de 1."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'phoenix' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Psylocke est une assassine de flanc. Elle évite le couloir principal, approche invisible une cible isolée, la tue en un enchaînement, puis revient vers son équipe. Chacun de ses tirs réduit le cooldown de toutes ses capacités : elle n'est jamais longtemps sans outils.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["Passe **par un flanc**, loin du centre, et cherche les duels.", "Active l'invisibilité **à la bonne distance** : tu dois réapparaître à portée.", "Entre deux dives, **tire sur les tanks** pour récupérer tes cooldowns."], "difficulty": 3, "tags": ["Assassin", "Invisibilité", "Combos", "Flanc"], "strengths": ["Approche invisible", "Tirs qui rechargent toutes ses capacités", "Deux dashes pour entrer et sortir"], "weaknesses": ["Portée efficace courte", "Révélée par tourelles, nids et marques", "Ult diluée sur un groupe"], "playbook": [{"when": "Un tireur adverse tient un angle (Hela, Hawkeye, Black Widow)", "then": "Contourne-le, **invisibilité**, puis **tir, shurikens, rappel, deux tirs**."}, {"when": "Tu viens de tuer ou de forcer un cooldown", "then": "**Dash vers ton équipe.** Tu reviendras dans dix secondes avec tout ton kit."}, {"when": "Tes capacités sont en cooldown", "then": "**Tire sur un tank**, même de loin : chaque projectile qui touche les fait revenir."}, {"when": "On te poursuit", "then": "**Dash derrière un mur, puis invisibilité** : l'adversaire perd toute information."}, {"when": "Un ou deux ennemis sont isolés et les ults de soin sont dépensées", "then": "**Ult sur eux** : moins il y a de cibles, plus chaque coup compte."}, {"when": "Loki a posé ses clones, ou Hulk a sa bulle", "then": "**Garde ton ult** : les clones absorbent les coups, la bulle les bloque."}], "sections": [{"title": "Philosophie de jeu", "lead": "Patience, timing, exécution : choisis la bonne cible, entre au bon moment, repars avant la riposte.", "ability": "", "key": "", "kind": "tips", "items": ["Le cycle : **flanc, combo sur un héros fragile, dash vers ton équipe**, et on recommence.", "La visée compte moins que **l'approche** : une cible qui ne t'a pas vue ne bouge pas.", "Elle excelle contre les **tireurs installés** : c'est toi qui dois aller les chercher.", "N'engage pas **hors de ta portée efficace**, même si la cible est basse."], "diagram": "reset"}, {"title": "Arbalète", "lead": "Des rafales instantanées qui partent en triangle autour de ton viseur. Chaque projectile qui touche réduit le cooldown de toutes tes capacités.", "ability": "Psionic Crossbow", "key": "Clic G", "kind": "default", "items": ["Au-delà de la mi-distance, la dispersion rend le tir à la tête illusoire : **approche-toi**.", "En difficulté, tire **sur un tank** pour récupérer ton dash.", "Un coup de mêlée en fin de rechargement **raccourcit l'animation**."], "diagram": ""}, {"title": "Shurikens", "lead": "Cinq shurikens lancés en carré, puis rappelés vers toi. Ils te donnent un peu de vie bonus.", "ability": "Wing Shurikens", "key": "Clic D", "kind": "default", "items": ["Ils n'infligent pas de dégâts critiques : vise **le torse**.", "Au rappel, ils passent **par l'endroit que tu vises** avant de revenir.", "Enchaînement : **tir, shurikens, rappel, deux tirs**.", "Variante : tir, shurikens, **dash à travers la cible** (le dash rappelle les shurikens)."], "diagram": ""}, {"title": "Dash", "lead": "Deux charges. Le dash blesse les ennemis traversés.", "ability": "Psi-Blade Dash", "key": "", "kind": "default", "items": ["**Une charge pour entrer, une pour sortir.**", "Vise **le sol en biais** : le dash est plus court et tu termines face à ta cible.", "Tes tirs réduisent le cooldown de la charge déjà dépensée."], "diagram": ""}, {"title": "Invisibilité", "lead": "Quelques secondes d'invisibilité et de vitesse. Le début et la fin font du bruit.", "ability": "Psychic Stealth", "key": "", "kind": "default", "items": ["**Pour masquer ton flanc** : traverse la zone exposée invisible, l'adversaire ne sait pas d'où tu arriveras.", "**Pour engager** : trop tôt, tu réapparais avant d'être à portée ; trop tard, on t'a déjà vue.", "**Pour fuir** : toujours après avoir rompu la ligne de vue.", "Invisible, tu peux recharger et ramasser un pack de soin."], "diagram": "", "scene": {"title": "Arriver invisible, repartir au dash", "caption": "L'invisibilité se déclenche hors de vue et se termine à portée. Le second dash te ramène.", "steps": ["Tu contournes par le flanc, hors de vue.", "Invisibilité derrière le mur : tu réapparais à portée du tireur.", "Combo, puis dash vers ton équipe."], "els": [{"t": "cover", "at": [150, 34], "size": [70, 14], "label": "Mur"}, {"t": "pawn", "at": [96, 60], "team": "me", "ghost": true}, {"t": "path", "kind": "move", "team": "me", "pts": [[96, 60], [110, 14], [176, 16]], "n": 1}, {"t": "area", "at": [184, 4], "size": [78, 26], "label": "Invisible", "team": "me"}, {"t": "path", "kind": "move", "team": "me", "pts": [[190, 16], [240, 14], [262, 40]], "n": 2}, {"t": "pawn", "at": [284, 56], "team": "enemy", "hero": "hela", "ko": true}, {"t": "pawn", "at": [262, 48], "team": "me", "ghost": true}, {"t": "path", "kind": "move", "team": "me", "pts": [[262, 54], [210, 120], [130, 116]], "n": 3}, {"t": "pawn", "at": [124, 118], "team": "me"}, {"t": "pawn", "at": [214, 96], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [250, 140], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [294, 110], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [296, 150], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [96, 150], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [60, 110], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [40, 60], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [40, 146], "team": "ally", "role": "heal"}]}}, {"title": "Ultime", "lead": "Pendant quelques secondes, tu tranches les ennemis autour de toi, en commençant par ceux qui ont reçu le moins de coups.", "ability": "Dance of the Butterfly", "key": "Q", "kind": "default", "items": ["Vise **un ou deux ennemis isolés** : sur un groupe, les coups se répartissent et personne ne meurt.", "Les **clones de Loki** absorbent des coups, et un ennemi invisible n'est pas ciblé.", "**Force d'abord** les ults de soin et les cooldowns défensifs.", "Tu ne peux pas dasher immédiatement après : termine **près d'une sortie**."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Jouer **au centre**, comme un DPS de ligne.", "Activer l'invisibilité **trop tôt, ou sous les yeux de l'ennemi**.", "Dépenser **les deux dashes** pour entrer.", "Lancer l'ult **au milieu de cinq ennemis**.", "Dasher **à travers** la cible et perdre son angle de tir."], "diagram": ""}], "combos": [{"note": "Puis **dash vers ton équipe** et recommence.", "steps": [{"key": "Clic G", "label": "tir"}, {"key": "Clic D", "label": "shurikens"}, {"key": "", "label": "Rappel"}, {"key": "Clic G", "label": "tir"}, {"key": "Clic G", "label": "tir"}], "title": "Éliminer un fragile"}], "counters": [{"hero": "peni-parker", "note": "Sa toile te révèle et te ralentit ; ses mines gardent ta cible."}, {"hero": "namor", "note": "Ses tourelles te verrouillent même invisible."}, {"hero": "hulk", "note": "Sa bulle bloque ton ult sur tout son groupe."}, {"hero": "star-lord", "note": "Il te suit en l'air et gagne le duel à mi-distance."}, {"hero": "rocket-raccoon", "note": "Ses kits d'armure font survivre ta cible à ton combo."}, {"hero": "loki", "note": "Ses clones absorbent ton ult."}], "synergies": [{"hero": "captain-america", "note": "Il entre par un côté et attire les cooldowns ; tu arrives par l'autre."}, {"hero": "venom", "note": "Deux menaces simultanées dans la backline."}, {"hero": "emma-frost", "note": "Elle tient le front seule pendant tes flancs."}, {"hero": "jeff-the-land-shark", "note": "Il occupe et entame les supports que tu viens finir."}, {"hero": "luna-snow", "note": "Ses soins te suivent loin sur le flanc."}], "sources": [{"url": "https://www.youtube.com/watch?v=Vsua14VUmGg", "title": "Psylocke Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Light & Dark Darts", "partners": ["cloak-and-dagger"], "key": "", "text": "Fléchettes de lumière et domaine d'ombre. **Amélioré :** Domaine plus grand, fléchettes relancées."}, {"name": "Mental Projection", "partners": ["emma-frost"], "key": "", "text": "Une illusion dashe et imite les frappes. **Amélioré :** Permet d'échanger de place avec l'illusion."}, {"name": "Psionic Fox", "partners": ["white-fox"], "key": "", "text": "La forme de renard ne coûte plus d'énergie. **Amélioré :** Cooldown fortement réduit."}, {"name": "Senbonzakura Strike", "partners": ["hawkeye"], "key": "", "text": "Hawkeye stocke des flèches psioniques (33 dégâts en 10.5) et les tire ensemble. **Amélioré :** Encochage plus rapide et explosions."}], "changes": [{"season": "Saison 10", "text": "Wing Shurikens plus rapides (120 → 150 m/s), 10 dégâts par shuriken au lieu de 9."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'psylocke' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Rocket Raccoon est un Strategist de soins de zone. Ses orbes rebondissent sur le décor et soignent tout ce qu'ils frôlent, sa balise ressuscite un allié tombé, et son ult donne à toute l'équipe un bonus de dégâts qui retourne un fight. Sa survie tient entièrement à sa mobilité.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["**Reste en vie et charge ton ult** : tout le reste passe après.", "Pose la **balise à l'abri**, et déplace-la dès qu'un diver s'en approche.", "Pose l'ult **derrière un coin** : l'ennemi doit s'exposer pour la détruire."], "difficulty": 1, "tags": ["Soins de zone", "Résurrection", "Mobilité", "Bonus de dégâts"], "strengths": ["Soins de zone par rebonds", "Résurrection d'un allié", "Très difficile à attraper"], "weaknesses": ["Aucun soin d'urgence sur une seule cible", "Balise et ult destructibles", "Auto-soin réduit en saison 11"], "playbook": [{"when": "Ton équipe est groupée dans un couloir", "then": "**Orbes au sol ou contre un mur**, à ses pieds : ils rebondissent et restent sur place."}, {"when": "Un diver te prend pour cible (Iron Fist, Spider-Man, Venom)", "then": "**Dash vers ton équipe**, pas à l'opposé : c'est elle qui le tuera. Chaque dash te donne 25 de vie bonus depuis la saison 11."}, {"when": "Un sniper te vise (Hela, Hawkeye, Black Widow)", "then": "**Dash derrière un couvert**, puis avance de couvert en couvert."}, {"when": "Un flanker approche de ta balise", "then": "**Récupère-la et repose-la ailleurs** : intacte, elle revient vite ; détruite, très lentement."}, {"when": "L'adversaire pousse en pensant avoir gagné le fight", "then": "**Ult derrière un coin** : ton équipe frappe plus fort au moment où il s'avance."}, {"when": "Deux Rocket posent leur ult en même temps", "then": "**Détruis la sienne** au laser avant de soigner."}], "sections": [{"title": "Philosophie de jeu", "lead": "Comme tous les Strategists, Rocket gagne en ayant son ult avant l'adversaire, et en étant vivant pour la poser.", "ability": "", "key": "", "kind": "tips", "items": ["**Avant le fight**, tire au laser pour charger ton ult.", "**Pendant le fight**, soins et survie d'abord.", "Tes dashes ne doivent pas rester inutilisés, mais ils doivent être disponibles **quand les divers arrivent**."], "diagram": "heal"}, {"title": "Orbes de soin", "lead": "Des orbes qui soignent les alliés qu'ils frôlent et ceux qu'ils touchent. Ils rebondissent sur les murs et ralentissent près des alliés.", "ability": "", "key": "Clic D", "kind": "default", "items": ["**Fais-les rebondir** sur le sol et les murs pour toucher plusieurs alliés.", "Vise **les pieds**.", "Ne vide pas ton chargeur juste avant que ton équipe engage.", "Leur soin au passage a légèrement baissé en saison 11 : multiplie les rebonds."], "diagram": ""}, {"title": "Tir laser", "lead": "Une rafale rapide, puissante de près. Depuis la saison 11, elle garde ses dégâts jusqu'à 15 mètres au lieu de 10.", "ability": "", "key": "Clic G", "kind": "default", "items": ["Sers-t'en pour **détruire les objets adverses** : tourelles de Namor, ankhs, amplificateur d'un autre Rocket.", "Pendant une **ult de soin alliée**, tu peux passer aux dégâts.", "En plein fight sans ult active, soigne."], "diagram": ""}, {"title": "Balise de résurrection", "lead": "Une balise qui distribue des kits d'armure et de super-saut, et ressuscite un allié tombé à portée.", "ability": "Battle Rebirth Beacon", "key": "", "kind": "default", "items": ["Place-la **à l'abri, mais à portée du fight**.", "Pose-la **avant** que tes alliés soient en danger : un pas en arrière, la balise, et tu reprends les soins.", "Contre Captain America ou Iron Fist, surveille-la et **déplace-la** avant qu'ils la trouvent.", "Les kits d'armure cassent les seuils de kill des tireurs : rappelle à tes alliés de les prendre."], "diagram": ""}, {"title": "Jetpack et murs", "lead": "Deux charges de dash, la course sur les murs et un vol plané.", "ability": "Jetpack Dash · Wild Crawl", "key": "Maj", "kind": "default", "items": ["Contre un **brawler** (The Thing, Emma Frost), dash à l'opposé : il doit te poursuivre.", "Accroche-toi à un mur, puis **dash vers le haut** : tu sors du champ de vision adverse.", "Ne dépense pas un dash pour une Hela qui ne fait que te menacer : passe d'un couvert à l'autre."], "diagram": ""}, {"title": "Ultime", "lead": "Un amplificateur posé au sol qui donne un bonus de dégâts et de la vie bonus à tous les alliés qu'il voit. Il peut être détruit.", "ability": "C.Y.A.", "key": "Q", "kind": "default", "items": ["Le bonus dépend de la **ligne de vue** : derrière un coin, oui ; derrière un mur plein, non.", "Posée trop tôt, l'adversaire recule et attend. C'est une ult de **retournement**.", "Pour répondre à une grosse ult de dégâts, ton autre support est souvent mieux placé.", "L'onde de choc de Phoenix la détruit instantanément."], "diagram": "", "scene": {"title": "L'amplificateur derrière un coin", "caption": "L'amplificateur doit voir tes alliés sans être vu des ennemis. Un coin de mur fait exactement cela.", "steps": ["L'adversaire avance, sûr de gagner le fight.", "Tu poses l'ult derrière le coin : tes alliés en vue sont boostés.", "Pour la détruire, un ennemi doit s'avancer à découvert."], "els": [{"t": "cover", "at": [124, 24], "size": [16, 62], "label": "Mur"}, {"t": "mark", "at": [108, 66], "kind": "turret", "team": "me", "label": "Ult"}, {"t": "note", "at": [108, 40], "text": "2", "team": "me"}, {"t": "pawn", "at": [70, 60], "team": "me"}, {"t": "path", "kind": "sight", "team": "me", "pts": [[108, 66], [150, 110]]}, {"t": "path", "kind": "sight", "team": "me", "pts": [[108, 66], [110, 140]]}, {"t": "path", "kind": "sight", "team": "me", "pts": [[108, 66], [168, 150]]}, {"t": "pawn", "at": [150, 110], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [110, 140], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [168, 150], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [60, 120], "team": "ally", "role": "heal"}, {"t": "path", "kind": "move", "team": "enemy", "pts": [[250, 110], [200, 110]], "n": 1}, {"t": "pawn", "at": [256, 110], "team": "enemy", "role": "tank"}, {"t": "path", "kind": "move", "team": "enemy", "pts": [[250, 50], [190, 30], [150, 14]], "n": 3}, {"t": "pawn", "at": [254, 52], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [292, 90], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [292, 132], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [250, 156], "team": "enemy", "role": "dps"}]}}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Dépenser **ses dashes** avant l'arrivée des divers.", "Laisser la balise **se faire détruire**.", "Poser l'ult **à découvert**, ou trop tôt.", "Tirer au laser **en plein fight**.", "Vider son chargeur **juste avant l'engage**."], "diagram": ""}], "combos": [], "counters": [{"hero": "captain-america", "note": "Il te suit en sprint et finit par trouver ta balise."}, {"hero": "venom", "note": "Il plonge sur toi et t'oblige à dépenser tes deux dashes."}, {"hero": "iron-fist", "note": "Une fois au contact, tu ne lui échappes pas sans aide."}, {"hero": "hela", "note": "Elle te force à dasher de loin, avant même le fight."}, {"hero": "phoenix", "note": "Son ult détruit ton amplificateur."}], "synergies": [{"hero": "magneto", "note": "Une équipe groupée derrière lui : chaque orbe soigne tout le monde."}, {"hero": "groot", "note": "Ses murs font rebondir tes orbes, et votre team-up ajoute des spores de soin."}, {"hero": "the-punisher", "note": "Ton ult et votre team-up décuplent son tir continu."}, {"hero": "peni-parker", "note": "Son nid distribue tes kits d'armure."}, {"hero": "luna-snow", "note": "Elle apporte le soin d'urgence sur une cible, que tu n'as pas."}], "sources": [{"url": "https://www.youtube.com/watch?v=CGw4ZlAMAF4", "title": "Rocket Raccoon Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Ammo Overload", "partners": ["the-punisher"], "key": "", "text": "Rocket pose un appareil qui accélère la cadence des alliés. **Amélioré :** Munitions infinies en plus."}, {"name": "Fantastic Amplifier", "partners": ["mister-fantastic"], "key": "", "text": "Un amplificateur augmente l'élasticité et le gonflement. **Amélioré :** Les coups projettent les ennemis."}, {"name": "Mammalian Bond", "partners": ["squirrel-girl"], "key": "", "text": "Glands de vitalité qui soignent et réduisent les cooldowns. **Amélioré :** Plus de charges."}, {"name": "Planet X Pals", "partners": ["groot"], "key": "", "text": "Spores épineuses qui blessent et soignent. **Amélioré :** Rocket peut monter sur Groot."}, {"name": "Rocket Network", "partners": ["peni-parker"], "key": "", "text": "Le nid d'araignées largue des drones et des kits d'armure. **Amélioré :** Régénération et plus d'unités."}], "changes": [{"season": "Saison 11", "text": "Repair Mode : soin au passage 55 → 50, auto-soin continu 30 → 20/s."}, {"season": "Saison 11", "text": "Tir principal : la baisse de dégâts commence à 15 m (au lieu de 10) et se termine à 30 m (au lieu de 20)."}, {"season": "Saison 11", "text": "Jetpack Dash : 25 de vie bonus à chaque utilisation."}, {"season": "Saison 10", "text": "Tous les Strategists : l'ult se charge un peu moins vite (65 % du soin et 50 % des dégâts convertis en énergie, au lieu de 70 % et 55 %)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'rocket-raccoon' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Rogue est un Vanguard exigeant, bâti sur les enchaînements. Elle pare les dégâts, projette et regroupe les ennemis, absorbe l'énergie et parfois une capacité de sa cible, et son ult vide la jauge d'ultime des adversaires proches.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["**Approche à couvert** : tu dois arriver au contact avec toute ta vie.", "Le coup de pied doit **toucher d'abord** : c'est lui qui garantit l'absorption.", "Ton ult se lance **en premier**, avant celles de l'adversaire."], "difficulty": 3, "tags": ["Combos", "Absorption", "Contrôle", "Anti-ult"], "strengths": ["Ult qui retire leurs ults aux ennemis", "Vole une capacité adverse", "Regroupe et projette les ennemis"], "weaknesses": ["Absorption très coûteuse si elle rate", "Dépend de ses cooldowns pour s'engager", "Vulnérable aux contrôles pendant l'incantation de l'ult"], "playbook": [{"when": "Tu arrives au contact d'une cible", "then": "**Coup de pied** (elle décolle), **tir de pied**, puis **absorption** : elle ne peut pas l'esquiver."}, {"when": "Un support adverse a son ult prête", "then": "**Ult et dive sur lui** : sa jauge se vide avant qu'il appuie."}, {"when": "Une ult alliée de zone part (Moon Knight, Namor)", "then": "**Attraction** : tu ramènes les ennemis dedans."}, {"when": "Le météore de Magneto ou le canon d'Iron Man arrive", "then": "**Garde**, pleine de vie. Pour protéger un allié d'Iron Man, va intercepter le projectile."}, {"when": "Tu as absorbé une Luna ou une Invisible Woman", "then": "Tu as sa **boule de neige** ou sa **poussée** : garde-la pour l'ult de Doctor Strange."}, {"when": "Tes cooldowns sont dépensés", "then": "**Recule derrière un mur.** Sans coup de pied ni garde chargée, tu n'es qu'une cible."}], "sections": [{"title": "Philosophie de jeu", "lead": "Rogue demande de l'initiative. Ton plan dépend du rapport de force entre les deux lignes de front.", "ability": "", "key": "", "kind": "tips", "items": ["Avec un **front plus fort**, avance au centre et écrase.", "Avec un **front plus faible**, verrouille un couloir latéral : tu offres des angles à tes DPS.", "Sans cooldowns, **ne t'engage pas**.", "Ne pare pas tout : les dégâts que tes supports soignent chargent leurs ults."], "diagram": "brawl"}, {"title": "Garde et ruée", "lead": "Une garde frontale qui réduit fortement les dégâts reçus. Pendant la garde, tu charges une ruée qui libère une onde d'énergie.", "ability": "Southern Brawl", "key": "Clic D · Clic G", "kind": "default", "items": ["Plus tu as paré de dégâts, **plus la ruée frappe fort**.", "L'onde part **après** la ruée : tu peux reculer, te retourner et toucher quand même.", "Depuis la saison 11, la garde absorbe dans un rayon plus étroit (1,2 m) mais convertit mieux les dégâts en énergie : **place-toi sur la trajectoire**, pas à côté.", "Tes deux premiers coups de poing frappent plus fort en saison 11."], "diagram": ""}, {"title": "Coup de pied", "lead": "Une charge suivie d'un coup de pied qui projette en l'air. Tu peux ensuite rester en vol un instant, lancer deux tirs de pied à distance, puis t'écraser au sol.", "ability": "Kinetic Kick", "key": "E", "kind": "default", "items": ["Un **tir de pied juste après la projection** touche à coup sûr.", "Au front, il **écarte un tank** et ouvre le fight. Sur un angle, il **renvoie une cible vers ton équipe**.", "En dive, il isole un support ou celui qui le protège.", "Contre Groot, reste en l'air : ses murs ne t'arrêtent pas.", "Enchaînement complet : **deux coups de poing, coup de pied, tir de pied, impact au sol, tir de pied**."], "diagram": ""}, {"title": "Attraction", "lead": "Une charge, puis une zone qui attire vers toi tous les ennemis proches, au moment où tu le décides.", "ability": "Fatal Attraction", "key": "", "kind": "default", "items": ["Elle **interrompt les déplacements** (dash de Black Panther, charge de Winter Soldier), si tu la déclenches à temps.", "Elle **ramène les ennemis** dans une ult alliée.", "Regroupement : **dash, attraction, coup de pied** pour renvoyer une cible au milieu de son équipe."], "diagram": ""}, {"title": "Absorption", "lead": "Tu fonces sur une cible et tu absorbes son énergie : un bonus selon son rôle, et souvent l'une de ses capacités.", "ability": "Ability Absorption", "key": "", "kind": "default", "items": ["La rater coûte très cher : **prépare-la toujours avec le coup de pied**.", "**Vanguard** : vie maximale. **Duelist** : gros bonus de dégâts. **Strategist** : régénération.", "Une icône au-dessus de la tête de la cible indique qu'elle te donnera **une capacité**.", "Pendant l'absorption, la cible est à terre : son **bouclier disparaît** un instant."], "diagram": "", "scene": {"title": "Le coup de pied garantit l'absorption", "caption": "Une cible projetée en l'air ne peut ni fuir ni se défendre. C'est le seul moment où l'absorption ne se rate pas.", "steps": ["Tu approches derrière le mur, vie pleine.", "Coup de pied : la cible décolle.", "Absorption sur la cible en l'air : bonus et capacité volée."], "els": [{"t": "cover", "at": [140, 50], "size": [16, 76], "label": "Mur"}, {"t": "pawn", "at": [104, 96], "team": "me", "ghost": true}, {"t": "path", "kind": "move", "team": "me", "pts": [[104, 96], [140, 20], [190, 64]], "n": 1}, {"t": "pawn", "at": [194, 72], "team": "me"}, {"t": "pawn", "at": [228, 78], "team": "enemy", "role": "dps", "ghost": true}, {"t": "path", "kind": "push", "team": "me", "pts": [[232, 76], [264, 52]], "n": 2}, {"t": "pawn", "at": [270, 48], "team": "enemy", "role": "dps", "label": "En l'air", "above": true}, {"t": "note", "at": [296, 64], "text": "3", "team": "me"}, {"t": "note", "at": [272, 82], "text": "absorption", "team": "me"}, {"t": "pawn", "at": [226, 150], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [298, 116], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [292, 156], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [216, 24], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [84, 56], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [84, 140], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [40, 80], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [40, 124], "team": "ally", "role": "heal"}]}}, {"title": "Ultime", "lead": "Une aura qui vide la jauge d'ultime des ennemis proches et te donne des bonus selon leurs rôles.", "ability": "Heartbreaker", "key": "Q", "kind": "default", "items": ["**Prends l'initiative** : lance-la et va sur le support qui allait utiliser la sienne.", "Sans ult de support adverse prête, vise le **Star-Lord ou le Punisher**.", "Lancée **après deux ults adverses**, elle ne retire plus rien.", "Tu peux être étourdie pendant l'incantation : lance-la **à couvert**, surtout face à une Emma Frost.", "Elle te rend aussi très difficile à déloger d'un point."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Tenter l'absorption **sans coup de pied**.", "Parer **tous** les dégâts.", "S'engager **sans cooldowns**.", "Lancer l'ult **trop tard**.", "Incanter l'ult **à découvert**."], "diagram": ""}], "combos": [{"note": "Envoie une cible au milieu de son équipe.", "steps": [{"key": "", "label": "Dash"}, {"key": "", "label": "Zone d'attraction"}, {"key": "E", "label": "coup de pied"}], "title": "Regroupement"}], "counters": [{"hero": "the-thing", "note": "Son impact au sol t'immobilise en plein enchaînement."}, {"hero": "hela", "note": "Elle t'entame avant que tu sois au contact, si tu approches à découvert."}, {"hero": "winter-soldier", "note": "Son crochet interrompt ta charge."}, {"hero": "wolverine", "note": "Ses dégâts en pourcentage ignorent ta vie bonus."}, {"hero": "invisible-woman", "note": "Sa poussée te renvoie en plein combo."}, {"hero": "emma-frost", "note": "Son étranglement interrompt l'incantation de ton ult."}], "synergies": [{"hero": "gambit", "note": "Son ult te fait traverser l'équipe adverse, et votre team-up revient en 15 secondes en saison 11."}, {"hero": "magneto", "note": "Sa bulle couvre ton approche."}, {"hero": "moon-knight", "note": "Tu attires les ennemis sous ses mains."}, {"hero": "phoenix", "note": "Tu regroupes, elle fait exploser."}, {"hero": "nightcrawler", "note": "Nouveau team-up de la saison 11 : après sa frappe, tu projettes les ennemis vers lui."}], "sources": [{"url": "https://www.youtube.com/watch?v=LGAj_h43m5A", "title": "Rogue Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Explosive Entanglement", "partners": ["magneto"], "key": "", "text": "Un champ magnétique renforce la posture défensive de Rogue. **Amélioré :** Ajoute un recul et des dégâts aux murs."}, {"name": "Mr. & Mrs. X", "partners": ["gambit"], "key": "", "text": "Explosions cinétiques sur les attaques (cooldown 15 s en saison 11, explosions et soins un peu réduits). **Amélioré :** Verrouille Hearts as One."}, {"name": "Protective Siblings", "partners": ["nightcrawler"], "key": "", "text": "Nightcrawler disparaît, blesse les ennemis et soigne les alliés, puis retombe en frappant avec ses trois épées (ralentissement). **Amélioré :** Rogue rappelle son énergie après l'impact : soin, dégâts et ennemis projetés vers Nightcrawler."}, {"name": "Telekinetic Beatdown", "partners": ["phoenix"], "key": "", "text": "Coups télékinétiques qui sautent d'une cible à l'autre. **Amélioré :** Étincelles et frappes en plus."}], "changes": [{"season": "Saison 11", "text": "Power Surge Punch : 35 → 40 de dégâts sur les deux premiers coups."}, {"season": "Saison 11", "text": "Defensive Stance : rayon d'absorption 2 → 1,2 m ; conversion des dégâts en énergie 0,55 → 0,6."}, {"season": "Saison 11", "text": "Team-up avec Gambit (Mr. & Mrs. X) : cooldown 30 → 15 s, explosion cinétique 5 + 1 % → 3 + 1 % de la vie max, soin des alliés 15 → 10."}, {"season": "Saison 11", "text": "Nouveau team-up avec Nightcrawler : Protective Siblings."}, {"season": "Saison 10", "text": "Bouclier régénérant 250 → 275, absorption de Vanguard 125 → 150, énergie 15/s → 25/s."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'rogue' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Scarlet Witch est une Duelist de pression à mi-distance. Depuis sa refonte de la saison 10, elle marque d'abord ses ennemis, puis son rayon les frappe tous en même temps et lui rend de la vie bonus. Elle use les héros fragiles, défend bien sa backline, et son ult oblige l'adversaire à reculer.", "patch_note": "Scarlet Witch a été retravaillée en saison 10 : ce guide décrit le nouveau kit (marques du chaos, Scarlet Hex). Le plan de jeu vient d'une vidéo antérieure à la refonte ; les touches de certaines capacités sont à vérifier en jeu.", "tldr": ["**Marque d'abord, tire ensuite** : ton rayon touche tous les ennemis marqués à la fois.", "Cherche les **2 contre 1** depuis un angle : soignée, tu gagnes presque tous tes duels.", "Ton ult n'a pas besoin de tuer : elle **impose le tempo**."], "difficulty": 1, "tags": ["Marques", "Pression", "Anti-dive", "Accessible"], "strengths": ["Rayon multi-cibles sur ennemis marqués", "Vie bonus à chaque dégât sur une marque", "Zone d'étourdissement et de ralentissement"], "weaknesses": ["Inoffensive sans marques", "Portée courte (20 m)", "Très exposée pendant l'incantation de l'ult"], "playbook": [{"when": "Plusieurs ennemis sont alignés dans un couloir ou sur le point", "then": "**Scarlet Hex** en enfilade : chacun est marqué. Puis **Chaos Control** : le rayon les touche tous."}, {"when": "Un diver saute sur ta backline", "then": "**Dark Seal** sur tes supports : il est étourdi, ralenti et marqué. Rayon dessus."}, {"when": "Un ennemi canalise ou se regroupe dans une zone étroite", "then": "Dark Seal, puis Scarlet Hex, puis rayon, puis projectiles : tout ce qui reste dans le sceau garde sa marque."}, {"when": "On te prend pour cible", "then": "**Mystic Projection** : intangible, tu rejoins un pack de soin ou ton équipe. Ne la dépense pas avant."}, {"when": "L'adversaire lance une ult offensive et avance", "then": "**Reality Erasure** depuis un couvert : il doit reculer ou mourir, et l'incantation fait désormais des dégâts continus."}, {"when": "Ta vie bonus est au maximum", "then": "Inutile d'insister sur la même cible : **change de position** ou marque un autre groupe."}], "sections": [{"title": "Philosophie de jeu", "lead": "Tu ne gagneras pas tous tes duels, mais tu forces des cooldowns à chaque passage : bulle de Cloak, poussée d'Invisible Woman, boule de neige de Luna, runes de Loki.", "ability": "", "key": "", "kind": "tips", "items": ["Prends une **hauteur qui donne sur les deux côtés** du fight : tu marques au centre et tu défends ta backline.", "Joue **en duo** avec un autre DPS sur son angle : à deux, vous êtes très difficiles à déloger.", "Ton cycle : **marquer, tirer, encaisser grâce à la vie bonus, te replacer**.", "Reste près des **chokes et des objectifs** : c'est là que les ennemis sont assez groupés pour être marqués ensemble."], "diagram": "angle"}, {"title": "Marque du chaos", "lead": "Toute la refonte tient à cette mécanique : les dégâts que tu infliges à un ennemi marqué te rendent un quart de leur valeur en vie bonus.", "ability": "Scarlet Hex · passif", "key": "", "kind": "default", "items": ["Deux capacités posent la marque : **Scarlet Hex** (une onde en rectangle, longue et étroite) et **Dark Seal** (tant que l'ennemi reste dans le sceau).", "**Chaos Control** frappe tous les ennemis marqués dans un large cône devant toi, chacun pour les mêmes dégâts.", "Vise **deux ou trois marques** avant de t'engager sur le rayon : plus de dégâts, plus de vie bonus.", "La vie bonus est plafonnée : elle te fait gagner un duel, pas tenir un front."], "diagram": "", "scene": {"title": "Marquer, puis tirer", "caption": "Sans marque, ton rayon ne touche personne. Avec trois marques, il touche trois cibles et te rend de la vie bonus sur chacune.", "steps": ["Scarlet Hex en enfilade : chaque ennemi touché est marqué.", "Chaos Control : le rayon frappe tous les marqués à la fois.", "Chaque dégât te rend de la vie bonus."], "els": [{"t": "area", "at": [120, 70], "size": [172, 44], "label": "Scarlet Hex", "team": "me"}, {"t": "note", "at": [104, 62], "text": "1", "team": "me"}, {"t": "pawn", "at": [92, 92], "team": "me"}, {"t": "pawn", "at": [200, 84], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [244, 100], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [280, 86], "team": "enemy", "role": "heal"}, {"t": "path", "kind": "shot", "team": "me", "pts": [[92, 92], [200, 84]], "n": 2}, {"t": "path", "kind": "shot", "team": "me", "pts": [[92, 92], [244, 100]], "n": 2}, {"t": "path", "kind": "shot", "team": "me", "pts": [[92, 92], [280, 86]], "n": 2}, {"t": "note", "at": [96, 128], "text": "+ vie bonus", "team": "me"}, {"t": "note", "at": [60, 126], "text": "3", "team": "me"}, {"t": "pawn", "at": [250, 150], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [290, 36], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [140, 140], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [100, 160], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [46, 60], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [40, 104], "team": "ally", "role": "heal"}]}}, {"title": "Dégâts", "lead": "Chaos Control est ton rayon ; Chthonian Burst, tes projectiles explosifs. Depuis la refonte, le rayon dépend des marques.", "ability": "Chaos Control · Chthonian Burst", "key": "Clic G · Clic D", "kind": "tips", "items": ["**Rayon** : il ne sert que sur des ennemis marqués. Sans marque, passe aux projectiles.", "**Projectiles** : plus rapides depuis la saison 10, ils finissent une cible marquée qui recule.", "Enchaînement de base : **Scarlet Hex, rayon**. Version burst : **Scarlet Hex, projectiles, rayon**.", "Garde toujours une capacité en rechargement : tes dégâts bruts sont modestes, c'est le cycle qui compte."], "diagram": ""}, {"title": "Contrôle", "lead": "Dark Seal crée une zone : un bref étourdissement à la détonation, puis un ralentissement, des dégâts continus et une marque sur tout ennemi qui y reste.", "ability": "Dark Seal", "key": "", "kind": "tips", "items": ["Pose-le **sur tes supports** contre le dive : le diver est étourdi à l'arrivée et marqué tant qu'il insiste.", "L'étourdissement est très court depuis la refonte : il **interrompt**, il n'immobilise plus.", "Dans un couloir ou sur un point, il **interdit le passage** et marque tout ce qui le traverse.", "Pose-le sur le support qui soigne ta cible : il doit bouger ou encaisser."], "diagram": ""}, {"title": "Mobilité", "lead": "Mystic Projection te rend intangible et plus rapide pendant quelques secondes. Tu peux ramasser des packs de soin et recevoir des soins pendant ce temps.", "ability": "Mystic Projection", "key": "Maj", "kind": "tips", "items": ["Son bonus de vitesse a été réduit avec la refonte : c'est une **sortie**, pas un moyen de transport.", "Ne la dépense pas pour monter sur ta position avant le fight : **marche**.", "Joue **près des packs de soin** : tu frappes, tu te soignes, tu reviens."], "diagram": ""}, {"title": "Ultime", "lead": "Une incantation de quelques secondes, puis une énorme explosion autour de toi. Pendant l'incantation, les ennemis proches subissent désormais des dégâts croissants.", "ability": "Reality Erasure", "key": "Q", "kind": "default", "items": ["Elle sert à **faire reculer** : si l'adversaire quitte la zone, tu as gagné l'espace.", "Incante **derrière un mur** et ne sors qu'au dernier moment.", "Contre une ult offensive adverse, la tienne **bloque leur avancée**.", "Force d'abord la **bulle de Magneto**, et méfie-toi d'une **Emma Frost** en diamant qui peut t'étrangler.", "Ne monte pas trop haut : l'explosion couvre moins de terrain au sol."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Tirer au rayon **sans avoir marqué**.", "Rester **au centre** sur les tanks.", "Dépenser Mystic Projection **avant le fight**.", "Incanter l'ult **à découvert**.", "**Garder l'ult** plusieurs fights."], "diagram": ""}], "combos": [], "counters": [{"hero": "magneto", "note": "Sa bulle protège la cible marquée et absorbe ton ult."}, {"hero": "emma-frost", "note": "Elle t'étrangle pendant l'incantation de ton ult."}, {"hero": "hela", "note": "Elle te tue hors de ta portée de 20 mètres."}, {"hero": "star-lord", "note": "Plus mobile que toi, il gagne le duel à mi-distance."}, {"hero": "black-widow", "note": "Un tir à la tête pendant ton incantation et l'ult est perdue."}], "synergies": [{"hero": "venom", "note": "Les supports qu'il attaque se regroupent : une seule onde les marque tous."}, {"hero": "captain-america", "note": "Tu suis son dive à mi-distance et tu tires sur ce qu'il harcèle."}, {"hero": "phoenix", "note": "Deux Duelists de zone sur le même angle."}, {"hero": "hawkeye", "note": "Ton sceau garde son angle contre les divers."}, {"hero": "rocket-raccoon", "note": "La vie bonus de son ult te fait survivre à ton incantation."}], "sources": [{"url": "https://www.youtube.com/watch?v=cPujUz0S7nQ", "title": "Scarlet Witch Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Chaos Collision", "partners": ["the-hood"], "key": "", "text": "Zone arcanique et téléportation. **Amélioré :** Ajoute une onde de choc."}, {"name": "Hex Fireworks", "partners": ["jubilee"], "key": "", "text": "Détonation de sceau plasmoïde. **Amélioré :** Ajoute un soin continu."}, {"name": "Metallic Chaos", "partners": ["magneto"], "key": "", "text": "Coup d'épée du chaos (cooldown 18 s depuis la saison 10). **Amélioré :** Le Mag-Cannon devient des épées chargées."}, {"name": "Sorcerers Supreme", "partners": ["doctor-strange"], "key": "", "text": "Salve de missiles mystiques. **Amélioré :** Devient activable à volonté."}], "changes": [{"season": "Saison 10", "text": "Refonte : nouveau Scarlet Hex (40 de dégâts, pose une marque du chaos), Chaos Control 85/s → 75/s, vitesse de Mystic Projection +35 % au lieu de +50 %."}, {"season": "Saison 10.5", "text": "Chthonian Burst 40 → 35 de dégâts de zone."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'scarlet-witch' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Spider-Man est l'assassin le plus mobile du jeu. Il tourne autour du fight, pose un traceur sur un support isolé, plonge, tue et ressort avant la riposte. Il n'a aucun cooldown défensif : sa survie tient à son mouvement et au choix de ses engages.", "patch_note": "Plan de jeu issu de guides enregistrés entre les saisons 0 et 2. Les principes restent valables, mais certains enchaînements ont changé (Amazing Combo revient en une seconde depuis la saison 10) : travaille-les au champ de tir avant de les tenter en partie.", "tldr": ["**Aucun cooldown défensif** : entre vite, tue, ressors. Dans le doute, un passage rapide et tu repars.", "Le **traceur** (clic droit) est la base de tout : il ouvre les combos et te permet de te tirer vers la cible.", "Vise les **supports et les volants**, presque jamais les tanks."], "difficulty": 3, "tags": ["Dive", "Assassin", "Mobilité", "Mécanique"], "strengths": ["Mobilité sans équivalent", "Étourdissement à distance (Get Over Here)", "Tue un héros fragile en un enchaînement"], "weaknesses": ["Aucune défense : un contrôle, et il meurt", "Très exigeant mécaniquement", "Inutile contre une backline bien gardée"], "playbook": [{"when": "Un support est isolé", "then": "**Traceur, se tirer, uppercut, coup aérien.** Puis swing immédiat pour ressortir."}, {"when": "La backline a encore ses défenses (lien d'Adam, sommeil de Mantis, coup de pied de Widow)", "then": "**Passage rapide** : uppercut en passant, sans t'arrêter. Tu forces le cooldown, tu reviens après."}, {"when": "La backline est trop protégée pour un dive", "then": "**Pêche** : attire un ennemi isolé vers ton équipe au lieu d'aller le chercher."}, {"when": "Un ennemi canalise une ult (Scarlet Witch, Iron Man) ou ouvre un portail", "then": "**Get Over Here** sur une cible sans traceur : la traction l'étourdit."}, {"when": "Un support est dans son ult de zone", "then": "**Attire-le hors de sa zone** : ton équipe le tue dehors."}, {"when": "Tu entends un crochet se charger, ou tu vois un fusil à pompe", "then": "**Ne dive pas.** Winter Soldier et Punisher te tuent en un contrôle."}], "sections": [{"title": "Philosophie de jeu", "lead": "Spider-Man est un assassin de backline fragile. Immobile au milieu de l'équipe adverse, il est mort ; en mouvement, presque personne ne le touche.", "ability": "", "key": "", "kind": "tips", "items": ["Tourne autour du fight, choisis **une cible isolée**, pose un traceur, puis engage.", "Avant de t'engager vraiment, **fais dépenser les défenses adverses** avec un passage rapide.", "Après le kill, **ressors tout de suite** : une seconde de trop et tu es étourdi.", "Si la backline est imprenable, passe en mode **pêche** : ramène des ennemis isolés vers ton équipe."], "diagram": "dive"}, {"title": "Réglages à changer", "lead": "Trois réglages du héros conditionnent une bonne partie de ses techniques.", "ability": "", "key": "", "kind": "tips", "items": ["**Désactive le swing automatique** : tu choisis le point d'accroche, et viser sous la ligne d'horizon déclenche un zip (traction en ligne droite).", "**Maintenir pour grimper** : tu quittes le mur dès que tu relâches la touche.", "Place **« tirer la cible vers toi »** sur une touche séparée : tu peux attirer un ennemi même s'il porte ton traceur.", "Sur PC, le **saut sur la molette** accélère nettement l'escalade."], "diagram": ""}, {"title": "Traceurs et coups", "lead": "Le clic droit lance une toile qui pose un traceur : la prochaine capacité sur cette cible le fait exploser. Le clic gauche enchaîne deux coups de poing et un coup de pied.", "ability": "Web-Cluster · Spider-Power", "key": "Clic D · Clic G", "kind": "default", "items": ["Les toiles sont aussi ta **réserve de mouvement** : ne les vide pas avant d'engager.", "Tes coups de poing **s'annulent par n'importe quelle capacité** : glisse-en un entre deux.", "Après un double saut, le clic gauche devient un **coup aérien plongeant** : c'est la conclusion des combos actuels.", "Un seul traceur par cible."], "diagram": ""}, {"title": "Swing et web zip", "lead": "Viser au-dessus de l'horizon donne un long swing ; viser en dessous donne un zip, une traction rapide vers le point visé.", "ability": "Web-Swing", "key": "Maj", "kind": "default", "items": ["Annuler un zip par une toile **conserve ton élan** et supprime l'animation d'arrivée.", "Sauter au moment où tu touches le sol après un zip conserve ta vitesse : indispensable en intérieur.", "Un **zip aux pieds** d'un ennemi, suivi d'un uppercut, fait des dégâts sans dépenser Get Over Here.", "Garde **toujours un swing** pour repartir."], "diagram": ""}, {"title": "Attirer et se tirer", "lead": "Sur une cible sans traceur, tu l'attires vers toi. Sur une cible avec traceur, c'est toi qui te tires vers elle, et tu la frappes à l'arrivée.", "ability": "Get Over Here!", "key": "E", "kind": "default", "items": ["La traction est un **étourdissement** : elle interrompt une ult canalisée ou un portail.", "Tu n'as pas besoin de regarder la cible : **zippe vers une ligne de vue**, puis tire-toi vers elle.", "Au bord d'un vide, **attirer un tank sans mobilité** peut suffire à gagner le fight."], "diagram": "", "scene": {"title": "Traceur, plongeon, sortie", "caption": "Tout l'engage tient en trois secondes. La quatrième, tu dois déjà être reparti.", "steps": ["Depuis ton swing, traceur sur le support isolé.", "Tu te tires vers lui : uppercut, coup aérien.", "Swing immédiat pour ressortir."], "els": [{"t": "cover", "at": [150, 8], "size": [80, 14], "label": "Mur"}, {"t": "pawn", "at": [124, 50], "team": "me", "ghost": true}, {"t": "path", "kind": "sight", "team": "me", "pts": [[124, 50], [270, 76]], "n": 1}, {"t": "path", "kind": "move", "team": "me", "pts": [[124, 50], [200, 40], [258, 70]], "n": 2}, {"t": "pawn", "at": [274, 78], "team": "enemy", "role": "heal", "ko": true}, {"t": "pawn", "at": [256, 80], "team": "me", "ghost": true}, {"t": "path", "kind": "move", "team": "me", "pts": [[256, 86], [230, 170], [140, 140]], "n": 3}, {"t": "pawn", "at": [134, 138], "team": "me"}, {"t": "pawn", "at": [212, 104], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [250, 132], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [298, 124], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [296, 34], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [100, 92], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [66, 60], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [46, 100], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [60, 150], "team": "ally", "role": "heal"}]}}, {"title": "Uppercut", "lead": "Un uppercut à deux charges qui projette en l'air. C'est ton outil de combo principal ; son cooldown n'est plus que d'une seconde depuis la saison 10.", "ability": "Amazing Combo", "key": "F", "kind": "default", "items": ["Il **annule ton swing en gardant l'élan** : un uppercut en passant fait des dégâts sans t'arrêter.", "Il touche large : sur un groupe, il charge ton ult et force des cooldowns.", "La cible projetée suit une trajectoire prévisible : c'est le moment de l'attirer."], "diagram": ""}, {"title": "Combos", "lead": "La logique : traceur, approche, uppercut, puis un coup aérien ou une toile pour conclure. Plus la cible a de vie, plus la fin s'allonge.", "ability": "", "key": "", "kind": "tips", "items": ["**Héros fragile** : traceur, se tirer, uppercut, swing annulé en coup aérien.", "**Un peu plus de vie** : remplace la fin par un zip annulé par une toile, puis coup aérien.", "**Sans Get Over Here** : zip aux pieds, toile, uppercut, zip annulé, toile, coup aérien.", "**Pêche** : traceur, attirer la cible, coup, toile pour annuler, uppercut.", "Travaille chacun sur les bots du champ de tir avant de le tenter en classé."], "diagram": ""}, {"title": "Ultime", "lead": "Tu gagnes beaucoup de vie bonus et tu projettes des toiles tout autour de toi : elles blessent et immobilisent.", "ability": "Spectacular Spin", "key": "Q", "kind": "default", "items": ["Tu restes **sensible aux contrôles** : un crochet de Winter Soldier ou une toile de Peni l'interrompt.", "L'élan du swing est conservé : **arrive au plus près** avant de la lancer.", "Lance-la **après** les ults défensives adverses."], "diagram": ""}, {"title": "Les matchups clés", "lead": "Presque tout le roster a une réponse à Spider-Man. Savoir laquelle évite les engages perdus d'avance.", "ability": "", "key": "", "kind": "tips", "items": ["**Adam Warlock** : force son lien d'âmes, attends qu'il retombe, reviens.", "**Mantis** : son sommeil se pose facilement sur un héros de mêlée. Ressors dès l'uppercut.", "**Rocket** : cherche sa balise en tournant, et ne le poursuis pas s'il a ses dashes.", "**Black Widow** : son coup de pied frappe tout autour d'elle.", "**Winter Soldier, Namor, Punisher** : tes vrais contres. Écoute le crochet, attends la chute des tourelles, recule devant le fusil à pompe.", "Contre un autre Spider-Man, **la première toile qui touche** gagne le duel."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Garder le **swing automatique**.", "Engager **sans traceur**.", "Rester dans la backline **après le kill**.", "Plonger sur un support qui a encore **son contrôle**.", "Vider ses toiles et **ne plus pouvoir fuir**.", "Viser **les tanks**."], "diagram": ""}], "combos": [{"title": "Fragile", "steps": [{"key": "Clic D", "label": "traceur"}, {"key": "E", "label": "se tirer"}, {"key": "F", "label": "uppercut"}, {"key": "", "label": "Swing annulé"}, {"key": "Clic G", "label": "slam"}], "note": "Le swing doit s'accrocher à une surface pour donner l'slam aérien."}, {"title": "Fishing", "steps": [{"key": "Clic D", "label": "traceur"}, {"key": "", "label": "Attirer la cible"}, {"key": "Clic G", "label": "coup"}, {"key": "Clic D", "label": "annule le coup"}, {"key": "F", "label": "uppercut"}], "note": "Mets « attirer la cible » sur une touche à part pour pouvoir le faire même avec un traceur."}, {"title": "Drive-by", "steps": [{"key": "Clic D", "label": "traceur"}, {"key": "", "label": "Zip aux pieds"}, {"key": "F", "label": "uppercut en passant"}, {"key": "Clic D", "label": "toile"}, {"key": "E", "label": "se tirer"}, {"key": "Clic G", "label": "finir"}], "note": "Zippe à côté de la cible, pas devant elle, sinon tu restes bloqué contre elle."}], "counters": [{"hero": "winter-soldier", "note": "Son crochet interrompt tes combos et ton ult."}, {"hero": "namor", "note": "Ses tourelles te suivent et te ralentissent dès l'approche."}, {"hero": "the-punisher", "note": "Son fusil à pompe te tue en deux tirs au contact."}, {"hero": "black-widow", "note": "Son coup de pied t'étourdit, même de dos."}, {"hero": "adam-warlock", "note": "Son lien d'âmes absorbe ton burst."}, {"hero": "mantis", "note": "Son sommeil met fin à ton engage."}, {"hero": "peni-parker", "note": "Sa toile te ralentit et interrompt ton ult."}], "synergies": [{"hero": "venom", "note": "Le partenaire de dive idéal, avec un team-up qui repousse les ennemis."}, {"hero": "mantis", "note": "Son bonus de dégâts juste avant ton engage rend tes combos mortels."}, {"hero": "luna-snow", "note": "Sa marque te soigne même hors de sa vue."}, {"hero": "hulk", "note": "Il attire tous les regards pendant que tu frappes."}, {"hero": "black-cat", "note": "Votre team-up marque la cible et lui vole de la Fortune."}], "sources": [{"title": "Ultimate Spider-Man Guide (Beginner/Advanced)", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=Mwf3_k7gffw"}, {"title": "The Complete Advanced Spider-Man Tech Guide", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=9h5BoOXEgOE"}, {"title": "Season 2 Spider-Man Combos Guide", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=kHP_8vkpk3c"}, {"title": "37 Spider-Man Tips to Instantly Improve", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=AX2BsGJ_ZvU"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Binding Ties", "partners": ["black-cat"], "key": "", "text": "Un grappin de toile vole de la Fortune et marque la cible, qui prend plus de dégâts."}, {"name": "ESU Alumnus", "partners": ["squirrel-girl"], "key": "", "text": "Bombe de toile qui explose et laisse une zone de toile. **Amélioré :** La toile collante reste au sol."}, {"name": "Parker Power-Up", "partners": ["peni-parker"], "key": "", "text": "Bombe-araignée collante qui marque les ennemis (cooldown 10 s depuis la saison 10). **Amélioré :** Vie bonus à la détonation."}, {"name": "Symbiote Bond", "partners": ["venom"], "key": "", "text": "Pointes de symbiote qui repoussent les ennemis. **Amélioré :** Ajoute des tentacules qui relient."}], "changes": [{"season": "Saison 10", "text": "Amazing Combo : cooldown 2 s → 1 s."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'spider-man' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Squirrel Girl a un plan de jeu simple : elle arrose le passage principal de glands explosifs pour user les tanks et les héros fragiles, garde sa backline grâce à son gland étourdissant, et lance son ult dès qu'elle l'a. Depuis la saison 11, Mammal Bond lui donne aussi cinq secondes de tir rapide et tendu.", "patch_note": "Squirrel Girl a été largement retouchée en saison 11 : glands un peu moins forts, gland étourdissant rapide suivi d'une pluie de glands, et Mammal Bond transformé en accélération de tir. Les sections concernées décrivent le nouveau fonctionnement ; vérifie les détails en jeu.", "tldr": ["**Arrose le centre** : boucliers, tanks, puis tout ce qui dépasse.", "Garde ton **gland étourdissant** pour le diver ou l'ult qui arrive.", "Lance ton ult **dès qu'elle est prête**, en la faisant rebondir sur un mur."], "difficulty": 1, "tags": ["Spam", "Anti-dive", "Couloirs", "Charge d'ult"], "strengths": ["Dégâts de zone sans avoir à viser juste", "Immobilise et ralentit un diver", "Ult très rapide à charger"], "weaknesses": ["Inefficace contre les volants", "Dominée sur les longues lignes de vue", "Ses projectiles s'arrêtent sur un bouclier"], "playbook": [{"when": "Un tank tient son bouclier dans un couloir", "then": "Tire **vers le sol, en biais** : les glands rebondissent par-dessus le bouclier et explosent derrière."}, {"when": "Un diver saute sur tes supports", "then": "**Gland étourdissant** : il est immobilisé, puis ralenti par la pluie de glands. **Mammal Bond** et vide ton chargeur sur lui."}, {"when": "Une ult mobile arrive (Magik, Spider-Man, Scarlet Witch)", "then": "Gland étourdissant : il ne l'annule pas, mais il **l'immobilise** le temps que ton équipe réagisse."}, {"when": "Un diver tourne autour de toi sans entrer", "then": "**Garde le gland.** Il attend que tu le lances pour venir."}, {"when": "Ton ult est prête", "then": "**Lance-la contre un mur**, à mi-distance : elle rebondit vers l'ennemi et vit plus longtemps."}, {"when": "Venom ou Captain America te prend pour cible", "then": "**Saut à la queue** vers une hauteur : il te donne aussi un peu de vie bonus depuis la saison 11."}], "sections": [{"title": "Philosophie de jeu", "lead": "Reste simple : une pression constante sur le passage principal suffit à peser dans la plupart des parties. Vouloir en faire plus, c'est mourir souvent.", "ability": "", "key": "", "kind": "tips", "items": ["Elle est à son meilleur sur les cartes à **passages étroits**.", "Tu es la **gardienne de ta backline** : dès qu'un diver entre, il devient ta priorité.", "Vise d'abord **le tank à portée**, puis les héros fragiles déjà entamés."], "diagram": "choke"}, {"title": "Glands explosifs", "lead": "Des glands qui explosent au contact du sol ou d'un ennemi. Un tir direct fait plus mal ; l'explosion rattrape les tirs approximatifs.", "ability": "Burst Acorn", "key": "Clic G", "kind": "default", "items": ["Ils **retombent** : vise plus haut à longue distance.", "Ils **rebondissent sur les murs** et n'explosent qu'au sol : un tir en biais passe par-dessus un bouclier.", "Vise **la moitié basse** des cibles.", "Depuis la saison 11, le tir direct fait moins de dégâts mais l'explosion en conserve davantage sur les côtés : **le tir de zone est mieux récompensé** que le tir précis."], "diagram": ""}, {"title": "Gland étourdissant", "lead": "Un gros gland qui immobilise brièvement la cible touchée. Depuis la saison 11, il est beaucoup plus rapide et laisse à l'impact une pluie de glands qui blesse et ralentit pendant deux secondes.", "ability": "Squirrel Blockade", "key": "Clic D", "kind": "default", "items": ["L'immobilisation est plus courte qu'avant (0,8 seconde) : c'est **la pluie de glands** qui retient la cible ensuite.", "**Immobilise un tank** mal placé pour offrir une élimination à ton équipe.", "Il fait tomber les volants et bloque sur place une ult mobile.", "Les bons divers attendent que tu l'aies lancé : **ne le dépense pas en premier**.", "Un coup de mêlée annule la charge sans lancer le gland."], "diagram": "", "scene": {"title": "Le gland étourdissant sur un diver", "caption": "L'immobilisation est courte. C'est la pluie de glands et ton tir accéléré qui font le reste.", "steps": ["Le diver saute sur ton support.", "Gland étourdissant : immobilisé, puis ralenti dans la pluie de glands.", "Mammal Bond : tu vides ton chargeur sur lui."], "els": [{"t": "pawn", "at": [220, 28], "team": "enemy", "role": "dps", "ghost": true}, {"t": "path", "kind": "move", "team": "enemy", "pts": [[220, 28], [160, 30], [108, 98]], "n": 1}, {"t": "zone", "at": [102, 108], "r": 26, "team": "me", "label": "Pluie de glands", "n": 2}, {"t": "pawn", "at": [102, 108], "team": "enemy", "hero": "black-panther"}, {"t": "pawn", "at": [56, 118], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [172, 130], "team": "me"}, {"t": "path", "kind": "beam", "team": "me", "pts": [[172, 130], [116, 112]], "n": 3}, {"t": "pawn", "at": [46, 70], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [196, 84], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [150, 52], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [246, 100], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [280, 140], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [296, 66], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [298, 110], "team": "enemy", "role": "heal"}]}}, {"title": "Saut à la queue", "lead": "Un saut vertical, plus haut si tu sautes juste avant. Depuis la saison 11, il donne 25 points de vie bonus.", "ability": "Tail Bounce", "key": "", "kind": "default", "items": ["Face à des **tireurs**, ne saute pas devant eux : ta trajectoire est prévisible.", "Face au **dive**, garde-le toujours pour fuir.", "Face à un **brawl**, il te fait reculer et esquive l'ult de The Thing ou de Moon Knight.", "Sous un plafond incliné, il te propulse à l'horizontale."], "diagram": ""}, {"title": "Mammal Bond", "lead": "Depuis la saison 11 : pendant cinq secondes, tu tires deux fois plus vite, tes glands partent en ligne droite, bien plus rapides, et chacun fait un peu moins de dégâts.", "ability": "", "key": "", "kind": "default", "items": ["C'est ta **fenêtre de burst** : sur un diver immobilisé, un tank isolé ou un bouclier à briser.", "Les tirs deviennent **tendus** : pendant l'effet, vise directement la cible, plus au-dessus d'elle.", "Contre un volant, c'est le seul moment où tes glands le touchent de façon régulière.", "Ne le lance pas à vide : cinq secondes sans cible sont cinq secondes perdues."], "diagram": ""}, {"title": "Ultime", "lead": "Une horde d'écureuils qui fonce, rebondit sur chaque mur vers l'ennemi le plus proche et blesse à chaque passage. Elle peut être détruite.", "ability": "Unbeatable Squirrel Tsunami", "key": "Q", "kind": "default", "items": ["Elle se charge **très vite** : ne la garde jamais.", "Lancée **contre un mur**, elle survit bien plus longtemps qu'en ligne droite.", "Lance-la **à mi-distance** et ajoute un gland sur le héros fragile qu'elle a entamé.", "Forcer une ult de support avec elle est un bon échange : tu auras la suivante avant eux.", "Le payload compte comme un mur."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Sauter **face aux tireurs**.", "Dépenser le gland étourdissant **avant** l'entrée du diver.", "**Garder l'ult**.", "Partir sur un flanc au lieu de **tenir la backline**.", "Lancer l'ult **en ligne droite**."], "diagram": ""}], "combos": [], "counters": [{"hero": "magneto", "note": "Son rideau absorbe ton gland étourdissant et ton ult."}, {"hero": "iron-man", "note": "Hors d'atteinte de tes glands en cloche."}, {"hero": "ultron", "note": "Un autre volant que tu ne touches presque jamais."}, {"hero": "hela", "note": "Sur une longue ligne de vue, elle te tue avant que tes glands arrivent."}, {"hero": "hawkeye", "note": "Même rapport de portée, et un tir chargé suffit."}, {"hero": "black-widow", "note": "Avec un bonus de dégâts, elle te tue de loin."}], "synergies": [{"hero": "emma-frost", "note": "Un front solide derrière lequel arroser le centre."}, {"hero": "doctor-strange", "note": "Son bouclier te couvre pendant que tu tires."}, {"hero": "the-punisher", "note": "Deux sources de dégâts constants sur le même passage."}, {"hero": "hela", "note": "Elle s'occupe des volants et des tireurs."}, {"hero": "mantis", "note": "Son bonus de dégâts pendant ton Mammal Bond."}], "sources": [{"url": "https://www.youtube.com/watch?v=hfHY0afkEUg", "title": "Squirrel Girl Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "ESU Alumnus", "partners": ["spider-man"], "key": "", "text": "Bombe de toile qui explose et laisse une zone de toile. **Amélioré :** La toile collante reste au sol."}, {"name": "Mammalian Bond", "partners": ["rocket-raccoon"], "key": "", "text": "Glands de vitalité qui soignent et réduisent les cooldowns. **Amélioré :** Plus de charges."}, {"name": "Squirrel Missile", "partners": ["iron-man"], "key": "", "text": "Un missile-écureuil à tête chercheuse. **Amélioré :** En tire un avec Squirrel Blockade."}], "changes": [{"season": "Saison 11", "text": "Burst Acorn : dégâts 110 → 95 ; à 3 m de l'explosion, 60 % de dégâts en moins au lieu de 70 %."}, {"season": "Saison 11", "text": "Squirrel Blockade : projectile bien plus rapide (60–90 m/s), immobilisation 1,3 → 0,8 s, dégâts 50 → 25 ; l'impact crée une pluie de glands de 5 m (30/s pendant 2 s, 20 % de ralentissement)."}, {"season": "Saison 11", "text": "Mammal Bond : +100 % de vitesse d'attaque pendant 5 s, projectiles à 150 m/s sans gravité, Burst Acorn à 65 % de ses dégâts pendant l'effet."}, {"season": "Saison 11", "text": "Tail Bounce : donne 25 de vie bonus à l'activation."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'squirrel-girl' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Star-Lord change de rôle à chaque partie : flanker qui tue les supports, chasseur de volants, ou tireur qui use les tanks pour charger son ult. Ses roulades le rendent intouchable un instant et rechargent ses pistolets.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["En début de partie, **décide qui tu dois gêner** : le flanker, le sniper ou le volant.", "Les **roulades** esquivent et rechargent. Elles ne servent pas à se déplacer.", "Entre dans ton ult **avec deux roulades** et depuis une position préparée."], "difficulty": 2, "tags": ["Polyvalent", "Anti-volant", "Mobilité", "Esquive"], "strengths": ["Roulade intouchable qui recharge", "Très mobile en vol", "Ult à visée automatique"], "weaknesses": ["Fragile une fois les roulades dépensées", "Dégâts faibles à distance", "Ult annulée par Magneto et les bulles"], "playbook": [{"when": "Un sniper ou un Namor tient une hauteur", "then": "Vole sur son flanc, **tire en rafale** : il doit partir. Prends ensuite la hauteur toi-même."}, {"when": "Une ult ou un tir décisif part sur toi (Doctor Strange, Magneto, The Thing, flèche de Hawkeye)", "then": "**Roulade** : tu es intouchable pendant le mouvement."}, {"when": "Une Storm adverse booste son équipe", "then": "C'est **ta cible prioritaire** : tu es l'un des rares à l'atteindre."}, {"when": "Deux ults de soin s'affrontent", "then": "**Toupie au milieu du fight**, de préférence sous une bulle de Magneto : tu charges ton ult."}, {"when": "Tu veux lancer ton ult", "then": "Place-toi d'abord avec tes bottes : **près d'un couvert, dans la ligne de vue d'un support**, deux roulades prêtes."}, {"when": "Ton carburant est presque vide et tu es sur un flanc", "then": "**Attends qu'il se recharge** avant le duel : sans lui, tu n'as pas de sortie."}], "sections": [{"title": "Philosophie de jeu", "lead": "Star-Lord s'adapte à ce dont son équipe a besoin. Il n'a pas à tuer à chaque fight : chasser un ennemi de sa position suffit souvent.", "ability": "", "key": "", "kind": "tips", "items": ["Contre **un flanker, un sniper ou un volant** : occupe-toi de lui en priorité.", "Contre une compo **brawl ou poke** : mets la pression sur la backline.", "Contre une compo **sans ult défensive** : use les tanks pour charger ton ult.", "Après un fight gagné, utilise ta mobilité pour **te placer immédiatement** pour le suivant."], "diagram": "flank"}, {"title": "Pistolets", "lead": "Deux pistolets à cadence élevée. La dispersion augmente très vite pendant la rafale.", "ability": "Element Guns", "key": "Clic G", "kind": "default", "items": ["Commence la rafale **sur la tête**, laisse-la descendre vers le cou : la dispersion couvre alors la cible.", "Les dégâts baissent vite avec la distance, mais une rafale lointaine suffit à **déloger** un ennemi.", "Un rechargement par roulade est plus rapide qu'un rechargement normal."], "diagram": ""}, {"title": "Roulade", "lead": "Deux charges. Pendant la roulade, tu es intouchable, tu recharges tes pistolets et tu te déplaces légèrement.", "ability": "Stellar Shift", "key": "", "kind": "default", "items": ["Elle **esquive les ults** : Doctor Strange, Magneto, The Thing, Groot.", "En duel contre **Hela ou Namor**, roule au moment de leur tir clé.", "Sur un tank isolé, elle sert à **recharger et finir**.", "Ne la dépense **jamais pour avancer** : tes bottes sont là pour cela."], "diagram": ""}, {"title": "Bottes", "lead": "Tu voles deux fois plus vite, mais tu ne peux pas tirer. La jauge se recharge lentement.", "ability": "Rocket Propulsion", "key": "Maj", "kind": "default", "items": ["Rejoins ton flanc, **laisse la jauge remonter**, puis engage.", "Pour gagner du temps sur un point, vole dans tous les sens.", "Démarre le vol et coupe-le aussitôt : un petit élan qui coûte très peu de carburant."], "diagram": "", "scene": {"title": "Chasser de la hauteur", "caption": "Tu n'as pas besoin de tuer la sniper : il suffit qu'elle quitte sa position et que tu la prennes.", "steps": ["La sniper adverse tient la hauteur.", "Tu voles sur son flanc et tu tires : elle doit partir.", "Tu prends la hauteur, carburant rechargé."], "els": [{"t": "area", "at": [170, 8], "size": [110, 50], "label": "Hauteur"}, {"t": "pawn", "at": [232, 34], "team": "enemy", "hero": "hela", "ghost": true}, {"t": "note", "at": [232, 12], "text": "1", "team": "enemy"}, {"t": "pawn", "at": [96, 70], "team": "me", "ghost": true}, {"t": "path", "kind": "move", "team": "me", "pts": [[96, 70], [140, 6], [190, 30]], "n": 2}, {"t": "path", "kind": "move", "team": "enemy", "pts": [[240, 40], [280, 60], [292, 96]]}, {"t": "pawn", "at": [296, 104], "team": "enemy", "hero": "hela"}, {"t": "pawn", "at": [196, 34], "team": "me"}, {"t": "note", "at": [258, 72], "text": "3", "team": "me"}, {"t": "path", "kind": "shot", "team": "me", "pts": [[196, 34], [224, 122]]}, {"t": "pawn", "at": [226, 130], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [262, 148], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [292, 150], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [120, 116], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [90, 150], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [46, 100], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [50, 140], "team": "ally", "role": "heal"}]}}, {"title": "Toupie", "lead": "Tu tournoies quelques secondes en tirant sur tout ce qui t'entoure.", "ability": "Blaster Barrage", "key": "", "kind": "default", "items": ["Elle **achève** une cible, ou révèle une **Psylocke ou un Loki** invisible.", "Une cible placée devant une autre prend **double dégâts**.", "Tu n'es pas invulnérable : lance-la **avec ton équipe**, ou sous une bulle."], "diagram": ""}, {"title": "Ultime", "lead": "Tu t'envoles et tes tirs visent automatiquement pendant quelques secondes. Tes bottes sont indisponibles pendant l'ult.", "ability": "Galactic Legend", "key": "Q", "kind": "default", "items": ["Tu deviens la cible numéro un : **reste près d'un couvert et dans la vue de tes supports**.", "Contre des divers au sol, tu peux monter haut. Contre Hela ou Namor, reste bas.", "Si possible, **tue d'abord ton contre** (la Hela) avec l'ult.", "Ton chargeur pendant l'ult passe de 40 à 50 balles en saison 11 : un rechargement de moins.", "Face à une ult de soin, il te reste souvent un court instant pour tuer un ennemi resté hors de la zone."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["**Rouler pour se déplacer**.", "Vider son **carburant** avant le duel.", "Lancer l'ult **sans roulade**.", "Monter **trop haut** pendant l'ult.", "Ignorer la **Storm ou le flanker** adverse."], "diagram": ""}], "combos": [], "counters": [{"hero": "hela", "note": "Un tir à la tête et tu es presque mort."}, {"hero": "namor", "note": "Ses tourelles te suivent en vol si personne ne les détruit."}, {"hero": "magneto", "note": "Son ult absorbe toute la tienne."}, {"hero": "iron-fist", "note": "Il te rejoint en l'air et te ramène au sol."}, {"hero": "hulk", "note": "Son saut t'attrape pendant ton ult."}], "synergies": [{"hero": "venom", "note": "Il plonge, tu finis la cible depuis les airs."}, {"hero": "captain-america", "note": "Il fait dépenser les défenses avant ton ult."}, {"hero": "magneto", "note": "Sa bulle pendant ta toupie ou ton ult."}, {"hero": "adam-warlock", "note": "Un support qui tient un angle avec toi."}, {"hero": "mantis", "note": "Son bonus de dégâts juste avant ton ult."}], "sources": [{"url": "https://www.youtube.com/watch?v=71rolJfkehc", "title": "Star-Lord Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Asgardians of the Galaxy", "partners": ["angela"], "key": "", "text": "Révèle une zone et cloue les ennemis au sol avec un impact. **Amélioré :** Ajoute de la vie bonus."}, {"name": "Flora Munitions", "partners": ["groot"], "key": "", "text": "Pièges d'épines qui immobilisent. **Amélioré :** Plus de pièges et de dégâts."}, {"name": "Star Blossom", "partners": ["mantis"], "key": "", "text": "Relancer la fleur de soin propage le soin (10 + 3 %/s depuis la saison 10). **Amélioré :** Déclenchement immédiat."}, {"name": "Star-Soul", "partners": ["adam-warlock"], "key": "", "text": "Téléportation sur une balise et réapparition en cocon. **Amélioré :** Les kills réduisent le cooldown de la balise."}], "changes": [{"season": "Saison 11", "text": "Galactic Legend : chargeur des Element Guns 40 → 50 pendant l'ult."}, {"season": "Saison 11", "text": "Team-up de résurrection en cocon (« Cosmic Soul » dans les notes) : cooldown 30 → 25 s, résurrection 120 → 105 s."}, {"season": "Saison 10", "text": "Bouclier régénérant 100 → 125, Blaster Barrage 75/s → 80/s."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'star-lord' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Storm est une Duelist de soutien. Elle joue au milieu de son équipe et lui donne une aura de vitesse ou de dégâts, tout en tirant des lames qui traversent les ennemis et chargent rapidement son ult. Ce n'est pas une héroïne d'angle.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["Reste **au milieu de ton équipe**, assez bas pour que l'aura couvre tout le monde.", "**Vent** pour placer ou ramener tes alliés, **foudre** dès qu'ils sont en position.", "Incante ton ult **à l'abri** : elle peut être interrompue."], "difficulty": 1, "tags": ["Auras", "Soutien offensif", "Vol", "Charge d'ult"], "strengths": ["Bonus de dégâts ou de vitesse pour toute l'équipe", "Lames qui traversent les groupes", "Ult qui aspire et donne de la vie bonus"], "weaknesses": ["Lente et visible en vol", "Faible face au dive", "Dégâts réduits à distance"], "playbook": [{"when": "Ton équipe sort du spawn ou doit prendre position", "then": "**Aura de vent** : tout le monde arrive plus vite."}, {"when": "Tes alliés sont en place et commencent à tirer", "then": "**Aura de foudre**, puis **boost divin** quand le fight s'engage."}, {"when": "Un allié lance son ult (Punisher, Star-Lord, Black Widow sur son angle)", "then": "**Foudre renforcée** : ses dégâts s'ajoutent aux tiens sur les ennemis proches."}, {"when": "Un allié est allé trop loin", "then": "Vent renforcé : il revient plus vite et **les ennemis sont ralentis**."}, {"when": "Tu veux lancer ton ult", "then": "Incante **derrière ton équipe**, puis déplace l'ouragan. Ne le termine pas au milieu de l'équipe adverse."}, {"when": "Un héros fragile est isolé et sans soin", "then": "**Lame, boost divin, lame, éclair.**"}], "sections": [{"title": "Philosophie de jeu", "lead": "Storm exerce une pression constante, par ses propres dégâts et par ceux qu'elle ajoute à son équipe.", "ability": "", "key": "", "kind": "tips", "items": ["Place-toi dans un **endroit sûr au milieu de ton équipe**, près du sol.", "Pour jouer les angles décalés, Psylocke ou Hela font mieux.", "Elle est forte dans les compos **de poke et de brawl**, nettement moins face au **dive**."], "diagram": "", "scene": {"title": "L'aura couvre l'équipe", "caption": "L'aura est une sphère autour de toi. Trop haut ou trop loin, tes alliés en sortent et tu ne boostes plus que toi-même.", "steps": ["Vent : ton équipe rejoint sa position plus vite.", "Foudre dès que tes alliés tirent.", "Boost divin au moment où le fight s'engage."], "els": [{"t": "zone", "at": [112, 92], "r": 56, "team": "me", "label": "Aura"}, {"t": "pawn", "at": [112, 92], "team": "me"}, {"t": "pawn", "at": [40, 60], "team": "ally", "role": "dps", "ghost": true}, {"t": "path", "kind": "move", "team": "ally", "pts": [[40, 60], [96, 52]], "n": 1}, {"t": "pawn", "at": [100, 52], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [40, 128], "team": "ally", "role": "dps", "ghost": true}, {"t": "path", "kind": "move", "team": "ally", "pts": [[40, 128], [100, 134]], "n": 1}, {"t": "pawn", "at": [104, 134], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [150, 92], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [72, 92], "team": "ally", "role": "heal"}, {"t": "path", "kind": "shot", "team": "ally", "pts": [[100, 52], [212, 86]], "n": 2}, {"t": "path", "kind": "shot", "team": "ally", "pts": [[104, 134], [212, 98]], "n": 2}, {"t": "note", "at": [160, 44], "text": "3", "team": "me"}, {"t": "pawn", "at": [214, 92], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [244, 58], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [244, 126], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [284, 74], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [284, 112], "team": "enemy", "role": "heal"}]}}, {"title": "Lames de vent et éclair", "lead": "Des lames qui traversent les ennemis, et un éclair instantané qui frappe en ligne verticale.", "ability": "Wind Blade · Bolt Rush", "key": "Clic G · Clic D", "kind": "default", "items": ["Les lames **traversent** : dans un groupe, elles chargent ton ult très vite.", "Pas de dégâts critiques, et une perte de dégâts à distance.", "L'éclair **juste après une lame** annule l'animation.", "L'éclair sert surtout à **achever**."], "diagram": ""}, {"title": "Auras", "lead": "Une aura sphérique autour de toi : vent pour la vitesse, foudre pour les dégâts.", "ability": "Weather Control", "key": "", "kind": "default", "items": ["**Vent** : pour un allié qui doit se placer, pour sauver un allié trop avancé, pour revenir du spawn.", "**Foudre** : dès que tes alliés sont en position et tirent.", "Début de fight type : **vent pour se placer, foudre pour se battre**.", "Si tu montes trop haut, tes alliés sortent de la sphère."], "diagram": ""}, {"title": "Boost divin", "lead": "Renforce temporairement l'aura active. Le cooldown ne démarre qu'à la fin de l'effet.", "ability": "Goddess Boost", "key": "", "kind": "default", "items": ["**Vent renforcé** : ton équipe accélère, l'ennemi est ralenti. Idéal pour un brawl ou une retraite.", "**Foudre renforcée** : gros bonus de dégâts, et des dégâts de zone autour de toi.", "Combo : **lame, boost, lame, éclair**."], "diagram": ""}, {"title": "Ultime", "lead": "Tu choisis un point de départ, puis tu deviens un ouragan qui blesse et aspire les ennemis. Tu gagnes beaucoup de vie bonus.", "ability": "Omega Hurricane", "key": "Q", "kind": "default", "items": ["L'**incantation** peut être interrompue : lance-la depuis le milieu de ton équipe.", "Attends-toi à une ult de soin en réponse : cherche **l'ennemi resté hors de la zone**.", "Tu réapparais **au centre de l'ouragan** : ne finis pas dans la backline adverse.", "**Iron Man** te tue avec son ult, **Phoenix** retire ta vie bonus.", "Elle peut se lancer **en revenant du spawn** pour retourner un fight en cours."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Jouer **sur un angle isolé**.", "Voler **trop haut**.", "Rester en **foudre** quand l'équipe doit se déplacer.", "Incanter l'ult **à découvert**.", "Terminer l'ult **au milieu de l'ennemi**."], "diagram": ""}], "combos": [{"note": "L'éclair juste après une lame annule l'animation.", "steps": [{"key": "Clic G", "label": "lame"}, {"key": "", "label": "Boost divin"}, {"key": "Clic G", "label": "lame"}, {"key": "Clic D", "label": "éclair"}], "title": "Fragile sans soins"}], "counters": [{"hero": "star-lord", "note": "Il te chasse en l'air : tu es sa cible prioritaire."}, {"hero": "hulk", "note": "Son saut t'attrape, et son exil te sort de ton ult."}, {"hero": "the-thing", "note": "Il saute sur toi si tu voles trop près du front."}, {"hero": "iron-man", "note": "Il gagne le duel aérien et son ult te tue dans la tienne."}, {"hero": "spider-man", "note": "Tu n'as aucune fuite rapide contre lui."}, {"hero": "luna-snow", "note": "Ses tirs te délogent et son ult résiste à la tienne."}], "synergies": [{"hero": "magneto", "note": "Son rideau et sa bulle te gardent en sécurité au centre."}, {"hero": "the-punisher", "note": "Sous ton aura de foudre, son tir continu devient terrifiant."}, {"hero": "winter-soldier", "note": "Un DPS qui reste dans ton aura."}, {"hero": "black-widow", "note": "Avec ton aura, son tir à la tête tue."}, {"hero": "adam-warlock", "note": "Votre team-up donne à son lien un boost de vitesse doublé en saison 11."}], "sources": [{"url": "https://www.youtube.com/watch?v=mlewjqlw91c", "title": "Storm Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Cosmic Cyclone", "partners": ["adam-warlock"], "key": "", "text": "Soul Bond donne un boost de vitesse (100 % en saison 11). **Amélioré :** Ajoute un boost de dégâts (8 % en saison 11)."}, {"name": "Damisa-Yao", "partners": ["black-panther"], "key": "", "text": "Explosion élémentaire de l'armure qui ralentit et marque. **Amélioré :** Projette les ennemis vers Black Panther."}, {"name": "Gods of Thunder", "partners": ["thor"], "key": "", "text": "Rayon de foudre. **Amélioré :** Bolt Rush devient un éclair en chaîne qui rebondit."}, {"name": "Jaws of Fate", "partners": ["jeff-the-land-shark"], "key": "", "text": "Averse qui soigne. **Amélioré :** Jeff peut nager dans une tornade (Jeff-nado)."}, {"name": "Storming Ignition", "partners": ["human-torch"], "key": "", "text": "Un vortex de feu attire les ennemis. **Amélioré :** Allume des ouragans enflammés."}], "changes": [{"season": "Saison 11", "text": "Team-up avec Adam Warlock : boost de vitesse 67 % → 100 %, boost de dégâts du Soul Bond amélioré 12 % → 8 %."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'storm' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "The Hood est un Vanguard à distance. Il tire sans interruption pour charger son énergie démoniaque ; à 100, il se transforme en démon armé de mitrailleuses, avec vol de vie. Entre deux transformations, il tient grâce à sa bulle d'absorption, son voile et sa marche dans le vide.", "patch_note": "Conseils issus d'un guide enregistré à la sortie du héros (saison 9.5), mis à jour avec les saisons 10 et 11. Vérifie les détails en jeu.", "tldr": ["**Tire en continu** : chaque balle qui touche charge ton énergie démoniaque.", "À 100 d'énergie, la **forme de démon** est ton pic de pression : choisis son moment.", "Pose ton **voile derrière le tank adverse** : il reçoit moins de soins et son équipe fait moins de dégâts."], "difficulty": 2, "tags": ["Distance", "Second tank", "Usure", "Forme de démon"], "strengths": ["Vrais dégâts à distance pour un Vanguard", "Bulle qui absorbe n'importe quel burst", "Voile qui réduit soins et dégâts adverses"], "weaknesses": ["Peu de protection pour ses alliés", "Faible tant que l'énergie n'est pas chargée", "Vol de vie annulé par l'anti-soin"], "playbook": [{"when": "Le fight commence", "then": "**Tire sans t'arrêter** sur le tank adverse : l'énergie ne redescend pas tant que tu n'es pas transformé."}, {"when": "Le tank adverse s'avance", "then": "**Voile juste derrière lui** : ses soins et les tirs de son équipe sont réduits en le traversant."}, {"when": "Un gros burst arrive sur toi ou sur tes supports (Iron Man, Magneto)", "then": "**Bulle d'absorption** au moment de l'impact : elle absorbe tout et te rend de l'énergie."}, {"when": "Tu es à 100 d'énergie et le fight est engagé", "then": "**Forme de démon** : mitrailleuses et vol de vie. Hors fight, attends."}, {"when": "Tu vas mourir", "then": "**Marche dans le vide** pour sortir. Si l'ult est prête, lance-la : tu repars avec toute ta vie."}, {"when": "Une Hela ou un Iron Man lance son ult en l'air", "then": "**Voile devant lui**, en hauteur : ses dégâts sont réduits."}], "sections": [{"title": "Philosophie de jeu", "lead": "Tu joues au front, de préférence en second tank. Ton objectif : survivre assez longtemps pour atteindre la forme de démon, puis faire fondre l'équipe adverse.", "ability": "", "key": "", "kind": "tips", "items": ["Ta force est la **guerre d'usure** : tu forces les cooldowns des supports adverses.", "La bulle te garde en vie **et** te rend de l'énergie : utilise-la à chaque retour de cooldown utile.", "Tu protèges mal tes alliés : laisse l'espace et le peel à l'autre Vanguard."], "diagram": "space"}, {"title": "Pistolets et énergie", "lead": "Deux pistolets capables de tirs à la tête. Chaque balle qui touche charge l'énergie démoniaque : cadence accrue à 50, forme de démon à 100.", "ability": "Pistolets · Ruinous Pact", "key": "Clic G", "kind": "default", "items": ["En démon, tes pistolets deviennent des **mitrailleuses**, avec vol de vie et vie bonus.", "L'énergie se vide dès la transformation : **choisis le moment**, pas seulement la jauge pleine.", "Tu peux quitter la forme de démon au-dessus de 50 : tu conserves 25 d'énergie au lieu de repartir de zéro."], "diagram": ""}, {"title": "Bulle d'absorption", "lead": "Une bulle très brève qui absorbe n'importe quelle quantité de dégâts et de soins, et te rend de l'énergie. Indisponible en forme de démon.", "ability": "Mantle of Oblivion", "key": "Clic D", "kind": "default", "items": ["Passe-la en **mode bascule** dans les réglages : tu ne l'annuleras plus par erreur.", "Au-dessus de 50 d'énergie, elle est **plus grande**.", "Placé sur tes supports ou dans la trajectoire d'une ult, tu **absorbes à leur place**. Le timing est serré, et son cooldown est de 12 secondes."], "diagram": ""}, {"title": "Marche dans le vide", "lead": "Tu deviens inciblable et tu te déplaces librement un court instant. À la sortie, une explosion blesse autour de toi et tu gagnes un peu de vitesse.", "ability": "Void Walk", "key": "", "kind": "default", "items": ["C'est ta **sortie de secours** : ne la dépense pas pour entrer.", "Elle te rend aussi de l'énergie.", "Elle peut te faire **monter** pour lancer ton ult depuis une hauteur."], "diagram": ""}, {"title": "Voile", "lead": "Un grand voile qui réduit les dégâts et les soins ennemis qui le traversent. Tirer à travers te donne plus d'énergie et plus de vol de vie.", "ability": "Abyssal Veil", "key": "", "kind": "default", "items": ["**Pour survivre et charger** : entre toi et le tank adverse.", "**Pour tuer** : juste derrière le tank adverse.", "Il se pose **en l'air**.", "Un ennemi qui le traverse est blessé et aveuglé.", "Avec Cloak & Dagger dans l'équipe, vos voiles repoussent aussi les ennemis depuis la saison 11."], "diagram": "", "scene": {"title": "Le voile derrière leur tank", "caption": "Le voile agit dans les deux sens : les soins destinés au tank sont réduits, et les tirs de son équipe aussi.", "steps": ["Le tank adverse s'avance.", "Tu poses le voile juste derrière lui.", "Tu tires : il est mal soigné, et son équipe te fait moins mal."], "els": [{"t": "pawn", "at": [184, 92], "team": "enemy", "role": "tank", "label": "Cible"}, {"t": "note", "at": [184, 62], "text": "1", "team": "enemy"}, {"t": "bar", "from": [222, 44], "to": [222, 142], "team": "me", "label": "Voile", "n": 2}, {"t": "pawn", "at": [110, 92], "team": "me"}, {"t": "path", "kind": "shot", "team": "me", "pts": [[110, 92], [184, 92]], "n": 3}, {"t": "path", "kind": "heal", "team": "enemy", "pts": [[284, 70], [230, 84]]}, {"t": "path", "kind": "heal", "team": "enemy", "pts": [[284, 116], [230, 102]]}, {"t": "path", "kind": "shot", "team": "enemy", "pts": [[258, 150], [228, 138]]}, {"t": "pawn", "at": [284, 70], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [284, 116], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [262, 154], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [256, 30], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [120, 40], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [126, 144], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [52, 76], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [52, 120], "team": "ally", "role": "heal"}]}}, {"title": "Ultime", "lead": "Tu récupères toute ta vie et tu deviens une tourelle de 1000 PV, avec six tirs perçants dévastateurs qui donnent aussi de la vie bonus à ton équipe.", "ability": "Demon of the End", "key": "Q", "kind": "default", "items": ["Le **sixième tir** fait presque le double des autres : garde-le pour la cible qui compte.", "La portée est courte : lance-la **au contact du fight**.", "C'est aussi une **seconde vie** : au bord de la mort, elle te remet à plein.", "Combinée à une autre ult (Winter Soldier), elle tue un support dans sa propre ult."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["**Cesser de tirer**.", "Se transformer **hors du fight**.", "Oublier que la bulle est **indisponible en démon**.", "Poser le voile **au hasard**.", "Dépenser la marche dans le vide **pour engager**."], "diagram": ""}], "combos": [], "counters": [{"hero": "the-punisher", "note": "Son tir continu dépasse ce que ta bulle et ta vie bonus absorbent."}, {"hero": "blade", "note": "Son anti-soin annule ton vol de vie en forme de démon."}, {"hero": "hela", "note": "Elle te bat à distance avant que ton énergie soit chargée."}, {"hero": "emma-frost", "note": "Elle charge son rayon sur toi et t'étrangle pendant ta forme de démon."}], "synergies": [{"hero": "jubilee", "note": "Votre team-up rend son tir hitscan."}, {"hero": "cloak-and-dagger", "note": "Vos voiles repoussent les ennemis depuis la saison 11."}, {"hero": "magik", "note": "Chaque portail invoque un démon supplémentaire."}, {"hero": "moon-knight", "note": "Votre team-up crée une barrière sur laquelle ses tirs rebondissent."}, {"hero": "winter-soldier", "note": "Son ult et la tienne ensemble tuent un support dans sa zone."}], "sources": [{"title": "Ultimate The Hood Guide (Beginner/Advanced)", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=QCuItyqk75U"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Chaos Collision", "partners": ["scarlet-witch"], "key": "", "text": "Zone arcanique et téléportation. **Amélioré :** Ajoute une onde de choc."}, {"name": "Hellfire Sparks", "partners": ["jubilee"], "key": "", "text": "Forme hitscan avec auto-soin. **Amélioré :** Garde la marque de magie du vide."}, {"name": "New Moon's Shadow", "partners": ["moon-knight"], "key": "", "text": "Une barrière lunaire explose (détection des rebonds à 6 m depuis la saison 10). **Amélioré :** Les attaques rebondissent."}, {"name": "Oblivion Shroud", "partners": ["cloak-and-dagger"], "key": "", "text": "Les voiles affaiblissent dégâts et soins ennemis, et repoussent les ennemis sur leur passage depuis la saison 11. **Amélioré :** Plus larges, avec un boost de dégâts."}, {"name": "Void Pentagram", "partners": ["magik"], "key": "", "text": "Les Stepping Discs rendent de l'énergie et invoquent des démons du Limbo (cooldown 20 s depuis la saison 10). **Amélioré :** Démons plus solides, plus de portée."}], "changes": [{"season": "Saison 11", "text": "Team-up avec Cloak & Dagger : les voiles repoussent désormais les ennemis sur leur passage."}, {"season": "Saison 10", "text": "Vie de base 600 → 550, Mantle of Oblivion 10 s → 12 s de cooldown, réduction des dégâts des projectiles 35 % → 20 %."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'the-hood' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Le Punisher est un Duelist de dégâts constants. Il ne cherche pas l'élimination rapide : il use les tanks trop avancés, les volants à découvert et les supports trop confiants, pour que l'adversaire arrive entamé au moment où le fight se décide.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["Tire sur **les bonnes cibles** : pas sur un tank soigné par deux supports.", "**Change d'arme avant de sortir** : le changement n'est pas instantané.", "Prépare une **tyrolienne de sortie** avant de poser ta tourelle."], "difficulty": 1, "tags": ["Dégâts constants", "Anti-volant", "Tourelle", "Accessible"], "strengths": ["Dégâts hitscan constants à toute distance", "Tourelle insensible aux contrôles", "Ult qui tue à travers une ult de soin"], "weaknesses": ["Peu mobile une fois installé", "Neutralisé par le rideau de Magneto", "Tourelle lente et bruyante à poser"], "playbook": [{"when": "Un volant reste à découvert (Iron Man, Storm, Human Torch)", "then": "**Fusil d'assaut à la tête** : tu es son meilleur contre."}, {"when": "Un diver ou une Hela te prend pour cible", "then": "**Fumigène** : il te propulse en arrière et coupe la ligne de vue."}, {"when": "Tu veux poser ta tourelle sur une position avancée", "then": "**Tyrolienne de sortie d'abord**, tourelle ensuite, hors de vue directe."}, {"when": "Une cible basse arrive au contact", "then": "**Fusil à pompe**, déjà en main avant qu'elle tourne le coin."}, {"when": "Ton ult est prête", "then": "Lance-la **derrière un mur**, et attends que Magneto ait dépensé rideau et ult, ou demande une bulle."}, {"when": "Deux ults de soin s'échangent", "then": "Ult, et tire à la tête sur **celui qui est resté hors de la zone**."}], "sections": [{"title": "Philosophie de jeu", "lead": "Le Punisher demande de la patience et un bon suivi de cible : il use l'adversaire pendant tout le fight, il ne le conclut pas en une seconde.", "ability": "", "key": "", "kind": "tips", "items": ["Tirer sur un tank que tu ne peux pas tuer **charge les ults de ses supports**.", "Fais **douter les volants** : un Iron Man qui se cache ne tire pas.", "Si personne ne te regarde, **reste immobile** : tu vises mieux.", "Avec l'ult prête, prends un angle en tyrolienne sur la backline."], "diagram": "poke"}, {"title": "Fusil d'assaut", "lead": "Un fusil hitscan à cadence élevée, dangereux à la tête même de loin.", "ability": "Adjudication", "key": "Clic G", "kind": "default", "items": ["Tire **par rafales** pour contenir la dispersion.", "C'est ton outil de pression et de charge d'ult en début de fight.", "Travaille ton **suivi de cible** : c'est le geste du héros."], "diagram": ""}, {"title": "Fusil à pompe", "lead": "Un fusil à pompe qui tue à bout portant et perd très vite ses dégâts avec la distance.", "ability": "Deliverance", "key": "", "kind": "default", "items": ["**De près uniquement.** Un peu plus loin, vise le torse.", "Il **achève** les cibles basses en fin de fight.", "Changer d'arme ne recharge pas : **recharge les deux** après chaque fight."], "diagram": ""}, {"title": "Tourelle", "lead": "Tu t'installes derrière une tourelle protégée de face, qui tire des projectiles explosifs. Elle te rend insensible aux contrôles.", "ability": "Culling Turret", "key": "E", "kind": "default", "items": ["Excellente sur **un groupe**, moins sur une cible seule.", "Place-la **hors de vue directe, au-dessus d'un passage**.", "L'installation est lente et s'entend : **prévois ta sortie**.", "Installée devant un support, elle le protège du météore de Magneto."], "diagram": "", "scene": {"title": "La tourelle et sa sortie", "caption": "La tourelle te fixe sur place. La tyrolienne posée avant est ce qui te permet d'en repartir vivant.", "steps": ["Tu poses une tyrolienne vers ton équipe.", "Tourelle en hauteur, au-dessus du passage : tu arroses le groupe.", "Un diver arrive : tyrolienne."], "els": [{"t": "area", "at": [120, 8], "size": [110, 50], "label": "Hauteur"}, {"t": "cover", "at": [196, 70], "size": [16, 40]}, {"t": "cover", "at": [196, 136], "size": [16, 40]}, {"t": "path", "kind": "sight", "team": "me", "pts": [[160, 36], [60, 110]], "n": 1}, {"t": "note", "at": [96, 62], "text": "tyrolienne", "team": "me"}, {"t": "pawn", "at": [164, 34], "team": "me"}, {"t": "mark", "at": [186, 40], "kind": "turret", "team": "me"}, {"t": "note", "at": [186, 16], "text": "2", "team": "me"}, {"t": "path", "kind": "shot", "team": "me", "pts": [[190, 44], [240, 118]]}, {"t": "path", "kind": "shot", "team": "me", "pts": [[190, 44], [262, 104]]}, {"t": "pawn", "at": [240, 124], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [266, 108], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [290, 132], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [250, 30], "team": "enemy", "hero": "psylocke", "above": true}, {"t": "path", "kind": "move", "team": "enemy", "pts": [[296, 20], [270, 16], [258, 28]], "n": 3}, {"t": "pawn", "at": [300, 22], "team": "enemy", "role": "dps", "ghost": true}, {"t": "pawn", "at": [60, 118], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [100, 136], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [40, 150], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [130, 160], "team": "ally", "role": "dps"}]}}, {"title": "Tyrolienne et fumigène", "lead": "Une tyrolienne très rapide (trois en place au maximum), et une grenade fumigène qui te propulse en arrière.", "ability": "Vantage Connection · Scourge Grenade", "key": "Maj · Clic D", "kind": "default", "items": ["**Pose des tyroliennes à l'avance** pour revenir vite du spawn.", "Le fumigène est d'abord un **outil de survie**.", "Tyrolienne et fumigène combinés atteignent des hauteurs et des flancs inattendus.", "Ton passif te montre quelques secondes, à travers les murs, les ennemis que tu viens de voir."], "diagram": ""}, {"title": "Ultime", "lead": "Deux mitrailleuses et des missiles guidés pendant quelques secondes : assez pour tuer une Luna à travers son ult, à condition de viser la tête.", "ability": "Final Judgment", "key": "Q", "kind": "default", "items": ["Il y a une animation avant le tir : **lance-la derrière un mur**.", "Le **Magneto** adverse garde son rideau et son ult pour toi : joue près de ton tank, ou demande une bulle ou un bouclier d'Invisible Woman.", "Elle se charge vite en tirant sur les tanks.", "Sous une aura de Storm ou un bonus de Luna, elle détruit une équipe."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Vider ses chargeurs sur un **tank soigné**.", "Changer d'arme **à découvert**.", "Poser la tourelle **sans sortie**.", "Lancer l'ult **face à un Magneto prêt**.", "Utiliser le fumigène **pour avancer**."], "diagram": ""}], "combos": [], "counters": [{"hero": "magneto", "note": "Son rideau annule ton tir et son ult absorbe la tienne."}, {"hero": "psylocke", "note": "Elle arrive invisible sur ta tourelle."}, {"hero": "hela", "note": "Deux tirs à la tête avant que tu sois installé."}, {"hero": "rocket-raccoon", "note": "Ses kits d'armure et ses soins de zone neutralisent ton usure."}, {"hero": "doctor-strange", "note": "Son bouclier t'oblige à changer d'angle."}], "synergies": [{"hero": "emma-frost", "note": "Un front solide derrière lequel tirer sans bouger."}, {"hero": "groot", "note": "Ses murs découpent le fight, ton tir conclut."}, {"hero": "doctor-strange", "note": "Son bouclier couvre ta tourelle, son portail te ramène."}, {"hero": "storm", "note": "Son aura de foudre pendant ton ult."}, {"hero": "winter-soldier", "note": "Il attrape, tu achèves au fusil à pompe."}, {"hero": "rocket-raccoon", "note": "Votre team-up accélère ta cadence et te donne des munitions infinies."}], "sources": [{"url": "https://www.youtube.com/watch?v=T0d2S3gRW-M", "title": "Punisher Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Ammo Overload", "partners": ["rocket-raccoon"], "key": "", "text": "Rocket pose un appareil qui accélère la cadence des alliés. **Amélioré :** Munitions infinies en plus."}, {"name": "Bestial Hunt", "partners": ["daredevil"], "key": "", "text": "Balles perforantes avec bonus de dégâts. **Amélioré :** Détruit les murs plus vite."}, {"name": "Primal Punishment", "partners": ["devil-dinosaur"], "key": "", "text": "Canons magnétiques qui font saigner (cooldown 18 s en saison 11). **Amélioré :** The Punisher chevauche Devil Dinosaur et partage les dégâts."}, {"name": "Timeless Veterans", "partners": ["winter-soldier"], "key": "", "text": "Pointe d'électricité qui repousse. **Amélioré :** Cloue au sol en plus."}], "changes": [{"season": "Saison 11", "text": "Team-up avec Devil Dinosaur (Primal Punishment) : cooldown 12 → 18 s."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'the-punisher' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "The Thing est un Vanguard de corps à corps qui domine les espaces étroits. Il ne peut être ni repoussé ni attiré, sa charge interdit aux ennemis d'utiliser leurs déplacements, il saute vers un allié pour le protéger, et son ult étourdit tout ce qui se trouve devant lui.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["Impose le fight **dans un espace serré** : en terrain ouvert, tu perds.", "Ta **charge** est ta capacité clé : elle prive les ennemis de leurs déplacements.", "Pendant un échange d'ults de soin, **frappe sans arrêt** : ton ult se charge très vite."], "difficulty": 1, "tags": ["Brawl", "Anti-dive", "Contrôle", "Couloirs"], "strengths": ["Insensible aux poussées et aux attractions", "Charge qui bloque les déplacements adverses", "Ult d'étourdissement rapide à charger"], "weaknesses": ["Impuissant à distance", "Large hitbox qui nourrit les ults adverses", "Lent sans ses sauts"], "playbook": [{"when": "Un diver saute sur tes supports (Black Panther, Magik, Spider-Man)", "then": "**Charge et frappe au sol sur tes supports** : dans la zone, il ne peut plus dasher ni se téléporter."}, {"when": "Une cible vient de dépenser sa défense (bulle de Magneto, saut d'un support)", "then": "**Charge sur elle** : sans déplacement, elle ne t'échappe pas."}, {"when": "Un allié en ult est exposé (Star-Lord, Punisher), ou ton support est visé par Magneto", "then": "**Saute vers lui** : vous encaissez moins tous les deux."}, {"when": "Tu as chargé loin dans la backline", "then": "Dès qu'ils se retournent, **saute vers un allié** qui te voit."}, {"when": "Une Invisible Woman essaie de te repousser", "then": "**Avance.** Ses poussées ne te font rien."}, {"when": "L'adversaire vient de lancer une ult interruptible (Doctor Strange, Hawkeye)", "then": "**Ult** : l'onde traverse les boucliers et étourdit."}], "sections": [{"title": "Philosophie de jeu", "lead": "Un ennemi qui ne peut pas fuir perd contre The Thing. Ton travail est de choisir un endroit où il sera obligé de venir à toi.", "ability": "", "key": "", "kind": "tips", "items": ["Tiens-toi **à couvert près d'un passage obligé**.", "En défense, il fait souvent mieux qu'une Peni Parker sur les cartes à couloirs.", "Ne t'avance pas trop : ta large hitbox **charge les ults** des DPS adverses.", "Après un fight gagné, prends la position suivante avant que l'ennemi revienne."], "diagram": "brawl"}, {"title": "Coups et crochet", "lead": "Des coups de poing en cône qui touchent plusieurs ennemis, et un crochet lourd à longue allonge qui te donne de la vie bonus.", "ability": "Rocky Jabs · Stone Haymaker", "key": "Clic G · Clic D", "kind": "default", "items": ["Les ennemis à portée de coup sont **surlignés**.", "Le **crochet** est ton outil de poke : utilise-le presque en continu.", "**Deux coups, puis crochet** : un héros fragile est mort.", "Charge le crochet avant de sauter sur un volant pour le faire tomber."], "diagram": ""}, {"title": "Charge", "lead": "Tu fonces, puis tu frappes le sol : les ennemis sont projetés, et une zone les empêche d'utiliser leurs capacités de déplacement. Tu gagnes de la vie bonus pendant la charge.", "ability": "Yancy Street Charge", "key": "Maj", "kind": "default", "items": ["Dans les paramètres, passe-la en **mode maintenu** : tu frappes le sol à l'instant où tu relâches.", "La zone empêche même **Phoenix de lancer son ult**.", "Pendant la charge, la **boule de neige de Luna** ne t'arrête pas.", "Son cooldown est passé à 12 secondes en saison 10 : ne la dépense pas pour traverser la carte.", "Si tu t'en sers pour entrer, garde **un saut** pour revenir."], "diagram": "", "scene": {"title": "La charge sur ta backline", "caption": "La zone laissée par la frappe au sol interdit les déplacements : le diver qui comptait repartir en dash ne repart pas.", "steps": ["Le diver saute sur ton support.", "Tu charges et tu frappes le sol sur eux.", "Privé de ses déplacements, il meurt sur place."], "els": [{"t": "pawn", "at": [220, 28], "team": "enemy", "role": "dps", "ghost": true}, {"t": "path", "kind": "move", "team": "enemy", "pts": [[220, 28], [160, 30], [100, 96]], "n": 1}, {"t": "pawn", "at": [200, 116], "team": "me", "ghost": true}, {"t": "path", "kind": "move", "team": "me", "pts": [[200, 116], [142, 122]], "n": 2}, {"t": "zone", "at": [96, 110], "r": 30, "team": "me"}, {"t": "note", "at": [96, 158], "text": "zone sans déplacement", "team": "me"}, {"t": "pawn", "at": [96, 104], "team": "enemy", "hero": "black-panther", "above": true}, {"t": "pawn", "at": [58, 122], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [136, 126], "team": "me"}, {"t": "note", "at": [170, 150], "text": "3", "team": "ally"}, {"t": "pawn", "at": [40, 70], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [170, 166], "team": "ally", "role": "dps"}, {"t": "path", "kind": "shot", "team": "ally", "pts": [[170, 166], [108, 114]]}, {"t": "pawn", "at": [180, 60], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [250, 100], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [280, 140], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [296, 66], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [298, 110], "team": "enemy", "role": "heal"}]}}, {"title": "Sauts", "lead": "Deux charges communes : saute vers un allié (vous encaissez moins tous les deux) ou vers un ennemi (toi seul encaisses moins).", "ability": "Embattled Leap · Battle Blitz", "key": "", "kind": "default", "items": ["**Charge dans la backline, puis saut vers ton équipe** : c'est ton aller-retour.", "Pour aider un allié en duel, saute **vers l'allié** : même position, plus de protection.", "Tu peux **intercepter l'ult de Phoenix** en sautant dessus.", "Ne saute **jamais** sur un Punisher en ult.", "Contre un volant, attends qu'il soit occupé ailleurs."], "diagram": ""}, {"title": "Passif", "lead": "Tu ne peux être ni repoussé, ni attiré, ni projeté. Les étourdissements, eux, fonctionnent.", "ability": "Unyielding Will", "key": "", "kind": "default", "items": ["Le crochet de **Winter Soldier** ne te déplace pas, mais il t'étourdit.", "Une prison de Groot ou une attraction d'Invisible Woman ne te regroupe pas avec les autres."], "diagram": ""}, {"title": "Ultime", "lead": "Tu frappes le sol : une onde se propage devant toi et étourdit tous les ennemis touchés. Elle traverse les boucliers.", "ability": "It's Clobberin' Time!", "key": "Q", "kind": "default", "items": ["Elle se charge **très vite** : dans un long fight, tu peux en avoir deux.", "Lance-la **juste après** une ult adverse interruptible.", "Sans ult de soin dans ton équipe, cherche à **étourdir la Luna** avant qu'elle lance la sienne.", "Avec un Punisher ou un Star-Lord en ult, étourdis l'équipe adverse : il tire sur des cibles immobiles."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Se battre **en terrain ouvert**.", "Laisser la charge **en mode par défaut**.", "Entrer **sans saut** pour revenir.", "Sauter **sur un Punisher en ult**.", "**Garder l'ult** au lieu de l'utiliser."], "diagram": ""}], "combos": [{"note": "", "steps": [{"key": "Clic G", "label": "coup"}, {"key": "Clic G", "label": "coup"}, {"key": "Clic D", "label": "crochet"}], "title": "Éliminer un fragile"}], "counters": [{"hero": "emma-frost", "note": "Ta hitbox charge son rayon en deux secondes."}, {"hero": "groot", "note": "Il ferme un mur derrière toi après ton engage."}, {"hero": "the-punisher", "note": "Il vide ta barre de vie à une distance où tu ne peux rien."}, {"hero": "squirrel-girl", "note": "Ses glands te touchent à chaque tir."}, {"hero": "iron-man", "note": "Hors de portée, avec beaucoup de dégâts."}, {"hero": "phoenix", "note": "Elle déclenche ses chaînes sur toi."}, {"hero": "moon-knight", "note": "Ses ricochets te prennent comme relais."}], "synergies": [{"hero": "magneto", "note": "Un second tank qui tient le front pendant que tu protèges."}, {"hero": "magik", "note": "Une Duelist de contact qui se bat à tes côtés."}, {"hero": "phoenix", "note": "Tu regroupes les ennemis, elle les fait exploser."}, {"hero": "human-torch", "note": "Tu retiens les ennemis dans ses zones de feu."}, {"hero": "invisible-woman", "note": "Elle attire les cibles dans ta portée ; votre team-up te donne de la vie bonus."}, {"hero": "wolverine", "note": "Il emporte une cible, tu tiens le reste."}], "sources": [{"url": "https://www.youtube.com/watch?v=8IJGdtB9s2s", "title": "The Thing Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Clobberin' Research Dept.", "partners": ["mister-fantastic"], "key": "", "text": "Posture de bagarre avec un coup de poing chargé (activable à volonté depuis la saison 10). **Amélioré :** Ajoute un coup de marteau chargé."}, {"name": "Iron & Stone", "partners": ["iron-fist"], "key": "", "text": "Uppercut qui projette en l'air puis coup de pied (fonctionne même sans The Thing, cooldown 12 s depuis la saison 10). **Amélioré :** Enchaînements et dégâts en plus."}, {"name": "Two-in-One", "partners": ["human-torch"], "key": "", "text": "Poings enflammés (cooldown 18 s, 8 s de durée depuis la saison 10). **Amélioré :** Soulève et écrase avec étourdissement."}, {"name": "Unbreakable Forces", "partners": ["invisible-woman"], "key": "", "text": "Armure psionique qui donne de la vie bonus (cooldown 15 s en 10.5). **Amélioré :** Impulsions de soin de zone (seuil de 125 dégâts en 10.5)."}], "changes": [{"season": "Saison 10", "text": "Vie de base 750 → 725, Stone Haymaker 10 % → 8 % de la vie max, Yancy Street Charge 10 s → 12 s de cooldown."}, {"season": "Saison 10.5", "text": "Team-up avec Invisible Woman : cooldown 20 s → 15 s."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'the-thing' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Thor est un Vanguard flexible qui se joue sur une ressource, la Thorforce. Il conteste les positions tenues par les DPS adverses, passe par les flancs, et utilise son dash pour emporter un tank ennemi au milieu de sa propre équipe.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["**Gère ta Thorforce** : un coup de marteau entre deux capacités la recharge.", "**Conteste les hauteurs** des DPS adverses, puis ramène un tank chez toi.", "N'active l'**Éveil** que si rien ne s'interpose entre toi et tes cibles."], "difficulty": 2, "tags": ["Ressource", "Déplacement d'ennemis", "Flexible", "Duels"], "strengths": ["Emporte un tank adverse dans son équipe", "Dôme qui bloque les déplacements", "Ult insensible aux contrôles"], "weaknesses": ["Tout dépend de la Thorforce", "Dash chargé facile à interrompre", "Éveil inutile face à un bouclier"], "playbook": [{"when": "Le tank adverse s'avance", "then": "Contourne-le, **dash chargé** dans son dos, et tourne pendant le dash pour le déposer dans ton équipe. Puis **dôme**."}, {"when": "Un DPS adverse tient une hauteur", "then": "**Monte dessus** : il recule, et son tank doit reculer avec lui."}, {"when": "Tu viens d'utiliser une capacité", "then": "**Frappe** pendant le délai avant la suivante : chaque premier impact rend une Thorforce."}, {"when": "Angela ou un diver s'en prend à tes supports", "then": "**Dôme sur eux** : les déplacements sont bloqués à l'intérieur."}, {"when": "Rien ne protège la backline adverse", "then": "**Lancer de marteau, puis Éveil** pendant qu'il vole."}, {"when": "Une ult à projectiles vise tes supports et tu n'as rien d'autre", "then": "**Dash vers le lanceur** : tu encaisses à leur place."}], "sections": [{"title": "Philosophie de jeu", "lead": "Pose-toi toujours la même question : qui dois-je mettre sous pression, et quand ? Thor peut tout faire, à condition de choisir.", "ability": "", "key": "", "kind": "tips", "items": ["Avec un **front fort**, bats-toi au centre.", "Si le **front adverse est plus fort**, prends les angles et les duels.", "En défense, tiens-toi **un pas derrière ton front**, prêt à emporter le tank qui s'avance."], "diagram": "", "scene": {"title": "Ramener un tank", "caption": "Un tank déposé au milieu de cinq ennemis, derrière un dôme qui bloque ses déplacements, ne revoit pas ses supports.", "steps": ["Tu passes par le flanc pendant que le tank s'avance.", "Dash chargé dans son dos : tu l'emportes vers ton équipe.", "Dôme : il ne peut plus repartir."], "els": [{"t": "pawn", "at": [120, 40], "team": "me", "ghost": true}, {"t": "path", "kind": "move", "team": "me", "pts": [[120, 40], [190, 10], [236, 60]], "n": 1}, {"t": "pawn", "at": [214, 92], "team": "enemy", "role": "tank", "ghost": true}, {"t": "pawn", "at": [236, 68], "team": "me", "ghost": true}, {"t": "path", "kind": "pull", "team": "me", "pts": [[232, 76], [180, 108], [128, 100]], "n": 2}, {"t": "zone", "at": [112, 100], "r": 30, "team": "me", "label": "Dôme", "n": 3}, {"t": "pawn", "at": [104, 104], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [132, 92], "team": "me", "above": true}, {"t": "pawn", "at": [70, 66], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [72, 140], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [40, 100], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [116, 150], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [256, 56], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [260, 132], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [294, 78], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [294, 116], "team": "enemy", "role": "heal"}]}}, {"title": "Thorforce", "lead": "La plupart de tes capacités consomment de la Thorforce et te donnent de la vie bonus. Elle revient avec le temps, ou en touchant un ennemi.", "ability": "Thorforce", "key": "", "kind": "default", "items": ["Après chaque capacité, un court délai précède la suivante : **frappe pendant ce délai**.", "Une Thorforce bien gérée, c'est une capacité de plus par fight."], "diagram": ""}, {"title": "Marteau", "lead": "Des coups de marteau, et un lancer qui revient comme un boomerang.", "ability": "Mjolnir Bash · Hammer Throw", "key": "Clic G · Clic D", "kind": "default", "items": ["Chaque **premier impact** d'un coup rend une Thorforce.", "Le marteau lancé **revient plus vite** s'il touche une cible proche.", "Pendant le lancer, tu ne peux pas dasher, mais tu peux activer l'Éveil."], "diagram": ""}, {"title": "Dash", "lead": "Maintiens pour charger, relâche pour foncer. Tu peux emporter un ennemi et tourner pendant le dash.", "ability": "Storm Surge", "key": "Maj", "kind": "default", "items": ["La charge s'entend : un étourdissement (Hela, Phoenix, Luna) ou une attraction l'annule. **Charge hors de vue.**", "Pour sortir du spawn, un dash non chargé suffit.", "Après avoir déposé une cible, le dôme la retient."], "diagram": ""}, {"title": "Dôme de foudre", "lead": "Une sphère autour de toi : les ennemis qui la traversent sont blessés, ralentis et privés de leurs déplacements. Elle te rend de la Thorforce selon le nombre d'ennemis à l'intérieur.", "ability": "Lightning Realm", "key": "", "kind": "default", "items": ["Posé **après un dash**, il empêche la cible de repartir.", "Faire entrer et sortir un ennemi avec ton dash **multiplie les dégâts**.", "Contre Angela, pose-le **sur tes supports** : elle ne peut plus les emporter."], "diagram": ""}, {"title": "Éveil", "lead": "Tu consommes toute ta Thorforce : tes coups deviennent des projectiles puissants, par séries de quatre, et une aura blesse autour de toi.", "ability": "Awakening Rune", "key": "", "kind": "default", "items": ["C'est un gros investissement : **vérifie que rien ne bloque tes tirs**.", "Face à un bouclier (Magneto, Strange), contourne ou bouscule d'abord.", "Contre **Peni Parker**, il nettoie son nid et ses mines.", "Tu peux **l'interrompre tôt** pour récupérer une Thorforce et dasher."], "diagram": ""}, {"title": "Ultime", "lead": "Tu t'élèves, insensible aux contrôles, au-dessus d'une zone qui blesse, puis tu t'écrases en étourdissant tout ce qui s'y trouve.", "ability": "God of Thunder", "key": "Q", "kind": "default", "items": ["Avec un **bonus de dégâts** (Luna, Rocket), l'impact tue à travers une ult de soin.", "Elle vaut le plus dans un **passage étroit**.", "Dépense de la Thorforce juste avant : tu pars avec de la vie bonus.", "Ne la lance pas face à un **Punisher ou un Hawkeye en ult** : tu es une cible immobile en l'air."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Enchaîner les capacités **sans frapper**.", "Charger le dash **à la vue d'un étourdissement**.", "Activer l'Éveil **dans un bouclier**.", "Lancer l'ult **face à une ult de Duelist**.", "Affronter **The Thing** en duel au centre."], "diagram": ""}], "combos": [{"note": "Lance l'Éveil pendant que le marteau vole.", "steps": [{"key": "Clic D", "label": "lancer marteau"}, {"key": "", "label": "Éveil"}], "title": "Éveil en vol"}], "counters": [{"hero": "emma-frost", "note": "Elle charge son rayon sur toi et t'étrangle en plein dash."}, {"hero": "rogue", "note": "Elle te projette et peut voler ton Éveil."}, {"hero": "the-thing", "note": "Sa zone t'interdit de dasher, et tu ne peux pas l'emporter."}, {"hero": "the-punisher", "note": "Son tir continu perce ta vie bonus."}, {"hero": "moon-knight", "note": "Même usure à distance."}, {"hero": "invisible-woman", "note": "Sa poussée annule ton dash chargé."}], "synergies": [{"hero": "angela", "note": "Deux tanks qui déplacent les ennemis : personne n'est à l'abri dans leur équipe."}, {"hero": "hela", "note": "Tu chasses le tireur adverse de sa hauteur ; votre team-up la ramène à la vie."}, {"hero": "storm", "note": "Votre team-up ajoute un rayon de foudre, et son aura couvre ton engage."}, {"hero": "luna-snow", "note": "Son bonus de dégâts rend ton ult mortelle."}, {"hero": "captain-america", "note": "Votre team-up te donne un projectile de foudre."}], "sources": [{"url": "https://www.youtube.com/watch?v=_F5nOfRLy8A", "title": "Thor Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Divine Armory", "partners": ["angela"], "key": "", "text": "La lance de foudre rend de la Thorforce. **Amélioré :** Vie bonus sur le saut."}, {"name": "Gods of Thunder", "partners": ["storm"], "key": "", "text": "Rayon de foudre. **Amélioré :** Bolt Rush devient un éclair en chaîne qui rebondit."}, {"name": "Ragnarok Rebirth", "partners": ["hela"], "key": "", "text": "Une vie bonus empêche la mort et permet de revenir sur un kill. **Amélioré :** Résurrection instantanée."}, {"name": "Thunder Overdrive", "partners": ["iron-man"], "key": "", "text": "Armor Overdrive gagne en dégâts (anneau de l'Unibeam à 80/s en 10.5). **Amélioré :** Anneau à 90/s en 10.5."}, {"name": "Voltaic Union", "partners": ["captain-america"], "key": "", "text": "Projectile-bouclier de foudre (10 s depuis la saison 10). **Amélioré :** Explosion de zone à chaque touche."}], "changes": [{"season": "Saison 10", "text": "Vie de base 300 → 325, Lightning Realm 40 → 50 de dégâts."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'thor' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Ultron n'est pas un soigneur principal. Il pose un drone qui soigne un allié et ses voisins où qu'ils soient, distribue de la vie bonus au moment critique, gagne ses duels grâce à son laser et à sa mobilité, et charge très vite une ult polyvalente. Il se joue en troisième support, ou avec des volants.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["Prends des **angles** et cherche des éliminations : rester derrière à soigner, c'est mal le jouer.", "Le **drone** est toujours sur un allié, et il change de porteur selon qui se bat.", "Après le **pare-feu**, attaque : la vie bonus ne dure que quelques secondes."], "difficulty": 2, "tags": ["Vol", "Duels", "Vie bonus", "Anti-dive"], "strengths": ["Drone de soin sans cooldown, à toute distance", "Vie bonus de groupe à la demande", "Ult rapide qui soigne et blesse"], "weaknesses": ["Volume de soins insuffisant en support principal", "Cible facile pour les hitscans", "Fragile une fois ses cooldowns dépensés"], "playbook": [{"when": "Le fight commence", "then": "**Drone sur ton tank.** Dès qu'un DPS part en duel, déplace-le sur lui ; si ta backline est attaquée, sur tes supports."}, {"when": "L'adversaire engage (ult de Venom, burst de zone, flèche chargée)", "then": "**Pare-feu** au moment de l'impact : la vie bonus absorbe le burst. Puis contre-attaque."}, {"when": "Un diver te prend pour cible", "then": "Préviens ton autre support, **recule vers tes tanks**, et retournez-vous ensemble sur lui."}, {"when": "Une Hela ou un Punisher te vise", "then": "**Reviens derrière un couvert.** Voler ne te protège pas d'un hitscan."}, {"when": "Ton front se fait écraser", "then": "**Ult depuis un couvert**, puis sors : tes salves soignent tes tanks et blessent les leurs."}, {"when": "Une cible basse s'enfuit derrière un mur", "then": "Charge le laser à couvert, **vol rapide**, tir."}], "sections": [{"title": "Philosophie de jeu", "lead": "La plupart des joueurs voient Ultron comme un soigneur. C'est l'erreur : ses forces sont les duels, les éliminations et la vie bonus donnée au bon instant.", "ability": "", "key": "", "kind": "tips", "items": ["Il se joue **avec des volants** (Iron Man, Human Torch, Storm) ou dans une compo de dive. Dans un brawl au sol, il ne soigne pas assez.", "Joue **à couvert, même en vol** : le ciel n'arrête pas un hitscan.", "Un angle sûr suffit : inutile de partir loin sur un flanc.", "Ne passe pas la partie à tirer sur les tanks.", "Ultron et Hela sur le même angle forment un duo très difficile à déloger."], "diagram": "pocket"}, {"title": "Laser", "lead": "Un rayon instantané suivi d'une petite explosion. Une pression suffit : il n'y a rien à maintenir.", "ability": "", "key": "Clic G", "kind": "default", "items": ["Deux tirs complets tuent un héros fragile, **trois à longue distance**.", "**Commence le tir derrière un mur** et sors juste avant l'explosion.", "Un coup de mêlée à mi-rechargement annule la fin de l'animation."], "diagram": ""}, {"title": "Vol rapide", "lead": "Un dash dans n'importe quelle direction, suivi d'un bonus de vitesse et d'un peu de vie bonus. Le cooldown ne démarre qu'à la fin de l'accélération.", "ability": "Dynamic Flight", "key": "Maj", "kind": "default", "items": ["La hauteur se règle **avec le viseur**.", "Il sert à revenir du spawn, à fuir après une élimination trop avancée, ou à conclure un duel.", "C'est **la seule capacité utilisable pendant ton ult** : garde-la pour t'en sortir."], "diagram": ""}, {"title": "Drone", "lead": "Un drone qui soigne son porteur, les alliés autour de lui, et toi si tu restes à proximité. Il n'a pas de cooldown.", "ability": "Imperative: Patch", "key": "", "kind": "default", "items": ["Il revient vers toi si son porteur est **trop loin ou hors de vue** trop longtemps : repasse régulièrement à portée.", "Posé sur un **volant**, il vous soigne tous les deux tant que vous volez ensemble.", "Si une Luna a déjà marqué ton diver, mets plutôt le drone sur les tanks.", "Un drone inactif est la faute la plus coûteuse du héros."], "diagram": ""}, {"title": "Pare-feu", "lead": "De la vie bonus pour toi et pour les alliés proches de toi ou de ton drone. Elle s'estompe en quelques secondes.", "ability": "Imperative: Firewall", "key": "Clic D", "kind": "default", "items": ["La zone est **une sphère autour de toi et une autre autour du drone** : si le drone est en l'air, les alliés au sol ne reçoivent rien.", "Il **empêche une élimination en un coup** : flèche de Hawkeye, baleine de Namor.", "Garde-le pour **le moment où l'ennemi engage**.", "Il donne moins de vie bonus et de vitesse aux alliés depuis la saison 11 (25 au lieu de 40) : le timing compte encore davantage."], "diagram": "", "scene": {"title": "Le pare-feu au moment de l'engage", "caption": "La vie bonus ne dure que quelques secondes. Posée au moment exact du burst adverse, elle l'annule.", "steps": ["Ton drone est sur l'allié qui se bat.", "L'adversaire engage : pare-feu, autour de toi et autour du drone.", "Le burst est absorbé : ton équipe contre-attaque."], "els": [{"t": "pawn", "at": [56, 50], "team": "me"}, {"t": "zone", "at": [56, 50], "r": 24, "team": "me"}, {"t": "note", "at": [92, 30], "text": "2", "team": "me"}, {"t": "pawn", "at": [150, 104], "team": "ally", "role": "tank"}, {"t": "mark", "at": [150, 78], "kind": "turret", "team": "me"}, {"t": "note", "at": [150, 62], "text": "drone", "team": "me"}, {"t": "note", "at": [182, 70], "text": "1", "team": "me"}, {"t": "zone", "at": [150, 104], "r": 34, "team": "me"}, {"t": "pawn", "at": [118, 128], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [176, 134], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [54, 116], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [256, 64], "team": "enemy", "role": "tank", "ghost": true}, {"t": "path", "kind": "move", "team": "enemy", "pts": [[256, 64], [210, 70], [182, 92]]}, {"t": "pawn", "at": [250, 124], "team": "enemy", "role": "dps"}, {"t": "path", "kind": "shot", "team": "enemy", "pts": [[250, 124], [182, 112]]}, {"t": "path", "kind": "shot", "team": "ally", "pts": [[118, 128], [242, 150]], "n": 3}, {"t": "pawn", "at": [250, 152], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [292, 84], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [268, 28], "team": "enemy", "role": "dps"}]}}, {"title": "Ultime", "lead": "Quatre drones apparaissent et tirent des salves qui soignent tes alliés et blessent les ennemis. Tu ne peux pas être étourdi, et tu peux utiliser ton vol rapide.", "ability": "Rage of Ultron", "key": "Q", "kind": "default", "items": ["Lance-la **derrière un couvert**, puis sors pendant que les drones tirent.", "C'est une ult de **retournement** : elle soigne tes tanks pendant qu'elle use les leurs.", "Les salves **se visent** : ce n'est pas une zone automatique.", "Elle répond bien aux menaces sur une cible : Magik, Iron Fist, Winter Soldier.", "Elle se recharge très vite si tu touches : tu peux gagner le cycle d'ults contre les supports adverses."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Rester **en retrait à soigner**.", "Laisser le **drone** sans porteur.", "Lancer le pare-feu **sans attaquer** ensuite.", "Voler **à découvert** face à un hitscan.", "Insister quand ton équipe manque de soins : **change de support**."], "diagram": ""}], "combos": [], "counters": [{"hero": "hela", "note": "Deux tirs à la tête dès que tu quittes un couvert."}, {"hero": "hawkeye", "note": "Sa flèche hypersonique te cloue au sol."}, {"hero": "the-punisher", "note": "Son tir continu te suit en l'air."}, {"hero": "star-lord", "note": "Il te poursuit en vol et gagne le duel rapproché."}, {"hero": "adam-warlock", "note": "Un hitscan de plus, côté supports."}, {"hero": "black-widow", "note": "Elle te tue de loin, surtout avec un bonus de dégâts."}], "synergies": [{"hero": "iron-man", "note": "Ton drone le soigne en l'air, et votre team-up lui donne un rayon de soin."}, {"hero": "captain-america", "note": "Le drone le suit pendant ses dives."}, {"hero": "psylocke", "note": "Même principe : un soin qui ne demande aucune ligne de vue."}, {"hero": "hela", "note": "Vous tenez le même angle, et tu la soignes en te battant."}, {"hero": "storm", "note": "Elle vole près de toi et son aura renforce ton laser."}, {"hero": "luna-snow", "note": "Elle assure le volume de soins que tu n'as pas."}], "sources": [{"url": "https://www.youtube.com/watch?v=YKcxUGf25Es", "title": "Ultron Guide", "author": "Paz (padswagger)"}, {"title": "The Only Ultron Guide You'll Ever Need", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=YXCTyF__Y0c"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Flawless Design", "partners": ["adam-warlock"], "key": "", "text": "Les Cosmic Cluster d'Adam soignent les alliés (18 par projectile en 10.5). **Amélioré :** Explosion de soin à l'impact (7 en 10.5)."}, {"name": "SP//DR Sync", "partners": ["peni-parker"], "key": "", "text": "Imperative: Patch s'applique aux alliés. **Amélioré :** Les drones cumulent les effets de Firewall."}, {"name": "Stark Protocol", "partners": ["iron-man"], "key": "", "text": "Nano-rayon qui soigne et blesse. **Amélioré :** Tire des missiles à tête chercheuse."}], "changes": [{"season": "Saison 11", "text": "Imperative: Firewall : vie bonus des alliés 40 → 25, bonus de vitesse 20 % → 10 %."}, {"season": "Saison 10", "text": "Firewall : vie bonus 65 → 40 pour Ultron, 50 → 40 pour les alliés ; nouvel auto-soin de 20/s pendant 3 s."}, {"season": "Saison 10", "text": "Tous les Strategists : l'ult se charge un peu moins vite (65 % du soin et 50 % des dégâts convertis en énergie, au lieu de 70 % et 55 %)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'ultron' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Venom est un Vanguard de dive. Il passe derrière l'équipe adverse, force ses cooldowns défensifs et la retient sur place, puis attend que son équipe soit en mesure de conclure. Il n'a pas besoin de tuer : la pression qu'il exerce ouvre le fight pour les autres.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["**Engage depuis un mur** avec le saut écrasé ; le balancement sert à **ressortir**.", "Lance ta **vie bonus vers 150 à 200 PV** : ni trop tôt, ni trop tard.", "Ne saute pas en tous sens : **un pas de côté** suffit, et tu vises mieux."], "difficulty": 2, "tags": ["Dive", "Pression", "Vie bonus", "Mobilité"], "strengths": ["Entrée et sortie les plus fiables des Vanguards", "Vie bonus proportionnelle aux dégâts subis", "Ult en pourcentage de la vie"], "weaknesses": ["Très large hitbox", "Peu de protection pour son équipe", "Vie bonus retirée par Phoenix"], "playbook": [{"when": "Tu veux entrer sur la backline", "then": "**Grimpe sur un mur, puis saut écrasé** directement sur la cible. Garde le balancement."}, {"when": "Tu viens d'atterrir sur les supports", "then": "**Tentacules corrosives** : ils doivent s'éloigner ou encaisser un pic de dégâts. Déplace-toi pour les en empêcher."}, {"when": "Ta vie descend vers 150 à 200 PV", "then": "**Vie bonus maintenant.** Plus tôt, tu en reçois peu ; plus tard, tu meurs avant."}, {"when": "Tes cooldowns sont dépensés, ou la vie bonus fond", "then": "**Balancement**, accroché bas sur un mur, pour partir à l'horizontale."}, {"when": "Une Luna adverse est proche d'avoir son ult", "then": "Colle-la avec ta vie bonus active : les dégâts sur la vie bonus **ne chargent pas** son ult."}, {"when": "Jeff sort pour avaler ton équipe", "then": "**Ult** et ressurgis sous lui."}], "sections": [{"title": "Philosophie de jeu", "lead": "Venom force les cooldowns le plus tôt possible, pour garder sa vie bonus jusqu'au moment où son équipe peut suivre.", "ability": "", "key": "", "kind": "tips", "items": ["Après un fight gagné, monte **au-dessus d'un passage**, laisse passer leurs tanks, puis tombe sur leurs supports.", "Sache **où est ton équipe** : un dive que personne ne suit ne vaut rien.", "Pas d'élimination ? Tu as retenu deux supports loin de leur front : ton équipe gagne à l'avant.", "Pour sortir vite du spawn : balancement, puis sauts enchaînés (saut sur la molette)."], "diagram": "dive"}, {"title": "Tentacules", "lead": "Des salves de tentacules à bonne portée, qui peuvent toucher la tête. Depuis la saison 11, elles touchent un peu plus large.", "ability": "", "key": "Clic G", "kind": "default", "items": ["Reste **à mi-distance** : la tête se touche mieux qu'au contact.", "Les sauts inutiles ruinent ta visée.", "Sur une cible unique, intercale des **coups de mêlée**."], "diagram": ""}, {"title": "Tentacules corrosives", "lead": "Tous les ennemis proches sont attachés et ralentis. S'ils ne s'éloignent pas à temps, ils subissent un gros pic de dégâts.", "ability": "Cellular Corrosion", "key": "Clic D", "kind": "default", "items": ["Utilise-les **à chaque engage** : elles forcent les cooldowns et séparent les cibles de leur équipe.", "**Suis les cibles** pour qu'elles ne puissent pas sortir de la portée.", "Elles s'accrochent aussi aux **héros invisibles**."], "diagram": ""}, {"title": "Balancement et murs", "lead": "Un balancement très rapide, accroché au décor, et la capacité de courir sur les murs et les plafonds.", "ability": "Venom Swing · Alien Biology", "key": "Maj", "kind": "default", "items": ["Le balancement est ta **sortie**. Accroché **bas sur un mur**, tu pars à l'horizontale, hors de vue des tireurs.", "Courir sur un mur s'entend : les supports savent que tu arrives.", "En duel près d'un mur, **monte et écrase-toi** sur la cible."], "diagram": ""}, {"title": "Saut écrasé", "lead": "Tu bondis et tu t'écrases au sol en projetant les ennemis. Les dégâts baissent quand tu tombes à côté de la cible.", "ability": "Frenzied Arrival", "key": "", "kind": "default", "items": ["Vise **la cible elle-même** : depuis la saison 11, les dégâts chutent davantage au-delà de trois mètres.", "Tu ne peux pas être gelé en vol, mais un bon support **attendra ton atterrissage**.", "Enchaînement : **mur, saut écrasé, tentacules corrosives, tirs**."], "diagram": "", "scene": {"title": "Entrer par le mur, sortir au balancement", "caption": "Le saut écrasé t'amène ; le balancement te ramène. Dépenser le second pour entrer, c'est rester dans la backline adverse.", "steps": ["Tu grimpes sur un mur, puis saut écrasé sur les supports.", "Tentacules corrosives : ils sont retenus. Vie bonus vers 150 à 200 PV.", "Balancement, accroché bas, pour ressortir."], "els": [{"t": "cover", "at": [170, 6], "size": [70, 16], "label": "Mur"}, {"t": "pawn", "at": [190, 34], "team": "me", "ghost": true}, {"t": "path", "kind": "move", "team": "me", "pts": [[190, 34], [250, 30], [268, 74]], "n": 1}, {"t": "zone", "at": [272, 88], "r": 28, "team": "me", "n": 2}, {"t": "pawn", "at": [286, 78], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [292, 108], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [266, 90], "team": "me", "ghost": true}, {"t": "path", "kind": "move", "team": "me", "pts": [[262, 98], [200, 170], [128, 132]], "n": 3}, {"t": "pawn", "at": [122, 128], "team": "me"}, {"t": "pawn", "at": [216, 96], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [236, 142], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [238, 54], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [110, 74], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [76, 96], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [40, 80], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [46, 136], "team": "ally", "role": "heal"}]}}, {"title": "Vie bonus", "lead": "Tu gagnes de la vie bonus en proportion de la vie qui te manque : plus tu es blessé, plus tu en reçois.", "ability": "Symbiotic Resilience", "key": "", "kind": "default", "items": ["Elle a été réduite en saison 11 (525 au lieu de 595 à 300 PV restants) : **le bon moment compte plus qu'avant**.", "Les dégâts sur la vie bonus **ne chargent pas** les ults adverses.", "**Survis** après l'avoir lancée : mourir avec, c'est avoir offert de l'ult pour rien.", "Phoenix la retire avec son ult ; celle d'Ultron la fait fondre."], "diagram": ""}, {"title": "Ultime", "lead": "Tu t'enfouis et tu te déplaces très vite, puis tu ressurgis en dévorant un pourcentage de la vie des ennemis autour de toi, converti en vie bonus.", "ability": "Feast of the Abyss", "key": "Q", "kind": "default", "items": ["Elle **prolonge un engage** sur les supports, ou force leurs ults.", "Avec un **bonus de dégâts** (Luna, Rocket) : tentacules corrosives, puis ressurgis au moment où leur pic tombe. Cela tue à travers une ult de soin.", "Enfoui, ta tête reste touchable, et l'ennemi peut te barrer le passage."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["**Entrer au balancement** et ne plus pouvoir sortir.", "Sauter sans arrêt et **rater ses tirs**.", "Lancer la vie bonus **trop tôt**.", "Diver **sans équipe** derrière.", "S'écraser **à côté** de la cible."], "diagram": ""}], "combos": [{"note": "", "steps": [{"key": "", "label": "Mur"}, {"key": "", "label": "Saut écrasé"}, {"key": "Clic D", "label": "tentacules"}, {"key": "Clic G", "label": "tirs"}], "title": "Engage"}], "counters": [{"hero": "emma-frost", "note": "Elle charge son rayon sur toi, puis t'étrangle à l'atterrissage."}, {"hero": "the-thing", "note": "Sa zone t'interdit le balancement : tu ne ressors pas."}, {"hero": "thor", "note": "Son dôme bloque aussi ta sortie."}, {"hero": "the-punisher", "note": "Ton énorme hitbox sous son tir continu."}, {"hero": "phoenix", "note": "Son ult retire toute ta vie bonus."}, {"hero": "luna-snow", "note": "Elle te gèle au moment où tu touches le sol."}], "synergies": [{"hero": "captain-america", "note": "Il arrive par l'autre côté : la backline ne peut pas regarder partout."}, {"hero": "psylocke", "note": "Tu retiens les supports, elle les tue."}, {"hero": "black-widow", "note": "Elle achève de loin les cibles que tu as attachées."}, {"hero": "jeff-the-land-shark", "note": "Il harcèle la même backline et te soigne en passant."}, {"hero": "luna-snow", "note": "Sa marque sur toi, et son bonus de dégâts pour ton ult."}, {"hero": "gorr-the-god-butcher", "note": "Votre team-up lui donne une griffe qui attire les ennemis."}], "sources": [{"url": "https://www.youtube.com/watch?v=3HMlrN1UxIc", "title": "Venom Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Abyssal Flames", "partners": ["phoenix"], "key": "", "text": "Les griffes de Venom posent des étincelles de Phoenix, qui explosent à 3 cumuls."}, {"name": "Blood Leech", "partners": ["blade"], "key": "", "text": "Cellular Corrosion vole de la vie. **Amélioré :** Ajoute un soin ponctuel."}, {"name": "Guardian of the Deep", "partners": ["jeff-the-land-shark"], "key": "", "text": "Tentacules de soin qui donnent de la vie bonus. **Amélioré :** Ajoute des coups de fouet qui blessent."}, {"name": "Hel Tendrils", "partners": ["hela"], "key": "", "text": "Des tentacules attirent et ralentissent les ennemis. **Amélioré :** Les Nightsword Thorns soignent en plus."}, {"name": "Hive Mind", "partners": ["gorr-the-god-butcher"], "key": "", "text": "Une griffe de symbiote attire les ennemis. **Amélioré :** Ajoute un boost de dégâts et un ralentissement."}, {"name": "Symbiote Bond", "partners": ["spider-man"], "key": "", "text": "Pointes de symbiote qui repoussent les ennemis. **Amélioré :** Ajoute des tentacules qui relient."}], "changes": [{"season": "Saison 11", "text": "Dark Predation : zone de détection légèrement agrandie."}, {"season": "Saison 11", "text": "Frenzied Arrival : la baisse de dégâts avec la distance commence à 3 m (au lieu de 2) et atteint 60 % à 6 m (au lieu de 40 %)."}, {"season": "Saison 11", "text": "Symbiotic Resilience : vie bonus de base 100 → 75, part de la vie manquante 110 % → 100 % (à 300 PV restants : 595 → 525)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'venom' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "White Fox est une Strategist d'utilitaires. Elle soigne avec des projectiles à rebond, charme un ennemi avec son renard spectral, se téléporte sur un allié en danger, puis passe en forme de renard pour se battre au corps à corps quand son équipe engage. Son ult rend un allié insensible aux contrôles.", "patch_note": "White Fox a été rééquilibrée en saison 11 : son renard spectral ne rend plus les alliés invulnérables et le bouclier de sa téléportation est réduit, mais sa forme de renard dure plus longtemps et son ult peut être soignée. Le guide tient compte de ces changements.", "tldr": ["**Touche directement** tes cibles : un tir raté, c'est du soin et de la charge d'ult perdus.", "Garde des **queues spirituelles** pour la forme de renard : elle dure désormais jusqu'à 12 secondes.", "Passe en **forme de renard** quand ton équipe engage, ou quand un diver te tombe dessus."], "difficulty": 3, "tags": ["Utilitaire", "Téléportation", "Corps à corps", "Brawl"], "strengths": ["Téléportation sur un allié à travers les murs", "Charme qui annule un déplacement adverse", "Forme de renard longue et autonome"], "weaknesses": ["Plus d'invulnérabilité pour ses alliés (saison 11)", "Soins dépendants de sa précision", "Ult volumineuse et sans mobilité"], "playbook": [{"when": "Un allié se fait attaquer loin de toi (ta Hela sur son angle, ton diver)", "then": "**Téléportation sur lui** : soin immédiat et petit bouclier. Reste ensuite à couvert avec lui."}, {"when": "Un diver s'apprête à utiliser son déplacement (Black Panther, Venom, Hulk)", "then": "**Renard spectral** en plein sur lui : charmé, il marche vers toi au lieu de sauter. Il faut désormais toucher juste."}, {"when": "Un diver t'attaque seule", "then": "**Forme de renard** : tes griffes te soignent, et tu gagnes le duel contre la plupart des divers isolés."}, {"when": "Ton équipe engage et l'ennemi vient de dépenser un gros cooldown", "then": "Forme de renard, **bond** derrière une cible, puis seconde partie du bond pour la pousser vers ton équipe."}, {"when": "Ton front prend l'avantage sur le point", "then": "Téléportation sur lui, puis **ult** : tu soignes autour de toi et tu rends un allié insensible aux contrôles."}, {"when": "Un allié lance une ult canalisée (Doctor Strange, Scarlet Witch)", "then": "**Bénédiction de l'ult sur lui** : personne ne peut l'interrompre."}], "sections": [{"title": "Philosophie de jeu", "lead": "Lis ce que l'adversaire joue et prépare, puis choisis l'utilitaire qui y répond. L'objectif reste d'avoir ton ult, mais le chemin dépend de la compo.", "ability": "", "key": "", "kind": "tips", "items": ["**En brawl**, téléportation et forme de renard pour te battre avec ton front.", "**En poke**, téléporte-toi sur ton tireur quand il est en duel.", "Elle s'entend surtout avec les **divers** : suis-les à portée de téléportation.", "Boucle de jeu : **accumuler deux queues**, prendre un angle ou un duel, exécuter, **se téléporter** vers son équipe.", "Depuis la saison 11, tu ne peux plus sauver un allié d'une ult par l'invulnérabilité : ta protection passe par la **téléportation et le soin**."], "diagram": "heal"}, {"title": "Billes de renard", "lead": "Des projectiles qui soignent ou blessent, puis rebondissent une fois vers une cible proche.", "ability": "Fox Marbles", "key": "Clic G", "kind": "default", "items": ["L'essentiel du soin est dans **le premier impact** : vise la cible, pas ses environs.", "Sur une cible lointaine ou très mobile, vise **ses pieds ou le mur derrière elle**.", "Elles chargent tes **queues spirituelles**."], "diagram": ""}, {"title": "Renard spectral", "lead": "Un renard qui traverse les cibles en soignant les alliés et en blessant les ennemis. Il coûte une queue. S'il touche un ennemi de plein fouet, il le charme : l'ennemi marche vers toi un instant.", "ability": "Spectral Surge", "key": "Clic D", "kind": "default", "items": ["Depuis la saison 11, il **ne rend plus les alliés invulnérables**, et la zone de charme est plus étroite.", "Le charme **annule un déplacement** : lance-le quand le diver s'apprête à bondir, pas après.", "Il **interrompt une ult canalisée** comme celle de Doctor Strange.", "Dans un fight neutre, **aligne le plus de cibles possible** : il soigne et blesse tout ce qu'il traverse."], "diagram": ""}, {"title": "Forme de renard", "lead": "Tu consommes toutes tes queues pour passer au corps à corps : tes griffes te soignent, toi et les alliés proches, et tu gagnes un bond et un coup de queue.", "ability": "Fox Form Awakening", "key": "", "kind": "default", "items": ["Depuis la saison 11, elle dure **8 secondes, plus 2 par queue** (12 au maximum), les griffes frappent plus fort et le bond revient en 4 secondes.", "**Contre le dive**, c'est ton outil de survie.", "**Contre un brawl**, passe en renard quand l'adversaire vient de dépenser un gros cooldown.", "Le **bond** te place derrière la cible ; sa seconde partie la **pousse vers ton équipe**.", "Le **coup de queue** achève ou repousse.", "**Recharge avant** de te transformer, et vérifie que ton équipe est là."], "diagram": ""}, {"title": "Téléportation", "lead": "Tu te téléportes sur un allié, à travers les murs. Vous êtes soignés tous les deux et un bouclier apparaît autour de vous.", "ability": "Spirit Sanctuary", "key": "", "kind": "default", "items": ["Le bouclier a été **divisé par deux** en saison 11 (100) : il arrête un tir, plus une ult.", "Il **n'a pas de toit** : inutile sous un Magneto ou un Iron Man.", "**Feinte** : laisse un diver venir sur toi, puis disparais vers un allié.", "C'est ta **survie** : ne la dépense pour attaquer que si l'élimination est quasi certaine.", "Bond et téléportation ont des cooldowns séparés : bond, sortie de la forme, téléportation."], "diagram": "", "scene": {"title": "Suivre son diver", "caption": "Tu n'entres pas dans la backline adverse : tu restes à portée de téléportation, et tu y vas quand il en a besoin.", "steps": ["Ton diver entre sur les supports adverses.", "Tu le soignes de loin, à portée de téléportation.", "Il est en danger : tu te téléportes sur lui, soin immédiat."], "els": [{"t": "cover", "at": [186, 44], "size": [16, 60], "label": "Mur"}, {"t": "pawn", "at": [96, 44], "team": "ally", "role": "dps", "ghost": true}, {"t": "path", "kind": "move", "team": "ally", "pts": [[96, 44], [180, 4], [262, 56]], "n": 1}, {"t": "pawn", "at": [266, 62], "team": "ally", "hero": "magik", "above": true}, {"t": "pawn", "at": [96, 124], "team": "me", "ghost": true}, {"t": "path", "kind": "heal", "team": "me", "pts": [[96, 124], [160, 160], [254, 74]], "n": 2}, {"t": "path", "kind": "move", "team": "me", "pts": [[106, 120], [190, 124], [246, 92]], "n": 3}, {"t": "pawn", "at": [246, 96], "team": "me"}, {"t": "zone", "at": [256, 78], "r": 26, "team": "me"}, {"t": "pawn", "at": [296, 74], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [294, 118], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [214, 140], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [262, 160], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [130, 96], "team": "ally", "role": "tank"}, {"t": "pawn", "at": [60, 156], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [46, 80], "team": "ally", "role": "heal"}]}}, {"title": "Ultime", "lead": "Tu deviens un renard à neuf queues, avec beaucoup de vie. Tu soignes autour de toi, et tu peux bénir des alliés : ils deviennent insensibles aux contrôles et volent de la vie.", "ability": "Kumiho Unleashed", "key": "Q", "kind": "default", "items": ["Depuis la saison 11, **tes alliés peuvent te soigner** pendant l'ult ; en contrepartie, tu as moins de vie (1000).", "Lance-la **en premier**, pendant une vraie poussée, pas en réaction.", "Reste **derrière tes tanks** : ta hitbox est énorme et tu n'as plus de mobilité.", "Bénis **un allié en ult** (Star-Lord, Doctor Strange) ou **tes tanks** au front. Chaque bénédiction te coûte de la vie.", "Frapper les ennemis augmente tes soins."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Viser **à côté** en comptant sur le rebond.", "Compter encore sur le renard spectral pour **sauver un allié d'une ult**.", "Passer en renard **sans son équipe**.", "Dépenser la téléportation **pour attaquer**.", "Lancer l'ult **en réaction**, comme une ult de Luna."], "diagram": ""}], "combos": [], "counters": [{"hero": "hela", "note": "Elle te domine sur les longues lignes de vue."}, {"hero": "phoenix", "note": "Son burst passe ton petit bouclier, et son ult détruit ta vie bonus."}, {"hero": "the-thing", "note": "Sa zone interdit ton bond et ta téléportation."}, {"hero": "the-punisher", "note": "Ta large hitbox en ult sous son tir continu."}, {"hero": "wolverine", "note": "Ses dégâts en pourcentage te tuent pendant l'ult."}, {"hero": "angela", "note": "Elle peut t'emporter loin de ton équipe."}], "synergies": [{"hero": "luna-snow", "note": "Elle apporte le volume de soins ; votre team-up donne un renard qui soigne et blesse davantage en saison 11."}, {"hero": "groot", "note": "Ses murs créent les fights serrés où ta forme de renard vaut le plus."}, {"hero": "emma-frost", "note": "Un front de brawl à suivre."}, {"hero": "magik", "note": "Une diver à accompagner à portée de téléportation."}, {"hero": "star-lord", "note": "Ta bénédiction le rend impossible à interrompre pendant son ult."}, {"hero": "psylocke", "note": "Votre team-up réduit le coût de ta forme de renard."}], "sources": [{"url": "https://www.youtube.com/watch?v=agc2g5G7fwM", "title": "White Fox Guide", "author": "Paz (padswagger)"}, {"title": "Ultimate White Fox Guide (Beginner/Advanced)", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=H9G10NfC2TI"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Atlas Bond", "partners": ["luna-snow"], "key": "", "text": "Un renard spirituel soigne les alliés (80) et blesse les ennemis (45). Il ne charme plus depuis la saison 11. **Amélioré :** Le renard revient tout seul."}, {"name": "Kumiho Palm", "partners": ["iron-fist"], "key": "", "text": "Yat Jee Chung Kuen soigne les alliés. **Amélioré :** Portée de verrouillage augmentée."}, {"name": "Lucky Loan", "partners": ["black-cat"], "key": "", "text": "Un orbe de vie alimente l'aura à neuf queues. **Amélioré :** Les queues spirituelles ne coûtent plus rien."}, {"name": "Psionic Fox", "partners": ["psylocke"], "key": "", "text": "La forme de renard ne coûte plus d'énergie. **Amélioré :** Cooldown fortement réduit."}], "changes": [{"season": "Saison 11", "text": "Spirit Sanctuary : bouclier 200 → 100. Spectral Surge : plus d'invincibilité pour les alliés, rayon du charme 0,6 → 0,4 m."}, {"season": "Saison 11", "text": "Forme de renard : durée 7 → 8 s, +2 s par queue spirituelle (12 s max au lieu de 9) ; Claw Strike 35 → 40, cooldown de Predatory Pounce 6 → 4 s."}, {"season": "Saison 11", "text": "Kumiho Unleashed : peut être soignée par ses alliés pendant l'ult ; vie pendant l'ult 1200 → 1000."}, {"season": "Saison 10", "text": "Yeowoo Guseul : soin direct 50 → 55, rebond 35 → 40 ; zone de la forme de renard 35 → 40."}, {"season": "Saison 10", "text": "Tous les Strategists : l'ult se charge un peu moins vite (65 % du soin et 50 % des dégâts convertis en énergie, au lieu de 70 % et 55 %)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'white-fox' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Winter Soldier est un Duelist de front. Il joue avec ses tanks, attrape les ennemis au crochet, les déplace hors de portée de leurs soins et les achève au canon. Chacune de ses capacités recharge son arme et lui donne de la vie bonus.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["Joue **avec tes tanks** : c'est là que ton crochet vaut le plus.", "Chaque capacité **recharge ton canon** : tirs, capacité, tirs, capacité.", "Ton ult n'a pas à remplir le tableau : **une élimination et tu survis**, c'est gagné."], "difficulty": 2, "tags": ["Brawl", "Grappin", "Vie bonus", "Anti-dive"], "strengths": ["Crochet : contrôle dur qui interrompt les ults", "Ne recharge jamais s'il enchaîne bien", "Ult qui se relance à chaque élimination"], "weaknesses": ["Portée efficace réduite (30 m en saison 11)", "Crochet bloqué par murs, boucliers et bulles", "Dépend de son équipe pour conclure"], "playbook": [{"when": "Le tank adverse s'avance", "then": "**Crochet**, passe derrière lui, **uppercut** vers ton équipe, de préférence derrière un mur : ses supports ne le voient plus."}, {"when": "Un héros fragile est à portée de crochet", "then": "**Crochet, tir à la tête, uppercut, tir.**"}, {"when": "Un diver saute sur tes supports (Black Panther, Spider-Man)", "then": "**Uppercut ou boule d'énergie** sur lui : il est arrêté net, puis crochet s'il tente de fuir."}, {"when": "Un ennemi canalise une ult (Doctor Strange, Iron Man, Star-Lord)", "then": "**Crochet** : le mini-étourdissement l'interrompt."}, {"when": "Une ult de soin adverse est active", "then": "**Charge ton crochet** et sors un ennemi de la zone, ou prépare ton ult par-dessus avec un allié."}, {"when": "Tu viens de tuer avec ton ult", "then": "Ne la relance pas aussitôt : attends une cible **déjà entamée**, sinon tu perds la relance."}], "sections": [{"title": "Philosophie de jeu", "lead": "Comme Wolverine, il prépare le terrain pour son front en déplaçant les ennemis, surtout les tanks. C'est aussi l'un des meilleurs gardiens de backline.", "ability": "", "key": "", "kind": "tips", "items": ["Reste **près de ton tank** : une cible attrapée est aussitôt coupée de ses soins.", "Tu es un **peeler** : près de tes supports, tu punis Black Panther, Spider-Man et les autres divers.", "**Annonce qui tu attrapes** et sur qui tu lances ton ult : tu dépends de ceux qui tirent avec toi.", "Les fights sont longs : tu as le temps d'attendre la bonne ouverture."], "diagram": "pull"}, {"title": "Canon", "lead": "Trois tirs explosifs par chargeur. Un tir direct fait mal, et l'explosion touche aussi ce qui se trouve derrière la cible.", "ability": "Roterstern", "key": "Clic G", "kind": "default", "items": ["Deux tirs à la tête tuent un héros fragile.", "**N'importe quelle capacité** recharge entièrement le canon, même si elle rate.", "Depuis la saison 11, les dégâts baissent plus tôt avec la distance (minimum atteint à 30 mètres) : **reste juste derrière tes tanks**.", "Enchaînement de contact : **tir à la tête, uppercut, mêlée**."], "diagram": ""}, {"title": "Passif", "lead": "Chaque capacité te donne de la vie bonus, qui s'estompe ensuite.", "ability": "Ceaseless Charge", "key": "", "kind": "default", "items": ["Crochet, uppercut et boule d'énergie enchaînés te rendent **très solide** au front.", "Ne dépense pas une capacité uniquement pour la vie bonus : elle doit aussi recharger ton canon au bon moment."], "diagram": ""}, {"title": "Grappin", "lead": "Un crochet qui porte plus loin s'il est chargé. Il peut attraper plusieurs ennemis côte à côte et applique un mini-étourdissement.", "ability": "Bionic Hook", "key": "", "kind": "default", "items": ["C'est un **contrôle dur** : il interrompt une ult et sort un Cloak & Dagger de la sienne.", "Pendant que le crochet ramène la cible, **tourne ton viseur** pour la déposer derrière un couvert.", "Charge-le quand **un bouclier adverse va tomber**.", "La charge maximale fait un bruit reconnaissable : l'adversaire sait que tu es prêt.", "Il est arrêté par **les murs, les boucliers et les bulles**."], "diagram": "", "scene": {"title": "Crochet, puis uppercut", "caption": "Le crochet amène le tank à toi. L'uppercut l'envoie derrière ton mur, là où ses supports ne peuvent plus le soigner.", "steps": ["Crochet sur le tank qui s'avance.", "Tu passes derrière lui : uppercut vers ton équipe.", "Derrière le mur, sans soin, il meurt."], "els": [{"t": "cover", "at": [128, 26], "size": [16, 70], "label": "Mur"}, {"t": "pawn", "at": [262, 96], "team": "enemy", "role": "tank", "ghost": true}, {"t": "path", "kind": "pull", "team": "me", "pts": [[262, 96], [206, 110]], "n": 1}, {"t": "pawn", "at": [198, 112], "team": "enemy", "role": "tank", "ghost": true}, {"t": "pawn", "at": [140, 134], "team": "me", "ghost": true}, {"t": "path", "kind": "move", "team": "me", "pts": [[140, 134], [190, 168], [232, 134]], "n": 2}, {"t": "pawn", "at": [236, 128], "team": "me"}, {"t": "path", "kind": "push", "team": "me", "pts": [[190, 110], [140, 116], [100, 76]]}, {"t": "pawn", "at": [96, 68], "team": "enemy", "role": "tank", "label": "Sans soin"}, {"t": "note", "at": [64, 40], "text": "3", "team": "ally"}, {"t": "pawn", "at": [56, 66], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [70, 112], "team": "ally", "role": "tank"}, {"t": "path", "kind": "shot", "team": "ally", "pts": [[56, 66], [86, 68]]}, {"t": "pawn", "at": [36, 130], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [96, 156], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [292, 60], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [296, 130], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [246, 36], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [280, 164], "team": "enemy", "role": "dps"}]}}, {"title": "Dash et boule d'énergie", "lead": "Un uppercut en dash qui emporte les ennemis devant toi, même à travers un bouclier, et deux charges d'une boule d'énergie qui traverse et ralentit.", "ability": "Trooper's Fist · Tainted Voltage", "key": "Maj", "kind": "default", "items": ["L'uppercut **traverse les boucliers** de Strange et de Magneto, mais te laisse exposé de l'autre côté.", "Il sert à **entrer ou à sortir**, pas aux deux.", "La boule d'énergie **ralentit** et fait tomber les volants (Iron Man, Human Torch, Storm, Ultron).", "Ne la lance pas dans un bouclier.", "Garde une boule pour enchaîner six tirs sans recharger."], "diagram": ""}, {"title": "Ultime", "lead": "Tu bondis, puis tu t'écrases sur une zone en marquant les ennemis touchés. Ceux qui passent sous un seuil de vie meurent, et chaque élimination d'une cible marquée te rend l'ult.", "ability": "Kraken Impact", "key": "Q", "kind": "default", "items": ["**Entame d'abord une cible**, puis lance l'ult dessus : la relance est presque assurée.", "N'importe quelle élimination sur une cible marquée te rend l'ult, même par un allié.", "Vise d'abord les **supports qui ont leur ult**.", "Face à des ults de soin prêtes, **force-les d'abord** avec ton kit.", "Elle sert aussi à **défendre** : écrase-toi sur un diver qui a dépensé ses cooldowns.", "Les clones de Loki comptent pour la relance."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Jouer **sur un flanc**, comme une Psylocke.", "Lancer crochet et boules **dans un bouclier**.", "Traverser le front à l'uppercut et **mourir de l'autre côté**.", "S'enfoncer trop loin **pendant l'ult**.", "Recharger à la main au lieu d'**utiliser une capacité**."], "diagram": ""}], "combos": [{"note": "", "steps": [{"key": "Clic G", "label": "tête"}, {"key": "Maj", "label": "dash"}, {"key": "Mêlée", "label": ""}], "title": "Tuer un fragile"}], "counters": [{"hero": "emma-frost", "note": "Elle pose son bouclier dès qu'elle entend ton crochet se charger."}, {"hero": "magneto", "note": "Sa bulle annule ton crochet et protège ta cible."}, {"hero": "the-thing", "note": "Tu ne peux pas le déplacer."}, {"hero": "hela", "note": "Elle te domine à une distance où ton canon ne fait plus rien."}, {"hero": "iron-man", "note": "Un bon volant évite tes boules d'énergie."}, {"hero": "hawkeye", "note": "Une flèche chargée avant que tu sois à portée."}], "synergies": [{"hero": "groot", "note": "Il ferme un mur derrière chaque cible que tu attrapes."}, {"hero": "magneto", "note": "Tu déposes tes cibles derrière son rideau."}, {"hero": "doctor-strange", "note": "Même principe derrière son bouclier."}, {"hero": "the-punisher", "note": "Deux sources de dégâts sur le même tank."}, {"hero": "peni-parker", "note": "Tu attires les ennemis sur ses mines."}, {"hero": "captain-america", "note": "Votre team-up te fait bondir vers lui en partageant de la vie bonus."}], "sources": [{"url": "https://www.youtube.com/watch?v=mc--EjMwJgA", "title": "Winter Soldier Guide", "author": "Paz (padswagger)"}, {"title": "The Only Bucky Guide You'll Ever Need", "author": "Kingsman", "url": "https://www.youtube.com/watch?v=pm32chmreII"}, {"title": "Ultimate Winter Soldier Guide (Beginner/Advanced)", "author": "Tephra98", "url": "https://www.youtube.com/watch?v=Tu7coC3c2XI"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Expert Instinct", "partners": ["elsa-bloodstone"], "key": "", "text": "Les kills donnent des cumuls d'instinct. **Amélioré :** Augmente la vie bonus de Ceaseless Charge (55 en saison 10)."}, {"name": "Stars Aligned", "partners": ["captain-america"], "key": "", "text": "Saut vers l'allié qui partage de la vie bonus. **Amélioré :** Ralliement mutuel."}, {"name": "Timeless Veterans", "partners": ["the-punisher"], "key": "", "text": "Pointe d'électricité qui repousse. **Amélioré :** Cloue au sol en plus."}], "changes": [{"season": "Saison 11", "text": "Roterstern : la baisse de dégâts maximale passe de 70 % à 40 m à 65 % à 30 m ; dégâts du champ 45 → 40."}, {"season": "Saison 10", "text": "Tainted Voltage : charge 5 s → 6 s, ralentissement 35 % → 25 %."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'winter-soldier' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.guides (kind, hero_id, status, content) select 'hero', h.id, 'published', $j${"title": "", "summary": "Wolverine est le meilleur anti-tank du jeu. Ses griffes infligent des dégâts en pourcentage de la vie maximale, et son attrape emporte une cible, de préférence un Vanguard, au milieu de son équipe. Sa rage monte au fil du fight et renforce tout son kit.", "patch_note": "Guide à jour de la saison 11 (patch du 13 novembre 2026). Les chiffres précis du kit changent à chaque saison : seuls les derniers changements et les team-ups sont détaillés, dans la section dédiée en bas de page.", "tldr": ["**Ramène** les cibles chez toi au lieu d'aller te battre chez elles.", "**Hurle avant chaque attrape** : toute l'équipe adverse va te tirer dessus.", "Garde ta **rage** haute, sans mourir pour elle."], "difficulty": 2, "tags": ["Anti-tank", "Déplacement d'ennemis", "Rage", "Brawl"], "strengths": ["Dégâts en pourcentage : les tanks fondent", "Emporte une cible hors de portée de ses soins", "Passif qui lui évite une mort"], "weaknesses": ["Aucune portée", "Attrape plus rare en saison 11 (15 s)", "Annulé par l'attraction d'Invisible Woman et les bulles"], "playbook": [{"when": "Le tank adverse s'avance", "then": "**Hurlement**, bond dans son dos, **attrape** : tu l'emportes vers ton équipe. Griffes rapides ensuite."}, {"when": "Un support ou un DPS adverse a son ult prête", "then": "Si tu peux l'atteindre, **attrape-le** et ramène-le : il ne la lancera pas."}, {"when": "Venom ou un autre tank dive sur ta backline", "then": "Reste près de tes supports et **emporte-le** loin d'eux."}, {"when": "Ton attrape est en cooldown", "then": "Frappe aux griffes pour **monter ta rage**, à couvert. Ne t'engage pas sans elle : elle revient en 15 secondes depuis la saison 11."}, {"when": "Ton passif de survie vient de se déclencher", "then": "Tu as quelques secondes de vie bonus : **finis ta cible**, puis sors au bond."}, {"when": "Le météore de Magneto tombe", "then": "**Hurlement, puis bond dedans** : tu l'encaisses à la place de ton équipe."}], "sections": [{"title": "Philosophie de jeu", "lead": "Wolverine ne part presque jamais sur un flanc. Il rôde à couvert près de son front et ramène les cibles vers son équipe.", "ability": "", "key": "", "kind": "tips", "items": ["Les **tanks** sont ta cible principale ; un support sur le point d'avoir son ult vaut aussi le déplacement.", "Contre une compo de dive, joue **en gardien de ta backline**.", "Avec une ult de Gambit, tu peux exceptionnellement plonger sur leurs supports.", "Sans tank à attraper en face (un Captain America seul), **change de héros**."], "diagram": "", "scene": {"title": "Ramener le tank", "caption": "Tu ne te bats pas chez l'ennemi. Tu prends leur tank et tu le poses chez toi, là où quatre alliés l'attendent.", "steps": ["Hurlement, puis bond dans le dos du tank.", "Attrape : tu l'emportes vers ton équipe.", "Griffes rapides : sans soin, il fond."], "els": [{"t": "cover", "at": [150, 34], "size": [16, 60], "label": "Mur"}, {"t": "pawn", "at": [136, 120], "team": "me", "ghost": true}, {"t": "path", "kind": "move", "team": "me", "pts": [[136, 120], [200, 150], [240, 112]], "n": 1}, {"t": "pawn", "at": [224, 96], "team": "enemy", "role": "tank", "ghost": true}, {"t": "pawn", "at": [240, 104], "team": "me", "ghost": true}, {"t": "path", "kind": "pull", "team": "me", "pts": [[232, 100], [180, 60], [118, 70]], "n": 2}, {"t": "zone", "at": [104, 76], "r": 32, "team": "ally", "label": "Ton équipe"}, {"t": "pawn", "at": [100, 70], "team": "enemy", "role": "tank"}, {"t": "pawn", "at": [126, 92], "team": "me"}, {"t": "note", "at": [150, 112], "text": "3", "team": "me"}, {"t": "pawn", "at": [70, 56], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [72, 100], "team": "ally", "role": "dps"}, {"t": "pawn", "at": [40, 76], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [60, 140], "team": "ally", "role": "heal"}, {"t": "pawn", "at": [264, 60], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [268, 140], "team": "enemy", "role": "dps"}, {"t": "pawn", "at": [296, 84], "team": "enemy", "role": "heal"}, {"t": "pawn", "at": [296, 120], "team": "enemy", "role": "heal"}]}}, {"title": "Rage et régénération", "lead": "Tes attaques et les dégâts que tu subis remplissent ta rage, qui augmente tes dégâts. Ton passif t'évite la mort une fois de temps en temps et te rend de la vie.", "ability": "Berserker Rage · Regenerative Healing Factor", "key": "", "kind": "default", "items": ["La rage **retombe avec le temps** : reste actif.", "Chaque élimination ou assistance **réduit le cooldown** du passif.", "Quand le passif s'est déclenché, tu peux rester agressif quelques secondes pour conclure."], "diagram": ""}, {"title": "Griffes et bond", "lead": "Des coups de griffes dont les dégâts dépendent de la vie maximale de la cible, et un bond court qui frappe de la même manière.", "ability": "Savage Claw · Vicious Rampage", "key": "Clic G · Clic D", "kind": "default", "items": ["En début de fight, frappe pour **remplir ta rage** avant de penser à l'attrape.", "Le bond est ta **sortie de secours**.", "Il sert aussi à **passer derrière un tank** pour l'attraper dans le bon sens."], "diagram": ""}, {"title": "Hurlement", "lead": "Tu encaisses beaucoup moins de dégâts pendant quelques secondes.", "ability": "Undying Animal", "key": "", "kind": "default", "items": ["**Avant chaque attrape.**", "Joue à couvert pour ne pas avoir à le dépenser avant.", "En sortant du spawn, bond puis hurlement annule l'animation et te fait gagner du temps."], "diagram": ""}, {"title": "Attrape", "lead": "Tu bondis, tu saisis une cible et tu l'écrases au sol en l'étourdissant. Tes griffes frappent ensuite beaucoup plus vite pendant un moment.", "ability": "Feral Leap", "key": "", "kind": "default", "items": ["**Bond pour te rapprocher, puis attrape** : à cette distance, elle ne se rate presque pas.", "Les griffes rapides qui suivent font fondre un tank en quelques secondes.", "Son cooldown est de **15 secondes** depuis la saison 11 : une attrape ratée te coûte presque un fight.", "Sur certaines cartes, emporte la cible **dans le vide**."], "diagram": ""}, {"title": "Ultime", "lead": "Tu projettes en l'air les ennemis devant toi, puis tu les écrases au sol en les étourdissant. Les dégâts dépendent de leur vie maximale et de ta rage.", "ability": "Last Stand", "key": "Q", "kind": "default", "items": ["L'ult ne donne pas les griffes rapides : **attrape d'abord, ult ensuite**.", "Le bonus de rage a été réduit en saison 11 : elle déplace et étourdit, elle tue moins qu'avant.", "Elle **sort un support de son ult de zone** (Invisible Woman, Cloak & Dagger).", "Vise l'atterrissage en pente douce pour ne perdre personne en route."], "diagram": ""}, {"title": "Erreurs fréquentes", "lead": "", "ability": "", "key": "", "kind": "mistakes", "items": ["Aller **se battre chez l'ennemi**.", "Attraper **sans hurler**.", "Dépenser le hurlement **en début de fight**.", "Lancer l'ult **sans attrape** juste avant.", "Insister face à une **Invisible Woman**."], "diagram": ""}], "combos": [{"note": "Presque impossible à rater.", "steps": [{"key": "Clic D", "label": "bond"}, {"key": "", "label": "Attrape"}], "title": "Attrape fiable"}], "counters": [{"hero": "invisible-woman", "note": "Son attraction te fait lâcher prise à chaque attrape."}, {"hero": "magneto", "note": "Sa bulle protège la cible que tu emportes."}, {"hero": "emma-frost", "note": "En diamant, elle t'étrangle : force d'abord sa transformation."}, {"hero": "captain-america", "note": "Trop mobile pour être attrapé, et pas assez de vie pour tes griffes."}, {"hero": "hela", "note": "Elle te tue sans jamais entrer dans ta portée."}, {"hero": "iron-man", "note": "Les volants sont hors d'atteinte."}], "synergies": [{"hero": "the-thing", "note": "Il ouvre le brawl, tu en sors leur tank."}, {"hero": "hulk", "note": "Votre team-up lui permet de te lancer sur une cible."}, {"hero": "phoenix", "note": "Ses explosions achèvent ce que tu ramènes."}, {"hero": "magneto", "note": "Sa bulle sur toi pendant l'attrape."}, {"hero": "winter-soldier", "note": "Deux héros qui déplacent les tanks : le front adverse n'existe plus."}, {"hero": "rocket-raccoon", "note": "Son kit de saut t'emmène plus loin avec ta cible."}], "sources": [{"url": "https://www.youtube.com/watch?v=J2sqWAV2ubs", "title": "Wolverine Guide", "author": "Paz (padswagger)"}], "kit": {"season": "Saison 11", "health": "", "abilities": [], "teamups": [{"name": "Blast Slash", "partners": ["cyclops"], "key": "", "text": "Griffes plus longues et Kinetic Claws. **Amélioré :** L'effet reste actif en permanence."}, {"name": "Gamma Fastball", "partners": ["hulk"], "key": "", "text": "État furieux et Scars of Rage (+25 % vitesse d'attaque et de déplacement en 10.5). **Amélioré :** Débloque le Fastball Special (Unstoppable : seuil 400, cooldown 45 s en 10.5)."}, {"name": "Pair of Threes", "partners": ["gambit"], "key": "", "text": "Amélioration cinétique avec des particules qui explosent. **Amélioré :** Ajoute un soin continu."}], "changes": [{"season": "Saison 11", "text": "Feral Leap : cooldown 12 → 15 s."}, {"season": "Saison 11", "text": "Last Stand : bonus par point de rage 0,3 % → 0,2 % de la vie max de la cible (rage pleine : 150 → 125 sur 250 PV, 330 → 260 sur 700 PV)."}, {"season": "Saison 10", "text": "Savage Claw 15 → 18 de dégâts de base ; le soin ne dépend plus de la rage (300 fixes)."}], "source": {"title": "Team-ups : fichiers du jeu saison 10.5 (rivalsdex.com) · équilibrage : notes de patch des saisons 10, 10.5 et 11", "url": "https://rivalsdex.com/team-ups"}}}$j$::jsonb from public.heroes h where h.slug = 'wolverine' on conflict (hero_id) where kind = 'hero' do update set content = public.rc_merge_guide(public.guides.content, excluded.content);
insert into public.quiz_questions (key, hero_id, map_id, guide_slug, topic, prompt, options, answer, explain, section) values
('mantis-1', (select id from public.heroes where slug = 'mantis'), null, null, 'Kit', 'Comment Mantis récupère-t-elle ses orbes de vie le plus vite ?', '["En réussissant des headshots", "En soignant ses alliés", "En se mettant à couvert", "Toutes les dix secondes"]'::jsonb, 0, 'Un headshot rend une orbe entière, même sur un tank. Depuis la saison 11, un tir au corps en rend 0,3 : la précision reste trois fois plus rentable. C''est pour cela que Mantis se joue comme une DPS déguisée.', 'Tirs'),
('mantis-2', (select id from public.heroes where slug = 'mantis'), null, null, 'Kit', 'Quelle est la capacité la plus importante de Mantis ?', '["Le bonus de dégâts, placé sur l''allié qui va décider du fight", "La fleur de soin", "Le sommeil", "L''ult"]'::jsonb, 0, 'Booste le DPS qui s''engage (Star-Lord en duel, Punisher qui arrose, Storm) : le bonus accélère aussi sa charge d''ult. Depuis la saison 11, il coûte deux orbes sur un allié : choisis ta cible, et ne le relance pas sur un allié qui l''a déjà.', 'Bonus de dégâts'),
('white-fox-2', (select id from public.heroes where slug = 'white-fox'), null, null, 'Mise en situation', 'Un Black Panther s''apprête à bondir sur ton autre support. Que fais-tu de ton renard spectral ?', '["Je le lance sur lui juste avant le bond : le charme annule son déplacement", "Je le lance sur mon support pour le rendre invulnérable", "Je le garde pour soigner après le dive", "Je le lance une fois son combo terminé"]'::jsonb, 0, 'Depuis la saison 11, le renard spectral ne rend plus les alliés invulnérables. Il lui reste le charme, sur une zone plus étroite : touché de plein fouet, l''ennemi marche vers toi et perd son déplacement. Il interrompt aussi une ult canalisée comme celle de Doctor Strange.', 'Renard spectral'),
('white-fox-4', (select id from public.heroes where slug = 'white-fox'), null, null, 'Ultime', 'Comment utiliser ton ult ?', '["En premier, pendant une vraie poussée sur le point", "En réaction, comme une ult de Luna", "Seule, sur la backline", "Pour fuir"]'::jsonb, 0, 'Lance-la proactivement, en restant derrière tes tanks : ta hitbox devient énorme et tu n''as plus de mobilité. Depuis la saison 11, tes alliés peuvent te soigner pendant l''ult, mais tu as moins de vie. Ta bénédiction rend un allié insensible aux contrôles.', 'Ultime'),
('squirrel-girl-1', (select id from public.heroes where slug = 'squirrel-girl'), null, null, 'Kit', 'Depuis la saison 11, quand activer Mammal Bond ?', '["Quand une cible est exposée : cinq secondes de tir deux fois plus rapide, en ligne droite", "Avant tes capacités, pour geler leurs cooldowns", "Dès qu''il est prêt, même sans cible en vue", "Pour faire rebondir tes glands par-dessus un bouclier"]'::jsonb, 0, 'Mammal Bond a été refait : pendant cinq secondes, ta vitesse d''attaque double et tes glands partent tout droit, bien plus vite, pour des dégâts un peu réduits. C''est une fenêtre de burst, sur un diver immobilisé, un tank isolé ou un volant. Lancé sans cible, il est perdu.', 'Mammal Bond'),
('loki-1', (select id from public.heroes where slug = 'loki'), null, null, 'Placement', 'Tu arrives sur le point avant le fight. Où poser tes deux clones ?', '["Un près de ton front, un à l''abri : le second est ta sortie", "Les deux au même endroit, pour concentrer les soins", "Les deux en première ligne, pour encaisser à ta place", "Aucun : je les garde pour plus tard"]'::jsonb, 0, 'Les clones tirent et posent leurs runes en même temps que toi, depuis leur position. Deux angles différents couvrent plus de terrain, et le clone à l''abri te sert de sortie grâce à l''échange de place.', 'Clones'),
('loki-2', (select id from public.heroes where slug = 'loki'), null, null, 'Mise en situation', 'Un Iron Man adverse lance son ult sur ton équipe. Que fais-tu ?', '["Je pose mes runes sous mes alliés : les dégâts subis dedans deviennent du soin", "Je passe invisible pour me sauver", "Rien de plus : je les avais posées en début de fight", "J''échange de place avec un clone"]'::jsonb, 0, 'Les runes sont l''une des meilleures réponses à une ult de dégâts, à condition de les avoir gardées. Chaque clone pose aussi les siennes : la zone couverte dépend de leur placement. Elles ne protègent pas d''un déplacement forcé.', 'Runes'),
('loki-3', (select id from public.heroes where slug = 'loki'), null, null, 'Ultime', 'Ton autre support vient de finir son ult et le fight continue. Qui copier ?', '["Lui : je relance la même ult juste après la sienne", "Un tank adverse, pour encaisser", "Le Duelist adverse le mieux classé", "Personne : je garde l''ult pour le fight suivant"]'::jsonb, 0, 'Copier un héros te donne son ult immédiatement. Deux ults de soin à la suite sont presque impossibles à traverser. Copier un Duelist n''a d''intérêt que si tu sais le jouer.', 'Ultime'),
('loki-4', (select id from public.heroes where slug = 'loki'), null, null, 'Kit', 'À quoi sert avant tout l''échange de place avec un clone ?', '["À sortir : c''est ta seule vraie mobilité", "À avancer sur la backline adverse", "À soigner le clone", "À recharger tes runes"]'::jsonb, 0, 'Loki n''a ni dash ni saut. Garde toujours un clone hors de danger : l''échange est ta sortie face à un diver, et Deception (invisibilité) revient désormais en 18 secondes.', 'Invisibilité et échange'),
('gorr-the-god-butcher-1', (select id from public.heroes where slug = 'gorr-the-god-butcher'), null, null, 'Kit', 'D''où lancer Living Abyss ?', '["Depuis un endroit sûr : le Berserker laissé au départ est ta sortie", "Depuis le milieu du fight, pour gagner du temps", "Peu importe : il ne laisse rien derrière lui", "Uniquement quand tu fuis"]'::jsonb, 0, 'Living Abyss laisse un Berserker à son point de départ. Shadow Harvest te ramène dessus : l''aller et le retour sont préparés par la même capacité. Il sert à entrer, pas à fuir.', 'Living Abyss'),
('gorr-the-god-butcher-2', (select id from public.heroes where slug = 'gorr-the-god-butcher'), null, null, 'Mise en situation', 'Ton engage tourne mal et Living Abyss est en cooldown. Que fais-tu ?', '["Shadow Harvest sur le Berserker resté en arrière", "Necro-Power sur l''ennemi le plus proche", "Je continue de frapper pour la vie bonus", "Je lance l''ult pour me sauver"]'::jsonb, 0, 'Shadow Harvest te téléporte sur un Berserker et te donne de la vie bonus en le sacrifiant. Gorr n''a ni double saut ni escalade : sans Berserker de repli, un engage raté ne se rattrape pas.', 'Shadow Harvest'),
('gorr-the-god-butcher-3', (select id from public.heroes where slug = 'gorr-the-god-butcher'), null, null, 'Kit', 'Quand Necro-Power est-il le plus fort ?', '["Quand plusieurs Berserkers sont en place : ils se téléportent tous sur la cible", "Quand aucun Berserker n''est posé", "Pendant Living Abyss", "Sur un tank à pleine vie"]'::jsonb, 0, 'La cible touchée est ralentie, et les Berserkers proches se téléportent sur elle pour une double frappe qui la projette en l''air. Plus ils sont nombreux, plus l''effet se multiplie.', 'Necro-Power'),
('gorr-the-god-butcher-4', (select id from public.heroes where slug = 'gorr-the-god-butcher'), null, null, 'Placement', 'Tes cooldowns sont prêts, mais aucun ennemi n''est isolé. Que fais-tu ?', '["J''attends une erreur de placement adverse", "Je plonge quand même sur leur tank", "Je plonge en premier pour ouvrir le fight", "Je lance l''ult pour forcer"]'::jsonb, 0, 'Gorr engage sur une erreur adverse, un support écarté ou un Duelist sans défense, pas simplement parce que ses capacités sont prêtes. Chaque élimination lui offre un Berserker de plus : c''est en tête qu''il devient difficile à arrêter.', 'Philosophie de jeu'),
('nightcrawler-1', (select id from public.heroes where slug = 'nightcrawler'), null, null, 'Mise en situation', 'Ton tank est isolé au milieu des ennemis. D''où lancer Tandem Teleport ?', '["Depuis un couvert : c''est là que vous réapparaissez tous les deux", "Depuis le milieu du fight, pour arriver plus vite", "Peu importe : vous réapparaissez au spawn", "Depuis une hauteur à découvert"]'::jsonb, 0, 'Tandem Teleport t''emmène sur ton allié, puis vous ramène tous les deux à ton point de départ, soignés et accélérés. Il faut que l''allié accepte l''invitation : annonce-la.', 'Téléportation à deux'),
('nightcrawler-2', (select id from public.heroes where slug = 'nightcrawler'), null, null, 'Kit', 'Pourquoi garder au moins une téléportation en réserve ?', '["Ce sont à la fois tes soins et ta survie : sans elles, tu es fragile", "Elles chargent ton ult plus vite en réserve", "Elles soignent davantage quand elles sont toutes disponibles", "Ce n''est pas utile : il faut tout dépenser dès que possible"]'::jsonb, 0, 'Chaque téléportation dépensée est un soin donné et une sortie en moins. Entre deux interventions, soigne aux grenades et replace-toi hors de portée.', 'Plan de jeu'),
('nightcrawler-3', (select id from public.heroes where slug = 'nightcrawler'), null, null, 'Ultime', 'Que fait la relance de ton ult ?', '["Elle frappe les ennemis présents dans la fumée et les attire vers toi", "Elle ramène ton équipe à son point de départ", "Elle ressuscite un allié", "Elle rend ton équipe invisible"]'::jsonb, 0, 'L''ult téléporte ton équipe vers une destination, avec bonus de dégâts, soin et vie bonus. Une zone de fumée se forme à l''arrivée ; la relance attire les ennemis qui s''y trouvent, loin de leurs soins ou vers un bord de carte.', 'Ultime'),
('nightcrawler-4', (select id from public.heroes where slug = 'nightcrawler'), null, null, 'Mise en situation', 'Un diver te colle. Comment utiliser Smoke Shift ?', '["Un ou deux passages pour le projeter, puis la troisième activation me ramène à la marque", "Trois passages vers l''avant, pour m''éloigner le plus possible", "Je le garde pour soigner mon équipe", "Je ne l''utilise pas : il ne touche pas les ennemis"]'::jsonb, 0, 'La fumée blesse et projette les ennemis, et soigne les alliés. Tu marques ton point de départ en lançant la capacité : la troisième activation t''y ramène.', 'Fumée')
